INSERT INTO recipe_templates (name, cuisine_tags, diet_tags, prep_minutes, cook_minutes, total_minutes, difficulty, macros, servings, ingredients, instructions, image_url, source) VALUES
('Garides Saganaki', ARRAY['greek', 'seafood']::text[], ARRAY['gluten_free']::text[], 21, 35, 56, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Raw king prawns","measure":"500g"},{"name":"Olive oil","measure":"3 tablespoons"},{"name":"Chopped onion","measure":"1"},{"name":"Freshly chopped parsley","measure":"pinch"},{"name":"White wine","measure":"250ml"},{"name":"Chopped tomatoes","measure":"1 (400g) tin"},{"name":"Minced garlic","measure":"1/2 teaspoon"},{"name":"Cubed Feta cheese","measure":"1 (200g) pack"}]'::jsonb, '["Place the prawns in a pot and add enough water to cover. Boil for 5 minutes. Drain, reserving the liquid, and set aside.","Heat 2 tablespoons of oil in a saucepan. Add the onion; cook and stir until soft. Mix in the parsley, wine, tomatoes, garlic and remaining olive oil. Simmer, stirring occasionally, for about 30 minutes, or until the sauce is thickened.","While the sauce is simmering, the prawns should become cool enough to handle. First remove the legs by pinching them, and then pull off the shells, leaving the head and tail on.","When the sauce has thickened, stir in the prawns. Bring to a simmer again if the sauce has cooled with the prawns, and cook for about 5 minutes. Add the feta and remove from the heat. Let stand until the cheese starts to melt. Serve warm with slices of crusty bread.","Though completely untraditional, you can add a few tablespoons of stock or passata to this recipe to make a delicious pasta sauce. Toss with pasta after adding the feta, and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wuvryu1468232995.jpg', 'themealdb'),
('Bakewell tart', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 25, 55, 80, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"plain flour","measure":"175g/6oz"},{"name":"chilled butter","measure":"75g/2½oz"},{"name":"cold water","measure":"2-3 tbsp"},{"name":"raspberry jam","measure":"1 tbsp"},{"name":"butter","measure":"125g/4½oz"},{"name":"caster sugar","measure":"125g/4½oz"},{"name":"ground almonds","measure":"125g/4½oz"},{"name":"free-range egg, beaten","measure":"1"},{"name":"almond extract","measure":"½ tsp"},{"name":"flaked almonds","measure":"50g/1¾oz"}]'::jsonb, '["To make the pastry, measure the flour into a bowl and rub in the butter with your fingertips until the mixture resembles fine breadcrumbs. Add the water, mixing to form a soft dough.","Roll out the dough on a lightly floured work surface and use to line a 20cm/8in flan tin. Leave in the fridge to chill for 30 minutes.","Preheat the oven to 200C/400F/Gas 6 (180C fan).","Line the pastry case with foil and fill with baking beans. Bake blind for about 15 minutes, then remove the beans and foil and cook for a further five minutes to dry out the base.","For the filing, spread the base of the flan generously with raspberry jam.","Melt the butter in a pan, take off the heat and then stir in the sugar. Add ground almonds, egg and almond extract. Pour into the flan tin and sprinkle over the flaked almonds.","Bake for about 35 minutes. If the almonds seem to be browning too quickly, cover the tart loosely with foil to prevent them burning."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wyrqqq1468233628.jpg', 'themealdb'),
('Spaghetti Bolognese', ARRAY['italian', 'beef']::text[], ARRAY[]::text[], 29, 45, 74, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"onions","measure":"2"},{"name":"olive oil","measure":"1tbsp"},{"name":"garlic","measure":"1 clove"},{"name":"lean minced beef","measure":"500g"},{"name":"mushrooms","measure":"90g"},{"name":"dried oregano","measure":"1tsp"},{"name":"tomatoes","measure":"400g can"},{"name":"hot beef stock","measure":"300ml"},{"name":"tomato puree","measure":"1tbsp"},{"name":"worcestershire sauce","measure":"1tbsp"},{"name":"spaghetti","measure":"350g"},{"name":"parmesan","measure":"Topping"}]'::jsonb, '["Put the onion and oil in a large pan and fry over a fairly high heat for 3-4 mins. Add the garlic and mince and fry until they both brown. Add the mushrooms and herbs, and cook for another couple of mins.","Stir in the tomatoes, beef stock, tomato ketchup or purée, Worcestershire sauce and seasoning. Bring to the boil, then reduce the heat, cover and simmer, stirring occasionally, for 30 mins.","Meanwhile, cook the spaghetti in a large pan of boiling, salted water, according to packet instructions. Drain well, run hot water through it, put it back in the pan and add a dash of olive oil, if you like, then stir in the meat sauce. Serve in hot bowls and hand round Parmesan cheese, for sprinkling on top."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sutysw1468247559.jpg', 'themealdb'),
('Teriyaki Chicken Casserole', ARRAY['japanese', 'chicken']::text[], ARRAY['dairy_free']::text[], 23, 40, 63, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"soy sauce","measure":"3/4 cup"},{"name":"water","measure":"1/2 cup"},{"name":"brown sugar","measure":"1/4 cup"},{"name":"ground ginger","measure":"1/2 teaspoon"},{"name":"minced garlic","measure":"1/2 teaspoon"},{"name":"cornstarch","measure":"4 Tablespoons"},{"name":"chicken breasts","measure":"2"},{"name":"stir-fry vegetables","measure":"1 (12 oz.)"},{"name":"brown rice","measure":"3 cups"}]'::jsonb, '["Preheat oven to 350° F. Spray a 9x13-inch baking pan with non-stick spray.","Combine soy sauce, ½ cup water, brown sugar, ginger and garlic in a small saucepan and cover. Bring to a boil over medium heat. Remove lid and cook for one minute once boiling.","Meanwhile, stir together the corn starch and 2 tablespoons of water in a separate dish until smooth. Once sauce is boiling, add mixture to the saucepan and stir to combine. Cook until the sauce starts to thicken then remove from heat.","Place the chicken breasts in the prepared pan. Pour one cup of the sauce over top of chicken. Place chicken in oven and bake 35 minutes or until cooked through. Remove from oven and shred chicken in the dish using two forks.","*Meanwhile, steam or cook the vegetables according to package directions.","Add the cooked vegetables and rice to the casserole dish with the chicken. Add most of the remaining sauce, reserving a bit to drizzle over the top when serving. Gently toss everything together in the casserole dish until combined. Return to oven and cook 15 minutes. Remove from oven and let stand 5 minutes before serving. Drizzle each serving with remaining sauce. Enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/wvpsxx1468256321.jpg', 'themealdb'),
('Mediterranean Pasta Salad', ARRAY['italian', 'seafood']::text[], ARRAY['pescatarian', 'gluten_free']::text[], 23, 50, 73, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"mozzarella balls","measure":"200 g"},{"name":"baby plum tomatoes","measure":"250 g"},{"name":"fresh basil","measure":"1  bunch"},{"name":"farfalle","measure":"350 g"},{"name":"extra virgin olive oil","measure":"3  tablespoons"},{"name":"Green Olives","measure":"40 g"},{"name":"tuna","measure":"200 g"},{"name":"salt","measure":"to taste"},{"name":"pepper","measure":"to taste"}]'::jsonb, '["Bring a large saucepan of salted water to the boil","Add the pasta, stir once and cook for about 10 minutes or as directed on the packet.","Meanwhile, wash the tomatoes and cut into quarters. Slice the olives. Wash the basil.","Put the tomatoes into a salad bowl and tear the basil leaves over them. Add a tablespoon of olive oil and mix.","When the pasta is ready, drain into a colander and run cold water over it to cool it quickly.","Toss the pasta into the salad bowl with the tomatoes and basil.","Add the sliced olives, drained mozzarella balls, and chunks of tuna. Mix well and let the salad rest for at least half an hour to allow the flavours to mingle.","Sprinkle the pasta with a generous grind of black pepper and drizzle with the remaining olive oil just before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wvqpwt1468339226.jpg', 'themealdb'),
('Rigatoni with fennel sausage sauce', ARRAY['italian', 'lamb']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 39, 50, 89, 'hard', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 6, '[{"name":"olive oil","measure":"2½ tbsp"},{"name":"Italian fennel sausages","measure":"6 cut into 1.5cm-thick slices"},{"name":"onion","measure":"1 large peeled and chopped"},{"name":"fennel bulb","measure":"1 trimmed and roughly chopped; reserve any fronds to garnish"},{"name":"smoky paprika","measure":"½ tsp"},{"name":"garlic","measure":"1 clove, peeled and sliced"},{"name":"fennel seeds","measure":"2 tsp lightly toasted and then gently crushed"},{"name":"red wine","measure":"100ml"},{"name":"chopped tomatoes","measure":"400g tinned"},{"name":"caster sugar","measure":"½ tsp"},{"name":"pitted black olives","measure":"50g cut in half lengthways"},{"name":"rigatoni","measure":"500g"},{"name":"pecorino","measure":"30g roughly crumbled into 0.5cm pieces"},{"name":"anchovy fillet","measure":"1  rinsed and patted dry"},{"name":"garlic","measure":"1 clove, peeled and crushed"},{"name":"olive oil","measure":"60ml"},{"name":"basil leaves","measure":"50g torn"}]'::jsonb, '["Heat a tablespoon of oil in a large saute pan for which you have a lid. Add the sausage pieces and fry on a medium-high heat for 10 minutes, stirring regularly, until golden-brown all over. Transfer the sausages to a plate, then add the onion and fennel to the hot pan and fry for 15 minutes, stirring once in a while, until soft and caramelised; if the pan goes a bit dry, add a teaspoon or so of extra oil. Stir in the paprika, garlic and half the fennel seeds, fry for two minutes more, then pour on the wine and boil for 30 seconds, to reduce by half. Add the tomatoes, sugar, 100ml water, the seared sausage and half a teaspoon of salt, cover and simmer for 30 minutes; remove the lid after 10 minutes, and cook until the sauce is thick and rich. Remove from the heat, stir through the olives and remaining fennel seeds and set aside until you’re ready to serve.","Bring a large pot of salted water to a boil, add the pasta and cook for 12-14 minutes (or according to the instructions on the packet), until al dente. Meanwhile, reheat the sauce. Drain the pasta, return it to the pot, stir in a tablespoon of oil, then divide between the bowls.","Put all the pesto ingredients except the basil in the small bowl of a food processor. Add a tablespoon of water and blitz to a rough paste. Add the basil, then blitz until just combined (the pesto has a much better texture if the basil is not overblended).","Spoon over the ragù and top with a spoonful of pesto. Finish with a sprinkling of chopped fennel fronds, if you have any, and serve at once."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qtqvys1468573168.jpg', 'themealdb'),
('Smoky Lentil Chili with Squash', ARRAY['british', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 43, 75, 118, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 6, '[{"name":"Olive Oil","measure":"1 tbls"},{"name":"Onion","measure":"1"},{"name":"Leek","measure":"1 chopped"},{"name":"Garlic","measure":"3 cloves"},{"name":"Cumin","measure":"4 tsp ground"},{"name":"Coriander","measure":"2 tsp ground"},{"name":"Smoked Paprika","measure":"1 tsp"},{"name":"Cinnamon","measure":"1/2 tsp"},{"name":"Chili Powder","measure":"1 tsp"},{"name":"Cocoa","measure":"1 tsp"},{"name":"Dried Oregano","measure":"1/2 tsp"},{"name":"Diced Tomatoes","measure":"1 can"},{"name":"Water","measure":"3 cups"},{"name":"Carrots","measure":"3 chopped"},{"name":"Brown Lentils","measure":"1 1/2 cups"},{"name":"Sea Salt","measure":"1 tsp"},{"name":"Squash","measure":"1 Small"},{"name":"Cashews","measure":"1 Cup"},{"name":"Apple Cider Vinegar","measure":"1 tsp"}]'::jsonb, '["Begin by roasting the squash. Slice it into thin crescents and drizzle with a little oil and sprinkle with sea salt. I added a fresh little sage I had in the fridge, but it’s unnecessary. Roast the squash a 205 C (400 F) for 20-30 minutes, flipping halfway through, until soft and golden. Let cool and chop into cubes.","Meanwhile, rinse the lentils and cover them with water. Bring them to the boil then turn down to a simmer and let cook (uncovered) for 20-30 minutes, or until tender. Drain and set aside.","While the lentils are cooking heat the 1 Tbsp. of oil on low in a medium pot. Add the onions and leeks and sauté for 5 or so minutes, or until they begin to soften. Add the garlic next along with the cumin and coriander, cooking for a few more minutes. Add the remaining spices – paprika, cinnamon, chilli, cocoa, Worcestershire sauce, salt, and oregano. Next add the can of tomatoes, the water or stock, and carrots. Let simmer, covered, for 20 minutes or until the veg is tender and the mixture has thickened up. You’ll need to check on the pot periodically for a stir and a top of of liquid if needed.","Add the lentils and chopped roasted squash. Let cook for 10 more minutes to heat through.","Serve with sliced jalapeno, lime wedges, cilantro, green onions, and cashew sour cream.","SIMPLE CASHEW SOUR CREAM","Cup Raw Unsalted Cashews","Pinch Sea Salt","tsp. Apple Cider Vinegar","Water","Bring some water to the boil, and use it to soak the cashews for at least four hours. Alternatively, you can use cold water and let the cashews soak overnight, but I’m forgetful/lazy, so often use the boil method which is much faster.","After the cashews have soaked, drain them and add to a high speed blender. Begin to puree, slowly adding about 1/2 cup fresh water, until a creamy consistency is reached. You may need to add less or more water to reach the desired consistency.","Add a pinch of sea salt and vinegar (or lemon juice)."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uwxqwy1483389553.jpg', 'themealdb'),
('Rocky Road Fudge', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 15, 70, 85, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Miniature Marshmallows","measure":"2 cups"},{"name":"Chocolate Chips","measure":"3 cups"},{"name":"Peanut Butter","measure":"½ cup"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Peanuts","measure":"1 ¼ cups"}]'::jsonb, '["Line an 8-inch-square baking pan with wax paper or foil, and coat with non-stick spray.","Pour ½ cup of the miniature marshmallows into the bottom of the lined baking dish.","In a microwave-safe bowl, combine the chocolate chips and peanut butter. Microwave the chocolate mixture in 20-second intervals, stirring in between each interval, until the chocolate is melted.","Add the vanilla extract and stir well, until smooth.","Reserve 2 tablespoons of the chopped almonds or peanuts, and set aside.","Fold 1 ½ cups of the miniature marshmallows and the remaining chopped nuts into the chocolate mixture.","Transfer the chocolate mixture into the prepared pan and spread into an even layer. Immediately top with the reserved chopped nuts and the mallow bits or additional miniature marshmallows, if using.","Refrigerate for 4 hours, or until set.","Remove the fudge and wax paper from the pan. Carefully peel all of wax paper from the fudge.","Cut the fudge into bite-sized pieces and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vtxyxv1483567157.jpg', 'themealdb'),
('Hot Chocolate Fudge', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 17, 70, 87, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Chocolate Chips","measure":"2 cups"},{"name":"Heavy Cream","measure":"2 tbs"},{"name":"Condensed Milk","measure":"1 – 14-ounce can"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"White Chocolate Chips","measure":"1-⅓ cups"},{"name":"Miniature Marshmallows","measure":"1-½ cups"}]'::jsonb, '["Line an 8-inch-square baking pan with wax paper or foil, and coat with non-stick spray.","In a microwave-safe bowl, combine the dark chocolate chips, heavy cream and half of the sweetened condensed milk. Microwave the dark chocolate mixture in 20-second intervals, stirring in between each interval, until the chocolate is melted.","Add the vanilla extract to the dark chocolate mixture and stir well until smooth.","Transfer the dark chocolate mixture into the prepared pan and spread into an even layer.","In a separate bowl, combine the white chocolate chips with the remaining half of the sweetened condensed milk. Microwave the white chocolate mixture in 20-second intervals, stirring in between each interval, until the chocolate is melted.","Evenly spread the white chocolate mixture on top of dark chocolate layer.","Top the chocolate layers with the Mallow Bits or miniature marshmallows, and gently press them down.","Refrigerate for 4 hours, or until set.","Remove the fudge and wax paper from the pan. Carefully peel all of the wax paper from the fudge.","Cut the fudge into bite-sized pieces and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xrysxr1483568462.jpg', 'themealdb'),
('Eton Mess', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 15, 35, 50, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"strawberries","measure":"500g"},{"name":"double cream","measure":"400ml"},{"name":"meringue nests","measure":"3 x 7.5cm"},{"name":"ginger cordial","measure":"1 tbsp"},{"name":"Mint","measure":"sprigs of fresh"}]'::jsonb, '["Purée half the strawberries in a blender. Chop the remaining strawberries, reserving four for decoration.","Whip the double cream until stiff peaks form, then fold in the strawberry purée and crushed meringue. Fold in the chopped strawberries and ginger cordial, if using.","Spoon equal amounts of the mixture into four cold wine glasses. Serve garnished with the remaining strawberries and a sprig of mint."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uuxwvq1483907861.jpg', 'themealdb'),
('Sticky Toffee Pudding Ultimate', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 35, 45, 80, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Medjool dates","measure":"225g"},{"name":"water","measure":"175ml Boiling"},{"name":"vanilla extract","measure":"1 tsp"},{"name":"self-raising flour","measure":"175g"},{"name":"bicarbonate of soda","measure":"1 tsp"},{"name":"eggs","measure":"2"},{"name":"butter","measure":"85g"},{"name":"demerara sugar","measure":"140g"},{"name":"black treacle","measure":"2 tbsp"},{"name":"milk","measure":"100ml"},{"name":"ice cream","measure":"1 scoop"},{"name":"muscovado sugar","measure":"175g"},{"name":"butter","measure":"50g"},{"name":"double cream","measure":"225ml"},{"name":"black treacle","measure":"1 tbsp"}]'::jsonb, '["Stone and chop the dates quite small, put them in a bowl, then pour the boiling water over. Leave for about 30 mins until cool and well-soaked, then mash a bit with a fork. Stir in the vanilla extract. Butter and flour seven mini pudding tins (each about 200ml/7fl oz) and sit them on a baking sheet. Heat oven to 180C/fan 160C/gas 4.","While the dates are soaking, make the puddings. Mix the flour and bicarbonate of soda together and beat the eggs in a separate bowl. Beat the butter and sugar together in a large bowl for a few mins until slightly creamy (the mixture will be grainy from the sugar). Add the eggs a little at a time, beating well between additions. Beat in the black treacle then, using a large metal spoon, gently fold in one-third of the flour, then half the milk, being careful not to overbeat. Repeat until all the flour and milk is used. Stir the soaked dates into the pudding batter. The mix may look a little curdled at this point and will be like a soft, thick batter. Spoon it evenly between the tins and bake for 20-25 mins, until risen and firm.","Meanwhile, put the sugar and butter for the sauce in a medium saucepan with half the cream. Bring to the boil over a medium heat, stirring all the time, until the sugar has completely dissolved. Stir in the black treacle, turn up the heat slightly and let the mixture bubble away for 2-3 mins until it is a rich toffee colour, stirring occasionally to make sure it doesn’t burn. Take the pan off the heat and beat in the rest of the cream.","Remove the puddings from the oven. Leave in the tins for a few mins, then loosen them well from the sides of the tins with a small palette knife before turning them out. You can serve them now with the sauce drizzled over, but they’ll be even stickier if left for a day or two coated in the sauce. To do this, pour about half the sauce into one or two ovenproof serving dishes. Sit the upturned puddings on the sauce, then pour the rest of the sauce over them. Cover with a loose tent of foil so that the sauce doesn’t smudge (no need to chill).","When ready to serve, heat oven to 180C/fan 160C/gas 4. Warm the puddings through, still covered, for 15-20 mins or until the sauce is bubbling. Serve them on their own, or with cream or custard."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xrptpq1483909204.jpg', 'themealdb'),
('Vegan Chocolate Cake', ARRAY['united_states', 'vegan']::text[], ARRAY['vegetarian']::text[], 21, 25, 46, 'easy', '{"calories":360,"protein_g":14,"carbs_g":52,"fat_g":12}'::jsonb, 4, '[{"name":"Self-raising Flour","measure":"1 1/4 cup"},{"name":"coco sugar","measure":"1/2 cup"},{"name":"cacao","measure":"1/3 cup raw"},{"name":"baking powder","measure":"1 tsp"},{"name":"flax eggs","measure":"2"},{"name":"almond milk","measure":"1/2 cup"},{"name":"vanilla","measure":"1 tsp"},{"name":"water","measure":"1/2 cup boiling"}]'::jsonb, '["Simply mix all dry ingredients with wet ingredients and blend altogether.","Bake for 45 min on 180 degrees.","Decorate with some melted vegan chocolate"]'::jsonb, 'https://www.themealdb.com/images/media/meals/qxutws1486978099.jpg', 'themealdb'),
('Chicken Alfredo Primavera', ARRAY['italian', 'chicken']::text[], ARRAY[]::text[], 43, 110, 153, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Butter","measure":"2 tablespoons"},{"name":"Olive Oil","measure":"3 tablespoons"},{"name":"Chicken","measure":"5 boneless"},{"name":"Salt","measure":"1 teaspoon"},{"name":"Squash","measure":"1 cut into 1/2-inch cubes"},{"name":"Broccoli","measure":"1 Head chopped"},{"name":"mushrooms","measure":"8-ounce sliced"},{"name":"Pepper","measure":"1 red"},{"name":"onion","measure":"1 chopped"},{"name":"garlic","measure":"3 cloves"},{"name":"red pepper flakes","measure":"1/2 teaspoon"},{"name":"white wine","measure":"1/2 cup"},{"name":"milk","measure":"1/2 cup"},{"name":"heavy cream","measure":"1/2 cup"},{"name":"Parmesan cheese","measure":"1 cup grated"},{"name":"bowtie pasta","measure":"16 ounces"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Parsley","measure":"chopped"}]'::jsonb, '["Heat 1 tablespoon of butter and 2 tablespoons of olive oil in a large skillet over medium-high heat.","Season both sides of each chicken breast with seasoned salt and a pinch of pepper.","Add the chicken to the skillet and cook for 5-7 minutes on each side, or until cooked through.","While the chicken is cooking, bring a large pot of water to a boil.","Season the boiling water with a few generous pinches of kosher salt.","Add the pasta and give it a stir.","Cook, stirring occasionally, until al dente, about 12 minutes.","Reserve 1/2 cup of  pasta water before draining the pasta.","Remove the chicken from the pan and transfer it to a cutting board; allow it to rest.","Turn the heat down to medium and dd the remaining 1 tablespoon of butter and olive oil to the same pan you used to cook the chicken.","Add the veggies (minus the garlic) and red pepper flakes to the pan and stir to coat with the oil and butter (refrain from seasoning with salt until the veggies are finished browning).","Cook, stirring often, until the veggies are tender, about 5 minutes.","Add the garlic and a generous pinch of salt and pepper to the pan and cook for 1 minute.","Deglaze the pan with the white wine.","Continue to cook until the wine has reduced by half, about 3 minutes.","Stir in the milk, heavy cream, and reserved pasta water.","Bring the mixture to a gentle boil and allow to simmer and reduce for 2-3 minutes.","Turn off the heat and add the Parmesan cheese and cooked pasta.","Season with salt and pepper to taste.","Garnish with Parmesan cheese and chopped parsley, if desired."]'::jsonb, 'https://www.themealdb.com/images/media/meals/syqypv1486981727.jpg', 'themealdb'),
('Fish pie', ARRAY['british', 'seafood']::text[], ARRAY['pescatarian']::text[], 35, 35, 70, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Floury Potatoes","measure":"900g"},{"name":"Olive Oil","measure":"2 tbsp"},{"name":"Semi-skimmed Milk","measure":"600ml"},{"name":"White Fish Fillets","measure":"800g"},{"name":"Plain flour","measure":"1 tbsp"},{"name":"Nutmeg","measure":"Grating"},{"name":"Double Cream","measure":"3 tbsp"},{"name":"Jerusalem Artichokes","measure":"200g"},{"name":"Leek","measure":"1 finely sliced"},{"name":"Prawns","measure":"200g peeled raw"},{"name":"Parsley","measure":"Large handful"},{"name":"Dill","measure":"Handful"},{"name":"Lemon","measure":"Grated zest of 1"},{"name":"Gruyère","measure":"25g grated"},{"name":"Lemon","measure":"Juice of 1"}]'::jsonb, '["Put the potatoes in a large pan of cold salted water and bring to the boil. Lower the heat, cover, then simmer gently for 15 minutes until tender. Drain, then return to the pan over a low heat for 30 seconds to drive off any excess water. Mash with 1 tbsp olive oil, then season.","Meanwhile put the milk in a large sauté pan, add the fish and bring to the boil. Remove from the heat, cover and stand for 3 minutes. Remove the fish (reserving the milk) and pat dry with kitchen paper, then gently flake into an ovenproof dish, discarding the skin and any bones.","Heat the remaining oil in a pan, stir in the flour and cook for 30 seconds. Gradually stir in 200-250ml of the reserved milk (discard the rest). Grate in nutmeg, season, then bubble until thick. Stir in the cream.","Preheat the oven to 190°C/fan170°C/gas 5. Grate the artichokes and add to the dish with the leek, prawns and herbs. Stir the lemon zest and juice into the sauce, then pour over. Mix gently with a wooden spoon.","Spoon the mash onto the fish mixture, then use a fork to make peaks, which will crisp and brown as it cooks. Sprinkle over the cheese, then bake for 35-40 minutes until golden and bubbling. Serve with wilted greens."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ysxwuq1487323065.jpg', 'themealdb'),
('Poutine', ARRAY['canadian', 'miscellaneous']::text[], ARRAY['gluten_free']::text[], 13, 40, 53, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Vegetable Oil","measure":"Dash"},{"name":"Beef Gravy","measure":"1 Can"},{"name":"Potatoes","measure":"5 thin cut"},{"name":"Cheese Curds","measure":"2 cups"}]'::jsonb, '["Heat oil in a deep fryer or deep heavy skillet to 365°F (185°C).","Warm gravy in saucepan or microwave.","Place the fries into the hot oil, and cook until light brown, about 5 minutes.","Remove to a paper towel lined plate to drain.","Place the fries on a serving platter, and sprinkle the cheese over them.","Ladle gravy over the fries and cheese, and serve immediately."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uuyrrx1487327597.jpg', 'themealdb'),
('Lamb Biryani', ARRAY['india', 'lamb']::text[], ARRAY['gluten_free']::text[], 45, 105, 150, 'hard', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 6, '[{"name":"Cashew nuts","measure":"12"},{"name":"Khus khus","measure":"½ tbsp"},{"name":"Cumin seeds","measure":"½ tbsp"},{"name":"Onions","measure":"3 sliced thinly"},{"name":"Ginger garlic paste","measure":"2 tsp"},{"name":"Garlic","measure":"4 whole"},{"name":"Mint","measure":"Leaves"},{"name":"Cilantro","measure":"Leaves"},{"name":"Saffron","measure":"½ tsp dissolved in ½ cup warm milk"},{"name":"Ghee","measure":"2 tbsp"},{"name":"Basmati rice","measure":"2 Cups"},{"name":"Full fat yogurt","measure":"½ cup"},{"name":"Cumin Seeds","measure":"1 tbsp"},{"name":"Bay leaf","measure":"½"},{"name":"Cinnamon","measure":"1 thin piece"},{"name":"Cloves","measure":"3"},{"name":"Cardamom","measure":"2"},{"name":"Lamb","measure":"1 lb"},{"name":"Red Chilli powder","measure":"1 tsp"},{"name":"Biryani masala","measure":"1 tbsp"}]'::jsonb, '["Grind the cashew, poppy seeds and cumin seeds into a smooth paste, using as little water as possible. Set aside.","Deep fry the sliced onions when it is hot. Don’t overcrowd the oil. When the onions turn light brown, remove from oil and drain on paper towel. The fried onion will crisp up as it drains. Also fry the cashewnuts till golden brown. Set aside.","Wash the rice and soak in water for twenty minutes.","Meanwhile, take a big wide pan, add oil in medium heat, add the sliced onions, add the blended paste, to it add the green chillies, ginger garlic paste and garlic and fry for a minute.","Then add the tomatoes and sauté them well till they are cooked and not mushy.","Then to it add the red chilli powder, biryani powder, mint, coriander leaves and sauté them well.","Add the yogurt and mix well. I always move the skillet away from the heat when adding yogurt which prevents it from curdling.","Now after returning the skillet back to the stove, add the washed lamb and salt and ½ cup water and mix well. Cook for 1 hour and cook it covered in medium low heat or put it in a pressure cooker for 6 whistles. If the water is not drained totally, heat it by keeping it open.","Take another big pan, add thrice the cup of rice you use, and boil it. When it is boiling high, add the rice, salt and jeera and mix well. After 7 minutes exact or when the rice is 80% done. Switch off and drain the rice.","Now, the layering starts. To the lamb, pat and level it. Add the drained hot rice on the top of it. Garnish with fried onions, ghee, mint, coriander leaves and saffron dissolved in milk.","Cover the dish and bake in a 350f oven for 15 minutes or till the cooked but not mushy. Or cook in the stove medium heat for 12 minutes and lowest heat for 5 minutes. And switch off. Mix and serve hot!","Notes","If you are cooking in oven, do make sure to cook in a big oven safe pan and cover it tight and then keep in oven for the final step.","You can skip biryani masala if you don’t have and add just garam masala (1 tsp and red chilli powder – 3 tsp instead of 1 tsp)","If it is spicy in the end, squeeze some lemon, it will reduce the heat and enhance the flavors also."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xrttsx1487339558.jpg', 'themealdb'),
('Tandoori chicken', ARRAY['india', 'chicken']::text[], ARRAY['gluten_free']::text[], 29, 25, 54, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"lemons","measure":"2 Juice"},{"name":"paprika","measure":"4 tsp"},{"name":"red onions","measure":"2 finely chopped"},{"name":"chicken thighs","measure":"16 skinnless"},{"name":"vegetable oil","measure":"For brushing"},{"name":"Greek yogurt","measure":"300ml"},{"name":"ginger","measure":"large piece"},{"name":"garlic clove","measure":"4"},{"name":"garam masala","measure":"¾ tsp"},{"name":"ground cumin","measure":"¾ tsp"},{"name":"chilli powder","measure":"½ tsp"},{"name":"turmeric","measure":"¼ tsp"}]'::jsonb, '["Mix the lemon juice with the paprika and red onions in a large shallow dish. Slash each chicken thigh three times, then turn them in the juice and set aside for 10 mins.","Mix all of the marinade ingredients together and pour over the chicken. Give everything a good mix, then cover and chill for at least 1 hr. This can be done up to a day in advance.","Heat the grill. Lift the chicken pieces onto a rack over a baking tray. Brush over a little oil and grill for 8 mins on each side or until lightly charred and completely cooked through."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qptpvt1487339892.jpg', 'themealdb'),
('Lamb Rogan josh', ARRAY['india', 'lamb']::text[], ARRAY['gluten_free']::text[], 33, 45, 78, 'hard', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 6, '[{"name":"Onion","measure":"2 quartered"},{"name":"Sunflower Oil","measure":"4 tbsp"},{"name":"Garlic","measure":"4 cloves"},{"name":"Ginger","measure":"Thumb sized peeled and very finely grated"},{"name":"Madras Paste","measure":"2 tbsp"},{"name":"Paprika","measure":"2 tsp"},{"name":"cinnamon stick","measure":"1"},{"name":"Cardamom","measure":"6 bashed to break shells"},{"name":"Cloves","measure":"4"},{"name":"Bay Leaf","measure":"2"},{"name":"Tomato Purée","measure":"1 tbsp"},{"name":"Lamb","measure":"1kg cubed"},{"name":"Greek yogurt","measure":"150ml"},{"name":"Coriander","measure":"Garnish chopped"}]'::jsonb, '["Put the onions in a food processor and whizz until very finely chopped. Heat the oil in a large heavy-based pan, then fry the onion with the lid on, stirring every now and then, until it is really golden and soft. Add the garlic and ginger, then fry for 5 mins more.","Tip the curry paste, all the spices and the bay leaves into the pan, with the tomato purée. Stir well over the heat for about 30 secs, then add the meat and 300ml water. Stir to mix, turn down the heat, then add the yogurt.","Cover the pan, then gently simmer for 40-60 mins until the meat is tender and the sauce nice and thick. Serve scattered with coriander, with plain basmati or pilau rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vvstvq1487342592.jpg', 'themealdb'),
('Recheado Masala Fish', ARRAY['india', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 33, 90, 123, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Mackerel","measure":"4"},{"name":"Red Chilli","measure":"18 dried"},{"name":"Ginger","measure":"1 inch"},{"name":"Garlic","measure":"8 cloves"},{"name":"Pepper","measure":"1.5 tsp"},{"name":"Cumin","measure":"1 tsp"},{"name":"Turmeric","measure":"½ tsp"},{"name":"Cinnamon stick","measure":""},{"name":"Cloves","measure":"4"},{"name":"Cardamom","measure":"2"},{"name":"Sugar","measure":"1 tbsp"},{"name":"Tamarind ball","measure":"2 marble sized"},{"name":"Vinegar","measure":"2.5 tbsp"},{"name":"Oil","measure":"for frying"}]'::jsonb, '["Soak all the spices, ginger, garlic, tamarind pulp and kashmiri chilies except oil in vinegar.","Add sugar and salt.","Also add turmeric powder.","Combine all nicely and marinate for 35-40 mins.","Grind the mixture until soft and smooth. Add more vinegar if required but ensure the paste has to be thick so add vinegar accordingly. If the masala paste is thin then it would not stick to the fish.","Rinse the fish slit from the center and give some incision from the top. You could see the fish below for clarity.","Now stuff the paste into the center and into the incision. Coat the entire fish with this paste. Marinate the fish for 30 mins.","Place oil in a shallow pan, once oil is quite hot shallow fry the stuffed mackerels.","Fry until golden brown from both sides","Serve the recheado mackerels hot with salad, lime wedges, rice and curry.","Notes","Ensure the masala paste is thick else the result won''t be good.","If you aren''t able to find kashmiri chilies then use bedgi chilies or kashmiri red chili powder.","You could use white vinegar or coconut vinegar.","Any left over paste could be stored in the fridge for future use.","Cinnamon could be avoided as it''s a strong spice used generally for meat or chicken."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uwxusv1487344500.jpg', 'themealdb'),
('Beef Brisket Pot Roast', ARRAY['united_states', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 27, 115, 142, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef Brisket","measure":"4-5 pound"},{"name":"Salt","measure":"Dash"},{"name":"Onion","measure":"3"},{"name":"Garlic","measure":"5 cloves"},{"name":"Thyme","measure":"1 Sprig"},{"name":"Rosemary","measure":"1 sprig"},{"name":"Bay Leaves","measure":"4"},{"name":"beef stock","measure":"2 cups"},{"name":"Carrots","measure":"3 Large"},{"name":"Mustard","measure":"1 Tbsp"},{"name":"Potatoes","measure":"4 Mashed"}]'::jsonb, '["Prepare the brisket for cooking: On one side of the brisket there should be a layer of fat, which you want. If there are any large chunks of fat, cut them off and discard them. Large pieces of fat will not be able to render out completely.","Using a sharp knife, score the fat in parallel lines, about 3/4-inch apart. Slice through the fat, not the beef. Repeat in the opposite direction to make a cross-hatch pattern.","Salt the brisket well and let it sit at room temperature for 30 minutes.","Sear the brisket: You''ll need an oven-proof, thick-bottomed pot with a cover, or Dutch oven, that is just wide enough to hold the brisket roast with a little room for the onions.","Pat the brisket dry and place it, fatty side down, into the pot and place it on medium high heat. Cook for 5-8 minutes, lightly sizzling, until the fat side is nicely browned. (If the roast seems to be cooking too fast, turn the heat down to medium. You want a steady sizzle, not a raging sear.)","Turn the brisket over and cook for a few minutes more to brown the other side.","Sauté the onions and garlic: When the brisket has browned, remove it from the pot and set aside. There should be a couple tablespoons of fat rendered in the pot, if not, add some olive oil.","Add the chopped onions and increase the heat to high. Sprinkle a little salt on the onions. Sauté, stirring often, until the onions are lightly browned, 5-8 minutes. Stir in the garlic and cook 1-2 more minutes.","Return brisket to pot, add herbs, stock, bring to simmer, cover, cook in oven: Preheat the oven to 300°F. Use kitchen twine to tie together the bay leaves, rosemary and thyme.","Move the onions and garlic to the sides of the pot and nestle the brisket inside. Add the beef stock and the tied-up herbs. Bring the stock to a boil on the stovetop.","Cover the pot, place the pot in the 300°F oven and cook for 3 hours. Carefully flip the brisket every hour so it cooks evenly.","Add carrots, continue to cook: After 3 hours, add the carrots. Cover the pot and cook for 1 hour more, or until the carrots are cooked through and the brisket is falling-apart tender.","Remove brisket to cutting board, tent with foil: When the brisket is falling-apart tender, take the pot out of the oven and remove the brisket to a cutting board. Cover it with foil. Pull out and discard the herbs.","Make sauce (optional): At this point you have two options. You can serve as is, or you can make a sauce with the drippings and some of the onions. If you serve as is, skip this step.","To make a sauce, remove the carrots and half of the onions, set aside and cover them with foil. Pour the ingredients that are remaining into the pot into a blender, and purée until smooth. If you want, add 1 tablespoon of mustard to the mix. Put into a small pot and keep warm.","Slice the meat across the grain: Notice the lines of the muscle fibers of the roast. This is the \"grain\" of the meat. Slice the meat perpendicular to these lines, or across the grain (cutting this way further tenderizes the meat), in 1/4-inch to 1/2-inch slices.","Serve with the onions, carrots and gravy. Serve with mashed, roasted or boiled potatoes, egg noodles or polenta."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ursuup1487348423.jpg', 'themealdb'),
('French Lentils With Garlic and Thyme', ARRAY['france', 'miscellaneous']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 23, 30, 53, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 4, '[{"name":"Olive Oil","measure":"3 tablespoons"},{"name":"Onion","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Carrots","measure":"1"},{"name":"French Lentils","measure":"2 1/4 cups"},{"name":"Thyme","measure":"1 teaspoon"},{"name":"Bay Leaf","measure":"3"},{"name":"Salt","measure":"1 tablespoon"},{"name":"Celery","measure":"2 sticks"}]'::jsonb, '["Place a large saucepan over medium heat and add oil. When hot, add chopped vegetables and sauté until softened, 5 to 10 minutes.","Add 6 cups water, lentils, thyme, bay leaves and salt. Bring to a boil, then reduce to a fast simmer.","Simmer lentils until they are tender and have absorbed most of the water, 20 to 25 minutes. If necessary, drain any excess water after lentils have cooked. Serve immediately, or allow them to cool and reheat later.","For a fuller taste, use some chicken stock and reduce the water by the same amount."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vwwspt1487394060.jpg', 'themealdb'),
('Roasted Eggplant With Tahini, Pine Nuts, and Lentils', ARRAY['united_states', 'vegetarian']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 35, 25, 60, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 6, '[{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Carrots","measure":"2 small cut into chunks"},{"name":"Celery","measure":"2 small stalks"},{"name":"Onion","measure":"1 medium finely diced"},{"name":"Garlic","measure":"6 medium cloves sliced"},{"name":"Brown Lentils","measure":"12 ounces (340g)"},{"name":"Bay Leaves","measure":"2"},{"name":"Water","measure":"4 cups"},{"name":"Salt","measure":"Pinch"},{"name":"Apple Cider Vinegar","measure":"2 teaspoons (10ml)"},{"name":"Pepper","measure":"Pinch"},{"name":"Egg Plants","measure":"2 large"},{"name":"Rosemary","measure":"4 sprigs"},{"name":"Pine nuts","measure":"1/4 cup"},{"name":"Parsley","measure":"2 tablespoons"}]'::jsonb, '["For the Lentils: Adjust oven rack to center position and preheat oven to 450°F to prepare for roasting eggplant. Meanwhile, heat 2 tablespoons olive oil in a medium saucepan over medium heat until shimmering. Add carrots, celery, and onion and cook, stirring, until softened but not browned, about 4 minutes. Add garlic and cook, stirring, until fragrant, about 30 seconds. Add lentils, bay leaves, stock or water, and a pinch of salt. Bring to a simmer, cover with the lid partially ajar, and cook until lentils are tender, about 30 minutes. (Top up with water if lentils are at any point not fully submerged.) Remove lid, stir in vinegar, and reduce until lentils are moist but not soupy. Season to taste with salt and pepper, cover, and keep warm until ready to serve.","For the Eggplant: While lentils cook, cut each eggplant in half. Score flesh with the tip of a paring knife in a cross-hatch pattern at 1-inch intervals. Transfer to a foil-lined rimmed baking sheet, cut side up, and brush each eggplant half with 1 tablespoon oil, letting each brushstroke be fully absorbed before brushing with more. Season with salt and pepper. Place a rosemary sprig on top of each one. Transfer to oven and roast until completely tender and well charred, 25 to 35 minutes. Remove from oven and discard rosemary.","To Serve: Heat 2 tablespoons olive oil and pine nuts in a medium skillet set over medium heat. Cook, tossing nuts frequently, until golden brown and aromatic, about 4 minutes. Transfer to a bowl to halt cooking. Stir half of parsley and rosemary into lentils and transfer to a serving platter. Arrange eggplant halves on top. Spread a few tablespoons of tahini sauce over each eggplant half and sprinkle with pine nuts. Sprinkle with remaining parsley and rosemary, drizzle with additional olive oil, and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ysqrus1487425681.jpg', 'themealdb'),
('Katsu Chicken curry', ARRAY['japanese', 'chicken']::text[], ARRAY['dairy_free']::text[], 37, 45, 82, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"chicken breast","measure":"4 pounded to 1cm thickness"},{"name":"plain flour","measure":"2 tablespoons"},{"name":"egg","measure":"1 beaten"},{"name":"breadcrumbs","measure":"100g fine"},{"name":"vegetable oil","measure":"230ml frying"},{"name":"sunflower oil","measure":"2 tablespoons"},{"name":"onions","measure":"2 sliced"},{"name":"garlic","measure":"5 chopped cloves"},{"name":"carrot","measure":"2 sliced"},{"name":"plain flour","measure":"2 tablespoons"},{"name":"curry powder","measure":"4 teaspoons"},{"name":"chicken stock","measure":"600ml"},{"name":"honey","measure":"2 teaspoons"},{"name":"soy sauce","measure":"4 teaspoons"},{"name":"bay leaf","measure":"1"},{"name":"garam masala","measure":"1 teaspoon"}]'::jsonb, '["Prep:15min  ›  Cook:30min  ›  Ready in:45min","For the curry sauce: Heat oil in medium non-stick saucepan, add onion and garlic and cook until softened. Stir in carrots and cook over low heat for 10 to 12 minutes.","Add flour and curry powder; cook for 1 minute. Gradually stir in stock until combined; add honey, soy sauce and bay leaf. Slowly bring to the boil.","Turn down heat and simmer for 20 minutes or until sauce thickens but is still of pouring consistency. Stir in garam masala. Pour the curry sauce through a sieve; return to saucepan and keep on low heat until ready to serve.","For the chicken: Season both sides of chicken breasts with salt and pepper. Place flour, egg and breadcrumbs in separate bowls and arrange in a row. Coat the chicken breasts in flour, then dip them into the egg, then coat in breadcrumbs, making sure you cover both sides.","Heat oil in large frying pan over medium-high heat. Place chicken into hot oil and cook until golden brown, about 3 or 4 minutes each side. Once cooked, place on kitchen paper to absorb excess oil.","Pour curry sauce over chicken, serve with white rice and enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/vwrpps1503068729.jpg', 'themealdb'),
('Salmon Prawn Risotto', ARRAY['italian', 'seafood']::text[], ARRAY['pescatarian', 'gluten_free']::text[], 27, 45, 72, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"butter","measure":"50g/2oz"},{"name":"onion","measure":"1 finely chopped"},{"name":"rice","measure":"150g"},{"name":"white wine","measure":"125ml"},{"name":"vegetable stock","measure":"1 litre hot"},{"name":"lemon","measure":"The juice and zest of one"},{"name":"King Prawns","measure":"240g large"},{"name":"salmon","measure":"150g"},{"name":"asparagus","measure":"100g tips blanched briefly in boiling water"},{"name":"black pepper","measure":"ground"},{"name":"Parmesan","measure":"50g shavings"}]'::jsonb, '["Melt the butter in a thick-based pan and gently cook the onion without colour until it is soft.","Add the rice and stir to coat all the grains in the butter","Add the wine and cook gently stirring until it is absorbed","Gradually add the hot stock, stirring until each addition is absorbed. Keep stirring until the rice is tender","Season with the lemon juice and zest, and pepper to taste. (there will probably be sufficient saltiness from the salmon to not need to add salt) Stir gently to heat through","Serve scattered with the Parmesan and seasonal vegetables.","Grill the salmon and gently place onto the risotto with the prawns and asparagus"]'::jsonb, 'https://www.themealdb.com/images/media/meals/xxrxux1503070723.jpg', 'themealdb'),
('Beef Sunday Roast', ARRAY['british', 'beef']::text[], ARRAY[]::text[], 21, 60, 81, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef","measure":"8 slices"},{"name":"Broccoli","measure":"12 florets"},{"name":"Potatoes","measure":"1 Packet"},{"name":"Carrots","measure":"1 Packet"},{"name":"plain flour","measure":"140g"},{"name":"Eggs","measure":"4"},{"name":"milk","measure":"200ml"},{"name":"sunflower oil","measure":"drizzle (for cooking)"}]'::jsonb, '["Cook the Broccoli and Carrots in a pan of boiling water until tender.","Roast the Beef and Potatoes in the oven for 45mins, the potatoes may need to be checked regularly to not overcook.","To make the Yorkshire puddings:","Heat oven to 230C/fan 210C/gas 8. Drizzle a little sunflower oil evenly into 2 x 4-hole Yorkshire pudding tins or a 12-hole non-stick muffin tin and place in the oven to heat through","To make the batter, tip 140g plain flour into a bowl and beat in four eggs until smooth. Gradually add 200ml milk and carry on beating until the mix is completely lump-free. Season with salt and pepper. Pour the batter into a jug, then remove the hot tins from the oven. Carefully and evenly pour the batter into the holes. Place the tins back in the oven and leave undisturbed for 20-25 mins until the puddings have puffed up and browned. Serve immediately.","Plate up and add the Gravy as desired."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ssrrrs1503664277.jpg', 'themealdb'),
('Crock Pot Chicken Baked Tacos', ARRAY['mexican', 'chicken']::text[], ARRAY['gluten_free']::text[], 33, 75, 108, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Chicken Breasts","measure":"4 - 6"},{"name":"Vinaigrette Dressing","measure":"1 bottle"},{"name":"Cumin","measure":"1½ tablespoon"},{"name":"Smoked Paprika","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 teaspoon"},{"name":"Refried Beans","measure":"1 can"},{"name":"Hard Taco Shells","measure":"12"},{"name":"Shredded Mexican Cheese","measure":"2 cups"},{"name":"Grape Tomatoes","measure":"Halved"},{"name":"Jalapeno","measure":"Sliced and Seeded"},{"name":"Avocado","measure":"Peeled and Sliced"},{"name":"Green Salsa","measure":"2 tablespoons"},{"name":"Sour Cream","measure":"3 tablespoons"},{"name":"Milk","measure":"1 tablespoon"}]'::jsonb, '["Put the uncooked chicken breasts in the crock pot. Pour the full bottle of salad dressing over the chicken. Sprinkle the rest of the ingredients over the top and mix them in a bit with a spoon.","Cover your crock pot with the lid and cook on high for 4 hours.","Remove all the chicken breasts from the crock pot and let cool.","Shred the chicken breasts and move to a glass bowl.","Pour most of the liquid over the shredded chicken.","FOR THE TACOS:","Make the guacamole sauce by mixing the avocado and green salsa together. Pour the guacamole mixture through a strainer until smooth and transfer to a squeeze bottle. Cut the tip off the lid of the squeeze bottle to make the opening more wide if needed.","Make the sour cream sauce by mixing the sour cream and milk together until you get a more liquid sour cream sauce. Transfer to a squeeze bottle.","In a 9x 13 glass baking dish, fill all 12+ tacos with a layer of refried beans, cooked chicken and shredded cheese.","Bake at 450 for 10-15 minutes just until the cheese is melted and bubbling.","Out of the oven top all the tacos with the sliced grape tomaotes, jalapeno and cilantro.","Finish with a drizzle of guacamole and sour cream.","Enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/ypxvwv1505333929.jpg', 'themealdb'),
('Chicken Karaage', ARRAY['japanese', 'chicken']::text[], ARRAY['dairy_free']::text[], 23, 30, 53, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Chicken","measure":"450 grams Boneless skin"},{"name":"Ginger","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 clove"},{"name":"Soy sauce","measure":"2 tablespoons"},{"name":"Sake","measure":"1 tablespoon"},{"name":"Granulated sugar","measure":"2 teaspoon"},{"name":"Potato starch","measure":"1/3 cup"},{"name":"Vegetable oil","measure":"1/3 cup"},{"name":"Lemon","measure":"1/3 cup"}]'::jsonb, '["Add the ginger, garlic, soy sauce, sake and sugar to a bowl and whisk to combine. Add the chicken, then stir to coat evenly. Cover and refrigerate for at least 1 hour.","Add 1 inch of vegetable oil to a heavy bottomed pot and heat until the oil reaches 360 degrees F. Line a wire rack with 2 sheets of paper towels and get your tongs out. Put the potato starch in a bowl","Add a handful of chicken to the potato starch and toss to coat each piece evenly.","Fry the karaage in batches until the exterior is a medium brown and the chicken is cooked through. Transfer the fried chicken to the paper towel lined rack. If you want the karaage to stay crispy longer, you can fry the chicken a second time, until it''s a darker color after it''s cooled off once. Serve with lemon wedges."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tyywsw1505930373.jpg', 'themealdb'),
('Venetian Duck Ragu', ARRAY['italian', 'pasta']::text[], ARRAY[]::text[], 35, 25, 60, 'hard', '{"calories":600,"protein_g":22,"carbs_g":78,"fat_g":20}'::jsonb, 6, '[{"name":"Olive Oil","measure":"1 tbls"},{"name":"Duck Legs","measure":"4"},{"name":"Onions","measure":"2 finely chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Cinnamon","measure":"2 tsp ground"},{"name":"Plain Flour","measure":"2 tsp"},{"name":"Red Wine","measure":"250ml"},{"name":"Chopped Tomatoes","measure":"800g"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Rosemary","measure":"3 sprigs"},{"name":"Bay Leaves","measure":"2"},{"name":"Sugar","measure":"1 tsp"},{"name":"Milk","measure":"2 tbs"},{"name":"Paccheri Pasta","measure":"600g"},{"name":"Parmesan Cheese","measure":"Grated"}]'::jsonb, '["Heat the oil in a large pan. Add the duck legs and brown on all sides for about 10 mins. Remove to a plate and set aside. Add the onions to the pan and cook for 5 mins until softened. Add the garlic and cook for a further 1 min, then stir in the cinnamon and flour and cook for a further min. Return the duck to the pan, add the wine, tomatoes, stock, herbs, sugar and seasoning. Bring to a simmer, then lower the heat, cover with a lid and cook for 2 hrs, stirring every now and then.","Carefully lift the duck legs out of the sauce and place on a plate – they will be very tender so try not to lose any of the meat. Pull off and discard the fat, then shred the meat with 2 forks and discard the bones. Add the meat back to the sauce with the milk and simmer, uncovered, for a further 10-15 mins while you cook the pasta.","Cook the pasta following pack instructions, then drain, reserving a cup of the pasta water, and add the pasta to the ragu. Stir to coat all the pasta in the sauce and cook for 1 min more, adding a splash of cooking liquid if it looks dry. Serve with grated Parmesan, if you like."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qvrwpt1511181864.jpg', 'themealdb'),
('Clam chowder', ARRAY['united_states', 'starter']::text[], ARRAY[]::text[], 27, 25, 52, 'medium', '{"calories":300,"protein_g":14,"carbs_g":28,"fat_g":14}'::jsonb, 4, '[{"name":"Clams","measure":"1½ kg"},{"name":"Butter","measure":"50g"},{"name":"Bacon","measure":"150g"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Thyme","measure":"sprigs of fresh"},{"name":"Bay Leaf","measure":"1"},{"name":"Plain Flour","measure":"1 tbls"},{"name":"Milk","measure":"150ml"},{"name":"Double Cream","measure":"150ml"},{"name":"Potatoes","measure":"2 medium"},{"name":"Parsley","measure":"Chopped"}]'::jsonb, '["Rinse the clams in several changes of cold water and drain well. Tip the clams into a large pan with 500ml of water. Cover, bring to the boil and simmer for 2 mins until the clams have just opened. Tip the contents of the pan into a colander over a bowl to catch the clam stock. When cool enough to handle, remove the clams from their shells – reserving a handful of empty shells for presentation if you want. Strain the clam stock into a jug, leaving any grit in the bottom of the bowl. You should have around 800ml stock.","Heat the butter in the same pan and sizzle the bacon for 3-4 mins until it starts to brown. Stir in the onion, thyme and bay and cook everything gently for 10 mins until the onion is soft and golden. Scatter over the flour and stir in to make a sandy paste, cook for 2 mins more, then gradually stir in the clam stock then the milk and the cream.","Throw in the potatoes, bring everything to a simmer and leave to bubble away gently for 10 mins or until the potatoes are cooked. Use a fork to crush a few of the potato chunks against the side of the pan to help thicken – you still want lots of defined chunks though. Stir through the clam meat and the few clam shells, if you''ve gone down that route, and simmer for a minute to reheat. Season with plenty of black pepper and a little salt, if needed, then stir through the parsley just before ladling into bowls or hollowed-out crusty rolls."]'::jsonb, 'https://www.themealdb.com/images/media/meals/rvtvuw1511190488.jpg', 'themealdb'),
('Creamy Tomato Soup', ARRAY['british', 'starter']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 31, 25, 56, 'medium', '{"calories":300,"protein_g":14,"carbs_g":28,"fat_g":14}'::jsonb, 4, '[{"name":"Olive Oil","measure":"3 tbsp"},{"name":"Onions","measure":"2 chopped"},{"name":"Celery","measure":"2 sticks"},{"name":"Carrots","measure":"300g"},{"name":"Potatoes","measure":"500g"},{"name":"Bay Leaf","measure":"4"},{"name":"Tomato Puree","measure":"5 tblsp"},{"name":"Sugar","measure":"2 tblsp"},{"name":"White Vinegar","measure":"2 tblsp"},{"name":"Chopped Tomatoes","measure":"1½ kg"},{"name":"Passata","measure":"500g"},{"name":"Vegetable Stock Cube","measure":"3"},{"name":"Whole Milk","measure":"400ml"}]'::jsonb, '["Put the oil, onions, celery, carrots, potatoes and bay leaves in a big casserole dish, or two saucepans. Fry gently until the onions are softened – about 10-15 mins. Fill the kettle and boil it.","Stir in the tomato purée, sugar, vinegar, chopped tomatoes and passata, then crumble in the stock cubes. Add 1 litre boiling water and bring to a simmer. Cover and simmer for 15 mins until the potato is tender, then remove the bay leaves. Purée with a stick blender (or ladle into a blender in batches) until very smooth. Season to taste and add a pinch more sugar if it needs it. The soup can now be cooled and chilled for up to 2 days, or frozen for up to 3 months.","To serve, reheat the soup, stirring in the milk – try not to let it boil. Serve in small bowls with cheesy sausage rolls."]'::jsonb, 'https://www.themealdb.com/images/media/meals/stpuws1511191310.jpg', 'themealdb'),
('Broccoli & Stilton soup', ARRAY['british', 'starter']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 23, 30, 53, 'medium', '{"calories":300,"protein_g":14,"carbs_g":28,"fat_g":14}'::jsonb, 4, '[{"name":"Rapeseed Oil","measure":"2 tblsp"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Celery","measure":"1"},{"name":"Leek","measure":"1 sliced"},{"name":"Potatoes","measure":"1 medium"},{"name":"Butter","measure":"1 knob"},{"name":"Vegetable Stock","measure":"1 litre hot"},{"name":"Broccoli","measure":"1 Head chopped"},{"name":"Stilton Cheese","measure":"140g"}]'::jsonb, '["Heat the rapeseed oil in a large saucepan and then add the onions. Cook on a medium heat until soft. Add a splash of water if the onions start to catch.","Add the celery, leek, potato and a knob of butter. Stir until melted, then cover with a lid. Allow to sweat for 5 minutes. Remove the lid.","Pour in the stock and add any chunky bits of broccoli stalk. Cook for 10 – 15 minutes until all the vegetables are soft.","Add the rest of the broccoli and cook for a further 5 minutes. Carefully transfer to a blender and blitz until smooth. Stir in the stilton, allowing a few lumps to remain. Season with black pepper and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tvvxpv1511191952.jpg', 'themealdb'),
('Lamb Tagine', ARRAY['moroccan', 'lamb']::text[], ARRAY[]::text[], 35, 50, 85, 'hard', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 6, '[{"name":"Olive Oil","measure":"2 tblsp"},{"name":"Onion","measure":"1 finely sliced"},{"name":"Carrots","measure":"2 chopped"},{"name":"Lamb Leg","measure":"500g"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Cumin","measure":"½ tsp"},{"name":"Ginger","measure":"½ tsp"},{"name":"Saffron","measure":"¼ tsp"},{"name":"Cinnamon","measure":"1 tsp"},{"name":"Honey","measure":"1 tblsp"},{"name":"Apricot","measure":"100g"},{"name":"Vegetable Stock Cube","measure":"1"},{"name":"Butternut Squash","measure":"1 medium chopped"},{"name":"Couscous","measure":"Steamed"},{"name":"Parsley","measure":"Chopped"}]'::jsonb, '["Heat the olive oil in a heavy-based pan and add the onion and carrot. Cook for 3- 4 mins until softened.","Add the diced lamb and brown all over. Stir in the garlic and all the spices and cook for a few mins more or until the aromas are released.","Add the honey and apricots, crumble in the stock cube and pour over roughly 500ml boiling water or enough to cover the meat. Give it a good stir and bring to the boil. Turn down to a simmer, put the lid on and cook for 1 hour.","Remove the lid and cook for a further 30 mins, then stir in the squash. Cook for 20 – 30 mins more until the squash is soft and the lamb is tender. Serve alongside rice or couscous and sprinkle with parsley and pine nuts, if using."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yuwtuu1511295751.jpg', 'themealdb'),
('Lasagne', ARRAY['italian', 'pasta']::text[], ARRAY[]::text[], 35, 35, 70, 'hard', '{"calories":600,"protein_g":22,"carbs_g":78,"fat_g":20}'::jsonb, 6, '[{"name":"Olive Oil","measure":"1 tblsp"},{"name":"Bacon","measure":"2"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Celery","measure":"1 Stick"},{"name":"Carrots","measure":"1 medium"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Minced Beef","measure":"500g"},{"name":"Tomato Puree","measure":"1 tbls"},{"name":"Chopped Tomatoes","measure":"800g"},{"name":"Honey","measure":"1 tblsp"},{"name":"Lasagne Sheets","measure":"500g"},{"name":"Creme Fraiche","measure":"400ml"},{"name":"Mozzarella Balls","measure":"125g"},{"name":"Parmesan Cheese","measure":"50g"},{"name":"Basil Leaves","measure":"Topping"}]'::jsonb, '["Heat the oil in a large saucepan. Use kitchen scissors to snip the bacon into small pieces, or use a sharp knife to chop it on a chopping board. Add the bacon to the pan and cook for just a few mins until starting to turn golden. Add the onion, celery and carrot, and cook over a medium heat for 5 mins, stirring occasionally, until softened.","Add the garlic and cook for 1 min, then tip in the mince and cook, stirring and breaking it up with a wooden spoon, for about 6 mins until browned all over.","Stir in the tomato purée and cook for 1 min, mixing in well with the beef and vegetables. Tip in the chopped tomatoes. Fill each can half full with water to rinse out any tomatoes left in the can, and add to the pan. Add the honey and season to taste. Simmer for 20 mins.","Heat oven to 200C/180C fan/gas 6. To assemble the lasagne, ladle a little of the ragu sauce into the bottom of the roasting tin or casserole dish, spreading the sauce all over the base. Place 2 sheets of lasagne on top of the sauce overlapping to make it fit, then repeat with more sauce and another layer of pasta. Repeat with a further 2 layers of sauce and pasta, finishing with a layer of pasta.","Put the crème fraîche in a bowl and mix with 2 tbsp water to loosen it and make a smooth pourable sauce. Pour this over the top of the pasta, then top with the mozzarella. Sprinkle Parmesan over the top and bake for 25–30 mins until golden and bubbling. Serve scattered with basil, if you like."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wtsvxx1511296896.jpg', 'themealdb'),
('Pork Cassoulet', ARRAY['france', 'pork']::text[], ARRAY['dairy_free']::text[], 37, 45, 82, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"Goose Fat","measure":"4 tbsp"},{"name":"Pork","measure":"350g"},{"name":"Onion","measure":"1 large"},{"name":"Garlic","measure":"10"},{"name":"Carrots","measure":"1 thinly sliced"},{"name":"Fennel Seeds","measure":"1 tsp"},{"name":"Red Wine Vinegar","measure":"2 tblsp"},{"name":"Vegetable Stock","measure":"600ml"},{"name":"Tomato Puree","measure":"1 tblsp"},{"name":"Rosemary","measure":"2 sticks"},{"name":"Parsley","measure":"Handful"},{"name":"Haricot Beans","measure":"400g"},{"name":"Breadcrumbs","measure":"2 tblsp"},{"name":"Oil","measure":"drizzle"},{"name":"Bread","measure":"to serve"},{"name":"Broccoli","measure":"to serve"}]'::jsonb, '["Heat oven to 140C/120C fan/gas 1. Put a large ovenproof pan (with a tight-fitting lid) on a high heat. Add your fat and diced meat, cook for a few mins to seal the edges, giving it a quick stir to cook evenly. Reduce the heat to low, add the sliced onion, whole garlic cloves, carrot and fennel seeds, and cook gently to soften the veg for a few mins.","Pour over the red wine vinegar, scraping any meaty bits off the bottom of the pan. Add the stock, tomato purée, and half the rosemary and parsley. Bring to the boil and simmer for 10 mins, then season, cover with a lid and put into the oven for 2 hrs, removing the lid for the final hour of cooking. Stir occasionally and add the beans with 30 mins to go.","Remove the pan from the oven and heat the grill. Scatter the top with the remaining herbs and breadcrumbs, drizzle a little oil over the top, and return to the oven for 5-10 mins, until the breadcrumbs are golden. Serve with crusty bread and green veg."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wxuvuv1511299147.jpg', 'themealdb'),
('Bean & Sausage Hotpot', ARRAY['british', 'miscellaneous']::text[], ARRAY['gluten_free']::text[], 15, 20, 35, 'easy', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Sausages","measure":"8 large"},{"name":"Tomato Sauce","measure":"1 Jar"},{"name":"Butter Beans","measure":"1200g"},{"name":"Black Treacle","measure":"1 tbls"},{"name":"English Mustard","measure":"1 tsp"}]'::jsonb, '["In a large casserole, fry the sausages until brown all over – about 10 mins.","Add the tomato sauce, stirring well, then stir in the beans, treacle or sugar and mustard. Bring to the simmer, cover and cook for 30 mins. Great served with crusty bread or rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vxuyrx1511302687.jpg', 'themealdb'),
('Spinach & Ricotta Cannelloni', ARRAY['italian', 'vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 35, 25, 60, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 6, '[{"name":"Olive Oil","measure":"3 tbsp"},{"name":"Garlic","measure":"8 cloves chopped"},{"name":"Caster Sugar","measure":"3 tbsp"},{"name":"Red Wine Vinegar","measure":"2 tblsp"},{"name":"Chopped Tomatoes","measure":"3 400g Cans"},{"name":"Basil Leaves","measure":"Bunch"},{"name":"Mascarpone","measure":"2 tubs"},{"name":"Milk","measure":"3 tbsp"},{"name":"Parmesan","measure":"85g"},{"name":"Mozzarella","measure":"2 sliced"},{"name":"Spinach","measure":"1kg"},{"name":"Parmesan","measure":"100g"},{"name":"Ricotta","measure":"3 tubs"},{"name":"Nutmeg","measure":"pinch"},{"name":"Cannellini Beans","measure":"400g"}]'::jsonb, '["First make the tomato sauce. Heat the oil in a large pan and fry the garlic for 1 min. Add the sugar, vinegar, tomatoes and some seasoning and simmer for 20 mins, stirring occasionally, until thick. Add the basil and divide the sauce between 2 or more shallow ovenproof dishes (see Tips for freezing, below). Set aside. Make a sauce by beating the mascarpone with the milk until smooth, season, then set aside.","Put the spinach in a large colander and pour over a kettle of boiling water to wilt it (you may need to do this in batches). When cool enough to handle squeeze out the excess water. Roughly chop the spinach and mix in a large bowl with 100g Parmesan and ricotta. Season well with salt, pepper and the nutmeg.","Heat oven to 200C/180C fan/gas 6. Using a piping bag or plastic food bag with the corner snipped off, squeeze the filling into the cannelloni tubes. Lay the tubes, side by side, on top of the tomato sauce and spoon over the mascarpone sauce. Top with Parmesan and mozzarella. You can now freeze the cannelloni, uncooked, or you can cook it first and then freeze. Bake for 30-35 mins until golden and bubbling. Remove from oven and let stand for 5 mins before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wspuvp1511303478.jpg', 'themealdb'),
('Chicken Couscous', ARRAY['moroccan', 'chicken']::text[], ARRAY['dairy_free']::text[], 25, 20, 45, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Olive Oil","measure":"1 tbsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Chicken Breast","measure":"200g"},{"name":"Ginger","measure":"pinch"},{"name":"Harissa Spice","measure":"2 tblsp"},{"name":"Dried Apricots","measure":"10"},{"name":"Chickpeas","measure":"220g"},{"name":"Couscous","measure":"200g"},{"name":"Chicken Stock","measure":"200ml"},{"name":"Coriander","measure":"Handful"}]'::jsonb, '["Heat the olive oil in a large frying pan and cook the onion for 1-2 mins just until softened. Add the chicken and fry for 7-10 mins until cooked through and the onions have turned golden. Grate over the ginger, stir through the harissa to coat everything and cook for 1 min more.","Tip in the apricots, chickpeas and couscous, then pour over the stock and stir once. Cover with a lid or tightly cover the pan with foil and leave for about 5 mins until the couscous has soaked up all the stock and is soft. Fluff up the couscous with a fork and scatter over the coriander to serve. Serve with extra harissa, if you like."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qxytrx1511304021.jpg', 'themealdb'),
('Nutty Chicken Curry', ARRAY['india', 'chicken']::text[], ARRAY['gluten_free']::text[], 23, 20, 43, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Red Chilli","measure":"1 large"},{"name":"Ginger","measure":"0.5"},{"name":"Garlic","measure":"1 large"},{"name":"Coriander","measure":"Bunch"},{"name":"Sunflower Oil","measure":"1 tbsp"},{"name":"Chicken Breasts","measure":"4"},{"name":"Peanut Butter","measure":"5 tblsp"},{"name":"Chicken Stock","measure":"150ml"},{"name":"Greek Yogurt","measure":"200g"}]'::jsonb, '["Finely slice a quarter of the chilli, then put the rest in a food processor with the ginger, garlic, coriander stalks and one-third of the leaves. Whizz to a rough paste with a splash of water if needed.","Heat the oil in a frying pan, then quickly brown the chicken chunks for 1 min. Stir in the paste for another min, then add the peanut butter, stock and yogurt. When the sauce is gently bubbling, cook for 10 mins until the chicken is just cooked through and sauce thickened. Stir in most of the remaining coriander, then scatter the rest on top with the chilli, if using. Eat with rice or mashed sweet potato."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yxsurp1511304301.jpg', 'themealdb'),
('Pancakes', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian']::text[], 19, 35, 54, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Flour","measure":"100g"},{"name":"Eggs","measure":"2 large"},{"name":"Milk","measure":"300ml"},{"name":"Sunflower Oil","measure":"1 tbls"},{"name":"Sugar","measure":"to serve"},{"name":"Raspberries","measure":"to serve"},{"name":"Blueberries","measure":"to serve"}]'::jsonb, '["Put the flour, eggs, milk, 1 tbsp oil and a pinch of salt into a bowl or large jug, then whisk to a smooth batter. Set aside for 30 mins to rest if you have time, or start cooking straight away.","Set a medium frying pan or crêpe pan over a medium heat and carefully wipe it with some oiled kitchen paper. When hot, cook your pancakes for 1 min on each side until golden, keeping them warm in a low oven as you go.","Serve with lemon wedges and sugar, or your favourite filling. Once cold, you can layer the pancakes between baking parchment, then wrap in cling film and freeze for up to 2 months."]'::jsonb, 'https://www.themealdb.com/images/media/meals/rwuyqx1511383174.jpg', 'themealdb'),
('Pumpkin Pie', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian']::text[], 27, 40, 67, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Pumpkin","measure":"750g"},{"name":"Shortcrust Pastry","measure":"350g"},{"name":"Plain Flour","measure":"Dusting"},{"name":"Caster Sugar","measure":"140g"},{"name":"Salt","measure":"½ tsp"},{"name":"Nutmeg","measure":"½ tsp"},{"name":"Cinnamon","measure":"1 tsp"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Butter","measure":"25g"},{"name":"Milk","measure":"175g"},{"name":"Icing Sugar","measure":"1 tblsp"}]'::jsonb, '["Place the pumpkin in a large saucepan, cover with water and bring to the boil. Cover with a lid and simmer for 15 mins or until tender. Drain pumpkin; let cool.","Heat oven to 180C/160C fan/gas 4. Roll out the pastry on a lightly floured surface and use it to line a 22cm loose-bottomed tart tin. Chill for 15 mins. Line the pastry with baking parchment and baking beans, then bake for 15 mins. Remove the beans and paper, and cook for a further 10 mins until the base is pale golden and biscuity. Remove from the oven and allow to cool slightly.","Increase oven to 220C/200C fan/gas 7. Push the cooled pumpkin through a sieve into a large bowl. In a separate bowl, combine the sugar, salt, nutmeg and half the cinnamon. Mix in the beaten eggs, melted butter and milk, then add to the pumpkin purée and stir to combine. Pour into the tart shell and cook for 10 mins, then reduce the temperature to 180C/160C fan/gas 4. Continue to bake for 35-40 mins until the filling has just set.","Leave to cool, then remove the pie from the tin. Mix the remaining cinnamon with the icing sugar and dust over the pie. Serve chilled."]'::jsonb, 'https://www.themealdb.com/images/media/meals/usuqtp1511385394.jpg', 'themealdb'),
('Chocolate Raspberry Brownies', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian']::text[], 21, 30, 51, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Dark Chocolate","measure":"200g"},{"name":"Milk Chocolate","measure":"100g"},{"name":"Salted Butter","measure":"250g"},{"name":"Light Brown Soft Sugar","measure":"400g"},{"name":"Eggs","measure":"4 large"},{"name":"Plain Flour","measure":"140g"},{"name":"Cocoa","measure":"50g"},{"name":"Raspberries","measure":"200g"}]'::jsonb, '["Heat oven to 180C/160C fan/gas 4. Line a 20 x 30cm baking tray tin with baking parchment. Put the chocolate, butter and sugar in a pan and gently melt, stirring occasionally with a wooden spoon. Remove from the heat.","Stir the eggs, one by one, into the melted chocolate mixture. Sieve over the flour and cocoa, and stir in. Stir in half the raspberries, scrape into the tray, then scatter over the remaining raspberries. Bake on the middle shelf for 30 mins or, if you prefer a firmer texture, for 5 mins more. Cool before slicing into squares. Store in an airtight container for up to 3 days."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yypvst1511386427.jpg', 'themealdb'),
('Peach & Blueberry Grunt', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian']::text[], 27, 40, 67, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Corn Flour","measure":"1 tsp"},{"name":"Orange","measure":"Juice of 2"},{"name":"Orange","measure":"Zest of 1"},{"name":"Caster Sugar","measure":"2 tbs"},{"name":"Peaches","measure":"6"},{"name":"Blueberries","measure":"250g"},{"name":"Self-raising Flour","measure":"200g"},{"name":"Butter","measure":"50g"},{"name":"Muscovado Sugar","measure":"100g"},{"name":"Cinnamon","measure":"1 tsp"},{"name":"Milk","measure":"6 tblsp"}]'::jsonb, '["Heat oven to 190C/170C fan/gas 5. Butter a wide shallow ovenproof dish. Blend the cornflour with the orange zest and juice, and put in a large pan with the sugar. Halve, stone and slice the peaches and add to the pan. Bring slowly to the boil, stirring gently until the sauce is shiny and thickened, about 3-4 mins. Remove from the heat, stir in the blueberries and tip into the prepared dish.","Tip the flour into a mixing bowl and add the 50g butter. Rub the butter into the flour until it resembles fine breadcrumbs, then stir in half the sugar. Mix the remaining sugar with the cinnamon and set aside.","Add the milk to the dry ingredients and mix to a soft dough. Turn out onto a lightly floured surface and knead briefly. Roll out to an oblong roughly 16 x 24cm. Brush with melted butter and sprinkle evenly with the spicy sugar. Roll up from one long side and cut into 12 slices. Arrange around the top of the dish, leaving the centre uncovered.","Bake for 20-25 mins, until the topping is crisp and golden. Serve warm."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ssxvup1511387476.jpg', 'themealdb'),
('Mushroom & Chestnut Rotolo', ARRAY['british', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 29, 40, 69, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Mushrooms","measure":"30g"},{"name":"Chestnuts","measure":"240g"},{"name":"Challots","measure":"3"},{"name":"Garlic","measure":"3 cloves"},{"name":"Rosemary","measure":"3 sprigs"},{"name":"Wild Mushrooms","measure":"500g"},{"name":"Soy Sauce","measure":"2 tblsp"},{"name":"White Wine","measure":"125ml"},{"name":"Lasagne Sheets","measure":"350g"},{"name":"Breadcrumbs","measure":"4 tbsp"},{"name":"Sage","measure":"1/2 handful"},{"name":"Truffle Oil","measure":"to serve"}]'::jsonb, '["Soak the dried mushrooms in 350ml boiling water and set aside until needed. Blitz ¾ of the chestnuts with 150ml water until creamy. Roughly chop the remaining chestnuts.","Heat 2 tbsp olive oil in a large non-stick frying pan. Fry the shallots with a pinch of salt until softened, then add the garlic, chopped chestnuts and rosemary, and fry for 2 mins more. Add the wild mushrooms, 2 tbsp oil and some seasoning. Cook for 3 mins until they begin to soften. Drain and roughly chop the dried mushrooms (reserve the soaking liquid), then add those too, along with the soy sauce, and fry for 2 mins more.","Whisk the wine, reserved mushroom liquid and chestnut cream together to create a sauce. Season, then add half to the mushroom mixture in the pan and cook for 1 min until the sauce becomes glossy. Remove and discard the rosemary sprigs, then set the mixture aside.","Heat oven to 180C/160C fan/gas 4. Bring a large pan of salted water to the boil and get a large bowl of ice water ready. Drop the lasagne sheets into the boiling water for 2 mins or until pliable and a little cooked, then immediately plunge them into the cold water. Using your fingers, carefully separate the sheets and transfer to a clean tea towel. Spread a good spoonful of the sauce on the bottom two thirds of each sheet, then, rolling away from yourself, roll up the shorter ends. Cut each roll in half, then position the rolls of pasta cut-side up in a pie dish that you are happy to serve from at the table. If you have any mushroom sauce remaining after you’ve rolled up all the sheets, simply push it into some of the exposed rolls of pasta.","Pour the rest of the sauce over the top of the pasta, then bake for 10 mins or until the pasta no longer has any resistance when tested with a skewer.","Meanwhile, put the breadcrumbs, the last 2 tbsp olive oil, sage leaves and some seasoning in a bowl, and toss everything together. Scatter the rotolo with the crumbs and sage, then bake for another 10 mins, until the top is golden and the sage leaves are crispy. Leave to cool for 10 mins to allow the pasta to absorb the sauce, then drizzle with a little truffle oil, if you like, before taking your dish to the table."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ssyqwr1511451678.jpg', 'themealdb'),
('Matar Paneer', ARRAY['india', 'vegetarian']::text[], ARRAY['vegetarian']::text[], 29, 20, 49, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Sunflower Oil","measure":"1 tbls"},{"name":"Paneer","measure":"225g"},{"name":"Ginger","measure":"2"},{"name":"Cumin","measure":"1 tsp"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Coriander","measure":"1 tsp"},{"name":"Green Chilli","measure":"1"},{"name":"Tomato","measure":"4 large"},{"name":"Peas","measure":"150g"},{"name":"Garam Masala","measure":"1 tsp"},{"name":"Coriander","measure":"Small bunch"},{"name":"Naan Bread","measure":"to serve"}]'::jsonb, '["Heat the oil in a frying pan over high heat until it’s shimmering hot. Add the paneer, then turn the heat down a little. Fry until it starts to brown at the edges, then turn it over and brown on each side – the paneer will brown faster than you think, so don’t walk away. Remove the paneer from the pan and drain on kitchen paper.","Put the ginger, cumin, turmeric, ground coriander and chilli in the pan, and fry everything for 1 min. Add the tomatoes, mashing them with the back of a spoon and simmer everything for 5 mins until the sauce smells fragrant. Add a splash of water if it’s too thick. Season well. Add the peas and simmer for a further 2 mins, then stir in the paneer and sprinkle over the garam masala. Divide between two bowls, top with coriander leaves and serve with naan bread, roti or rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xxpqsy1511452222.jpg', 'themealdb'),
('Squash linguine', ARRAY['italian', 'vegetarian']::text[], ARRAY['vegetarian']::text[], 15, 20, 35, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 2, '[{"name":"Butternut Squash","measure":"350g"},{"name":"Garlic","measure":"3 parts"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Linguine Pasta","measure":"350g"},{"name":"Sage","measure":"Small bunch"}]'::jsonb, '["Heat oven to 200C/180C fan/gas 6. Put the squash and garlic on a baking tray and drizzle with the olive oil. Roast for 35-40 mins until soft. Season.","Cook the pasta according to pack instructions. Drain, reserving the water. Use a stick blender to whizz the squash with 400ml cooking water. Heat some oil in a frying pan, fry the sage until crisp, then drain on kitchen paper. Tip the pasta and sauce into the pan and warm through. Scatter with sage."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wxswxy1511452625.jpg', 'themealdb'),
('Kidney Bean Curry', ARRAY['india', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 27, 25, 52, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Vegetable Oil","measure":"1 tbls"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Ginger","measure":"1 part"},{"name":"Coriander","measure":"1 Packet"},{"name":"Cumin","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Garam Masala","measure":"2 tsp"},{"name":"Chopped Tomatoes","measure":"400g"},{"name":"Kidney Beans","measure":"400g"},{"name":"Basmati Rice","measure":"to serve"}]'::jsonb, '["Heat the oil in a large frying pan over a low-medium heat. Add the onion and a pinch of salt and cook slowly, stirring occasionally, until softened and just starting to colour. Add the garlic, ginger and coriander stalks and cook for a further 2 mins, until fragrant.","Add the spices to the pan and cook for another 1 min, by which point everything should smell aromatic. Tip in the chopped tomatoes and kidney beans in their water, then bring to the boil.","Turn down the heat and simmer for 15 mins until the curry is nice and thick. Season to taste, then serve with the basmati rice and the coriander leaves."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sywrsu1511463066.jpg', 'themealdb'),
('Yaki Udon', ARRAY['japanese', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 25, 20, 45, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Udon Noodles","measure":"250g"},{"name":"Sesame Seed Oil","measure":"2 tbs"},{"name":"Onion","measure":"1 sliced"},{"name":"Cabbage","measure":"0.25"},{"name":"Shiitake Mushrooms","measure":"10"},{"name":"Spring Onions","measure":"4"},{"name":"Mirin","measure":"4 tbsp"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Caster Sugar","measure":"1 tblsp"},{"name":"Worcestershire Sauce","measure":"1 tblsp"}]'::jsonb, '["Boil some water in a large saucepan. Add 250ml cold water and the udon noodles. (As they are so thick, adding cold water helps them to cook a little bit slower so the middle cooks through). If using frozen or fresh noodles, cook for 2 mins or until al dente; dried will take longer, about 5-6 mins. Drain and leave in the colander.","Heat 1 tbsp of the oil, add the onion and cabbage and sauté for 5 mins until softened. Add the mushrooms and some spring onions, and sauté for 1 more min. Pour in the remaining sesame oil and the noodles. If using cold noodles, let them heat through before adding the ingredients for the sauce – otherwise tip in straight away and keep stir-frying until sticky and piping hot. Sprinkle with the remaining spring onions."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wrustq1511475474.jpg', 'themealdb'),
('Beef Dumpling Stew', ARRAY['british', 'beef']::text[], ARRAY[]::text[], 43, 85, 128, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Butter","measure":"25g"},{"name":"Beef","measure":"750g"},{"name":"Plain Flour","measure":"2 tblsp"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Onions","measure":"175g"},{"name":"Celery","measure":"150g"},{"name":"Carrots","measure":"150g"},{"name":"Leek","measure":"2 chopped"},{"name":"Swede","measure":"200g"},{"name":"Red Wine","measure":"150ml"},{"name":"Beef Stock","measure":"500g"},{"name":"Bay Leaf","measure":"2"},{"name":"Thyme","measure":"3 tbs"},{"name":"Parsley","measure":"3 tblsp chopped"},{"name":"Plain Flour","measure":"125g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Suet","measure":"60g"},{"name":"Water","measure":"Splash"}]'::jsonb, '["Preheat the oven to 180C/350F/Gas 4.","For the beef stew, heat the oil and butter in an ovenproof casserole and fry the beef until browned on all sides.","Sprinkle over the flour and cook for a further 2-3 minutes.","Add the garlic and all the vegetables and fry for 1-2 minutes.","Stir in the wine, stock and herbs, then add the Worcestershire sauce and balsamic vinegar, to taste. Season with salt and freshly ground black pepper.","Cover with a lid, transfer to the oven and cook for about two hours, or until the meat is tender.","For the dumplings, sift the flour, baking powder and salt into a bowl.","Add the suet and enough water to form a thick dough.","With floured hands, roll spoonfuls of the dough into small balls.","After two hours, remove the lid from the stew and place the balls on top of the stew. Cover, return to the oven and cook for a further 20 minutes, or until the dumplings have swollen and are tender. (If you prefer your dumplings with a golden top, leave the lid off when returning to the oven.)","To serve, place a spoonful of mashed potato onto each of four serving plates and top with the stew and dumplings. Sprinkle with chopped parsley."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uyqrrv1511553350.jpg', 'themealdb'),
('Beef and Mustard Pie', ARRAY['british', 'beef']::text[], ARRAY[]::text[], 35, 95, 130, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef","measure":"1kg"},{"name":"Plain Flour","measure":"2 tbs"},{"name":"Rapeseed Oil","measure":"2 tbs"},{"name":"Red Wine","measure":"200ml"},{"name":"Beef Stock","measure":"400ml"},{"name":"Onion","measure":"1 finely sliced"},{"name":"Carrots","measure":"2 chopped"},{"name":"Thyme","measure":"3 sprigs"},{"name":"Mustard","measure":"2 tbs"},{"name":"Egg Yolks","measure":"2 free-range"},{"name":"Puff Pastry","measure":"400g"},{"name":"Green Beans","measure":"300g"},{"name":"Butter","measure":"25g"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"}]'::jsonb, '["Preheat the oven to 150C/300F/Gas 2.","Toss the beef and flour together in a bowl with some salt and black pepper.","Heat a large casserole until hot, add half of the rapeseed oil and enough of the beef to just cover the bottom of the casserole.","Fry until browned on each side, then remove and set aside. Repeat with the remaining oil and beef.","Return the beef to the pan, add the wine and cook until the volume of liquid has reduced by half, then add the stock, onion, carrots, thyme and mustard, and season well with salt and pepper.","Cover with a lid and place in the oven for two hours.","Remove from the oven, check the seasoning and set aside to cool. Remove the thyme.","When the beef is cool and you''re ready to assemble the pie, preheat the oven to 200C/400F/Gas 6.","Transfer the beef to a pie dish, brush the rim with the beaten egg yolks and lay the pastry over the top. Brush the top of the pastry with more beaten egg.","Trim the pastry so there is just enough excess to crimp the edges, then place in the oven and bake for 30 minutes, or until the pastry is golden-brown and cooked through.","For the green beans, bring a saucepan of salted water to the boil, add the beans and cook for 4-5 minutes, or until just tender.","Drain and toss with the butter, then season with black pepper.","To serve, place a large spoonful of pie onto each plate with some green beans alongside."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sytuqu1511553755.jpg', 'themealdb'),
('McSinghs Scotch pie', ARRAY['british', 'lamb']::text[], ARRAY[]::text[], 37, 80, 117, 'hard', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 6, '[{"name":"Cumin","measure":"2 tsp"},{"name":"Rapeseed Oil","measure":"1 tbs"},{"name":"Red Onions","measure":"2 finely chopped"},{"name":"Garlic Clove","measure":"6"},{"name":"Green Chilli","measure":"3 finely chopped"},{"name":"Red Pepper","measure":"1 finely chopped"},{"name":"Nutmeg","measure":"1 tsp"},{"name":"Coriander","measure":"2 tsp"},{"name":"Lamb Mince","measure":"1kg"},{"name":"Pepper","measure":"1 tsp"},{"name":"Coriander","measure":"3 tbs"},{"name":"Plain Flour","measure":"340g"},{"name":"Salt","measure":"½ tsp"},{"name":"Milk","measure":"90 ml"},{"name":"Lard","measure":"150g"},{"name":"Egg Yolks","measure":"Beaten"}]'::jsonb, '["Heat a large frying pan and toast the cumin seeds for a few minutes, then set aside. Heat the oil in the same pan and fry the onion, garlic, chilli, pepper and a good pinch of salt for around eight minutes, until there is no moisture left. Remove from the heat, stir in the toasted cumin seeds, ground mace (or nutmeg) and ground coriander. Leave to cool.","In a large bowl mix together the minced lamb, white pepper, fresh coriander, and the cooled spiced onion mixture until combined. Set aside, covered, in the fridge.","Preheat the oven to 200C/400F/Gas 6 and generously grease a 20cm/8in diameter loose-bottomed or springform round cake tin with lard.","To make the pastry, sift the flour and salt in a large bowl and make a well in the centre.","Put the milk, lard and 90ml/3fl oz of water in a saucepan and heat gently. When the lard has melted, increase the heat and bring to the boil.","Pour the boiling liquid into the flour, and use a wooden spoon to combine until cool enough to handle. Bring together into a ball.","Dust a work surface with flour and, working quickly, knead the dough briefly – it will be soft and moist. Set aside a third of the pastry and roll the rest out on a well-floured surface. Line the pie dish with the pastry, pressing it right up the sides until it pokes just over the top of the tin.","Add the filling into the pastry-lined tin bit by bit. As you reach the top, form a slight peak. Roll out the reserved pastry and top the pie with it. Pinch the edges to seal and trim the excess. Poke a hole in the top of the pie and insert a small tube made from aluminium foil to allow steam to escape.","Brush the top of the pie with a little beaten egg yolk, and bake in the preheated oven for 30 minutes (put a tray on the shelf below to catch any drips). Then reduce the temperature to 160C/325F/Gas 3 and cook for a further 1¼ hours until golden-brown. Leave to cool completely before refrigerating for two hours, or overnight.","Run a knife around the edge of the pie, remove from the tin and serve with chutneys, salads or pickles."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vssrtx1511557680.jpg', 'themealdb'),
('Steak and Kidney Pie', ARRAY['british', 'beef']::text[], ARRAY['dairy_free']::text[], 29, 80, 109, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Puff Pastry","measure":"300g"},{"name":"Egg White","measure":"Beaten"},{"name":"Egg Yolks","measure":"Beaten"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Beef","measure":"70 ml"},{"name":"Lamb Kidney","measure":"200g"},{"name":"Onions","measure":"2 chopped"},{"name":"Plain Flour","measure":"30g"},{"name":"Beef Stock","measure":"85 ml"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Worcestershire Sauce","measure":"Dash"}]'::jsonb, '["Preheat the oven to 220C/425F/Gas 7","Heat the vegetable oil in a large frying pan, and brown the beef all over. (You may need to do this in batches.) Set aside, then brown the kidneys on both sides in the same pan. Add the onions and cook for 3-4 minutes.","Return the beef to the pan, sprinkle flour over and coat the meat and onions","Add the stock to the pan, stir well and bring to the boil.","Turn the heat down and simmer for 1½ hours without a lid. If the liquid evaporates too much, add more stock.","Remove from the heat. Add salt, pepper and Worcestershire sauce and allow to cool completely. Place the cooked meat mixture into a pie dish.","Roll out the pastry to 5mm/¼in thick and 5cm/2in larger than the dish you are using.","Using a rolling pin, lift the pastry and place it over the top of the pie dish. Trim and crimp the edges with your fingers and thumb.","Brush the surface with the beaten egg mixture and bake for 30-40 minutes until golden-brown and puffed.","Serve with creamy mash and steamed vegetables to soak up the gravy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qysyss1511558054.jpg', 'themealdb'),
('Lancashire hotpot', ARRAY['british', 'lamb']::text[], ARRAY[]::text[], 25, 45, 70, 'medium', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 4, '[{"name":"Butter","measure":"100g"},{"name":"Lamb","measure":"900g"},{"name":"Lamb Kidney","measure":"3"},{"name":"Onions","measure":"2 medium"},{"name":"Carrots","measure":"4 sliced"},{"name":"Plain Flour","measure":"25g"},{"name":"Worcestershire Sauce","measure":"2 tsp"},{"name":"Chicken Stock","measure":"500ml"},{"name":"Bay Leaves","measure":"2"},{"name":"Potatoes","measure":"900g"}]'::jsonb, '["Heat oven to 160C/fan 140C/gas 3. Heat some dripping or butter in a large shallow casserole dish, brown the lamb in batches, lift to a plate, then repeat with the kidneys.","Fry the onions and carrots in the pan with a little more dripping until golden. Sprinkle over the flour, allow to cook for a couple of mins, shake over the Worcestershire sauce, pour in the stock, then bring to the boil. Stir in the meat and bay leaves, then turn off the heat. Arrange the sliced potatoes on top of the meat, then drizzle with a little more dripping. Cover, then place in the oven for about 1½ hrs until the potatoes are cooked.","Remove the lid, brush the potatoes with a little more dripping, then turn the oven up to brown the potatoes, or finish under the grill for 5-8 mins until brown."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uttrxw1511637813.jpg', 'themealdb'),
('Bubble & Squeak', ARRAY['british', 'pork']::text[], ARRAY['gluten_free']::text[], 17, 40, 57, 'easy', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 2, '[{"name":"Butter","measure":"1 tbs"},{"name":"Bacon","measure":"4"},{"name":"Onion","measure":"1 finely sliced"},{"name":"Garlic Clove","measure":"1 chopped"},{"name":"Brussels Sprouts","measure":"20"},{"name":"Potatoes","measure":"400g"}]'::jsonb, '["Melt the fat in a non-stick pan, allow it to get nice and hot, then add the bacon. As it begins to brown, add the onion and garlic. Next, add the sliced sprouts or cabbage and let it colour slightly. All this will take 5-6 mins.","Next, add the potato. Work everything together in the pan and push it down so that the mixture covers the base of the pan – allow the mixture to catch slightly on the base of the pan before turning it over and doing the same again. It’s the bits of potato that catch in the pan that define the term ‘bubble and squeak’, so be brave and let the mixture colour. Cut into wedges and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xusqvw1511638311.jpg', 'themealdb'),
('Spotted Dick', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 23, 45, 68, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Self-raising Flour","measure":"250g"},{"name":"Salt","measure":"pinch"},{"name":"Suet","measure":"125g"},{"name":"Currants","measure":"175g"},{"name":"Caster Sugar","measure":"80g"},{"name":"Lemon","measure":"Zest of 1"},{"name":"Orange","measure":"Zest of 1"},{"name":"Milk","measure":"150ml"},{"name":"Custard","measure":"to serve"}]'::jsonb, '["Put the flour and salt in a bowl. Add the suet, currants, sugar, lemon and orange zest.","Pour in 150ml milk and mix to a firm but moist dough, adding the extra milk if necessary.","Shape into a fat roll about 20cm long. Place on a large rectangle of baking parchment. Wrap loosely to allow for the pudding to rise and tie the ends with string like a Christmas cracker.","Place a steamer over a large pan of boiling water, add the pudding to the steamer, cover and steam for 1 1/2 hours. Top up the pan with water from time to time.","Remove from the steamer and allow to cool slightly before unwrapping. Serve sliced with custard."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xqvyqr1511638875.jpg', 'themealdb'),
('Jam Roly-Poly', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 19, 40, 59, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Butter","measure":"50g"},{"name":"Self-raising Flour","measure":"250g"},{"name":"Vanilla","measure":"1 small"},{"name":"Suet","measure":"50g"},{"name":"Milk","measure":"150ml"},{"name":"Raspberry Jam","measure":"100g"},{"name":"Custard","measure":"to serve"}]'::jsonb, '["Put a deep roasting tin onto the bottom shelf of the oven, and make sure that there’s another shelf directly above it. Pull the roasting tin out on its shelf, fill two-thirds with boiling water from the kettle, then carefully slide it back in. Heat oven to 180C/160C fan/gas 4. Tear off a large sheet of foil and greaseproof paper (about 30 x 40cm). Sit the greaseproof on top of the foil and butter it.","Tip butter, flour and vanilla seeds into a food processor; pulse until the butter has disappeared. Tip into a mixing bowl. Stir through the suet, pour in the milk and work together with a cutlery knife until you get a sticky dough. You may need a drop more milk, depending on your flour.","Tip the dough out onto a floured surface, quickly pat together to smooth, then roll out to a square roughly 25 x 25cm. Spread the jam all over, leaving a gap along one edge, then roll up from the opposite edge. Pinch the jam-free edge into the dough where it meets, and pinch the ends roughly, too. Carefully lift onto the greased paper, join-side down (you might find a flat baking sheet helpful for this), loosely bring up the paper and foil around it, then scrunch together along the edges and ends to seal. The roly-poly will puff quite a bit during cooking so don’t wrap it tightly. Lift the parcel directly onto the rack above the tin and cook for 1 hr.","Let the pudding sit for 5 mins before unwrapping, then carefully open the foil and paper, and thickly slice to serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ysqupp1511640538.jpg', 'themealdb'),
('Treacle Tart', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 17, 95, 112, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Plain Flour","measure":"250g"},{"name":"Butter","measure":"135g"},{"name":"Golden Syrup","measure":"400g"},{"name":"Breadcrumbs","measure":"150g"},{"name":"Lemons","measure":"Zest of 2"},{"name":"Eggs","measure":"1 beaten"}]'::jsonb, '["First make the short crust pastry: measure the flour into a large bowl and rub in the butter with your fingertips until the mixture resembles fine breadcrumbs (alternatively, this can be done in a food processor). Add about three tablespoons of cold water and mix to a firm dough, wrap in cling film and chill in the fridge for about 20 minutes.","Preheat the oven to 200C/400F/Gas 6 and put a heavy baking tray in the oven to heat up. Grease a deep 18cm/7in loose-bottomed fluted flan tin with butter.","Remove about 150g/5½oz of pastry from the main ball and set aside for the lattice top.","Roll the rest of the pastry out thinly on a lightly floured work surface and line the prepared flan tin with the pastry.","Prick the base with a fork, to stop the base rising up during baking.","Place the reserved pastry for the lattice top on cling film and roll out thinly. Egg wash the pastry and set aside to chill in the fridge (the cling film makes it easier to move about). Do not cut into strips at this stage. Do not egg wash the strips once they are on the tart as it will drip into the treacle mixture.","To make the filling, heat the syrup gently in a large pan but do not boil.","Once melted, add the breadcrumbs, lemon juice and zest to the syrup. (You can add less lemon if you would prefer less citrus taste.) If the mixture looks runny, add a few more breadcrumbs.","Pour the syrup mixture into the lined tin and level the surface.","Remove the reserved pastry from the fridge and cut into long strips, 1cm/½in wide. Make sure they are all longer than the edges of the tart tin.","Egg wash the edge of the pastry in the tin, and start to make the woven laying lattice pattern over the mixture, leave the strips hanging over the edge of the tin.","Once the lattice is in place, use the tin edge to cut off the strips by pressing down with your hands, creating a neat finish.","Bake on the pre-heated baking tray in the hot oven for about 10 minutes until the pastry has started to colour, and then reduce the oven temperature to 180C/350F/Gas 4. If at this stage the lattice seems to be getting too dark brown, cover the tart with tin foil.","Bake for a further 25-30 minutes until the pastry is golden-brown and the filling set.","Remove the tart from the oven and leave to firm up in the tin. Serve warm or cold."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wprvrw1511641295.jpg', 'themealdb'),
('Apple & Blackberry Crumble', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 23, 35, 58, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Plain Flour","measure":"120g"},{"name":"Caster Sugar","measure":"60g"},{"name":"Butter","measure":"60g"},{"name":"Braeburn Apples","measure":"300g"},{"name":"Butter","measure":"30g"},{"name":"Demerara Sugar","measure":"30g"},{"name":"Blackberries","measure":"120g"},{"name":"Cinnamon","measure":"¼ teaspoon"},{"name":"Ice Cream","measure":"to serve"}]'::jsonb, '["Heat oven to 190C/170C fan/gas 5. Tip the flour and sugar into a large bowl. Add the butter, then rub into the flour using your fingertips to make a light breadcrumb texture. Do not overwork it or the crumble will become heavy. Sprinkle the mixture evenly over a baking sheet and bake for 15 mins or until lightly coloured.","Meanwhile, for the compote, peel, core and cut the apples into 2cm dice. Put the butter and sugar in a medium saucepan and melt together over a medium heat. Cook for 3 mins until the mixture turns to a light caramel. Stir in the apples and cook for 3 mins. Add the blackberries and cinnamon, and cook for 3 mins more. Cover, remove from the heat, then leave for 2-3 mins to continue cooking in the warmth of the pan.","To serve, spoon the warm fruit into an ovenproof gratin dish, top with the crumble mix, then reheat in the oven for 5-10 mins. Serve with vanilla ice cream."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xvsurr1511719182.jpg', 'themealdb'),
('Full English Breakfast', ARRAY['british', 'breakfast']::text[], ARRAY['dairy_free']::text[], 21, 55, 76, 'medium', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Sausages","measure":"4"},{"name":"Bacon","measure":"4"},{"name":"Mushrooms","measure":"4"},{"name":"Tomatoes","measure":"3"},{"name":"Black Pudding","measure":"2 sliced"},{"name":"Eggs","measure":"2"},{"name":"Bread","measure":"1 Slice"},{"name":"Baked Beans","measure":"100g"}]'::jsonb, '["Heat the flat grill plate over a low heat, on top of 2 rings/flames if it fits, and brush sparingly with light olive oil.","Cook the sausages first. Add the sausages to the hot grill plate/the coolest part if there is one and allow to cook slowly for about 15-20 minutes, turning occasionally, until golden. After the first 10 minutes, increase the heat to medium before beginning to cook the other ingredients. If you are struggling for space, completely cook the sausages and keep hot on a plate in the oven.","Snip a few small cuts into the fatty edge of the bacon. Place the bacon straight on to the grill plate and fry for 2-4 minutes each side or until your preferred crispiness is reached. Like the sausages, the cooked bacon can be kept hot on a plate in the oven.","For the mushrooms, brush away any dirt using a pastry brush and trim the stalk level with the mushroom top. Season with salt and pepper and drizzle over a little olive oil. Place stalk-side up on the grill plate and cook for 1-2 minutes before turning and cooking for a further 3-4 minutes. Avoid moving the mushrooms too much while cooking, as this releases the natural juices, making them soggy.","For the tomatoes, cut the tomatoes across the centre/or in half lengthways if using plum tomatoes , and with a small, sharp knife remove the green ''eye''. Season with salt and pepper and drizzle with a little olive oil. Place cut-side down on the grill plate and cook without moving for 2 minutes. Gently turn over and season again. Cook for a further 2-3 minutes until tender but still holding their shape.","For the black pudding, cut the black pudding into 3-4 slices and remove the skin. Place on the grill plate and cook for 1½-2 minutes each side until slightly crispy.","For ''proper'' fried bread it''s best to cook it in a separate pan. Ideally, use bread that is a couple of days old. Heat a frying pan to a medium heat and cover the base with oil. Add the bread and cook for 2-3 minutes each side until crispy and golden. If the pan becomes too dry, add a little more oil. For a richer flavour, add a knob of butter after you turn the slice.","For the fried eggs, break the egg straight into the pan with the fried bread and leave for 30 seconds. Add a good knob of butter and lightly splash/baste the egg with the butter when melted. Cook to your preferred stage, season and gently remove with a fish slice.","Once all the ingredients are cooked, serve on warm plates and enjoy straight away with a good squeeze of tomato ketchup or brown sauce."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sqrtwu1511721265.jpg', 'themealdb'),
('Dundee cake', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 60, 93, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Almonds","measure":"100g"},{"name":"Butter","measure":"180g"},{"name":"Muscovado Sugar","measure":"180g"},{"name":"Orange","measure":"Zest of 1"},{"name":"Apricot Jam","measure":"3 tbs"},{"name":"Plain Flour","measure":"225g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Eggs","measure":"3 Large"},{"name":"Ground Almonds","measure":"100g"},{"name":"Milk","measure":"2 tbs"},{"name":"Dried Fruit","measure":"500g"},{"name":"Glace Cherry","measure":"100g"},{"name":"Milk","measure":"1 tbs"},{"name":"Caster Sugar","measure":"2 tsp"}]'::jsonb, '["Put the almonds into a small bowl and pour over boiling water to just cover. Leave for 5 mins then drain in a sieve and leave to dry.","Preheat the oven to 180C/160 C fan/Gas Mark 4. Line a deep loose-based 20cm cake tin with baking parchment.","Put the butter in a large bowl and beat well until soft. Add the sugar and beat until light and fluffy. Stir in the orange zest and apricot jam.","Sieve together the flour and baking powder. Add the eggs to the creamed butter and sugar, a little at a time, beating well between each addition. If the mixture starts to curdle, stir in a little flour.","Add the remaining flour and ground almonds and mix well. Mix in the milk and then add the dried fruit and cherries and mix gently together.","Spoon the mixture into the prepared tin and spread level using the back of a spoon. Arrange the whole almonds close together in neat circles on the top of the cake. Bake in the oven for 45 mins.","Lower the oven temperature to 160C/140 C fan/Gas Mark 3 and cook for a further 60–80 minutes. Check the cake after 50 minutes by inserting a wooden or metal skewer into the cake. When it’s done it should have just a few crumbs attached. Check every 10 minutes - it’s important not to overcook this cake so the centre will be a little soft.","When cooked, remove the cake briefly from the oven, put the milk and sugar into a small pan and heat gently until the sugar has dissolved. Brush over the top of the cake and return the cake to the oven for 2-3 mins. Remove and allow the cake to cool in the tin. When quite cold remove from the tin and wrap in foil and keep for at least 2 days before cutting."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wxyvqq1511723401.jpg', 'themealdb'),
('Rock Cakes', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 21, 50, 71, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Self-raising Flour","measure":"225g"},{"name":"Caster Sugar","measure":"75g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Butter","measure":"125g"},{"name":"Dried Fruit","measure":"150g"},{"name":"Eggs","measure":"1"},{"name":"Milk","measure":"1 tbs"},{"name":"Vanilla Extract","measure":"2 tsp"}]'::jsonb, '["Preheat oven to 180C/350F/Gas 4 and line a baking tray with baking parchment.","Mix the flour, sugar and baking powder in a bowl and rub in the cubed butter until the mixture looks like breadcrumbs, then mix in the dried fruit.","In a clean bowl, beat the egg and milk together with the vanilla extract.","Add the egg mixture to the dry ingredients and stir with a spoon until the mixture just comes together as a thick, lumpy dough. Add a teaspoon more milk if you really need it to make the mixture stick together.","Place golfball-sized spoons of the mixture onto the prepared baking tray. Leave space between them as they will flatten and spread out to double their size during baking.","Bake for 15-20 minutes, until golden-brown. Remove from the oven, allow to cool for a couple of minutes then turn them out onto a wire rack to cool."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tqrrsq1511723764.jpg', 'themealdb'),
('French Onion Soup', ARRAY['france', 'side']::text[], ARRAY[]::text[], 25, 25, 50, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Butter","measure":"50g"},{"name":"Olive Oil","measure":"1 tbs"},{"name":"Onion","measure":"1 kg"},{"name":"Sugar","measure":"1 tsp"},{"name":"Garlic Clove","measure":"4 sliced"},{"name":"Plain Flour","measure":"2 tbs"},{"name":"Dry White Wine","measure":"250ml"},{"name":"Beef Stock","measure":"1L"},{"name":"Bread","measure":"4 sliced"},{"name":"Gruyère","measure":"140g"}]'::jsonb, '["Melt the butter with the oil in a large heavy-based pan. Add the onions and fry with the lid on for 10 mins until soft. Sprinkle in the sugar and cook for 20 mins more, stirring frequently, until caramelised. The onions should be really golden, full of flavour and soft when pinched between your fingers. Take care towards the end to ensure that they don’t burn.","Add the garlic for the final few mins of the onions’ cooking time, then sprinkle in the flour and stir well. Increase the heat and keep stirring as you gradually add the wine, followed by the hot stock. Cover and simmer for 15-20 mins.","To serve, turn on the grill, and toast the bread. Ladle the soup into heatproof bowls. Put a slice or two of toast on top of the bowls of soup, and pile on the cheese. Grill until melted. Alternatively, you can complete the toasts under the grill, then serve them on top."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xvrrux1511783685.jpg', 'themealdb'),
('Beef Bourguignon', ARRAY['france', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 35, 60, 95, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Goose Fat","measure":"3 tsp"},{"name":"Beef Shin","measure":"600g"},{"name":"Bacon","measure":"100g"},{"name":"Challots","measure":"350g"},{"name":"Chestnut Mushroom","measure":"250g"},{"name":"Garlic Clove","measure":"2 sliced"},{"name":"Bouquet Garni","measure":"1"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Red Wine","measure":"750 ml"},{"name":"Celeriac","measure":"600g"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Thyme","measure":"sprigs of fresh"},{"name":"Rosemary","measure":"sprigs of fresh"},{"name":"Bay Leaf","measure":"2"},{"name":"Cardamom","measure":"4"}]'::jsonb, '["Heat a large casserole pan and add 1 tbsp goose fat. Season the beef and fry until golden brown, about 3-5 mins, then turn over and fry the other side until the meat is browned all over, adding more fat if necessary. Do this in 2-3 batches, transferring the meat to a colander set over a bowl when browned.","In the same pan, fry the bacon, shallots or pearl onions, mushrooms, garlic and bouquet garni until lightly browned. Mix in the tomato purée and cook for a few mins, stirring into the mixture. This enriches the bourguignon and makes a great base for the stew. Then return the beef and any drained juices to the pan and stir through.","Pour over the wine and about 100ml water so the meat bobs up from the liquid, but isn’t completely covered. Bring to the boil and use a spoon to scrape the caramelised cooking juices from the bottom of the pan – this will give the stew more flavour.","Heat oven to 150C/fan 130C/gas 2. Make a cartouche: tear off a square of foil slightly larger than the casserole, arrange it in the pan so it covers the top of the stew and trim away any excess foil. Then cook for 3 hrs. If the sauce looks watery, remove the beef and veg with a slotted spoon, and set aside. Cook the sauce over a high heat for a few mins until the sauce has thickened a little, then return the beef and vegetables to the pan.","To make the celeriac mash, peel the celeriac and cut into cubes. Heat the olive oil in a large frying pan. Tip in the celeriac and fry for 5 mins until it turns golden. Season well with salt and pepper. Stir in the rosemary, thyme, bay and cardamom pods, then pour over 200ml water, enough to nearly cover the celeriac. Turn the heat to low, partially cover the pan and leave to simmer for 25-30 mins.","After 25-30 mins, the celeriac should be soft and most of the water will have evaporated. Drain away any remaining water, then remove the herb sprigs, bay and cardamom pods. Lightly crush with a potato masher, then finish with a glug of olive oil and season to taste. Spoon the beef bourguignon into serving bowls and place a large spoonful of the celeriac mash on top. Garnish with one of the bay leaves, if you like."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vtqxtu1511784197.jpg', 'themealdb'),
('Chocolate Souffle', ARRAY['france', 'dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 29, 40, 69, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Single Cream","measure":"142ml"},{"name":"Caster Sugar","measure":"25g"},{"name":"Dark Chocolate","measure":"100g"},{"name":"Butter","measure":"25g"},{"name":"Butter","measure":"drizzle"},{"name":"Caster Sugar","measure":"50g"},{"name":"Dark Chocolate","measure":"175g"},{"name":"Double Cream","measure":"2 tbs"},{"name":"Egg Yolks","measure":"4"},{"name":"Egg White","measure":"5"},{"name":"Double Cream","measure":"2 tbs"},{"name":"Icing Sugar","measure":"to serve"}]'::jsonb, '["Heat oven to 220C/fan 200C/gas 7 and place a baking tray on the top shelf. For the sauce, heat the cream and sugar until boiling. Remove from the heat, stir in the chocolate and butter until melted, then keep warm.","Brush 6 x 150ml ramekins with melted butter, sprinkle with the 2 tbsp caster sugar, then tip out any excess. Melt the chocolate and cream in a bowl over a pan of simmering water, cool, then mix in the egg yolks. Whisk the egg whites until they hold their shape, then add the sugar, 1 tbsp at a time, whisking back to the same consistency. Mix a spoonful into the chocolate, then gently fold in the rest.","Working quickly, fill the ramekins, wipe the rims clean and run your thumb around the edges. Turn oven down to 200C/fan 180C/gas 6, place the ramekins onto the baking tray, then bake for 8-10 mins until risen with a slight wobble. Don’t open the oven door too early as this may make them collapse.","Once the soufflés are ready, dust with icing sugar, scoop a small hole from their tops, then pour in some of the hot chocolate sauce. Replace the lids and serve straight away."]'::jsonb, 'https://www.themealdb.com/images/media/meals/twspvx1511784937.jpg', 'themealdb'),
('Duck Confit', ARRAY['france', 'miscellaneous']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 17, 30, 47, 'easy', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Sea Salt","measure":"Handful"},{"name":"Bay Leaf","measure":"4"},{"name":"Garlic","measure":"4 cloves"},{"name":"Thyme","measure":"Handful"},{"name":"Duck Legs","measure":"4"},{"name":"White Wine","measure":"100ml"}]'::jsonb, '["The day before you want to make the dish, scatter half the salt, half the garlic and half of the herbs over the base of a small shallow dish. Lay the duck legs, skin-side up, on top, then scatter over the remaining salt, garlic and herbs. Cover the duck and refrigerate overnight. This can be done up to 2 days ahead.","Pour the wine into a saucepan that will snugly fit the duck legs in a single layer. Brush the salt off the duck legs and place them, skin-side down, in the wine. Cover the pan with a lid and place over a medium heat. As soon as the wine starts to bubble, turn the heat down to the lowest setting and cook for 2 hours, checking occasionally that the liquid is just barely simmering. (If you own a heat diffuser, it would be good to use it here.) After 2 hours, the duck legs should be submerged in their own fat and the meat should feel incredibly tender when prodded. Leave to cool.","The duck legs are now cooked and can be eaten immediately – or you can follow the next step if you like them crisp. If you are preparing ahead, pack the duck legs tightly into a plastic container or jar and pour over the fat, but not the liquid at the bottom of the pan. Cover and leave in the fridge for up to a month, or freeze for up to 3 months. The liquid you are left with makes a tasty gravy, which can be chilled or frozen until needed.","To reheat and crisp up the duck legs, heat oven to 220C/fan 200C/gas 7. Remove the legs from the fat and place them, skin-side down, in an ovenproof frying pan. Roast for 30-40 mins, turning halfway through, until brown and crisp. Serve with the reheated gravy, a crisp salad and some crisp golden ptoatoes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wvpvsu1511786158.jpg', 'themealdb'),
('Ratatouille', ARRAY['france', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 25, 30, 55, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Aubergine","measure":"2 large"},{"name":"Courgettes","measure":"4"},{"name":"Yellow Pepper","measure":"2"},{"name":"Tomato","measure":"4 large"},{"name":"Olive Oil","measure":"5 tbs"},{"name":"Basil","measure":"Bunch"},{"name":"Onion","measure":"1 medium"},{"name":"Garlic Clove","measure":"3 finely chopped"},{"name":"Red Wine Vinegar","measure":"1 tsp"},{"name":"Sugar","measure":"1 tsp"}]'::jsonb, '["Cut the aubergines in half lengthways. Place them on the board, cut side down, slice in half lengthways again and then across into 1.5cm chunks. Cut off the courgettes ends, then across into 1.5cm slices. Peel the peppers from stalk to bottom. Hold upright, cut around the stalk, then cut into 3 pieces. Cut away any membrane, then chop into bite-size chunks.","Score a small cross on the base of each tomato, then put them into a heatproof bowl. Pour boiling water over the tomatoes, leave for 20 secs, then remove. Pour the water away, replace the tomatoes and cover with cold water. Leave to cool, then peel the skin away. Quarter the tomatoes, scrape away the seeds with a spoon, then roughly chop the flesh.","Set a sauté pan over medium heat and when hot, pour in 2 tbsp olive oil. Brown the aubergines for 5 mins on each side until the pieces are soft. Set them aside and fry the courgettes in another tbsp oil for 5 mins, until golden on both sides. Repeat with the peppers. Don’t overcook the vegetables at this stage, as they have some more cooking left in the next step.","Tear up the basil leaves and set aside. Cook the onion in the pan for 5 mins. Add the garlic and fry for a further min. Stir in the vinegar and sugar, then tip in the tomatoes and half the basil. Return the vegetables to the pan with some salt and pepper and cook for 5 mins. Serve with basil."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wrpwuu1511786491.jpg', 'themealdb'),
('Chinon Apple Tarts', ARRAY['france', 'dessert']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 19, 40, 59, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Puff Pastry","measure":"320g"},{"name":"Dark Brown Soft Sugar","measure":"4 tbs"},{"name":"Braeburn Apples","measure":"3"},{"name":"Red Wine Jelly","measure":"4 tbs"},{"name":"Creme Fraiche","measure":"100ml"},{"name":"Icing Sugar","measure":"1 tbs"},{"name":"Cardamom","measure":"3"}]'::jsonb, '["To make the red wine jelly, put the red wine, jam sugar, star anise, clove, cinnamon stick, allspice, split vanilla pod and seeds in a medium saucepan. Stir together, then heat gently to dissolve the sugar. Turn up the heat and boil for 20 mins until reduced and syrupy. Strain into a small, sterilised jam jar and leave to cool completely. Will keep in the fridge for up to 1 month.","Take the pastry out of the fridge and leave at room temperature for 10 mins, then unroll. Heat the grill to high and heat the oven to 180C/160C fan/gas 4. Cut out 2 x 13cm circles of pastry, using a plate as a guide, and place on a non-stick baking sheet. Sprinkle each circle with 1 tbsp sugar and grill for 5 mins to caramelise, watching carefully so that the sugar doesn’t burn. Remove from the grill. Can be done a few hours ahead, and left, covered, out of the fridge.","Peel, quarter and core the apples, cut into 2mm-thin slices and arrange on top of the pastry. Sprinkle over the remaining sugar and pop in the oven for 20-25 mins until the pastry is cooked through and golden, and the apples are softened. Remove and allow to cool slightly. Warm 3 tbsp of the red wine jelly in a small pan over a low heat with 1 tsp water to make it a little more runny, then brush over the top of the tarts.","Tip the crème fraîche into a bowl, sift over the icing sugar and cardamom, and mix together. Carefully lift the warm tarts onto serving plates and serve with the cardamom crème fraîche."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qtqwwu1511792650.jpg', 'themealdb'),
('Boulangère Potatoes', ARRAY['france', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 15, 20, 35, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Onions","measure":"2 finely chopped"},{"name":"Thyme","measure":"sprigs of fresh"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Potatoes","measure":"1.5kg"},{"name":"Vegetable Stock","measure":"425g"}]'::jsonb, '["Heat oven to 200C/fan 180C/gas 6. Fry the onions and thyme sprigs in the oil until softened and lightly coloured (about 5 mins).","Spread a layer of potatoes over the base of a 1.5-litre oiled gratin dish. Sprinkle over a few onions (see picture, above) and continue layering, finishing with a layer of potatoes. Pour over the stock and bake for 50-60 mins until the potatoes are cooked and the top is golden and crisp."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qywups1511796761.jpg', 'themealdb'),
('French Omelette', ARRAY['france', 'miscellaneous']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 19, 25, 44, 'easy', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 4, '[{"name":"Eggs","measure":"3"},{"name":"Butter","measure":"2 knobs"},{"name":"Parmesan","measure":"1 tsp"},{"name":"Tarragon Leaves","measure":"3 chopped"},{"name":"Parsley","measure":"1 tbs chopped"},{"name":"Chives","measure":"1 tbs chopped"},{"name":"Gruyère","measure":"4 tbs"}]'::jsonb, '["Get everything ready. Warm a 20cm (measured across the top) non-stick frying pan on a medium heat. Crack the eggs into a bowl and beat them with a fork so they break up and mix, but not as completely as you would for scrambled egg. With the heat on medium-hot, drop one knob of butter into the pan. It should bubble and sizzle, but not brown. Season the eggs with the Parmesan and a little salt and pepper, and pour into the pan.","Let the eggs bubble slightly for a couple of seconds, then take a wooden fork or spatula and gently draw the mixture in from the sides of the pan a few times, so it gathers in folds in the centre. Leave for a few seconds, then stir again to lightly combine uncooked egg with cooked. Leave briefly again, and when partly cooked, stir a bit faster, stopping while there’s some barely cooked egg left. With the pan flat on the heat, shake it back and forth a few times to settle the mixture. It should slide easily in the pan and look soft and moist on top. A quick burst of heat will brown the underside.","Grip the handle underneath. Tilt the pan down away from you and let the omelette fall to the edge. Fold the side nearest to you over by a third with your fork, and keep it rolling over, so the omelette tips onto a plate – or fold it in half, if that’s easier. For a neat finish, cover the omelette with a piece of kitchen paper and plump it up a bit with your fingers. Rub the other knob of butter over to glaze. Serve immediately."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yvpuuy1511797244.jpg', 'themealdb'),
('White chocolate creme brulee', ARRAY['france', 'dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 17, 35, 52, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Double Cream","measure":"568ml"},{"name":"White Chocolate Chips","measure":"100g"},{"name":"Vanilla","measure":"Pod of"},{"name":"Egg Yolks","measure":"6"},{"name":"Caster Sugar","measure":"2 tbs"},{"name":"Caster Sugar","measure":"Top"}]'::jsonb, '["Heat the cream, chocolate and vanilla pod in a pan until the chocolate has melted. Take off the heat and allow to infuse for 10 mins, scraping the pod seeds into the cream. If using the vanilla extract, add straight away. Heat oven to 160C/fan 140C/gas 3.","Beat yolks and sugar until pale. stir in the chocolate cream. Strain into a jug and pour into ramekins. Place in a deep roasting tray and pour boiling water halfway up the sides. Bake for 15-20 mins until just set with a wobbly centre. Chill in the fridge for at least 4 hrs.","To serve, sprinkle some sugar on top of the brûlées and caramelise with a blowtorch or briefly under a hot grill. Leave caramel to harden, then serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uryqru1511798039.jpg', 'themealdb'),
('Fish Stew with Rouille', ARRAY['france', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 41, 40, 81, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Prawns","measure":"6 large"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Dry White Wine","measure":"150ml"},{"name":"Fish Stock","measure":"200ml"},{"name":"Fennel","measure":"1 small finely diced"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Garlic","measure":"3 cloves Chopped"},{"name":"Potatoes","measure":"1 large"},{"name":"Orange","measure":"1"},{"name":"Star Anise","measure":"1"},{"name":"Bay Leaf","measure":"1"},{"name":"Harissa Spice","measure":"1 1/2 tsp"},{"name":"Tomato Puree","measure":"2 tbs"},{"name":"Chopped Tomatoes","measure":"400g"},{"name":"Mussels","measure":"Handful"},{"name":"White Fish","measure":"200g"},{"name":"Thyme","measure":"2"},{"name":"Bread","measure":"to serve"}]'::jsonb, '["Twist the heads from the prawns, then peel away the legs and shells, but leave the tails intact. Devein each prawn. Fry the shells in 1 tbsp oil for 5 mins, until dark pink and golden in patches. Add the wine, boil down by two thirds, then pour in the stock. Strain into a jug, discarding the shells.","Heat the rest of the oil in a deep frying pan or casserole. Add the fennel, onion and garlic, season, then cover and gently cook for 10 mins until softened. Meanwhile, peel the potato and cut into 2cm-ish chunks. Put into a pan of cold water, bring to the boil and cook for 5 mins until almost tender. Drain in a colander.","Peel a strip of zest from the orange. Put the zest, star anise, bay and ½ tsp harissa into the pan. Fry gently, uncovered, for 5-10 mins, until the vegetables are soft, sweet and golden.","Stir in the tomato purée, cook for 2 mins, then add the tomatoes and stock. Simmer for 10 mins until the sauce thickens slightly. Season to taste. The sauce can be made ahead, then reheated later in the day. Meantime, scrub the mussels or clams and pull away any stringy beards. Any that are open should be tapped sharply on the worktop – if they don’t close after a few seconds, discard them.","Reheat the sauce if necessary, then stir the potato, chunks of fish and prawns very gently into the stew. Bring back to the boil, then cover and gently simmer for 3 mins. Scatter the mussels or clams over the stew, then cover and cook for 2 mins more or until the shells have opened wide. Discard any that remain closed. The chunks of fish should flake easily and the prawns should be pink through. Scatter with the thyme leaves.","To make the quick rouille, stir the rest of the harissa through the mayonnaise. Serve the stew in bowls, topped with spoonfuls of rouille, which will melt into the sauce and enrich it. Have some good bread ready, as you’ll definitely want to mop up the juices."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vptqpw1511798500.jpg', 'themealdb'),
('Fennel Dauphinoise', ARRAY['france', 'side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 19, 20, 39, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Potatoes","measure":"225g"},{"name":"Fennel","measure":"1 small"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Milk","measure":"75 ml"},{"name":"Double Cream","measure":"100ml"},{"name":"Butter","measure":"For Greasing"},{"name":"Parmesan Cheese","measure":"to serve"}]'::jsonb, '["Heat oven to 180C/160C fan/gas 4. Put potatoes, fennel, and garlic in a medium non-stick pan. Pour in milk and double cream, season well and simmer gently, covered, for 10 mins, stirring halfway through, until potatoes are just tender.","Divide the mixture between 2 small (about 150ml) buttered ramekins and scatter with Parmesan. Bake for 40 mins until the potatoes are golden and tender when pierced with a knife. Snip the reserved fennel fronds over before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ytttsv1511798734.jpg', 'themealdb'),
('Tourtiere', ARRAY['canadian', 'pork']::text[], ARRAY['dairy_free']::text[], 27, 45, 72, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Potatoes","measure":"1 medium"},{"name":"Sunflower Oil","measure":"1 tsp"},{"name":"Minced Pork","measure":"500g"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Garlic Clove","measure":"1 finely chopped"},{"name":"Cinnamon","measure":"¼ tsp"},{"name":"Allspice","measure":"¼ tsp"},{"name":"Nutmeg","measure":"¼ tsp"},{"name":"Vegetable Stock","measure":"100ml"},{"name":"Shortcrust Pastry","measure":"400g"},{"name":"Egg","measure":"To Glaze"}]'::jsonb, '["Heat oven to 200C/180C fan/gas 6. Boil the potato until tender, drain and mash, then leave to cool. Heat the oil in a non-stick pan, add the mince and onion and quickly fry until browned. Add the garlic, spices, stock, plenty of pepper and a little salt and mix well. Remove from the heat, stir into the potato and leave to cool.","Roll out half the pastry and line the base of a 20-23cm pie plate or flan tin. Fill with the pork mixture and brush the edges of the pastry with water. Roll out the remaining dough and cover the pie. Press the edges of the pastry to seal, trimming off the excess. Prick the top of the pastry case to allow steam to escape and glaze the top with the beaten egg.","Bake for 30 mins until the pastry is crisp and golden. Serve cut into wedges with a crisp green salad. Leftovers are good cold for lunch the next day, served with a selection of pickles."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ytpstt1511814614.jpg', 'themealdb'),
('Montreal Smoked Meat', ARRAY['canadian', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 37, 60, 97, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef Brisket","measure":"1"},{"name":"Salt","measure":"3 tbs"},{"name":"Black Pepper","measure":"3 tbs"},{"name":"Coriander","measure":"1 tbs"},{"name":"Sugar","measure":"1 tbs"},{"name":"Bay Leaf","measure":"1 tsp"},{"name":"Cloves","measure":"1 tsp"},{"name":"Black Pepper","measure":"3 tbs"},{"name":"Coriander","measure":"1 tbs"},{"name":"Paprika","measure":"1 tbs"},{"name":"Garlic","measure":"1 tbs"},{"name":"Onion","measure":"1 tbs"},{"name":"Dill","measure":"1 tbs"},{"name":"English Mustard","measure":"1 tsp"},{"name":"Celery Salt","measure":"1 tbs"},{"name":"Red Pepper Flakes","measure":"1 tsp"}]'::jsonb, '["To make the cure, in a small bowl mix together salt, pink salt, black pepper, coriander, sugar, bay leaf, and cloves. Coat entire brisket with the cure and place in an extra-large resealable plastic bag. Place in the coldest part of the refrigerator and cure for 4 days, flipping brisket twice a day.","Remove brisket from bag and wash as much cure off as possible under cold running water. Place brisket in a large container and fill with water and let soak for 2 hours, replacing water every 30 minutes. Remove from water and pat dry with paper towels.","To make the rub, mix together black pepper, coriander, paprika, garlic powder, onion powder, dill weed, mustard, celery seed, and crushed red papper in a small bowl. Coat entire brisket with the rub.","Fire up smoker or grill to 225 degrees, adding chunks of smoking wood chunks when at temperature. When wood is ignited and producing smoke, place brisket in, fat side up, and smoke until an instant read thermometer registers 165 degrees when inserted into thickest part of the brisket, about 6 hours.","Transfer brisket to large roasting pan with V-rack. Place roasting pan over two burners on stovetop and fill with 1-inch of water. Bring water to a boil over high heat, reduce heat to medium, cover roasting pan with aluminum foil, and steam brisket until an instant read thermometer registers 180 degrees when inserted into thickest part of the meat, 1 to 2 hours, adding more hot water as needed.","Transfer brisket to cutting board and let cool slightly. Slice and serve, preferably on rye with mustard."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uttupv1511815050.jpg', 'themealdb'),
('BeaverTails', ARRAY['canadian', 'dessert']::text[], ARRAY['vegetarian']::text[], 29, 55, 84, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Water","measure":"1/2 cup"},{"name":"Yeast","measure":"2 parts"},{"name":"Sugar","measure":"1/2 cup"},{"name":"Milk","measure":"1/2 cup"},{"name":"Butter","measure":"6 tblsp"},{"name":"Eggs","measure":"2"},{"name":"Salt","measure":"1 ½ tsp"},{"name":"Flour","measure":"2-1/2 cups"},{"name":"Oil","measure":"for frying"},{"name":"Lemon","measure":"garnish"},{"name":"Sugar","measure":"garnish"},{"name":"Cinnamon","measure":"garnish"}]'::jsonb, '["In the bowl of a stand mixer, add warm water, a big pinch of sugar and yeast. Allow to sit until frothy.","Into the same bowl, add 1/2 cup sugar, warm milk, melted butter, eggs and salt, and whisk until combined.","Place a dough hook on the mixer, add the flour with the machine on, until a smooth but slightly sticky dough forms.","Place dough in a bowl, cover with plastic wrap, and allow to proof for 1 1/2 hours.","Cut dough into 12 pieces, and roll out into long oval-like shapes about 1/4 inch thick that resemble a beaver’s tail.","In a large, deep pot, heat oil to 350 degrees. Gently place beavertail dough into hot oil and cook for 30 to 45 seconds on each side until golden brown.","Drain on paper towels, and garnish as desired. Toss in cinnamon sugar, in white sugar with a squeeze of lemon, or with a generous slathering of Nutella and a handful of toasted almonds. Enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/ryppsv1511815505.jpg', 'themealdb'),
('Timbits', ARRAY['canadian', 'dessert']::text[], ARRAY['vegetarian']::text[], 23, 45, 68, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Flour","measure":"2 cups"},{"name":"Sugar","measure":"1/3 cup"},{"name":"Baking Powder","measure":"3 tsp"},{"name":"Salt","measure":"½ tsp"},{"name":"Egg","measure":"1 beaten"},{"name":"Milk","measure":"¾ cup"},{"name":"Oil","measure":"3 tbs"},{"name":"Oil","measure":"for frying"},{"name":"Icing Sugar","measure":"garnish"}]'::jsonb, '["Sift together dry ingredients.","Mix together wet ingredients and incorporate into dry. Stir until smooth.","Drop by teaspoonfuls(no bigger) into hot oil (365 degrees, no hotter), turning after a few moments until golden brown on all sides.","Remove and drain.","Roll in cinnamon sugar while still warm and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/txsupu1511815755.jpg', 'themealdb'),
('Pate Chinois', ARRAY['canadian', 'beef']::text[], ARRAY['gluten_free']::text[], 25, 60, 85, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Potatoes","measure":"4 cups"},{"name":"Butter","measure":"60ml"},{"name":"Milk","measure":"½ cup"},{"name":"Minced Beef","measure":"450g"},{"name":"Onion","measure":"1 finely chopped"},{"name":"Creamed Corn","measure":"500ml"},{"name":"Paprika","measure":"to taste"},{"name":"Parsley","measure":"to taste"},{"name":"Salt","measure":"Dash"},{"name":"Pepper","measure":"Dash"}]'::jsonb, '["In a large pot of salted water, cook the potatoes until they are very tender. Drain.","With a masher, coarsely crush the potatoes with at least 30 ml (2 tablespoons) of butter. With an electric mixer, purée with the milk. Season with salt and pepper. Set aside.","With the rack in the middle position, preheat the oven to 190 °C (375 °F).","In a large skillet, brown the onion in the remaining butter. Add the meat and cook until golden brown. Season with salt and pepper. Remove from the heat.","Lightly press the meat at the bottom of a 20-cm (8-inch) square baking dish. Cover with the corn and the mashed potatoes. Sprinkle with paprika and parsley.","Bake for about 30 minutes. Finish cooking under the broiler. Let cool for 10 minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yyrrxr1511816289.jpg', 'themealdb'),
('Sugar Pie', ARRAY['canadian', 'dessert']::text[], ARRAY['vegetarian']::text[], 19, 35, 54, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Brown Sugar","measure":"2 cups"},{"name":"Butter","measure":"¼ cup"},{"name":"Eggs","measure":"2"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Plain Flour","measure":"½ cup"},{"name":"Milk","measure":"1 1/2 cups"}]'::jsonb, '["Preheat oven to 350 degrees F (175 degrees C). Grease a 9-inch pie dish.","Place the brown sugar and butter in a mixing bowl, and beat them together with an electric mixer until creamy and very well combined, without lumps. Beat in eggs, one at a time, incorporating the first egg before adding the next one. Add the vanilla extract and salt; beat the flour in, a little at a time, and then the milk, making a creamy batter. Pour the batter into the prepared pie dish.","Bake in the preheated oven for 35 minutes; remove pie, and cover the rim with aluminum foil to prevent burning. Return to oven, and bake until the middle sets and the top forms a crusty layer, about 15 more minutes. Let the pie cool to room temperature, then refrigerate for at least 1 hour before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yrstur1511816601.jpg', 'themealdb'),
('Rappie Pie', ARRAY['canadian', 'chicken']::text[], ARRAY['gluten_free']::text[], 19, 40, 59, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Butter","measure":"2 tbs"},{"name":"Onions","measure":"2 chopped"},{"name":"Chicken Stock","measure":"4 qt"},{"name":"Chicken Breast","measure":"1.5kg"},{"name":"Potatoes","measure":"4kg"},{"name":"Salt","measure":"2 tbs"},{"name":"Black Pepper","measure":"1tbsp"}]'::jsonb, '["Preheat oven to 400 degrees F (200 degrees C). Grease a 10x14x2-inch baking pan.","Heat margarine in a skillet over medium heat; stir in onion. Cook and stir until onion has softened and turned translucent, about 5 minutes. Reduce heat to low and continue to cook and stir until onion is very tender and dark brown, about 40 minutes more.","Bring chicken broth to a boil in a large pot; stir in chicken breasts, reduce heat, and simmer until chicken is no longer pink at the center, about 20 minutes. Remove from heat. Remove chicken breasts to a plate using a slotted spoon; reserve broth.","Juice potatoes with an electric juicer; place dry potato flesh into a bowl and discard juice. Stir salt and pepper into potatoes; stir in enough reserved broth to make the mixture the consistency of oatmeal. Set remaining broth aside.","Spread half of potato mixture evenly into the prepared pan. Lay cooked chicken breast evenly over potatoes; scatter caramelized onion evenly over chicken. Spread remaining potato mixture over onions and chicken to cover.","Bake in the preheated oven until golden brown, about 1 hour. Reheat chicken broth; pour over individual servings as desired."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ruwpww1511817242.jpg', 'themealdb'),
('Saltfish and Ackee', ARRAY['jamaican', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 37, 70, 107, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Salt Cod","measure":"450g"},{"name":"Ackee","measure":"400g"},{"name":"Onion","measure":"1 chopped"},{"name":"Paprika","measure":"1 tsp"},{"name":"Curry Powder","measure":"2 tsp"},{"name":"Jerusalem Artichokes","measure":"2 tsp"},{"name":"Hotsauce","measure":"1 tsp"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Yellow Pepper","measure":"1 sliced"},{"name":"Tomatoes","measure":"200g"},{"name":"Salt","measure":"to taste"},{"name":"Pepper","measure":"to taste"},{"name":"Self-raising Flour","measure":"250g"},{"name":"Suet","measure":"30g"},{"name":"Salt","measure":"pinch"},{"name":"Olive Oil","measure":"for frying"}]'::jsonb, '["For the saltfish, soak the salt cod overnight, changing the water a couple of times.","Drain, then put the cod in a large pan of fresh water and bring to the boil. Drain again, add fresh water and bring to the boil again.","Simmer for about five minutes, or until cooked through, then drain and flake the fish into large pieces. Discard any skin or bones.","For the dumplings, mix the flour and suet with a pinch of salt and 250ml/9fl oz water to make a dough.","Wrap the mixture in clingfilm and leave in the fridge to rest.","Open the can of ackee, drain and rinse, then set aside.","Heat a tablespoon of olive oil in a pan and fry the onion until softened but not brown.","Add the spices, seasoning, pepper sauce and sliced peppers and continue to fry until the peppers are tender.","Add the chopped tomatoes, then the salt cod and mix together. Lastly stir in the ackee very gently and leave to simmer until ready to serve.","When you’re almost ready to eat, heat about 1cm/½in vegetable oil in a frying pan and heat until just smoking.","Shape the dumpling mix into plum-size balls and shallow-fry until golden-brown. (CAUTION: hot oil can be dangerous. Do not leave the pan unattended.)","Drain the dumplings on kitchen paper and serve with the saltfish and ackee."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vytypy1511883765.jpg', 'themealdb'),
('Jerk chicken with rice & peas', ARRAY['jamaican', 'chicken']::text[], ARRAY[]::text[], 45, 40, 85, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Chicken Thighs","measure":"12"},{"name":"Lime","measure":"1/2"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Ginger","measure":"1 tbs chopped"},{"name":"Garlic","measure":"3 cloves"},{"name":"Onion","measure":"1/2"},{"name":"Red Chilli","measure":"3 chopped"},{"name":"Thyme","measure":"1/2 teaspoon"},{"name":"Lime","measure":"Juice of 1"},{"name":"Soy Sauce","measure":"2 tbs"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Brown Sugar","measure":"3 tbs"},{"name":"Allspice","measure":"1 tbs"},{"name":"Basmati Rice","measure":"200g"},{"name":"Coconut Milk","measure":"400g"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Allspice","measure":"1 tbs"},{"name":"Kidney Beans","measure":"800g"}]'::jsonb, '["To make the jerk marinade, combine all the ingredients in a food processor along with 1 tsp salt, and blend to a purée. If you’re having trouble getting it to blend, just keep turning off the blender, stirring the mixture, and trying again. Eventually it will start to blend up – don’t be tempted to add water, as you want a thick paste.","Taste the jerk mixture for seasoning – it should taste pretty salty, but not unpleasantly, puckering salty. You can now throw in more chillies if it’s not spicy enough for you. If it tastes too salty and sour, try adding in a bit more brown sugar until the mixture tastes well balanced.","Make a few slashes in the chicken thighs and pour the marinade over the meat, rubbing it into all the crevices. Cover and leave to marinate overnight in the fridge.","If you want to barbecue your chicken, get the coals burning 1 hr or so before you’re ready to cook. Authentic jerked meats are not exactly grilled as we think of grilling, but sort of smoke-grilled. To get a more authentic jerk experience, add some wood chips to your barbecue, and cook your chicken over slow, indirect heat for 30 mins. To cook in the oven, heat to 180C/160C fan/gas 4. Put the chicken pieces in a roasting tin with the lime halves and cook for 45 mins until tender and cooked through.","While the chicken is cooking, prepare the rice & peas. Rinse the rice in plenty of cold water, then tip it into a large saucepan with all the remaining ingredients except the kidney beans. Season with salt, add 300ml cold water and set over a high heat. Once the rice begins to boil, turn it down to a medium heat, cover and cook for 10 mins.","Add the beans to the rice, then cover with a lid. Leave off the heat for 5 mins until all the liquid is absorbed. Squeeze the roasted lime over the chicken and serve with the rice & peas, and some hot sauce if you like it really spicy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tytyxu1515363282.jpg', 'themealdb'),
('Jamaican Beef Patties', ARRAY['jamaican', 'beef']::text[], ARRAY[]::text[], 45, 175, 220, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Plain Flour","measure":"4 cups"},{"name":"Salt","measure":"1 tsp"},{"name":"Curry Powder","measure":"1 tsp"},{"name":"Butter","measure":"250g"},{"name":"Water","measure":"1 cup"},{"name":"Minced Beef","measure":"900g"},{"name":"Allspice","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Vegetable Oil","measure":"2 tbs"},{"name":"Onions","measure":"1 cup"},{"name":"Red Pepper","measure":"Ground"},{"name":"Garlic","measure":"2 tsp ground"},{"name":"Thyme","measure":"1 tbs"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Tomato Ketchup","measure":"2 tbs"},{"name":"Water","measure":"2 cups"},{"name":"Onions","measure":"1/2 cup"},{"name":"Egg","measure":"1 beaten"},{"name":"Water","measure":"1 tbs"},{"name":"Water","measure":"1/4 cup"}]'::jsonb, '["Make the Pastry Dough","To a large bowl, add flour, 1 teaspoon salt, and turmeric and mix thoroughly.","Rub shortening into flour until there are small pieces of shortening completely covered with flour.","Pour in 1/2 cup of the ice water and mix with your hands to bring the dough together. Keep adding ice water 2 to 3 tablespoons at a time until the mixture forms a dough.","At this stage, you can cut the dough into 2 large pieces, wrap in plastic and refrigerate for 30 minutes before using it.","Alternatively, cut the dough into 10 to 12 equal pieces, place on a platter or baking sheet, cover securely with plastic wrap and let chill for 30 minutes while you make the filling.","Make the Filling","Add ground beef to a large bowl. Sprinkle in allspice and black pepper. Mix together and set aside.","Heat oil in a skillet until hot.","Add onions and sauté until translucent. Add hot pepper, garlic and thyme and continue to sauté for another minute. Add 1/4 teaspoon salt.","Add seasoned ground beef and toss to mix, breaking up any clumps, and let cook until the meat is no longer pink.","Add ketchup and more salt to taste.","Pour in 2 cups of water and stir. Bring the mixture to a boil then reduce heat and let simmer until most of the liquid has evaporated and whatever is remaining has reduced to a thick sauce.","Fold in green onions. Remove from heat and let cool completely.","Assemble the Patties","Beat the egg and water together to make an egg wash. Set aside.","Now you can prepare the dough in two ways.","First Method: Flour the work surface and rolling pin. If you had cut it into 2 large pieces, then take one of the large pieces and roll it out into a very large circle. Take a bowl with a wide rim (about 5 inches) and cut out three circles.","Place about 3 heaping tablespoons of the filling onto 1/2 of each circle. Dip a finger into the water and moisten the edges of the pastry. Fold over the other half and press to seal.","Take a fork and crimp the edges. Cut off any extra to make it look neat and uniform. Place on a parchment-lined baking sheet and continue to work until you have rolled all the dough and filled the patties.","Second Method: If you had pre-cut the dough into individual pieces, work with one piece of dough at a time. Roll it out on a floured surface into a 5-inch circle or a little larger. Don’t worry if the edges are not perfect.","Place 3 heaping tablespoons of the filling on one side of the circle. Dip a finger into the water and moisten the edges of the pastry. Fold over the other half and press to seal.","Take a fork and crimp the edges. Cut off any extra to make it look neat and uniform. Place on a parchment-lined baking sheet and continue work until you have rolled all the dough and filled the patties.","Frying and Serving the Patties","After forming the patties, place the pans in the refrigerator while you heat the oven to 350 F.","Just before adding the pans with the patties to the oven, brush the patties with egg wash.","Bake patties for 30 minutes or until golden brown.","Cool on wire racks.","Serve warm."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wsqqsw1515364068.jpg', 'themealdb'),
('Red Peas Soup', ARRAY['jamaican', 'beef']::text[], ARRAY[]::text[], 35, 70, 105, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Kidney Beans","measure":"2 cups"},{"name":"Carrots","measure":"1 large"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Thyme","measure":"4 sprigs"},{"name":"Onion","measure":"1 Diced"},{"name":"Black Pepper","measure":"1/2 tsp"},{"name":"Red Pepper","measure":"2 chopped"},{"name":"Garlic Clove","measure":"4 Mashed"},{"name":"Allspice","measure":"1 tbs"},{"name":"Beef","measure":"2 Lbs"},{"name":"Water","measure":"2L"},{"name":"Potatoes","measure":"4"},{"name":"Plain Flour","measure":"1 cup"},{"name":"Water","measure":"1/4 cup"},{"name":"Coconut Milk","measure":"1 cup"}]'::jsonb, '["Wash and rinse the dried kidney beans.. then cover with water in a deep bowl. Remember as they soak they will expand to at least triple the size they were originally so add a lot of water to the bowl. Soak them overnight or for at least 2 hrs to make the cooking step go quicker. I tossed out the water they were soaked in after it did the job.","Have your butcher cut the salted pigtail into 2 inch pieces as it will be very difficult to cut with an ordinary kitchen knife. Wash, then place a deep pot with water and bring to a boil. Cook for 20 minutes, then drain + rinse and repeat (boil again in water). The goal is to make the pieces of pig tails tender and to remove most of the salt it was cured in.","Time to start the soup. Place everything in the pot (except the flour and potato), then cover with water and place on a high flame to bring to a boil. As it comes to a boil, skim off any scum/froth at the top and discard. Reduce the heat to a gentle boil and allow it to cook for 1 hr and 15 mins.. basically until the beans are tender and start falling apart.","It’s now time to add the potato (and Yams etc if you’re adding it) as well as the coconut milk and continue cooking for 15 minutes.","Now is a good time to start making the basic dough for the spinner dumplings. Mix the flour and water (add a pinch of salt if you want) until you have a soft/smooth dough. allow it to rest for 5 minutes, then pinch of a tablespoon at a time and roll between your hands to form a cigarette shape.","Add them to the pot, stir well and continue cooking for another 15 minutes on a rolling boil.","You’ll notice that I didn’t add any salt to the pot as the remaining salt from the salted pigtails will be enough to properly season this dish. However you can taste and adjust accordingly. Lets recap the timing part of things so you’re not confused. Cook the base of the soup for 1 hr and 15 minute or until tender, then add the potatoes and cook for 15 minutes, then add the dumplings and cook for a further 15 minutes. Keep in mind that this soup will thicken quite a bit as it cools.","While this is not a traditional recipe to any one specific island, versions of this soup (sometimes called stewed peas) can be found throughout the Caribbean, Latin America and Africa. A hearty bowl of this soup will surely give you the sleepies (some may call it ethnic fatigue). You can certainly freeze the leftovers and heat it up another day."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sqpqtp1515365614.jpg', 'themealdb'),
('Escovitch Fish', ARRAY['jamaican', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 39, 35, 74, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Red Snapper","measure":"2 Pounds"},{"name":"Vegetable Oil","measure":"1/2 cup"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Ginger","measure":"1/2 tsp"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Bay Leaf","measure":"1"},{"name":"Red Pepper","measure":"0.5"},{"name":"Yellow Pepper","measure":"0.5"},{"name":"Onion","measure":"1 sliced"},{"name":"Carrots","measure":"1 chopped"},{"name":"Sugar","measure":"1 tbs"},{"name":"Allspice","measure":"1/2 tsp"},{"name":"Worcestershire Sauce","measure":"1 tsp"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Lime","measure":"1"},{"name":"Malt Vinegar","measure":"3/4 cup"},{"name":"Pepper","measure":"pinch"}]'::jsonb, '["Rinse fish; rub with lemon or lime, seasoned with salt and pepper or use your favorite seasoning. I used creole seasoning. Set aside or place in the oven to keep it warm until sauce is ready.","In large skillet heat oil over medium heat, until hot, add the fish, cook each side- for about 5-7 minutes until cooked through and crispy on both sides. Remove fish and set aside. Drain oil and leave about 2-3 tablespoons of oil","Add, bay leave, garlic and ginger, stir-fry for about a minute making sure the garlic does not burn","Then add onion, bell peppers, thyme, scotch bonnet, sugar, all spice-continue stirring for about 2-3 minutes. Add vinegar, mix an adjust salt and pepper according to preference. Let it simmer for about 2 more minutes.","Discard bay leave, thyme spring and serve over fish with a side of this bammy. You may make the sauce about 2 days in advance."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1520084413.jpg', 'themealdb'),
('Ma Po Tofu', ARRAY['chinese', 'beef']::text[], ARRAY['dairy_free']::text[], 39, 75, 114, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Tofu","measure":"450g"},{"name":"Minced Beef","measure":"100g"},{"name":"Sesame Seed Oil","measure":"1/2 tbs"},{"name":"Doubanjiang","measure":"1 1/2 tsp"},{"name":"Fermented Black Beans","measure":"1/2 tsp"},{"name":"Pepper","measure":"1 tbs"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sichuan pepper","measure":"1/2 tsp"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Water","measure":"400ml"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Scallions","measure":"2 chopped"},{"name":"Spring Onions","measure":"4"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Ginger","measure":"4 sliced"},{"name":"Water","measure":"2 1/2 tbs"},{"name":"Cornstarch","measure":"1 tbs"}]'::jsonb, '["Add a small pinch of salt and sesame oil to minced beef. Mix well and set aside.","Mix 1 tablespoon of cornstarch with 2 and ½ tablespoons of water in a small bowl to make water starch.","Cut tofu into square cubes (around 2cms). Bring a large amount of water to a boil and then add a pinch of salt. Slide the tofu in and cook for 1 minute. Move out and drain.","Get a wok and heat up around 2 tablespoons of oil, fry the minced meat until crispy. Transfer out beef out and leave the oil in.","Fry doubanjiang for 1 minute over slow fire and then add garlic, scallion white, ginger and fermented black beans to cook for 30 seconds until aroma. Then mix pepper flakes in.","Add water to the seasonings and bring to boil over high fire. Gently slide the tofu cubes. Add light soy sauce and beef.Slow the heat after boiling and then simmer for 6-8 minutes. Then add chopped garlic greens.","Stir the water starch and then pour half of the mixture to the simmering pot. Wait for around 30 seconds and then pour the other half. You can slightly taste the tofu and add pinch of salt if not salty enough. By the way, if you feel it is too spicy, add some sugar can milder the taste. But be carefully as the broth is very hot at this point.","Transfer out when almost all the seasonings stick to tofu cubes. Sprinkle Szechuan peppercorn powder (to taste)and chopped garlic greens if using.","Serve immediately with steamed rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1525874812.jpg', 'themealdb'),
('Wontons', ARRAY['chinese', 'pork']::text[], ARRAY['dairy_free']::text[], 27, 70, 97, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Pork","measure":"1lb"},{"name":"Garlic Clove","measure":"3 chopped"},{"name":"Ginger","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Carrots","measure":"3 finely chopped"},{"name":"Celery","measure":"3 finely chopped"},{"name":"Spring Onions","measure":"6 chopped"},{"name":"Wonton Skin","measure":"1 Packet"},{"name":"Oil","measure":"Fry"},{"name":"Water","measure":"Bottle"}]'::jsonb, '["Combine pork, garlic, ginger, soy sauce, sesame oil, and vegetables in a bowl.","Separate wonton skins.","Place a heaping teaspoon of filling in the center of the wonton.","Brush water on 2 borders of the skin, covering 1/4 inch from the edge.","Fold skin over to form a triangle, sealing edges.","Pinch the two long outside points together.","Heat oil to 450 degrees and fry 4 to 5 at a time until golden.","Drain and serve with sauce."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1525876468.jpg', 'themealdb'),
('Sweet and Sour Pork', ARRAY['chinese', 'pork']::text[], ARRAY['dairy_free']::text[], 25, 100, 125, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Pork","measure":"200g"},{"name":"Egg","measure":"1"},{"name":"Water","measure":"Dash"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Soy Sauce","measure":"10g"},{"name":"Starch","measure":"10g"},{"name":"Tomato Puree","measure":"30g"},{"name":"Vinegar","measure":"10g"},{"name":"Coriander","measure":"Dash"}]'::jsonb, '["Preparation","Crack the egg into a bowl. Separate the egg white and yolk.","Sweet and Sour Pork","Slice the pork tenderloin into strips.","Prepare the marinade using a pinch of salt, one teaspoon of starch, two teaspoons of light soy sauce, and an egg white.","Marinade the pork strips for about 20 minutes.","Put the remaining starch in a bowl. Add some water and vinegar to make a starchy sauce.","Sweet and Sour Pork","Cooking Instructions","Pour the cooking oil into a wok and heat to 190°C (375°F). Add the marinated pork strips and fry them until they turn brown. Remove the cooked pork from the wok and place on a plate.","Leave some oil in the wok. Put the tomato sauce and white sugar into the wok, and heat until the oil and sauce are fully combined.","Add some water to the wok and thoroughly heat the sweet and sour sauce before adding the pork strips to it.","Pour in the starchy sauce. Stir-fry all the ingredients until the pork and sauce are thoroughly mixed together.","Serve on a plate and add some coriander for decoration."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1529442316.jpg', 'themealdb'),
('General Tsos Chicken', ARRAY['chinese', 'chicken']::text[], ARRAY['dairy_free']::text[], 45, 75, 120, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Chicken Breast","measure":"1 1/2"},{"name":"Plain Flour","measure":"3/4 cup"},{"name":"Egg","measure":"1"},{"name":"Starch","measure":"2 tbs"},{"name":"Baking Powder","measure":"1 tbs"},{"name":"Salt","measure":"1 tsp"},{"name":"Onion Salt","measure":"1/2 tsp"},{"name":"Garlic Powder","measure":"1/4 tsp"},{"name":"Water","measure":"3/4 cup"},{"name":"Chicken Stock","measure":"1/2 cup"},{"name":"Duck Sauce","measure":"1/4 cup"},{"name":"Soy Sauce","measure":"3 tbs"},{"name":"Honey","measure":"2 tbs"},{"name":"Rice Vinegar","measure":"1 tbs"},{"name":"Sesame Seed Oil","measure":"2 tbs"},{"name":"Gochujang","measure":"1/2 tbs"},{"name":"Starch","measure":"2 tbs"},{"name":"Garlic","measure":"1 clove"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Ginger","measure":"1 tsp"}]'::jsonb, '["DIRECTIONS:","- SAUCE","In a bowl, add 2 Cups of water, 2 Tablespoon soy sauce, 2 Tablespoon white vinegar, sherry cooking wine, 1/4 Teaspoon white pepper, minced ginger, minced garlic, hot pepper, ketchup, hoisin sauce, and sugar.","Mix together well and set aside.","- MARINATING THE CHICKEN","In a bowl, add the chicken, 1 pinch of salt, 1 pinch of white pepper, 2 egg whites, and 3 Tablespoon of corn starch","- DEEP FRY THE CHICKEN","Deep fry the chicken at 350 degrees for 3-4 minutes or until it is golden brown and loosen up the chicken so that they don''t stick together.","Set the chicken aside.","- STIR FRY","Add the sauce to the wok and then the broccoli and wait until it is boiling.","To thicken the sauce, whisk together 2 Tablespoon of cornstarch and 4 Tablespoon of water in a bowl and slowly add to your stir-fry until it''s the right thickness.","Next add in the chicken and stir-fry for a minute and serve on a plate"]'::jsonb, 'https://www.themealdb.com/images/media/meals/1529444113.jpg', 'themealdb'),
('Beef Lo Mein', ARRAY['chinese', 'beef']::text[], ARRAY['dairy_free']::text[], 39, 85, 124, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef","measure":"1/2 lb"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Egg","measure":"1/2"},{"name":"Starch","measure":"3 tbs"},{"name":"Oil","measure":"5 tbs"},{"name":"Noodles","measure":"1/4 lb"},{"name":"Onion","measure":"1/2 cup"},{"name":"Minced Garlic","measure":"1 tsp"},{"name":"Ginger","measure":"1 tsp"},{"name":"Bean Sprouts","measure":"1 cup"},{"name":"Mushrooms","measure":"1 cup"},{"name":"Water","measure":"1 cup"},{"name":"Oyster Sauce","measure":"1 tbs"},{"name":"Sugar","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tsp"}]'::jsonb, '["- MARINATING THE BEEF","In a bowl, add the beef, salt, 1 pinch white pepper, 1 Teaspoon sesame seed oil, 1/2 egg, corn starch,1 Tablespoon of oil and mix together.","- BOILING THE THE NOODLES","In a 6 qt pot add your noodles to boiling water until the noodles are submerged and boil on high heat for 10 seconds. After your noodles is done boiling strain and cool with cold water.","- STIR FRY","Add 2 Tablespoons of oil, beef and cook on high heat untill beef is medium cooked.","Set the cooked beef aside","In a wok add 2 Tablespoon of oil, onions, minced garlic, minced ginger, bean sprouts, mushrooms, peapods and 1.5 cups of water or until the vegetables are submerged in water.","Add the noodles to wok","To make the sauce, add oyster sauce, 1 pinch white pepper, 1 teaspoon sesame seed oil, sugar, and 1 Teaspoon of soy sauce.","Next add the beef to wok and stir-fry"]'::jsonb, 'https://www.themealdb.com/images/media/meals/1529444830.jpg', 'themealdb'),
('Hot and Sour Soup', ARRAY['chinese', 'pork']::text[], ARRAY['dairy_free']::text[], 35, 65, 100, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"Mushrooms","measure":"1/3 cup"},{"name":"Wood Ear Mushrooms","measure":"1/3 cup"},{"name":"Tofu","measure":"2/3 Cup"},{"name":"Pork","measure":"1/2 cup"},{"name":"Chicken Stock","measure":"2-1/2 cups"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1/4 tsp"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Pepper","measure":"1/4 tsp"},{"name":"Hotsauce","measure":"1/2 tsp"},{"name":"Vinegar","measure":"1-½ cups"},{"name":"Soy Sauce","measure":"1 tsp"},{"name":"Cornstarch","measure":"1 tbs"},{"name":"Water","measure":"2 tbs"},{"name":"Spring Onions","measure":"1/4 cup"}]'::jsonb, '["- MAKING THE SOUP","In a wok add chicken broth and wait for it to boil.","Next add salt, sugar, sesame seed oil, white pepper, hot pepper sauce, vinegar and soy sauce and stir for few seconds.","Add Tofu, mushrooms, black wood ear mushrooms to the wok.","To thicken the sauce, whisk together 1 Tablespoon of cornstarch and 2 Tablespoon of water in a bowl and slowly add to your soup until it''s the right thickness.","Next add 1 egg slightly beaten with a knife or fork and add it to the soup and stir for 8 seconds","Serve the soup in a bowl and add the bbq pork and sliced green onions on top."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1529445893.jpg', 'themealdb'),
('Chicken Congee', ARRAY['chinese', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 23, 70, 93, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Chicken","measure":"8 oz"},{"name":"Salt","measure":"pinch"},{"name":"Pepper","measure":"pinch"},{"name":"Ginger Cordial","measure":"1 tsp"},{"name":"Ginger","measure":"1 tsp"},{"name":"Spring Onions","measure":"1 tbs"},{"name":"Rice","measure":"1/2 cup"},{"name":"Water","measure":"8 cups"},{"name":"Coriander","measure":"2 oz"}]'::jsonb, '["- MARINATING THE CHICKEN","In a bowl, add chicken, salt, white pepper, ginger juice and then mix it together well.","Set the chicken aside.","- RINSE THE WHITE RICE","Rinse the rice in a metal bowl or pot a couple times and then drain the water.","- BOILING THE WHITE RICE","Next add 8 cups of water and then set the stove on high heat until it is boiling. Once rice porridge starts to boil, set the stove on low heat and then stir it once every 8-10 minutes for around 20-25 minutes.","After 25 minutes, this is optional but you can add a little bit more water to make rice porridge to make it less thick or to your preference.","Next add the marinated chicken to the rice porridge and leave the stove on low heat for another 10 minutes.","After an additional 10 minutes add the green onions, sliced ginger, 1 pinch of salt, 1 pinch of white pepper and stir for 10 seconds.","Serve the rice porridge in a bowl","Optional: add Coriander on top of the rice porridge."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1529446352.jpg', 'themealdb'),
('Salmon Avocado Salad', ARRAY['british', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 21, 20, 41, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Salmon","measure":"400g"},{"name":"Avocado","measure":"3"},{"name":"Cucumber","measure":"1"},{"name":"Spinach","measure":"400g"},{"name":"Mint","measure":"4 tbs"},{"name":"Lime","measure":"zest and juice of 1"},{"name":"Honey","measure":"2 tsp"},{"name":"Olive Oil","measure":"3 tbs"}]'::jsonb, '["Season the salmon, then rub with oil. Mix the dressing ingredients together. Halve, stone, peel and slice the avocados. Halve and quarter the cucumber lengthways, then cut into slices. Divide salad, avocado and cucumber between four plates, then drizzle with half the dressing.","Heat a non-stick pan. Add the salmon and fry for 3-4 mins on each side until crisp but still moist inside. Put a salmon fillet on top of each salad and drizzle over the remaining dressing. Serve warm."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1549542994.jpg', 'themealdb'),
('Budino Di Ricotta', ARRAY['italian', 'dessert']::text[], ARRAY['vegetarian', 'dairy_free']::text[], 21, 30, 51, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Ricotta","measure":"500g"},{"name":"Eggs","measure":"4 large"},{"name":"Flour","measure":"3 tbs"},{"name":"Sugar","measure":"250g"},{"name":"Cinnamon","measure":"1 tsp"},{"name":"Lemons","measure":"Grated Zest of 2"},{"name":"Dark Rum","measure":"5 tbs"},{"name":"Icing Sugar","measure":"sprinking"}]'::jsonb, '["Mash the ricotta and beat well with the egg yolks, stir in the flour, sugar, cinnamon, grated lemon rind and the rum and mix well. You can do this in a food processor. Beat the egg whites until stiff, fold in and pour into a buttered and floured 25cm cake tin. Bake in the oven at 180ºC/160ºC fan/gas 4 for about 40 minutes, or until it is firm.","Serve hot or cold dusted with icing sugar."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1549542877.jpg', 'themealdb'),
('Shakshuka', ARRAY['egyptian', 'vegetarian']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 23, 20, 43, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Olive Oil","measure":"1 tbs"},{"name":"Red Onions","measure":"2 chopped"},{"name":"Red Chilli","measure":"1 finely chopped"},{"name":"Garlic","measure":"1 clove"},{"name":"Coriander","measure":"Chopped"},{"name":"Cherry Tomatoes","measure":"800g"},{"name":"Caster Sugar","measure":"1 tbs"},{"name":"Eggs","measure":"4"},{"name":"Feta","measure":"Spinkling"}]'::jsonb, '["Heat the oil in a frying pan that has a lid, then soften the onions, chilli, garlic and coriander stalks for 5 mins until soft. Stir in the tomatoes and sugar, then bubble for 8-10 mins until thick. Can be frozen for 1 month.","Using the back of a large spoon, make 4 dips in the sauce, then crack an egg into each one. Put a lid on the pan, then cook over a low heat for 6-8 mins, until the eggs are done to your liking. Scatter with the coriander leaves and serve with crusty bread."]'::jsonb, 'https://www.themealdb.com/images/media/meals/g373701551450225.jpg', 'themealdb'),
('Breakfast Potatoes', ARRAY['canadian', 'breakfast']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 23, 60, 83, 'hard', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Potatoes","measure":"3 Medium"},{"name":"Olive Oil","measure":"1 tbs"},{"name":"Bacon","measure":"2 strips"},{"name":"Garlic Clove","measure":"Minced"},{"name":"Maple Syrup","measure":"1 tbs"},{"name":"Parsley","measure":"Garnish"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Allspice","measure":"To taste"}]'::jsonb, '["Before you do anything, freeze your bacon slices that way when you''re ready to prep, it''ll be so much easier to chop!","Wash the potatoes and cut medium dice into square pieces. To prevent any browning, place the already cut potatoes in a bowl filled with water.","In the meantime, heat 1-2 tablespoons of oil in a large skillet over medium-high heat. Tilt the skillet so the oil spreads evenly.","Once the oil is hot, drain the potatoes and add to the skillet. Season with salt, pepper, and Old Bay as needed.","Cook for 10 minutes, stirring the potatoes often, until brown. If needed, add a tablespoon more of oil.","Chop up the bacon and add to the potatoes. The bacon will start to render and the fat will begin to further cook the potatoes. Toss it up a bit! The bacon will take 5-6 minutes to crisp.","Once the bacon is cooked, reduce the heat to medium-low, add the minced garlic and toss. Season once more. Add dried or fresh parsley. Control heat as needed.","Let the garlic cook until fragrant, about one minute.","Just before serving, drizzle over the maple syrup and toss. Let that cook another minute, giving the potatoes a caramelized effect.","Serve in a warm bowl with a sunny side up egg!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/1550441882.jpg', 'themealdb'),
('Mbuzi Choma (Roasted Goat)', ARRAY['kenyan', 'goat']::text[], ARRAY['dairy_free']::text[], 19, 75, 94, 'medium', '{"calories":480,"protein_g":36,"carbs_g":12,"fat_g":30}'::jsonb, 4, '[{"name":"Goat Meat","measure":"1 kg"},{"name":"Corn Flour","measure":"1 kg"},{"name":"Tomatoes","measure":"2"},{"name":"Salt","measure":"Pinch"},{"name":"Onion","measure":"1"},{"name":"Green Chilli","measure":"1"},{"name":"Coriander Leaves","measure":"1  bunch"}]'::jsonb, '["Steps for the Meat:","Roast meat over medium heat for 50 minutes and salt it as you turn it.","Steps for Ugali:","Bring the water and salt to a boil in a heavy-bottomed saucepan. Stir in the cornmeal slowly, letting it fall through the fingers of your hand.","Reduce heat to medium-low and continue stirring regularly, smashing any lumps with a spoon, until the mush pulls away from the sides of the pot and becomes very thick, about 10 minutes.","Remove from heat and allow to cool.","Place the ugali into a large serving bowl. Wet your hands with water, form a ball and serve.","Steps for Kachumbari: Mix the tomatoes, onions, chili and coriander leaves in a bowl.","Serve and enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/cuio7s1555492979.jpg', 'themealdb'),
('Tunisian Orange Cake', ARRAY['tunisian', 'dessert']::text[], ARRAY['vegetarian', 'dairy_free']::text[], 19, 45, 64, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Orange","measure":"1 large"},{"name":"Caster Sugar","measure":"300g"},{"name":"Olive Oil","measure":"75 ml"},{"name":"Flour","measure":"280g"},{"name":"Baking Powder","measure":"1 tbs"},{"name":"Eggs","measure":"4 large"},{"name":"Vanilla Extract","measure":"2 tsp"}]'::jsonb, '["Preheat oven to 190 C / Gas 5. Grease a 23cm round springform tin.","Cut off the hard bits from the top and bottom of the orange. Slice the orange and remove all seeds. Puree the orange with its peel in a food processor. Add one third of the sugar and the olive oil and continue to mix until well combined.","Sieve together flour and baking powder.","Beat the eggs and the remaining sugar with an electric hand mixer for at least five minutes until very fluffy. Fold in half of the flour mixture, then the orange and the vanilla, then fold in the remaining flour. Mix well but not for too long.","Pour cake mixture into prepared tin and smooth out. Bake in preheated oven for 20 minutes. Reduce the oven temperature to 160 C / Gas 2 and bake again for 30 minutes Bake until the cake is golden brown and a skewer comes out clean. Cool on a wire cake rack."]'::jsonb, 'https://www.themealdb.com/images/media/meals/y4jpgq1560459207.jpg', 'themealdb'),
('Kafteji', ARRAY['tunisian', 'vegetarian']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 23, 40, 63, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Potatoes","measure":"5 Large"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Green Pepper","measure":"1"},{"name":"Onions","measure":"5"},{"name":"Ras el hanout","measure":"1 tbs"},{"name":"Pumpkin","measure":"500g"},{"name":"Eggs","measure":"24 Skinned"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}]'::jsonb, '["Peel potatoes and cut into 5cm cubes.","Pour 1-2 cm of olive oil into a large pan and heat up very hot. Fry potatoes until golden brown for 20 minutes, turning from time to time. Place on kitchen paper to drain.","Cut the peppers in half and remove seeds. Rub a little olive oil on them and place the cut side down on a baking tray. Place them under the grill. Grill until the skin is dark and bubbly. While the peppers are still hot, put them into a plastic sandwich bag and seal it. Take them out after 15 minutes and remove skins.","In the meantime, heat more olive oil another pan. Peel the onions and cut into thin rings. Fry for 15 minutes until golden brown, turning them often. Add the Ras el hanout at the end.","Cut the pumpkin into 5cm cubes and fry in the same pan you used for the potatoes for 10-15 minutes until it is soft and slightly browned. Place on kitchen paper.","Pour the remaining olive oil out of the pan and put all the cooked vegetables into the pan and mix. Whisk eggs and pour them over the vegetables. Put the lid on the pan so that the eggs cook. Put the contents of the pan onto a large chopping board, add salt and pepper and chopped and mix everything with a big knife."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1bsv1q1560459826.jpg', 'themealdb'),
('Leblebi Soup', ARRAY['tunisian', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 25, 35, 60, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Onion","measure":"1 medium finely diced"},{"name":"Chickpeas","measure":"250g"},{"name":"Vegetable Stock","measure":"1.5L"},{"name":"Cumin","measure":"1 tsp"},{"name":"Garlic","measure":"5 cloves"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Harissa Spice","measure":"1 tsp"},{"name":"Pepper","measure":"Pinch"},{"name":"Lime","measure":"1/2"}]'::jsonb, '["Heat the oil in a large pot. Add the onion and cook until translucent.","Drain the soaked chickpeas and add them to the pot together with the vegetable stock. Bring to the boil, then reduce the heat and cover. Simmer for 30 minutes.","In the meantime toast the cumin in a small ungreased frying pan, then grind them in a mortar. Add the garlic and salt and pound to a fine paste.","Add the paste and the harissa to the soup and simmer until the chickpeas are tender, about 30 minutes.","Season to taste with salt, pepper and lemon juice and serve hot."]'::jsonb, 'https://www.themealdb.com/images/media/meals/x2fw9e1560460636.jpg', 'themealdb'),
('Keleya Zaara', ARRAY['tunisian', 'lamb']::text[], ARRAY['gluten_free']::text[], 21, 40, 61, 'easy', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 4, '[{"name":"Olive Oil","measure":"4 tbs"},{"name":"Lamb","measure":"750g"},{"name":"Saffron","measure":"1 1/2 tsp"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Water","measure":"25 ml"},{"name":"Parsley","measure":"30g"},{"name":"Butter","measure":"1 tbs"},{"name":"Lemon","measure":"1"}]'::jsonb, '["Heat the vegetable oil in a large frying pan over medium-high heat. Add the lamb and cook until browned on all sides, about 5 minutes. Season with saffron, salt and pepper to taste; stir in all but 4 tablespoons of the onion, and pour in the water. Bring to the boil, then cover, reduce heat to medium-low, and simmer until the lamb is tender, about 15 minutes.","Uncover the pan, stir in the butter and allow the sauce reduce 5 to 10 minutes to desired consistency. Season to taste with salt and pepper, then pour into a serving dish. Sprinkle with the remaining chopped onions and parsley. Garnish with lemon wedges to serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8x09hy1560460923.jpg', 'themealdb'),
('Tuna and Egg Briks', ARRAY['tunisian', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 27, 45, 72, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Olive Oil","measure":"2 tbs"},{"name":"Spring Onions","measure":"8"},{"name":"Spinach","measure":"200g"},{"name":"Filo Pastry","measure":"4"},{"name":"Tuna","measure":"1 can"},{"name":"Eggs","measure":"2"},{"name":"Hotsauce","measure":"Dash"},{"name":"Tomatoes","measure":"4 Chopped"},{"name":"Cucumber","measure":"1/4"},{"name":"Lemon Juice","measure":"1 tbs"},{"name":"Apricot Jam","measure":"4 tbs"}]'::jsonb, '["Heat 2 tsp of the oil in a large saucepan and cook the spring onions over a low heat for 3 minutes or until beginning to soften. Add the spinach, cover with a tight-fitting lid and cook for a further 2–3 minutes or until tender and wilted, stirring once or twice. Tip the mixture into a sieve or colander and leave to drain and cool.","Using a saucer as a guide, cut out 24 rounds about 12.5 cm (5 in) in diameter from the filo pastry, cutting 6 rounds from each sheet. Stack the filo rounds in a pile, then cover with cling film to prevent them from drying out.","When the spinach mixture is cool, squeeze out as much excess liquid as possible, then transfer to a bowl. Add the tuna, eggs, hot pepper sauce, and salt and pepper to taste. Mix well.","Preheat the oven to 200°C (400°F, gas mark 6). Take one filo round and very lightly brush with some of the remaining oil. Top with a second round and brush with a little oil, then place a third round on top and brush with oil.","Place a heaped tbsp of the filling in the middle of the round, then fold the pastry over to make a half-moon shape. Fold in the edges, twisting them to seal, and place on a non-stick baking sheet. Repeat with the remaining pastry and filling to make 8 briks in all.","Lightly brush the briks with the remaining oil. Bake for 12–15 minutes or until the pastry is crisp and golden brown.","Meanwhile, combine the tomatoes and cucumber in a bowl and sprinkle with the lemon juice and seasoning to taste. Serve the briks hot with this salad and the chutney."]'::jsonb, 'https://www.themealdb.com/images/media/meals/2dsltq1560461468.jpg', 'themealdb'),
('Cashew Ghoriba Biscuits', ARRAY['tunisian', 'dessert']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 17, 40, 57, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Cashew Nuts","measure":"250g"},{"name":"Icing Sugar","measure":"100g"},{"name":"Egg Yolks","measure":"2"},{"name":"Orange Blossom Water","measure":"2 tbs"},{"name":"Icing Sugar","measure":"To Glaze"},{"name":"Almonds","measure":"100g"}]'::jsonb, '["Preheat the oven at 180 C / Gas 4. Line a baking tray with greaseproof paper.","In a bowl, mix the cashews and icing sugar. Add the egg yolks and orange blossom water and mix to a smooth homogeneous paste.","Take lumps of the cashew paste and shape into small balls. Roll the balls in icing sugar and transfer to the baking tray. Push an almond in the centre of each ghribia.","Bake until the biscuits are lightly golden, about 20 minutes. Keep an eye on them, they burn quickly."]'::jsonb, 'https://www.themealdb.com/images/media/meals/t3r3ka1560461972.jpg', 'themealdb'),
('Corba', ARRAY['turkish', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 31, 45, 76, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Lentils","measure":"1 cup"},{"name":"Onion","measure":"1 large"},{"name":"Carrots","measure":"1 large"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Cumin","measure":"2 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Mint","measure":"1/2 tsp"},{"name":"Thyme","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Red Pepper Flakes","measure":"1/4 tsp"},{"name":"Vegetable Stock","measure":"4 cups"},{"name":"Water","measure":"1 cup"},{"name":"Sea Salt","measure":"Pinch"}]'::jsonb, '["Pick through your lentils for any foreign debris, rinse them 2 or 3 times, drain, and set aside.  Fair warning, this will probably turn your lentils into a solid block that you’ll have to break up later","In a large pot over medium-high heat, sauté the olive oil and the onion with a pinch of salt for about 3 minutes, then add the carrots and cook for another 3 minutes.","Add the tomato paste and stir it around for around 1 minute. Now add the cumin, paprika, mint, thyme, black pepper, and red pepper as quickly as you can and stir for 10 seconds to bloom the spices. Congratulate yourself on how amazing your house now smells.","Immediately add the lentils, water, broth, and salt. Bring the soup to a (gentle) boil.","After it has come to a boil, reduce heat to medium-low, cover the pot halfway, and cook for 15-20 minutes or until the lentils have fallen apart and the carrots are completely cooked.","After the soup has cooked and the lentils are tender, blend the soup either in a blender or simply use a hand blender to reach the consistency you desire. Taste for seasoning and add more salt if necessary.","Serve with crushed-up crackers, torn up bread, or something else to add some extra thickness.  You could also use a traditional thickener (like cornstarch or flour), but I prefer to add crackers for some texture and saltiness.  Makes great leftovers, stays good in the fridge for about a week."]'::jsonb, 'https://www.themealdb.com/images/media/meals/58oia61564916529.jpg', 'themealdb'),
('Stamppot', ARRAY['netherlands', 'pork']::text[], ARRAY['gluten_free']::text[], 25, 80, 105, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Potatoes","measure":"1.5kg"},{"name":"Bay Leaf","measure":"2 leaves"},{"name":"Shallots","measure":"2"},{"name":"Butter","measure":"3 tbs"},{"name":"Kale","measure":"750g"},{"name":"Sausages","measure":"2"},{"name":"Milk","measure":"500ml"},{"name":"Nutmeg","measure":"Grated"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"}]'::jsonb, '["Wash and peel the potatoes and cut into similarly sized pieces for even cooking.","In a large soup pot, boil the potatoes and the bay leaves in salted water for 20 minutes. Discard the bay leaves.","If you''re not using a bag of ready-cut curly kale, wash the bunches thoroughly under cool running water to get rid of all soil—you wouldn''t want that gritty texture in your finished dish. Trim any coarse stems and discard any brown leaves. With a sharp knife, cut the curly kale into thin strips.","Peel and chop the shallots.","In a frying pan or skillet, melt 1 tbsp. of butter and saute the shallots for a few minutes before adding the curly kale and 2 tbsp. of water. Season and cook for about 10 minutes, or until tender.","Warm the milk on the stove or in the microwave.","Drain, shake and dry the potatoes with kitchen towels before mashing with a potato masher or ricer. Working quickly, add the warm milk and the remaining butter. Season to taste with nutmeg, salt, and pepper.","Mix the cooked curly kale through the cooked mashed potato mixture.","Top with slices of the smoked sausage and serve hot with your favorite mustard or gravy.","Serve and enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/hyarod1565090529.jpg', 'themealdb'),
('Lasagna Sandwiches', ARRAY['united_states', 'pasta']::text[], ARRAY[]::text[], 23, 30, 53, 'medium', '{"calories":600,"protein_g":22,"carbs_g":78,"fat_g":20}'::jsonb, 4, '[{"name":"Sour Cream","measure":"1/4 cup"},{"name":"Chopped Onion","measure":"2 tbs"},{"name":"Dried Oregano","measure":"1/2 tbs"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Bread","measure":"8 slices"},{"name":"Bacon","measure":"8 slices"},{"name":"Tomato","measure":"8 slices"},{"name":"Mozzarella","measure":"4 slices"},{"name":"Butter","measure":"2 1/2 Tbs"}]'::jsonb, '["In a small bowl, combine the first four ingredients; spread on four slices of bread. Layer with bacon, tomato and cheese; top with remaining bread.","In a large skillet or griddle, melt 2 tablespoons butter. Toast sandwiches until lightly browned on both sides and cheese is melted, adding butter if necessary.","Nutrition Facts","sandwich: 445 calories, 24g fat (12g saturated fat), 66mg cholesterol, 1094mg sodium, 35g carbohydrate (3g sugars, 2g fiber), 21g protein."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xr0n4r1576788363.jpg', 'themealdb'),
('Classic Christmas pudding', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 27, 60, 87, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Almonds","measure":"50g"},{"name":"Bramley Apples","measure":"2 large"},{"name":"Candied Peel","measure":"200g"},{"name":"Nutmeg","measure":"1 whole"},{"name":"Raisins","measure":"1kg"},{"name":"Plain Flour","measure":"140g"},{"name":"Breadcrumbs","measure":"100g"},{"name":"Muscovado Sugar","measure":"100g"},{"name":"Eggs","measure":"3 Large"},{"name":"Brandy","measure":"2 tbs"},{"name":"Butter","measure":"250g"}]'::jsonb, '["Get everything for the pudding prepared. Chop the almonds coarsely. Peel, core and chop the cooking apples. Sharpen your knife and chop the candied peel. (You can chop the almonds and apples in a food processor, but the peel must be done by hand.) Grate three quarters of the nutmeg (sounds a lot but it''s correct).","Mix the almonds, apples, candied peel, nutmeg, raisins, flour, breadcrumbs, light muscovado sugar, eggs and 2 tbsp brandy or cognac in a large bowl.","Holding the butter in its wrapper, grate a quarter of it into the bowl, then stir everything together. Repeat until all the butter is grated, then stir for 3-4 mins – the mixture is ready when it subsides slightly after each stir. Ask the family to stir too, and get everyone to make a wish.","Generously butter two 1.2 litre bowls and put a circle of baking parchment in the bottom of each. Pack in the pudding mixture. Cover with a double layer of baking parchment, pleating it to allow for expansion, then tie with string (keep the paper in place with a rubber band while tying). Trim off any excess paper.","Now stand each bowl on a large sheet of foil and bring the edges up over the top, then put another sheet of foil over the top and bring it down underneath to make a double package (this makes the puddings watertight). Tie with more string, and make a handle for easy lifting in and out of the pan. Watch our video to see how to tie up a pudding correctly.","Boil or oven steam the puddings for 8 hrs, topping up with water as necessary. Remove from the pans and leave to cool overnight. When cold, discard the messy wrappings and re-wrap in new baking parchment, foil and string. Store in a cool, dry place until Christmas.","To make the brandy butter, cream the butter with the orange zest and icing sugar. Gradually beat in the brandy or cognac and chopped stem ginger. Put in a small bowl, fork the top attractively and put in the fridge to set. The butter will keep for a week in the fridge, or it can be frozen for up to six weeks.","On Christmas Day, boil or oven steam for 1 hr. Unwrap and turn out. To flame, warm 3-4 tbsp brandy in a small pan, pour it over the pudding and set light to it."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1d85821576790598.jpg', 'themealdb'),
('Christmas cake', ARRAY['british', 'dessert']::text[], ARRAY['vegetarian']::text[], 37, 35, 72, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Butter","measure":"200g"},{"name":"Muscovado Sugar","measure":"200g"},{"name":"Plain Flour","measure":"200g"},{"name":"Eggs","measure":"4 Beaten"},{"name":"Ground Almonds","measure":"50g"},{"name":"Sherry","measure":"100ml"},{"name":"Candied Peel","measure":"85g"},{"name":"Glace Cherry","measure":"85g"},{"name":"Raisins","measure":"250g"},{"name":"Currants","measure":"250g"},{"name":"Pecan Nuts","measure":"100g"},{"name":"Lemon","measure":"Grated zest of 1"},{"name":"Mixed Spice","measure":"1 ½ tbsp"},{"name":"Rose water","measure":"1 ½ tbsp"},{"name":"Vanilla Extract","measure":"1/2 tsp"},{"name":"Baking Powder","measure":"1/2 tsp"}]'::jsonb, '["Heat oven to 160C/fan 140C/gas 3. Line the base and sides of a 20 cm round, 7.5 cm deep cake tin. Beat the butter and sugar with an electric hand mixer for 1-2 mins until very creamy and pale in colour, scraping down the sides of the bowl half way through. Stir in a spoonful of the flour, then stir in the beaten egg and the rest of the flour alternately, a quarter at a time, beating well each time with a wooden spoon. Stir in the almonds.","Mix in the sherry (the mix will look curdled), then add the peel, cherries, raisins, cherries, nuts, lemon zest, spice, rosewater and vanilla. Beat together to mix, then stir in the baking powder.","Spoon mixture into the tin and smooth the top, making a slight dip in the centre. Bake for 30 mins, then lower temperature to 150C/fan 130C/gas 2 and bake a further 2-2¼ hrs, until a skewer insterted in the middle comes out clean. Leave to cool in the tin, then take out of the tin and peel off the lining paper. When completely cold, wrap well in cling film and foil to store until ready to decorate. The cake will keep for several months."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ldnrm91576791881.jpg', 'themealdb'),
('Honey Balsamic Chicken with Crispy Broccoli & Potatoes', ARRAY['united_states', 'chicken']::text[], ARRAY['gluten_free']::text[], 25, 45, 70, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Potatoes","measure":"5"},{"name":"Broccoli","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Chicken Breast","measure":"2"},{"name":"Balsamic Vinegar","measure":""},{"name":"Honey","measure":""},{"name":"Chicken Stock","measure":""},{"name":"Butter","measure":"1 tbsp"},{"name":"Vegetable Oil","measure":"1 tbsp"},{"name":"Olive Oil","measure":"1 tbsp"}]'::jsonb, '["Servings","Preheat oven to 425 degrees. Wash and dry all produce. Cut potatoes into 1/2-inch-thick wedges. Toss on one side of a baking sheet with a drizzle of oil, salt, and pepper. (For 4 servings, spread potatoes out across entire sheet.) Roast on top rack for 5 minutes (we''ll add the broccoli then).","Meanwhile, cut broccoli florets into bite-size pieces, if necessary. Peel and finely chop garlic. In a small microwave-safe bowl, combine 1 TBSP olive oil (2 TBSP for 4 servings) and half the garlic. Microwave until garlic sizzles, 30 seconds.","Once potatoes have roasted 5 minutes, remove sheet from oven and add broccoli to empty side; carefully toss with garlic oil, salt, and pepper. (For 4 servings, add broccoli to a second sheet.) Continue roasting until potatoes and broccoli are browned and crispy, 15-20 minutes more.","While veggies roast, pat chicken dry with paper towels; season all over with salt and pepper. Heat a drizzle of oil in a large pan over medium-high heat. Add chicken and cook until browned and cooked through, 5-6 minutes per side. (If chicken browns too quickly, reduce heat to medium.) Turn off heat; set chicken aside to rest. Wash out pan.","Heat pan used for chicken over medium-high heat. Add a drizzle of oil and remaining garlic; cook until fragrant, 30 seconds. Stir in vinegar, honey, stock concentrate, and 1/4 cup water (1/3 cup for 4 servings). Simmer until thick and glossy, 2-3 minutes. Remove from heat and stir in 1 TBSP butter (2 TBSP for 4). Season with salt and pepper.","Return chicken to pan and turn to coat in glaze. Divide chicken, broccoli, and potatoes between plates. Spoon any remaining glaze over chicken and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/kvbotn1581012881.jpg', 'themealdb'),
('BBQ Pork Sloppy Joes', ARRAY['united_states', 'pork']::text[], ARRAY['dairy_free']::text[], 31, 60, 91, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Potatoes","measure":"2"},{"name":"Red Onions","measure":"1"},{"name":"Garlic","measure":"2 cloves"},{"name":"Lime","measure":"1"},{"name":"Bread","measure":"2"},{"name":"Pork","measure":"1 lb"},{"name":"Barbeque Sauce","measure":""},{"name":"Hotsauce","measure":""},{"name":"Tomato Ketchup","measure":""},{"name":"Sugar","measure":""},{"name":"Vegetable Oil","measure":""},{"name":"Salt","measure":""},{"name":"Pepper","measure":""}]'::jsonb, '["Preheat oven to 450 degrees. Wash and dry all produce. Cut sweet potatoes into ½-inch-thick wedges. Toss on a baking sheet with a drizzle of oil, salt, and pepper. Roast until browned and tender, 20-25 minutes.","Meanwhile, halve and peel onion. Slice as thinly as possible until you have ¼ cup (½ cup for 4 servings); finely chop remaining onion. Peel and finely chop garlic. Halve lime; squeeze juice into a small bowl. Halve buns. Add 1 TBSP butter (2 TBSP for 4) to a separate small microwave-safe bowl; microwave until melted, 30 seconds. Brush onto cut sides of buns.","To bowl with lime juice, add sliced onion, ¼ tsp sugar (½ tsp for 4 servings), and a pinch of salt. Stir to combine; set aside to quick-pickle.","Heat a drizzle of oil in a large pan over medium-high heat. Add chopped onion and season with salt and pepper. Cook, stirring, until softened, 4-5 minutes. Add garlic and cook until fragrant, 30 seconds more. Add pork and season with salt and pepper. Cook, breaking up meat into pieces, until browned and cooked through, 4-6 minutes.","While pork cooks, in a third small bowl, combine BBQ sauce, pickling liquid from onion, 3 TBSP ketchup (6 TBSP for 4 servings), ½ tsp sugar (1 tsp for 4), and ¼ cup water (⅓ cup for 4). Once pork is cooked through, add BBQ sauce mixture to pan. Cook, stirring, until sauce is thickened, 2-3 minutes. Taste and season with salt and pepper.","Meanwhile, toast buns in oven or toaster oven until golden, 3-5 minutes. Divide toasted buns between plates and fill with as much BBQ pork as you’d like. Top with pickled onion and hot sauce. Serve with sweet potato wedges on the side."]'::jsonb, 'https://www.themealdb.com/images/media/meals/atd5sh1583188467.jpg', 'themealdb'),
('Beef Banh Mi Bowls with Sriracha Mayo, Carrot & Pickled Cucumber', ARRAY['vietnamese', 'beef']::text[], ARRAY['dairy_free']::text[], 21, 60, 81, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Rice","measure":"White"},{"name":"Onion","measure":"1"},{"name":"Lime","measure":"1"},{"name":"Garlic Clove","measure":"3"},{"name":"Cucumber","measure":"1"},{"name":"Carrots","measure":"3 oz"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Soy Sauce","measure":"2 oz"}]'::jsonb, '["Add''l ingredients: mayonnaise, siracha","Place rice in a fine-mesh sieve and rinse until water runs clear. Add to a small pot with 1 cup water (2 cups for 4 servings) and a pinch of salt. Bring to a boil, then cover and reduce heat to low. Cook until rice is tender, 15 minutes. Keep covered off heat for at least 10 minutes or until ready to serve.","Meanwhile, wash and dry all produce. Peel and finely chop garlic. Zest and quarter lime (for 4 servings, zest 1 lime and quarter both). Trim and halve cucumber lengthwise; thinly slice crosswise into half-moons. Halve, peel, and medium dice onion. Trim, peel, and grate carrot.","In a medium bowl, combine cucumber, juice from half the lime, ¼ tsp sugar (½ tsp for 4 servings), and a pinch of salt. In a small bowl, combine mayonnaise, a pinch of garlic, a squeeze of lime juice, and as much sriracha as you’d like. Season with salt and pepper.","Heat a drizzle of oil in a large pan over medium-high heat. Add onion and cook, stirring, until softened, 4-5 minutes. Add beef, remaining garlic, and 2 tsp sugar (4 tsp for 4 servings). Cook, breaking up meat into pieces, until beef is browned and cooked through, 4-5 minutes. Stir in soy sauce. Turn off heat; taste and season with salt and pepper.","Fluff rice with a fork; stir in lime zest and 1 TBSP butter. Divide rice between bowls. Arrange beef, grated carrot, and pickled cucumber on top. Top with a squeeze of lime juice. Drizzle with sriracha mayo."]'::jsonb, 'https://www.themealdb.com/images/media/meals/z0ageb1583189517.jpg', 'themealdb'),
('Vegetable Shepherds Pie', ARRAY['irish', 'beef']::text[], ARRAY['vegetarian']::text[], 43, 100, 143, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Potatoes","measure":"3 Lbs"},{"name":"Small Potatoes","measure":"3 Lbs"},{"name":"Salted Butter","measure":"1/2 cup"},{"name":"Mushrooms","measure":"1 oz"},{"name":"Brown Lentils","measure":"3/4 cup"},{"name":"Garlic","measure":"6 cloves"},{"name":"Kosher Salt","measure":"1 tsp"},{"name":"Onion","measure":"3 cups"},{"name":"Tomato Puree","measure":"2 tbsp"},{"name":"Bay Leaves","measure":""},{"name":"Olive Oil","measure":""},{"name":"Dry White Wine","measure":"2 cups"},{"name":"Vegetable Stock","measure":"8 cups"},{"name":"Cornstarch","measure":"2 tbsp"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Rosemary","measure":"2 sprigs"},{"name":"Parsley","measure":""},{"name":"Sage","measure":""},{"name":"Chives","measure":""}]'::jsonb, '["Add Ingredients:","cups chopped mixed vegetables","cup chopped fresh mushrooms","cup pearl onions","TOPPING:","Preheat oven to 450°. Bake potatoes on a foil-lined baking sheet until tender, about 45 minutes. Let cool slightly, then peel. Press potatoes through a ricer, food mill, or colander into a large bowl. Add butter; stir until well blended. Stir in milk. Season to taste with salt.","FILLING:","Soak dried porcini in 3 cups hot water; set aside. Combine lentils, 1 garlic clove, 1 tsp. salt, and 4 cups water in a medium saucepan. Bring to a boil; reduce heat and simmer, stirring occasionally, until lentils are tender but not mushy, 15–20 minutes. Drain lentils and discard garlic.","Heat 3 Tbsp. oil in a large heavy pot over medium heat. Add onions and cook, stirring occasionally, until soft, about 12 minutes. Add chopped garlic and cook for 1 minute. Stir in tomato paste. Cook, stirring constantly, until tomato paste is caramelized, 2–3 minutes.","Add bay leaves and wine; stir, scraping up any browned bits. Stir in porcini, slowly pouring porcini soaking liquid into pan but leaving any sediment behind. Bring to a simmer and cook until liquid is reduced by half, about 10 minutes. Stir in broth and cook, stirring occasionally, until reduced by half, about 45 minutes.","Strain mixture into a large saucepan and bring to a boil; discard solids in strainer. Stir cornstarch and 2 Tbsp. water in a small bowl to dissolve. Add cornstarch mixture; simmer until thickened, about 5 minutes. Whisk in miso. Season sauce with salt and pepper. Set aside.","Preheat oven to 450°. Toss vegetables and pearl onions with remaining 2 Tbsp. oil, 5 garlic cloves, and rosemary sprigs in a large bowl; season with salt and pepper. Divide between 2 rimmed baking sheets. Roast, stirring once, until tender, 20–25 minutes. Transfer garlic cloves to a small bowl; mash well with a fork and stir into sauce. Discard rosemary. DO AHEAD: Lentils, sauce, and vegetables can be made 1 day ahead. Cover separately; chill.","Arrange lentils in an even layer in a 3-qt. baking dish; set dish on a foil-lined rimmed baking sheet. Toss roasted vegetables with fresh mushrooms and chopped herbs; layer on top of lentils. Pour sauce over vegetables. Spoon potato mixture evenly over.","Bake until browned and bubbly, about 30 minutes. Let stand for 15 minutes before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/w8umt11583268117.jpg', 'themealdb'),
('Honey Yogurt Cheesecake', ARRAY['greek', 'dessert']::text[], ARRAY['vegetarian']::text[], 25, 35, 60, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Digestive Biscuits","measure":"100g"},{"name":"Almonds","measure":"85g"},{"name":"Butter","measure":"85g"},{"name":"Greek Yogurt","measure":"250ml"},{"name":"Mascarpone","measure":"750g"},{"name":"Eggs","measure":"2"},{"name":"Lemon","measure":"Zest of 1"},{"name":"Orange","measure":"Zest of 1"},{"name":"Honey","measure":"250ml"},{"name":"Fruit Mix","measure":"To serve"}]'::jsonb, '["Heat oven to 160C/140C fan/gas 3. Crush the biscuits and most of the almonds inside a plastic food bag using a rolling pin. Mix with the butter, then press into the bottom of a deep, oval, 23cm dish (or something similar in size – a roasting tin, baking dish or cake tin will work). Bake for 10 mins until crisp.","Stir or mash together the yogurt and mascarpone, then whisk in the eggs, one at a time. Stir in the lemon and orange zests, then stir in most of the honey, reserving about 3 tbsp. Spread over the biscuit base, cover loosely with foil and cook for 1 hr. Remove the foil and cook for 15 mins more until lightly golden and the top is firm with just the slightest wobble in the middle. Leave to cool. Can be kept in the fridge for up to 2 days.","To serve, scatter with almonds, drizzle over the remaining honey, and hand around fresh fruit to go with it."]'::jsonb, 'https://www.themealdb.com/images/media/meals/y2irzl1585563479.jpg', 'themealdb'),
('Stuffed Lamb Tomatoes', ARRAY['greek', 'lamb']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 31, 45, 76, 'medium', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 4, '[{"name":"Tomatoes","measure":"4 large"},{"name":"Sugar","measure":"Pinch"},{"name":"Olive Oil","measure":"4 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic Clove","measure":"2 finely chopped"},{"name":"Lamb","measure":"200g"},{"name":"Cinnamon","measure":"1 tbs"},{"name":"Tomato Puree","measure":"2 tbs chopped"},{"name":"Rice","measure":"50g"},{"name":"Chicken Stock","measure":"100ml"},{"name":"Dill","measure":"4 tbs"},{"name":"Chopped Parsley","measure":"2 tbs"},{"name":"Mint","measure":"1 tbs"}]'::jsonb, '["Heat oven to 180C/160C fan/gas 4. Slice the tops off the tomatoes and reserve. Scoop out most of the pulp with a teaspoon, being careful not to break the skin. Finely chop the pulp, and keep any juices. Sprinkle the insides of the tomatoes with a little sugar to take away the acidity, then place them on a baking tray.","Heat 2 tbsp olive oil in a large frying pan, add the onion and garlic, then gently cook for about 10 mins until soft but not coloured. Add the lamb, cinnamon and tomato purée, turn up the heat, then fry until the meat is browned. Add the tomato pulp and juice, the rice and the stock. Season generously. Bring to the boil, then simmer for 15 mins or until the rice is tender and the liquid has been absorbed. Set aside to cool a little, then stir in the herbs.","Stuff the tomatoes up to the brim, top tomatoes with their lids, drizzle with 2 tbsp more olive oil, sprinkle 3 tbsp water into the tray, then bake for 35 mins. Serve with salad and crusty bread, hot or cold."]'::jsonb, 'https://www.themealdb.com/images/media/meals/u55lbp1585564013.jpg', 'themealdb'),
('Lamb Tzatziki Burgers', ARRAY['greek', 'lamb']::text[], ARRAY[]::text[], 27, 45, 72, 'medium', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 4, '[{"name":"Bulgur Wheat","measure":"25g"},{"name":"Lamb Mince","measure":"500g"},{"name":"Cumin","measure":"1 tsp"},{"name":"Coriander","measure":"1 tsp"},{"name":"Paprika","measure":"1 tsp"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Olive Oil","measure":"For frying"},{"name":"Bun","measure":"4"},{"name":"Cucumber","measure":"Grated"},{"name":"Greek Yogurt","measure":"200g"},{"name":"Mint","measure":"2 tbs"}]'::jsonb, '["Tip the bulghar into a pan, cover with water and boil for 10 mins. Drain really well in a sieve, pressing out any excess water.","To make the tzatziki, squeeze and discard the juice from the cucumber, then mix into the yogurt with the chopped mint and a little salt.","Work the bulghar into the lamb with the spices, garlic (if using) and seasoning, then shape into 4 burgers. Brush with a little oil and fry or barbecue for about 5 mins each side until cooked all the way through. Serve in the buns (toasted if you like) with the tzatziki, tomatoes, onion and a few mint leaves."]'::jsonb, 'https://www.themealdb.com/images/media/meals/k420tj1585565244.jpg', 'themealdb'),
('Krispy Kreme Donut', ARRAY['united_states', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 40, 73, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Yeast","measure":"1/4 ounce"},{"name":"Water","measure":"1/4 cup"},{"name":"Water","measure":"1 1/2 cups"},{"name":"Sugar","measure":"1/2 cup"},{"name":"Salt","measure":"1 tsp"},{"name":"Eggs","measure":"2"},{"name":"Shortening","measure":"1/3 cup"},{"name":"Flour","measure":"5 drops"},{"name":"Canola Oil","measure":"Sprinking"},{"name":"Milk","measure":"1/2 cup"},{"name":"Sugar","measure":"2 cups"},{"name":"Vanilla","measure":"1 1/2 cups"},{"name":"Boiling Water","measure":"6 tablespoons"},{"name":"Butter","measure":"1/3 cup"}]'::jsonb, '["Dissolve yeast in warm water in 2 1/2-quart bowl. Add milk, sugar, salt, eggs, shortening and 2 cups flour. Beat on low for 30 seconds, scraping bowl constantly. Beat on medium speed for 2 minutes, scraping bowl occasionally. Stir in remaining flour until smooth. Cover and let rise until double, 50-60 minutes. (Dough is ready when indentation remains when touched.) Turn dough onto floured surface; roll around lightly to coat with flour. Gently roll dough 1/2-inch thick with floured rolling pin. Cut with floured doughnut cutter. Cover and let rise until double, 30-40 minutes.","Heat vegetable oil in deep fryer to 350°. Slide doughnuts into hot oil with wide spatula. Turn doughnuts as they rise to the surface. Fry until golden brown, about 1 minute on each side. Remove carefully from oil (do not prick surface); drain. Dip the doughnuts into creamy glaze set on rack.","Glaze:","Heat butter until melted. Remove from heat. Stir in powdered sugar and vanilla until smooth. Stir in water, 1 tablespoon at a time, until desired consistency."]'::jsonb, 'https://www.themealdb.com/images/media/meals/4i5cnx1587672171.jpg', 'themealdb'),
('Bigos (Hunters Stew)', ARRAY['polish', 'pork']::text[], ARRAY['dairy_free']::text[], 45, 60, 105, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"Bacon","measure":"2 sliced"},{"name":"Kielbasa","measure":"1 lb"},{"name":"Pork","measure":"1 lb"},{"name":"Flour","measure":"1/4 cup"},{"name":"Garlic","measure":"3 chopped"},{"name":"Onion","measure":"1 Diced"},{"name":"Mushrooms","measure":"1 1/2 cup"},{"name":"Cabbage","measure":"4 cups"},{"name":"Sauerkraut","measure":"1 Jar"},{"name":"Red Wine","measure":"1/4 cup"},{"name":"Bay Leaf","measure":"1"},{"name":"Basil","measure":"1 tsp"},{"name":"Marjoram","measure":"1 tsp"},{"name":"Paprika","measure":"1 tbs"},{"name":"Caraway Seed","measure":"1/8 teaspoon"},{"name":"Hotsauce","measure":"1 dash"},{"name":"Beef Stock","measure":"5 Cups"},{"name":"Tomato Puree","measure":"2 tbs"},{"name":"Diced Tomatoes","measure":"1 cup"},{"name":"Worcestershire Sauce","measure":"1 dash"}]'::jsonb, '["Preheat the oven to 350 degrees F (175 degrees C).","Heat a large pot over medium heat. Add the bacon and kielbasa; cook and stir until the bacon has rendered its fat and sausage is lightly browned. Use a slotted spoon to remove the meat and transfer to a large casserole or Dutch oven.","Coat the cubes of pork lightly with flour and fry them in the bacon drippings over medium-high heat until golden brown. Use a slotted spoon to transfer the pork to the casserole. Add the garlic, onion, carrots, fresh mushrooms, cabbage and sauerkraut. Reduce heat to medium; cook and stir until the carrots are soft, about 10 minutes. Do not let the vegetables brown.","Deglaze the pan by pouring in the red wine and stirring to loosen all of the bits of food and flour that are stuck to the bottom. Season with the bay leaf, basil, marjoram, paprika, salt, pepper, caraway seeds and cayenne pepper; cook for 1 minute.","Mix in the dried mushrooms, hot pepper sauce, Worcestershire sauce, beef stock, tomato paste and tomatoes. Heat through just until boiling. Pour the vegetables and all of the liquid into the casserole dish with the meat. Cover with a lid.","Bake in the preheated oven for 2 1/2 to 3 hours, until meat is very tender."]'::jsonb, 'https://www.themealdb.com/images/media/meals/md8w601593348504.jpg', 'themealdb'),
('Pierogi (Polish Dumplings)', ARRAY['polish', 'side']::text[], ARRAY['vegetarian']::text[], 27, 35, 62, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Butter","measure":"2 tbs"},{"name":"Chopped Onion","measure":"1/3 cup"},{"name":"Sauerkraut","measure":"1 1/2 cups"},{"name":"Butter","measure":"3 tbs"},{"name":"Chopped Onion","measure":"1/2 cup"},{"name":"Potatoes","measure":"2 cups"},{"name":"Eggs","measure":"3"},{"name":"Sour Cream","measure":"1 pot"},{"name":"Flour","measure":"3 cups"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Baking Powder","measure":"1 tbs"}]'::jsonb, '["To prepare the sauerkraut filling, melt the butter in a skillet over medium heat. Stir in the onion, and cook until translucent, about 5 minutes. Add the drained sauerkraut and cook for an additional 5 minutes. Season to taste with salt and pepper, then remove to a plate to cool.","For the mashed potato filling, melt the butter in a skillet over medium heat. Stir in the onion, and cook until translucent, about 5 minutes. Stir into the mashed potatoes, and season with salt and white pepper.","To make the dough, beat together the eggs and sour cream until smooth. Sift together the flour, salt, and baking powder; stir into the sour cream mixture until dough comes together. Knead the dough on a lightly floured surface until firm and smooth. Divide the dough in half, then roll out one half to 1/8 inch thickness. Cut into 3 inch rounds using a biscuit cutter.","Place a small spoonful of the mashed potato filling into the center of each round. Moisten the edges with water, fold over, and press together with a fork to seal. Repeat procedure with the remaining dough and the sauerkraut filling.","Bring a large pot of lightly salted water to a boil. Add perogies and cook for 3 to 5 minutes or until pierogi float to the top. Remove with a slotted spoon."]'::jsonb, 'https://www.themealdb.com/images/media/meals/45xxr21593348847.jpg', 'themealdb'),
('Golabki (cabbage roll)', ARRAY['polish', 'beef']::text[], ARRAY['gluten_free']::text[], 25, 70, 95, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Cabbage","measure":"1"},{"name":"Butter","measure":"2 tbs"},{"name":"Onion","measure":"1 chopped"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Ground Pork","measure":"1/2 lb"},{"name":"Rice","measure":"1 1/2 cups"},{"name":"Garlic","measure":"1 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Tomato Puree","measure":"3 cans"}]'::jsonb, '["Bring a large pot of lightly salted water to a boil. Place cabbage head into water, cover pot, and cook until cabbage leaves are slightly softened enough to remove from head, 3 minutes. Remove cabbage from pot and let cabbage sit until leaves are cool enough to handle, about 10 minutes.","Remove 18 whole leaves from the cabbage head, cutting out any thick tough center ribs. Set whole leaves aside. Chop the remainder of the cabbage head and spread it in the bottom of a casserole dish.","Melt butter in a large skillet over medium-high heat. Cook and stir onion in hot butter until tender, 5 to 10 minutes. Cool.","Stir onion, beef, pork, rice, garlic, 1 teaspoon salt, and 1/4 teaspoon pepper together in a large bowl.","Preheat oven to 350 degrees F (175 degrees C).","Place about 1/2 cup beef mixture on a cabbage leaf. Roll cabbage around beef mixture, tucking in sides to create an envelope around the meat. Repeat with remaining leaves and meat mixture. Place cabbage rolls in a layer atop the chopped cabbage in the casserole dish; season rolls with salt and black pepper.","Whisk tomato soup, tomato juice, and ketchup together in a bowl. Pour tomato soup mixture over cabbage rolls and cover dish wish aluminum foil.","Bake in the preheated oven until cabbage is tender and meat is cooked through, about 1 hour."]'::jsonb, 'https://www.themealdb.com/images/media/meals/q8sp3j1593349686.jpg', 'themealdb'),
('Rogaliki (Polish Croissant Cookies)', ARRAY['polish', 'dessert']::text[], ARRAY['vegetarian']::text[], 17, 65, 82, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Butter","measure":"1 cup"},{"name":"Egg Yolks","measure":"3"},{"name":"Cream Cheese","measure":"8 oz"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Flour","measure":"3 cups"},{"name":"Jam","measure":"1 Jar"}]'::jsonb, '["In a medium bowl mix egg yolks, philly cheese and baking powder using a hand held mixer. Carefully start adding the flour. When the mixture will not be mixing well, and will look like wood chips, put away the blending mixer and using your hands knead the dough.","Create a roll and cover in foil and freeze for 15 minutes. At this time preheat the oven to 375.","Take the dough out and separate into two. Roll and cut out 3 inch trangles.","Make as many as you can and on centre of each put a small spoon of jam. Roll them into a croissant shape.","Place the croissants onto a greased cookie sheet, and bake for 10-12 minutes or until golden.","Repeat with the rest of the dough.","When you take them out, put aside and sprinkle with powdered sugar on top.","This makes about 3 batches of 20 cookies each.","Total count about 60 cookies."]'::jsonb, 'https://www.themealdb.com/images/media/meals/7mxnzz1593350801.jpg', 'themealdb'),
('Tamiya', ARRAY['egyptian', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 23, 35, 58, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Broad Beans","measure":"3 cups"},{"name":"Spring Onions","measure":"6"},{"name":"Garlic Clove","measure":"4"},{"name":"Parsley","measure":"1/4 cup"},{"name":"Cumin","measure":"2 tsp"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Cayenne Pepper","measure":"1/2 tsp"},{"name":"Flour","measure":"Spinkling"},{"name":"Vegetable Oil","measure":"As required"}]'::jsonb, '["oak the beans in water to cover overnight.Drain. If skinless beans are unavailable, rub to loosen the skins, then discard the skins. Pat the beans dry with a towel.","Grind the beans in a food mill or meat grinder.If neither appliance is available, process them in a food processor but only until the beans form a paste. (If blended too smoothly, the batter tends to fall apart during cooking.) Add the scallions, garlic, cilantro, cumin, baking powder, cayenne, salt, pepper, and coriander, if using.  Refrigerate for at least 30 minutes.","Shape the bean mixture into 1-inch balls.Flatten slightly and coat with flour.","Heat at least 1½-inches of oil over medium heat to 365 degrees.","Fry the patties in batches, turning once, until golden brown on all sides, about 5 minutes.Remove with a wire mesh skimmer or slotted spoon. Serve as part of a meze or in pita bread with tomato-cucumber salad and tahina sauce."]'::jsonb, 'https://www.themealdb.com/images/media/meals/n3xxd91598732796.jpg', 'themealdb'),
('Koshari', ARRAY['egyptian', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 21, 45, 66, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Brown Lentils","measure":"1 1/2 cups"},{"name":"Rice","measure":"1 1/2 cups"},{"name":"Coriander","measure":"1/2 tsp"},{"name":"Macaroni","measure":"2 cups"},{"name":"Chickpeas","measure":"Can"},{"name":"Onion","measure":"1 large"},{"name":"Salt","measure":"Sprinking"},{"name":"Vegetable Oil","measure":"1/2 cup"}]'::jsonb, '["Cook the lentils. Bring lentils and 4 cups of water to a boil in a medium pot or saucepan over high heat. Reduce the heat to low and cook until lentils are just tender (15-17 minutes). Drain from water and season with a little salt. (Note: when the lentils are ready, they should not be fully cooked. They should be only par-cooked and still have a bite to them as they need to finish cooking with the rice).","Now, for the rice. Drain the rice from its soaking water. Combine the par-cooked lentils and the rice in the saucepan over medium-high heat with 1 tbsp cooking oil, salt, pepper, and coriander. Cook for 3 minutes, stirring regularly. Add warm water to cover the rice and lentil mixture by about 1 1/2 inches (you’ll probably use about 3 cups of water here). Bring to a boil; the water should reduce a bit. Now cover and cook until all the liquid has been absorbed and both the rice and lentils are well cooked through (about 20 minutes).  Keep covered and undisturbed for 5 minutes or so.","Now make the pasta. While the rice and lentils are cooking, make the pasta according to package instructions by adding the elbow pasta to boiling water with a dash of salt and a little oil. Cook until the pasta is al dente. Drain.","Cover the chickpeas and warm in the microwave briefly before serving.","Make the crispy onion topping.","Sprinkle the onion rings with salt, then toss them in the flour to coat. Shake off excess flour.","In a large skillet, heat the cooking oil over medium-high heat, cook the onion rings, stirring often, until they turn a nice caramelized brown. Onions must be crispy, but not burned (15-20 minutes)."]'::jsonb, 'https://www.themealdb.com/images/media/meals/4er7mj1598733193.jpg', 'themealdb'),
('Shawarma', ARRAY['egyptian', 'chicken']::text[], ARRAY[]::text[], 35, 60, 95, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Chicken Thighs","measure":"1 kg"},{"name":"Coriander","measure":"1 tbs"},{"name":"Cumin","measure":"1 tbs"},{"name":"Cardamom","measure":"1 tbs"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Paprika","measure":"2 tsp"},{"name":"Lemon Juice","measure":"2 tbs"},{"name":"Olive Oil","measure":"3 tbs"},{"name":"Greek Yogurt","measure":"1 cup"},{"name":"Garlic Clove","measure":"1"},{"name":"Cumin","measure":"1 tsp"},{"name":"Lemon Juice","measure":"Splash"},{"name":"Lettuce","measure":"Sliced"},{"name":"Tomato","measure":"Sliced"},{"name":"Pita Bread","measure":"6"}]'::jsonb, '["Combine the marinade ingredients in a large ziplock bag (or bowl).","Add the chicken and use your hands to make sure each piece is coated. If using a ziplock bag, I find it convenient to close the bag then massage the bag to disperse the rub all over each chicken piece.","Marinate overnight or up to 24 hours.","Combine the Yoghurt Sauce ingredients in a bowl and mix. Cover and put in the fridge until required (it will last for 3 days in the fridge).","Heat grill/BBQ (or large heavy based pan on stove) on medium high. You should not need to oil it because the marinade has oil in it and also thigh fillets have fat. But if you are worried then oil your hotplate/grill. (See notes for baking)","Place chicken on the grill and cook the first side for 4 to 5 minutes until nicely charred, then turn and cook the other side for 3 to 4 minutes (the 2nd side takes less time).","Remove chicken from the grill and cover loosely with foil. Set aside to rest for 5 minutes.","TO SERVE","Slice chicken and pile onto platter alongside flatbreads, Salad and the Yoghurt Sauce.","To make a wrap, get a piece of flatbread and smear with Yoghurt Sauce. Top with a bit of lettuce and tomato and Chicken Shawarma. Roll up and enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/kcv6hj1598733479.jpg', 'themealdb'),
('Mulukhiyah', ARRAY['egyptian', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 19, 80, 99, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Mulukhiyah","measure":"800g"},{"name":"Onion","measure":"1 chopped"},{"name":"Beef","measure":"300g"},{"name":"Salt","measure":"1 tsp"},{"name":"Water","measure":"1 Litre"},{"name":"Garlic Clove","measure":"1"},{"name":"Olive Oil","measure":"1/2 cup"}]'::jsonb, '["Saute the onions in the 3-4 tablespoons olive oil","Add the beef cubes or the chicken cutlets, sear for 3-4 min on each side","Add 1 liter of water or just enough to cover the meat","Cook over medium heat until the meat is done (I usually do this in the pressure cooker and press them for 5 min)","Add the frozen mulukhyia and stir until it thaws completely and then comes to a boil","In another pan add the 1/4 to 1/2 cup of olive oil and the cloves of garlic and cook over medium low heat until you can smell the garlic (don’t brown it, it will become bitter)","Add the oil and garlic to the mulukhyia and lower the heat and simmer for 5-10 minutes","Add salt to taste","Serve with a generous amount of lemon juice.","You can serve it with some short grain rice or some pita bread"]'::jsonb, 'https://www.themealdb.com/images/media/meals/x372ug1598733932.jpg', 'themealdb'),
('Egyptian Fatteh', ARRAY['egyptian', 'beef']::text[], ARRAY[]::text[], 35, 70, 105, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef","measure":"1lb"},{"name":"Onion","measure":"1"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Tomatoes","measure":"2"},{"name":"Garlic Clove","measure":"4"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Rice","measure":"2 cups"},{"name":"Noodles","measure":"1/4 cup"},{"name":"Butter","measure":"1/4 cup"},{"name":"Olive Oil","measure":"2 cups"},{"name":"Pita Bread","measure":"1"},{"name":"Cumin","measure":"1 tbs"},{"name":"White Wine Vinegar","measure":"3 tbs"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}]'::jsonb, '["To prepare bread for bottom of dish: Take pita bread and rip into bite size pieces. In a frying pan, add about a 1/4 stick of butter, add bread pieces and fry until golden brown and crisp. Put these pieces in a glass baking dish, preferably a square sized dish. Set aside.","Then add to same pan, a little more butter, salt, approximately 2 cloves of crushed fresh garlic, and a teaspoon or so of cumin stir around a bit until you can smell aroma, then add fried bread pieces to this mixture, stir to coat bread and put back into glass baking dish. Set aside.","To prepare meat: put some butter in a pot, stir fry meat until brown, add 1 onion quartered, salt & pepper, 1 cube of chicken bouillon and water to cover meat. Bring to a boil, turn down to simmer, cover and cook until tender, approximately 2 hours. After meat has cooled, take out chunks of meat and put in a bowl, set aside. Reserve soup from the meat separately.","To prepare the rice: Put some butter into a pot, add shareya (fideo noodles) like a handful or so, keep stirring until golden brown, not too dark, but very golden. Then add two cups of rice, stir a little bit until some of the rice turns an opaque white. Add 2-1/4 cups of water and salt to taste. Bring to a boil, cover and turn down to simmer, cook until tender. Test the rice tenderness after about 35 minutes.","Now take some of the soup from meat and add to the top of the bread pieces in baking dish to saturate.Add cooked rice on top of bread pieces. Slowly spoon remainder of soup onto rice, looking at glass dish sides to see level of soup, should reach just to top of rice, don’t worry, this doesn’t have to be exact. Now you’re ready to make the sauce and fry the meat to put on top.","To prepare red sauce: In a pan, add a little oil or butter, crushed tomato, a half teaspoon of tomato paste, salt & pepper, 2 cloves of fresh crushed garlic and cumin. Add also approximately 3 tablespoons of vinegar, stir this until you smell aroma and it is a bit smooth. It should be a bit thick, not watery, but if too thick you can add a bit of water. Spread with a wooden spoon atop the rice to cover.","To fry meat: In a pan add a bit of butter or oil, the meat, just a touch of tomato paste, about a tablespoon of fresh crushed garlic, salt & pepper, a teaspoon of cumin. Cook until meat is golden fried.","Spoon this atop the rice and serve. Enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/rlwcc51598734603.jpg', 'themealdb'),
('Japanese Katsudon', ARRAY['japanese', 'pork']::text[], ARRAY['dairy_free']::text[], 25, 40, 65, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Vegetable Oil","measure":"1 tbs"},{"name":"Onion","measure":"1 large"},{"name":"Pork","measure":"1 chopped"},{"name":"Vegetable Stock","measure":"150ml"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Mirin","measure":"1 tsp"},{"name":"Sugar","measure":"1 tsp"},{"name":"Eggs","measure":"2 Beaten"},{"name":"Sushi Rice","measure":"200g"},{"name":"Chives","measure":"Chopped"}]'::jsonb, '["Heat the oil in a pan, fry the sliced onion until golden brown, then add the tonkatsu (see recipe here), placing it in the middle of the pan. Mix the dashi, soy, mirin and sugar together and tip three-quarters of the mixture around the tonkatsu. Sizzle for a couple of mins so the sauce thickens a little and the tonkatsu reheats.","Tip the beaten eggs around the tonkatsu and cook for 2-3 mins until the egg is cooked through but still a little runny. Divide the rice between two bowls, then top each with half the egg and tonkatsu mix, sprinkle over the chives and serve immediately, drizzling with a little more soy if you want an extra umami kick."]'::jsonb, 'https://www.themealdb.com/images/media/meals/d8f6qx1604182128.jpg', 'themealdb'),
('Coddled pork with cider', ARRAY['irish', 'pork']::text[], ARRAY['gluten_free']::text[], 25, 45, 70, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Butter","measure":"Knob"},{"name":"Pork Chops","measure":"2"},{"name":"Bacon","measure":"4"},{"name":"Potatoes","measure":"2"},{"name":"Carrots","measure":"1"},{"name":"Swede","measure":"1/2"},{"name":"Cabbage","measure":"1/2"},{"name":"Bay Leaf","measure":"1"},{"name":"Cider","measure":"100ml"},{"name":"Chicken Stock","measure":"100g"}]'::jsonb, '["Heat the butter in a casserole dish until sizzling, then fry the pork for 2-3 mins on each side until browned. Remove from the pan.","Tip the bacon, carrot, potatoes and swede into the pan, then gently fry until slightly coloured. Stir in the cabbage, sit the chops back on top, add the bay leaf, then pour over the cider and stock. Cover the pan, then leave everything to gently simmer for 20 mins until the pork is cooked through and the vegetables are tender.","Serve at the table spooned straight from the dish."]'::jsonb, 'https://www.themealdb.com/images/media/meals/7vpsfp1608588991.jpg', 'themealdb'),
('Mustard champ', ARRAY['irish', 'side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 17, 25, 42, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Potatoes","measure":"1kg"},{"name":"Milk","measure":"200ml"},{"name":"Butter","measure":"50g"},{"name":"Mustard","measure":"2 tbs"},{"name":"Spring Onions","measure":"Bunch"},{"name":"Spring Onions","measure":"Bunch"}]'::jsonb, '["Boil the potatoes for 15 mins or until tender. Drain, then mash.","Heat the milk and half the butter in the corner of the pan, then beat into the mash, along with the wholegrain mustard.","Gently fry the spring onions in the remaining butter for 2 mins until just soft but still a perky green. Fold into the mash and serve. Great with gammon or to top a fish pie."]'::jsonb, 'https://www.themealdb.com/images/media/meals/o7p9581608589317.jpg', 'themealdb'),
('Grilled Portuguese sardines', ARRAY['portuguese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 19, 20, 39, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Sardines","measure":"8"},{"name":"Olive Oil","measure":"2 tbs"},{"name":"Garlic","measure":"3 cloves"},{"name":"Paprika","measure":"1 tbs"},{"name":"Lemon","measure":"1/2"},{"name":"Rosemary","measure":"4 sprigs"},{"name":"Red Chilli","measure":"1"}]'::jsonb, '["Put all of the ingredients, except the sardines, into a bowl and mix together with some seasoning. Pour into a baking dish, add the sardines and toss really well. Cover and chill for a few hours.","Heat a BBQ or griddle pan until hot. Cook the sardines for 4-5 minutes on each side or until really caramelised and charred. Put onto a serving plate, drizzle with oil, sprinkle with a little more paprika and squeeze over the lemon wedges."]'::jsonb, 'https://www.themealdb.com/images/media/meals/lpd4wy1614347943.jpg', 'themealdb'),
('Portuguese fish stew (Caldeirada de peixe)', ARRAY['portuguese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 37, 25, 62, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Onions","measure":"2 finely chopped"},{"name":"Red Pepper","measure":"1 Diced"},{"name":"Coriander","measure":"Small bunch"},{"name":"Red Chilli","measure":"1 small"},{"name":"Garlic","measure":"3 cloves"},{"name":"Dry White Wine","measure":"400ml"},{"name":"Saffron","measure":"Pinch"},{"name":"Bay Leaf","measure":"1"},{"name":"Potatoes","measure":"300g"},{"name":"Plum Tomatoes","measure":"400g"},{"name":"Cod","measure":"600g"},{"name":"Squid","measure":"300g"},{"name":"Tiger Prawns","measure":"8"},{"name":"Clams","measure":"500g"},{"name":"Mussels","measure":"500g"},{"name":"Baguette","measure":"1 sliced"}]'::jsonb, '["Heat a drizzle of oil in a large, deep-sided frying pan, and fry the onion and pepper on a medium heat until softened but not browned. Finely chop the coriander stalks (keep the leaves for later), and add to the pan with the chilli and chopped garlic. Fry for another few minutes. Add the wine, saffron and bay leaf and let it simmer until reduced by half.","Add the potatoes, tomatoes, and 300ml water and bring to a gentle boil. Break up the tomatoes with a spoon on the side of the pan and simmer for 20-25 minutes until the potatoes are just tender, and the tomatoes have broken down.","Season well, then gently push the fish into the sauce, and arrange the squid, prawns, clams and mussels on the surface. Put the lid on and cook for 6-8 minutes until the mussel and clam shells have opened, the prawns are cooked and the fish is flaky. Toast the bread, rub lightly with the halved garlic clove and drizzle with olive oil. Serve the stew scatted with chopped coriander leaves, and the toasts for dunking."]'::jsonb, 'https://www.themealdb.com/images/media/meals/do7zps1614349775.jpg', 'themealdb'),
('Mee goreng mamak', ARRAY['malaysian', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 35, 45, 80, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Peanuts","measure":"50g"},{"name":"Chilli","measure":"15g"},{"name":"Prawns","measure":"10g"},{"name":"Oil","measure":"5 tbs"},{"name":"Water","measure":"750 ml"},{"name":"Tamarind Paste","measure":"1/2 tbs"},{"name":"Potatoes","measure":"250g"},{"name":"Red Onions","measure":"2"},{"name":"Garlic Clove","measure":"4"},{"name":"Cabbage","measure":"30g"},{"name":"Chinese Broccoli","measure":"30g"},{"name":"Tofu","measure":"1"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Noodles","measure":"4"},{"name":"Egg","measure":"1"}]'::jsonb, '["Heat oil in a pan at medium heat. Then, add peanuts, dried chilies, dried shrimps and dhal. Fry the aromatics until fragrant. Remove from pan and leave aside.","Blend fried ingredients with tamarind paste and water until fine. Then, sauté the blended ingredients in oil heated over low heat. Continue cooking until the oil separates from the paste and turns a darker shade.","Skin and cut potatoes into small chunks and boil them in a pot of water until knife-tender. Once ready, remove them from the pot and leave aside. Discard water.","Slice onion and fried tofu, mince garlic, cut some cabbage and Chinese flowering cabbage (choi sam). Prepare prawn fritters and cut them. Boil noodles to soften them if bought dried. Also mix black soy sauce with water.","To fry one portion of mee goreng mamak, heat oil and add 1/4 of the following ingredients in this order: garlic, onion, paste. Sauté until fragrant. Optionally, add prawns.","Add in 1/4 amount of tofu, boiled potatoes, cabbage, Chinese flowering cabbage and prawn fritters. Sauté for another 30 seconds.","Add noodles to the wok. Add 3 tablespoons of dark soy sauce mixture. Mix evenly for the next 1 minute. Then, move the noodles to the side of the wok. Stir in an egg. Garnish with a slice of lime and slices of green chilies. To cook another plate of noodles, repeat from step 5 onwards."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xquakq1619787532.jpg', 'themealdb'),
('Apam balik', ARRAY['malaysian', 'dessert']::text[], ARRAY['vegetarian']::text[], 23, 40, 63, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Milk","measure":"200ml"},{"name":"Oil","measure":"60ml"},{"name":"Eggs","measure":"2"},{"name":"Flour","measure":"1600g"},{"name":"Baking Powder","measure":"3 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Unsalted Butter","measure":"25g"},{"name":"Sugar","measure":"45g"},{"name":"Peanut Butter","measure":"3 tbs"}]'::jsonb, '["Mix milk, oil and egg together. Sift flour, baking powder and salt into the mixture. Stir well until all ingredients are combined evenly.","Spread some batter onto the pan. Spread a thin layer of batter to the side of the pan. Cover the pan for 30-60 seconds until small air bubbles appear.","Add butter, cream corn, crushed peanuts and sugar onto the pancake. Fold the pancake into half once the bottom surface is browned.","Cut into wedges and best eaten when it is warm."]'::jsonb, 'https://www.themealdb.com/images/media/meals/adxcbq1619787919.jpg', 'themealdb'),
('Beef Rendang', ARRAY['malaysian', 'beef']::text[], ARRAY['gluten_free']::text[], 29, 45, 74, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef","measure":"1lb"},{"name":"Vegetable Oil","measure":"5 tbs"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Cloves","measure":"3"},{"name":"Star Anise","measure":"3"},{"name":"Cardamom","measure":"3"},{"name":"Coconut Cream","measure":"1 cup"},{"name":"Water","measure":"1 cup"},{"name":"Tamarind Paste","measure":"2 tbs"},{"name":"Lime","measure":"6"},{"name":"Sugar","measure":"1 tbs"},{"name":"Challots","measure":"5"}]'::jsonb, '["Chop the spice paste ingredients and then blend it in a food processor until fine.","Heat the oil in a stew pot, add the spice paste, cinnamon, cloves, star anise, and cardamom and stir-fry until aromatic. Add the beef and the pounded lemongrass and stir for 1 minute. Add the coconut milk, tamarind juice, water, and simmer on medium heat, stirring frequently until the meat is almost cooked. Add the kaffir lime leaves, kerisik (toasted coconut), sugar or palm sugar, stirring to blend well with the meat.","Lower the heat to low, cover the lid, and simmer for 1 to 1 1/2 hours or until the meat is really tender and the gravy has dried up. Add more salt and sugar to taste. Serve immediately with steamed rice and save some for overnight."]'::jsonb, 'https://www.themealdb.com/images/media/meals/bc8v651619789840.jpg', 'themealdb'),
('Cevapi Sausages', ARRAY['croatian', 'beef']::text[], ARRAY['dairy_free']::text[], 29, 55, 84, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Minced Beef","measure":"500g"},{"name":"Minced Pork","measure":"250g"},{"name":"Onion","measure":"1"},{"name":"Garlic","measure":"4 cloves"},{"name":"Parsley","measure":"3 tblsp chopped"},{"name":"Paprika","measure":"1 tbs"},{"name":"Baking Powder","measure":"3/4 teaspoon"},{"name":"Breadcrumbs","measure":"2 tbs"},{"name":"Water","measure":"3 tbs"},{"name":"Vegetable Stock Cube","measure":"1"},{"name":"Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1 tsp"}]'::jsonb, '["Place the ground meat in a bowl. Chop the onion very finely and grate the garlic cloves. Add to the bowl. Add the chopped parsley, all sorts of paprika, baking soda, dried breadcrumbs, water, Vegeta, salt, and pepper.","Mix well with the hand mixer fitted with the dough hooks. Cover the bowl with cling film/ plastic foil and leave to rest for 1 or 2 hours in the refrigerator.","Take portions of the meat mixture, about 50-55 g/ 1.7-1.9 oz/ ¼ cup portions, and form the cevapi. The rolls should be about as thick as your thumb and about 7-10 cm/ 3-4 inches long. I had 18 sausages. The recipe can be easily doubled.","Grill the cevapcici on the hot grill pan or on the barbecue for about 12-14 minutes, turning them several times in between, or until brown and cooked through. I checked by cutting one in the middle and then grilling the following batches for the same period of time.","Serve hot as suggested above. The cevapcici can be reheated in the oven at 180 degrees Celsius/ 350 degrees Fahrenheit for about 10 minutes or until heated through. Check one, if it is not hot enough, give the sausages a few more minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vc08jn1628769553.jpg', 'themealdb'),
('Croatian lamb peka', ARRAY['croatian', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 31, 130, 161, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Potatoes","measure":"600g"},{"name":"Courgettes","measure":"1 chopped"},{"name":"Carrots","measure":"1 chopped"},{"name":"Green Pepper","measure":"1 chopped"},{"name":"Aubergine","measure":"1 small"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Lamb Shoulder","measure":"800g"},{"name":"Garlic Sauce","measure":"1 tbs"},{"name":"Tomato Puree","measure":"1 tbs"},{"name":"Olive Oil","measure":"80 ml"},{"name":"Thyme","measure":"Sprinking"},{"name":"White Wine","measure":"250ml"},{"name":"Pepper","measure":"Pinch"}]'::jsonb, '["Preheat oven to 200°C fan / 220°C / 425°F / Gas mark 7","If you have not bought diced lamb, cut your lamb shoulder or leg into large chunks and place to one side.","Chunks of chopped lamb of a red chopping board","Make oil marinade -","Mix 80ml of olive oil in a bowl with garlic puree, sundried tomato puree ,black pepper and salt.","olive oil, gia sundried tomato puree and gia garlic puree and black pepper mixed together in a silver bowl to make Croatian peka","Add potatoes and vegetables into a large lidded casserole dish.","Chopped up vegetables which consist of chopped up red onion, courgette, potatoes red peppers in a cast iron pan","Place diced lamb on top of the vegetables, pour the marinade and wine over the top.","Chunks of lamb covered in in a sundried tomato oil sauce which is on top of chopped red onion, aubergine, courgette and potatoes in a cast iron pan","Add the rosemary, thyme and sage, trying to keep the herbs on top.","So you can easily remove the herb stalks once cooked.","Chunks of lamb coated in a sundried tomato oil sauce and covered with thyme, rosemary and sage which is on top of chopped red onion, aubergine, courgette and potatoes in a cast iron pan","Place lid on the casserole dish and cook for 1hr 30 minute","If you do not have a lid cover very well with kitchen foil","Cast iron dish with lid on in the oven","Take the lid off, remove any thick herb stems. Stir in 2 tbsp of olive oil.","Cook for a further 20-30 mins.","Cooked Croatian Lamb Peka in a cast iron pan in the oven","Serve with fresh homemade bread to dip into the juices."]'::jsonb, 'https://www.themealdb.com/images/media/meals/pn59o51628769837.jpg', 'themealdb'),
('Traditional Croatian Goulash', ARRAY['croatian', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 29, 65, 94, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef","measure":"500g"},{"name":"Onions","measure":"2 chopped"},{"name":"Carrots","measure":"2 chopped"},{"name":"Garlic","measure":"2 cloves"},{"name":"Bay Leaf","measure":"2"},{"name":"Red Wine","measure":"200ml"},{"name":"Water","measure":"2 Litres"},{"name":"Mustard","measure":"3 tbs"},{"name":"Salt","measure":"1tbsp"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Paprika","measure":"1/2 tsp"},{"name":"Vegetable Oil","measure":"2 tbs"}]'::jsonb, '["Clean the meat from the veins if there are some and cut it into smaller pieces, 3 × 3 cm. Marinate the meat in the mustard and spices and let it sit in the refrigerator for one hour","Heat one tablespoon of pork fat or vegetable oil in a pot and fry the meat on all sides until it gets browned. Once the meat is cooked, transfer it to a plate and add another tablespoon of fat to the pot","Cut the onions very fine, peel the carrots and shred it using a grater. Cook the onions and carrots over low heat for 15 minutes. You can salt the vegetables a little to make them soften faster","Once the vegetables have browned and become slightly mushy, add the meat and bay leaves and garlic. Pour over with wine and simmer for 10-15 minutes to allow the alcohol to evaporate. Now is the right time to add 2/3 the amount of liquid","Cover the pot and cook over low heat for an hour, stirring occasionally. After the first hour, pour over the rest of the water or stock and cook for another 30-45 minutes","Allow the stew to cool slightly and serve it with a sprinkle of chopped parsley and few slices of fresh hot pepper if you like to spice it up a bit","Slice ​​some fresh bread, season the salad and simply enjoying these wonderful flavors"]'::jsonb, 'https://www.themealdb.com/images/media/meals/n1hcou1628770088.jpg', 'themealdb'),
('Burek', ARRAY['croatian', 'side']::text[], ARRAY['dairy_free']::text[], 17, 40, 57, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Filo Pastry","measure":"1 Packet"},{"name":"Minced Beef","measure":"150g"},{"name":"Onion","measure":"150g"},{"name":"Oil","measure":"40g"},{"name":"Salt","measure":"Dash"},{"name":"Pepper","measure":"Dash"}]'::jsonb, '["Fry the finely chopped onions and minced meat in oil.","Add the salt and pepper.","Grease a round baking tray and put a layer of pastry in it.","Cover with a thin layer of filling and cover this with another layer of filo pastry which must be well coated in oil.","Put another layer of filling and cover with pastry.","When you have five or six layers, cover with filo pastry, bake at 200ºC/392ºF for half an hour and cut in quarters and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tkxquw1628771028.jpg', 'themealdb'),
('Fettuccine Alfredo', ARRAY['italian', 'pasta']::text[], ARRAY['vegetarian']::text[], 17, 35, 52, 'easy', '{"calories":600,"protein_g":22,"carbs_g":78,"fat_g":20}'::jsonb, 2, '[{"name":"Fettuccine","measure":"1 lb"},{"name":"Heavy Cream","measure":"1/2 cup"},{"name":"Butter","measure":"1/2 cup"},{"name":"Parmesan","measure":"1/2 cup"},{"name":"Parsley","measure":"2 tbsp"},{"name":"Black Pepper","measure":""}]'::jsonb, '["Cook pasta according to package instructions in a large pot of boiling water and salt.","Add heavy cream and butter to a large skillet over medium heat until the cream bubbles and the butter melts.","Whisk in parmesan and add seasoning (salt and black pepper).","Let the sauce thicken slightly and then add the pasta and toss until coated in sauce.","Garnish with parsley, and it''s ready."]'::jsonb, 'https://www.themealdb.com/images/media/meals/0jv5gx1661040802.jpg', 'themealdb'),
('Stuffed Bell Peppers with Quinoa and Black Beans', ARRAY['mexican', 'vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 35, 45, 80, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 6, '[{"name":"Green Pepper","measure":"4 whole"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Quinoa","measure":"1 cups"},{"name":"Black Beans","measure":"1 can"},{"name":"Sweetcorn","measure":"1 cup"},{"name":"Diced Tomatoes","measure":"1 can"},{"name":"Cumin","measure":"1 teaspoon"},{"name":"Chili Powder","measure":"½ tsp"},{"name":"Smoked Paprika","measure":"½ tsp"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Shredded Mexican Cheese","measure":"1 1/2 cup"},{"name":"Cilantro","measure":"Chopped"}]'::jsonb, '["Preheat your oven to 375°F (190°C). Lightly grease a 9x13-inch baking dish or a similar-sized casserole dish.","Place the bell pepper halves in the prepared baking dish, cut side up. Bake for 15-20 minutes, or until slightly softened.","While the bell peppers are baking, prepare the filling. In a large skillet, heat the olive oil over medium heat. Add the chopped onion, and cook for 3-4 minutes, until softened. Add the garlic, and cook for another 1 minute, until fragrant.","Stir in the cooked quinoa, black beans, corn, diced tomatoes, ground cumin, chili powder, smoked paprika, salt, and pepper. Cook for 5-7 minutes, until heated through. Remove the skillet from heat, and stir in 1 cup of the shredded cheese, if using.","Remove the bell peppers from the oven, and carefully stuff each pepper half with the quinoa and black bean mixture. Top the stuffed peppers with the remaining 1/2 cup of shredded cheese, if using.","Return the stuffed peppers to the oven, and bake for another 15-20 minutes, until the cheese is melted and the peppers are tender.","Remove from the oven, and allow the stuffed peppers to cool for 5 minutes before serving. Garnish with fresh chopped cilantro."]'::jsonb, 'https://www.themealdb.com/images/media/meals/b66myb1683207208.jpg', 'themealdb'),
('Bistek', ARRAY['filipino', 'beef']::text[], ARRAY['dairy_free']::text[], 21, 70, 91, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef","measure":"1 lb"},{"name":"Soy Sauce","measure":"5 tablespoons"},{"name":"Lemon","measure":"1"},{"name":"Garlic","measure":"3 cloves"},{"name":"Onion","measure":"3 parts"},{"name":"Olive Oil","measure":"4 tbs"},{"name":"Water","measure":"1 cup"},{"name":"Salt","measure":"1 pinch"}]'::jsonb, '["Marinate beef in soy sauce, lemon (or calamansi), and ground black pepper for at least 1 hour. Note: marinate overnight for best result","Heat the cooking oil in a pan then pan-fry half of the onions until the texture becomes soft. Set aside","Drain the marinade from the beef. Set it aside. Pan-fry the beef on the same pan where the onions were fried for 1 minute per side. Remove from the pan. Set aside","Add more oil if needed. Saute garlic and remaining raw onions until onion softens.","Pour the remaining marinade and water. Bring to a boil.","Add beef. Cover the pan and simmer until the meat is tender. Note: Add water as needed.","Season with ground black pepper and salt as needed. Top with pan-fried onions.","Transfer to a serving plate. Serve hot. Share and Enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/4pqimk1683207418.jpg', 'themealdb'),
('Beef Caldereta', ARRAY['filipino', 'beef']::text[], ARRAY[]::text[], 33, 70, 103, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef","measure":"2kg cut cubes"},{"name":"Beef Stock","measure":"1"},{"name":"Soy Sauce","measure":"1 tbs"},{"name":"Water","measure":"2 cups"},{"name":"Green Pepper","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Potatoes","measure":"1 sliced"},{"name":"Carrots","measure":"1 sliced"},{"name":"Tomato Puree","measure":"8 ounces"},{"name":"Peanut Butter","measure":"3  tablespoons"},{"name":"Chilli Powder","measure":"5"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"5 cloves"},{"name":"Olive Oil","measure":"3 tbs"}]'::jsonb, '["Heat oil in a cooking pot. Saute onion and garlic until onion softens","Add beef. Saute until the outer part turns light brown.","Add soy sauce. Pour tomato sauce and water. Let boil.","Add Knorr Beef Cube. Cover the pressure cooker. Cook for 30 minutes.","Pan-fry carrot and potato until it browns. Set aside.","Add chili pepper, liver spread and peanut butter. Stir.","Add bell peppers, fried potato and carrot. Cover the pot. Continue cooking for 5 to 7 minutes.","Season with salt and ground black pepper. Serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/41cxjh1683207682.jpg', 'themealdb'),
('Beef Asado', ARRAY['filipino', 'beef']::text[], ARRAY[]::text[], 33, 70, 103, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef","measure":"1.5kg"},{"name":"Beef Stock Concentrate","measure":"1"},{"name":"Tomato Puree","measure":"8 ounces"},{"name":"Water","measure":"3 cups"},{"name":"Soy Sauce","measure":"6 tablespoons"},{"name":"White Wine Vinegar","measure":"1 tbs"},{"name":"Pepper","measure":"2 tbs"},{"name":"Bay Leaf","measure":"4"},{"name":"Lemon","measure":"1/2"},{"name":"Tomato Sauce","measure":"2 tbs"},{"name":"Butter","measure":"3 tbs"},{"name":"Olive Oil","measure":"1/2 cup"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"4 cloves"}]'::jsonb, '["Combine beef, crushed peppercorn, soy sauce, vinegar, dried bay leaves, lemon, and tomato sauce. Mix well. Marinate beef for at least 30 minutes.","Put the marinated beef in a cooking pot along with remaining marinade. Add water. Let boil.","Add Knorr Beef Cube. Stir. Cover the pot and cook for 40 minutes in low heat.","Turn the beef over. Add tomato paste. Continue cooking until beef tenderizes. Set aside.","Heat oil in a pan. Fry the potato until it browns. Turn over and continue frying the opposite side. Remove from the pan and place on a clean plate. Do the same with the carrots.","Save 3 tablespoons of cooking oil from the pan where the potato was fried. Saute onion and garlic until onion softens.","Pour-in the sauce from the beef stew. Let boil. Add the beef. Cook for 2 minutes.","Add butter and let it melt. Continue cooking until the sauce reduces to half."]'::jsonb, 'https://www.themealdb.com/images/media/meals/pkopc31683207947.jpg', 'themealdb'),
('Grilled eggplant with coconut milk', ARRAY['filipino', 'vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 17, 30, 47, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 2, '[{"name":"Egg Plants","measure":"6"},{"name":"Coconut Milk","measure":"1 can"},{"name":"Lemon Juice","measure":"1 tbs"},{"name":"Salt","measure":"1 tsp"},{"name":"Red Pepper Flakes","measure":"To taste"},{"name":"Onions","measure":"4 Sticks"}]'::jsonb, '[".  Prepare the eggplants for grilling by pricking them all over with a fork.  This is so it won’t burst during the grilling process as the natural water in it heats up.","Grill the eggplants, turning them over frequently to ensure even cooking.  Grill until the skins are dark brown, even black and the eggplant is soft when you touch it.","Soak the grilled eggplant in a bowl of water to cool it down.  Peel the skin off the eggplant.  Place the whole eggplants in a shallow dish (my mom actually cuts the eggplant into small, bite-sized pieces).","In a small mixing bowl, mix together the coconut milk or cream, lemon powder, salt and hot pepper.  Mix until the lemon powder and salt dissolve.  Taste, then adjust the amount of lemon powder, salt and hot pepper to your liking.  Pour the mixture over the eggplant.  Sprinkle the green onions over the eggplant and coconut milk.  Stir gently to combine."]'::jsonb, 'https://www.themealdb.com/images/media/meals/bopa2i1683209167.jpg', 'themealdb'),
('15-minute chicken & halloumi burgers', ARRAY['united_states', 'chicken']::text[], ARRAY[]::text[], 27, 35, 62, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Chicken Breasts","measure":"2"},{"name":"Oil","measure":"1 tbsp"},{"name":"Hotsauce","measure":"4 tbsp"},{"name":"Lemon Juice","measure":"½"},{"name":"Buns","measure":"2"},{"name":"Cheese","measure":"250g"},{"name":"Cabbage","measure":"¼"},{"name":"Mayonnaise","measure":"2 tbsp"},{"name":"Sour Cream","measure":"4 tbsp"},{"name":"Lettuce","measure":"4 leaves"},{"name":"Red Pepper","measure":"2"}]'::jsonb, '["Put the chicken breasts between two pieces of baking parchment and use a rolling pin to gently bash them until they are approximately 1cm thick. Cut each chicken breast into two even pieces.","If you''re using a frying pan, heat two frying pans over medium-high heat, with one of them containing oil. Fry the chicken in the oiled pan for 3-4 mins on each side until they are cooked through. Season the chicken, reduce the heat, drizzle in the chilli sauce and half of the lemon juice, and cook for an additional 1-2 mins until the sauce is reduced. Remove the chicken from the heat.","If you''re using an air-fryer, preheat it to 180C for 4 mins. Add the chicken to the air-fryer and cook for 12 mins. Drizzle over the chilli sauce and half the lemon juice and cook for an additional 1-2 mins until the chicken is cooked through and the sauce is reduced. Remove the chicken and keep it warm.","While the chicken is cooking, toast the buns in the dry frying pan for 30 seconds. Transfer them to a plate. If you''re using an air fryer, put the buns in the air fryer for 1-2 mins until they are warm. Increase the air fryer temperature to 200C. Add the halloumi to the air fryer basket and cook for 10 mins, turning halfway through, until it''s golden. Toss the cabbage with the mayo and the remaining lemon juice.","Spoon the hummus (or dip of your choice) into the toasted buns, then top with the rocket, chilli chicken, halloumi, and peppers. Drizzle with a little more chilli sauce, spoon over the cabbage, season with black pepper, and top with the bun lids. Serve with any extra cabbage on the side or a green salad."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vdwloy1713225718.jpg', 'themealdb'),
('Syrian Spaghetti', ARRAY['syrian', 'pasta']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 19, 25, 44, 'easy', '{"calories":600,"protein_g":22,"carbs_g":78,"fat_g":20}'::jsonb, 4, '[{"name":"Spaghetti","measure":"16 ounces"},{"name":"Tomato Sauce","measure":"8 ounces"},{"name":"Tomato Puree","measure":"6 oz"},{"name":"Cinnamon","measure":"1 teaspoon"},{"name":"Vegetable Oil","measure":"1/4 cup"},{"name":"Salt","measure":"Dash"},{"name":"Pepper","measure":"Dash"}]'::jsonb, '["Preheat oven to 350 degrees F (175 degrees C). Grease a 9x13 inch baking dish.","Bring a large pot of lightly salted water to a boil. Add spaghetti and cook for 8 to 10 minutes or until al dente; drain and stir in tomato sauce, tomato paste, cinnamon, oil, salt and pepper. Transfer to prepared dish.","Bake in preheated oven for 1 hour, or until top is crunchy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5fu4ew1760524857.jpg', 'themealdb'),
('Baba Ghanoush', ARRAY['syrian', 'side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 25, 35, 60, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Egg Plants","measure":"4 large"},{"name":"Garlic","measure":"2 cloves"},{"name":"Kosher Salt","measure":"2 teaspoons"},{"name":"Lemon","measure":"1"},{"name":"Tahini","measure":"3  tablespoons"},{"name":"Extra Virgin Olive Oil","measure":"3  tablespoons"},{"name":"Greek Yogurt","measure":"2 tablespoons"},{"name":"Cayenne Pepper","measure":"1 pinch"},{"name":"Mint","measure":"1 Leaf"},{"name":"Parsley","measure":"2 tablespoons"}]'::jsonb, '["Preheat an outdoor grill for medium-high heat and lightly oil the grate. Prick the surface of the skin of eggplants several times with the tip of a knife.","Place eggplants directly on grill. Turn frequently with tongs while skin chars. Cook until eggplants have collapsed and are very soft, 25 to 30 minutes. Transfer to a bowl and cover tightly with aluminum foil and allow to cool, about 15 minutes.","When eggplants are cool enough to handle, split them in half and scrape flesh into a colander placed over a bowl. Drain 5 or 10 minutes.","Transfer eggplant to mixing bowl. Add crushed garlic and salt; mash until creamy but with a little texture, about 5 minutes. Whisk in lemon juice, tahini, olive oil, and cayenne pepper. Stir in yogurt.","Cover bowl with plastic wrap and refrigerate until completely chilled. Stir in mint and parsley, and taste to adjust seasonings before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/dlmh401760524897.jpg', 'themealdb'),
('Syrian Rice with Meat', ARRAY['syrian', 'miscellaneous']::text[], ARRAY['gluten_free']::text[], 25, 30, 55, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 4, '[{"name":"Butter","measure":"1/4 cup"},{"name":"Ground Beef","measure":"2 Pounds"},{"name":"Salt","measure":"2 teaspoons"},{"name":"Allspice","measure":"1/2 teaspoon"},{"name":"Cinnamon","measure":"1/2 teaspoon"},{"name":"Black Pepper","measure":"1/2 teaspoon"},{"name":"Chicken Stock","measure":"5 Cups"},{"name":"Rice","measure":"2 cups"},{"name":"Butter","measure":"2 tablespoons"},{"name":"Pine Nuts","measure":"1/2 cup"}]'::jsonb, '["Heat 1/4 cup butter in a large saucepan over medium-high heat. Add ground beef and season with salt, allspice, cinnamon, and black pepper. Cook and stir until beef is browned and crumbly, 7 to 10 minutes.","Stir chicken broth and rice into beef in the saucepan; bring to a boil. Reduce heat to low, cover, and cook until liquid is absorbed, about 20 minutes.","Meanwhile, melt 2 tablespoons butter in a small skillet over medium heat. Cook and stir pine nuts in hot butter until lightly browned, 3 to 5 minutes.","Mix pine nuts into beef-rice mixture before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/zg2b9l1760524940.jpg', 'themealdb'),
('Corned Beef Hash', ARRAY['british', 'beef']::text[], ARRAY['gluten_free']::text[], 19, 80, 99, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Unsalted Butter","measure":"3  tablespoons"},{"name":"Onion","measure":"1 medium chopped"},{"name":"Corned Beef","measure":"3 Cups"},{"name":"Potatoes","measure":"3 chopped"},{"name":"Kosher Salt","measure":"Dash"},{"name":"Black Pepper","measure":"Dash"},{"name":"Freshly Chopped Parsley","measure":"Chopped"}]'::jsonb, '["Sauté the onions:","Heat butter in a large skillet (preferably cast iron) on medium heat. Add the onion and cook a few minutes, until translucent.","Add the potatoes and corned beef:","Mix in the chopped corned beef and potatoes. Spread out evenly over the pan. Increase the heat to high or medium high and press down on the mixture with a metal spatula.","Cook until browned and then flip:","Do not stir the potatoes and corned beef, but let them brown. If you hear them sizzling, this is good.","Use a metal spatula to peek underneath and see if they are browning. If nicely browned, use the spatula to flip sections over in the pan so that they brown on the other side. Press down again with the spatula.","If there is too much sticking, you can add a little more butter to the pan. Continue to cook in this manner until the potatoes and the corned beef are nicely browned.","Stir in the parsley and season:","Remove from heat, stir in chopped parsley. Add plenty of freshly ground black pepper, and add salt to taste."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vz94r81760534692.jpg', 'themealdb'),
('Yorkshire Puddings', ARRAY['british', 'miscellaneous']::text[], ARRAY['vegetarian']::text[], 13, 45, 58, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Flour","measure":"140g"},{"name":"Egg","measure":"4"},{"name":"Milk","measure":"200ml"},{"name":"Sunflower Oil","measure":"Drizzle"}]'::jsonb, '["Heat oven to 230C/fan 210C/gas 8.","Drizzle a little sunflower oil evenly into two 4-hole Yorkshire pudding tins or two 12-hole non-stick muffin tins and place in the oven to heat through.","To make the batter, tip 140g plain flour into a bowl and beat in 4 eggs until smooth.","Gradually add 200ml milk and carry on beating until the mix is completely lump-free. Season with salt and pepper.","Pour the batter into a jug, then remove the hot tins from the oven. Carefully and evenly pour the batter into the holes.","Place the tins back in the oven and leave undisturbed for 20-25 mins until the puddings have puffed up and browned.","Serve immediately. You can now cool them and freeze for up to 1 month."]'::jsonb, 'https://www.themealdb.com/images/media/meals/x5qz5k1761595900.jpg', 'themealdb'),
('Squid, chickpea & chorizo salad', ARRAY['australian', 'seafood']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 23, 20, 43, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Red Pepper","measure":"4"},{"name":"Can of chickpeas","measure":"2 400g Cans"},{"name":"Parsley","measure":"Bunch"},{"name":"Red Chilli","measure":"1"},{"name":"Garlic Clove","measure":"2"},{"name":"Olive Oil","measure":"100 ml"},{"name":"Squid","measure":"600g"},{"name":"Chorizo","measure":"200g"},{"name":"Lemon","measure":"Juice/zest of one"}]'::jsonb, '["Cook the peppers whole under a grill, on a barbecue or griddle, until completely charred. Place the peppers in a bowl, cover with a plate until cool enough to handle, then peel, deseed and finely slice. In a large bowl mix the peppers and any juices with the chickpeas, parsley, chilli and garlic. Set aside.","Heat a large frying pan until smoking. Working quickly and carefully, add a splash of oil to the pan, then the squid. Stir-fry for about 30 secs. Scatter the chorizo over the squid, continue to cook for 30 secs more, then tip into the bowl with the peppers. Season everything with salt and pepper, then dress with the remaining oil, lemon juice and lemon zest. Mix together, pile onto a platter and let everyone help themselves."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wsu0rc1761848482.jpg', 'themealdb'),
('Lamingtons', ARRAY['australian', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 50, 83, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Salted Butter","measure":"125g"},{"name":"Golden Caster Sugar","measure":"250g"},{"name":"Egg","measure":"3 Large"},{"name":"Self-raising Flour","measure":"250g"},{"name":"Milk","measure":"3  tablespoons"},{"name":"Salt","measure":"1/2 teaspoon"},{"name":"Double Cream","measure":"250ml"},{"name":"Icing Sugar","measure":"2 tblsp"},{"name":"Raspberry Jam","measure":"200g"},{"name":"Desiccated Coconut","measure":"350g"},{"name":"Unsalted Butter","measure":"80g"},{"name":"Milk","measure":"250ml"},{"name":"Cocoa Powder","measure":"50g"},{"name":"Icing Sugar","measure":"400g"}]'::jsonb, '["Heat the oven to 200C/180C fan/gas 6. Butter and line a 20 x 30cm rectangle tin.","Beat the butter and sugar in a free-standing mixer until pale and fluffy. Add the eggs one at a time and beat well. Beat through the flour, milk and salt until fully combined, then spoon into the tin. Bake in the oven for 25 mins or until golden and firm to the touch. Set aside to cool completely.","Slice the sponge horizontally to create two halves. Trim the edges to make perfect corners. Cut the sponge into 18 squares. Lightly whip the cream with the icing sugar until it reaches soft peaks. Spread a little of the jam on half of the sponge squares then pipe or spread over a little of the cream. Sandwich each one with a second square of sponge then set aside in the fridge to chill.","To make the icing, whisk together the melted butter and milk in a bowl. Sieve the cocoa powder and icing sugar together in a seperate bowl. Gradually add the cocoa and sugar to the butter and milk mixture, whisking continuously to ensure there are no lumps. If it gets lumpy, whizz with a hand blender until smooth.","Divide the coconut between three shallow bowls (this keeps it from getting coated in too much chocolate whilst you’re dipping).","Dip each lamington in the icing until completely covered. Roll in the coconut and set on a wire rack. Repeat with the remaining sponges. Chill for a minimum of 1 hr."]'::jsonb, 'https://www.themealdb.com/images/media/meals/j2n7vg1761848636.jpg', 'themealdb'),
('Spiced smoky barbecued chicken', ARRAY['australian', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 27, 20, 47, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Garlic","measure":"2 cloves"},{"name":"Lemon","measure":"Juice/zest of one"},{"name":"Curry Powder","measure":"2 tblsp"},{"name":"Chilli Flakes","measure":"Pinch"},{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Chicken Thighs","measure":"12"},{"name":"Rosemary","measure":"Bunch"},{"name":"Rosemary","measure":"Bunch"},{"name":"Thyme","measure":"Bunch"},{"name":"Thyme","measure":"Bunch"},{"name":"Bay Leaves","measure":"2"}]'::jsonb, '["Make the marinade. Smash the garlic with a little salt using a pestle and mortar. Add the lemon zest and juice, the spice mix, chilli, oil and a good grinding of black pepper. Mix to a paste. This can be done in a mini food processor.","Toss the chicken in the marinade and set aside while you light the barbecue. When the barbecue’s hot, lay the bunches of herbs on the grid and put the chicken, skin side up, on top. Close the lid, if your barbecue has one, and cook the chicken on the smouldering herbs for about 10 minutes until the meat starts to colour. Turn the chicken and continue to cook for a further 20-30 minutes, turning as necessary, until it is slightly charred from the burnt herbs and cooked through to the bone."]'::jsonb, 'https://www.themealdb.com/images/media/meals/a08uqk1761848682.jpg', 'themealdb'),
('Quick salt & pepper squid', ARRAY['australian', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 17, 25, 42, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 2, '[{"name":"Squid","measure":"400g"},{"name":"Oil","measure":"3  tablespoons"},{"name":"Chinese five spice powder","measure":"1/2 teaspoon"},{"name":"Sesame Seed Oil","measure":"Dash"},{"name":"Coriander","measure":"Sprigs of fresh"},{"name":"sweet chilli sauce","measure":"Drizzle"}]'::jsonb, '["Ask the fishmonger to clean the squid; little ones often come ready-cleaned. Using kitchen scissors, cut open the body and open out. Wash well, then pat dry. If you have a large squid, cut the body into four portions, roughly square. Small squid can just be opened up.","Using the tip of a very sharp knife, score the top in a neat criss-cross. Brush with oil and set aside while you heat the barbecue or griddle until ready to cook.","Mix together 2 tsp sea salt, Chinese five-spice and 1 tsp freshly ground black pepper. Sprinkle on both sides of the squid just before cooking, according to taste. You may not need it all. Heat the griddle pan to hot and cook about 1 min each side, until it starts to curl. Remove with tongs to a serving plate and drizzle with a little sesame oil. To serve, garnish with coriander leaves and serve with small bowls of sweet chilli sauce to dip into."]'::jsonb, 'https://www.themealdb.com/images/media/meals/cp74zo1762341241.jpg', 'themealdb'),
('Kenyan Beef Curry', ARRAY['kenyan', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 33, 70, 103, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Water","measure":"4 cups"},{"name":"Sirloin Steak tips","measure":"2 Lbs"},{"name":"Garlic Clove","measure":"4"},{"name":"Ground Ginger","measure":"2 teaspoons"},{"name":"Oil","measure":"2 tblsp"},{"name":"Red Onions","measure":"2 medium"},{"name":"Tomato","measure":"4"},{"name":"Paprika","measure":"2 tblsp"},{"name":"Black Pepper","measure":"1/2 teaspoon"},{"name":"Curry Powder","measure":"2 teaspoons"},{"name":"Tomato Puree","measure":"4 tablespoons"},{"name":"Salt","measure":"Dash"},{"name":"Chilli","measure":"1"},{"name":"Cilantro","measure":"Leaves"}]'::jsonb, '["Bring the 4 cups of water to a boil in a Dutch oven or soup pot. Add the beef, garlic, and ginger, and stir well. Bring to a gentle simmer, cover, and cook, stirring occasionally, for 20 minutes. If you get any foamy scum on the top, not to worry, simply spoon it away or stir it back in.","Remove from the heat, and drain, but reserve the excess water for later.","Return the pot or Dutch oven to medium heat with the 2 tablespoons of cooking oil. Once the oil is shimmering, add the onions and cook, stirring occasionally, until softened, 5 to 7 minutes.","Add the tomatoes to the onions, and continue cooking, stirring occasionally, until the tomatoes are falling apart, 3 to 5 minutes.","Add the drained beef to the tomato and onion mixture, and stir well. Continue cooking over medium heat for 5 minutes, stirring occasionally.","Add the paprika, pepper, curry powder, tomato paste, and salt to taste, and stir well.","Add back the excess water that was used for cooking the beef, along with enough extra water to cover. Bring to a boil, reduce heat, and simmer, uncovered, stirring occasionally, for about 1 hour, or until the meat is tender and the sauce is thickened. Add additional water if your beef curry begins to dry and stick, or if would like your curry to have more of a soupy consistency.","When the beef curry is ready, remove from the heat, give it a taste, and adjust the seasonings as desired. Garnish with fresh chilis and cilantro."]'::jsonb, 'https://www.themealdb.com/images/media/meals/lqampv1762325397.jpg', 'themealdb'),
('Sukuma Wiki', ARRAY['kenyan', 'vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 15, 30, 45, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 2, '[{"name":"Oil","measure":"2 tablespoons"},{"name":"Red Onions","measure":"2 medium"},{"name":"Kale","measure":"1 lb"},{"name":"Salt","measure":"Dash"},{"name":"Double Cream","measure":"1 cup"}]'::jsonb, '["Heat the 2 tablespoons of oil in a large skillet or pot over medium heat until shimmering. Add the onions and cook, stirring occasionally, until softened, 5 to 7 minutes.","Add the shredded kale to the onions and mix well. Turn the heat to medium-low, cover and cook for 5 minutes.","After 5 minutes, remove the lid, add salt to taste, and stir in the cream. Continue cooking for another 5 minutes, uncovered, stirring occasionally. The cream will thicken slightly, making for a deliciously rich creamed kale and onions. Yumm!","Serve it up with your favorite Kenyan stew, and a side of ugali!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/60o82j1762341177.jpg', 'themealdb'),
('Ugali – Kenyan cornmeal', ARRAY['kenyan', 'breakfast']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 9, 30, 39, 'easy', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 2, '[{"name":"Water","measure":"2 cups"},{"name":"White Cornmeal","measure":"1 1/2 cups"}]'::jsonb, '["Bring the water to a boil in a medium saucepan.","Reduce the heat to low, and stirring constantly with a whisk, slowly add the cornmeal to the boiling water. The ugali will begin to thicken quite quickly.","Continue cooking on low heat, stirring constantly with a sturdy wooden spoon, until the ugali begins to pull away from the sides of the pan, hold together, and takes on the aroma of roasted corn. Turn it out immediately onto a serving plate. If you would like, using a spoon or spatula, quickly shape it into a thick disk or round.","The ugali will continue to firm as it cools and will be thick enough to cut with a knife (similar to firm polenta)."]'::jsonb, 'https://www.themealdb.com/images/media/meals/smoa3h1762341142.jpg', 'themealdb'),
('Cinnamon buns', ARRAY['norway', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 85, 118, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Unsalted Butter","measure":"100g"},{"name":"Milk","measure":"200ml"},{"name":"Salt","measure":"1 teaspoon"},{"name":"Flour","measure":"250g"},{"name":"Strong White Flour","measure":"250g"},{"name":"Fast action yeast","measure":"1 1/2 tsp"},{"name":"Cardamom","measure":"1 teaspoon"},{"name":"Caster Sugar","measure":"1 tblsp"},{"name":"Egg","measure":"2"},{"name":"Olive Oil","measure":"Dash"},{"name":"Unsalted Butter","measure":"75g"},{"name":"Caster Sugar","measure":"100g"},{"name":"Cinnamon","measure":"2 tbsp"},{"name":"Egg","measure":"1"}]'::jsonb, '["In a small saucepan heat the butter, milk and salt until the butter is melted. Allow the mixture to cool until it is lukewarm.","In a large bowl, stir together the flours, yeast, cardamom and sugar until combined.","Make a well in the centre and crack in the eggs. Pour in the lukewarm milk mixture and stir everything together to form a sticky dough. You may have to use your hands as the dough becomes stiffer.","Oil the work surface with a teaspoon of olive oil. Turn the dough out onto the oiled surface and knead vigorously for 5–8 minutes, using a plastic scraper as needed to prise the dough from the work surface. Don’t be tempted to add flour, as this will make the buns dry and tough. Keep kneading until the dough is considerably less sticky, smoother and more elastic.","Shape into a ball, and put into a large, greased bowl. Cover the bowl with a clean tea towel and set aside in a warm place to prove for an hour, or until doubled in size.","Meanwhile, for the filling and topping, mix the softened butter in a bowl with half the sugar and 1 tablespoon cinnamon. Use a fork to mix the sugar and spice into the butter until it is completely combined.","Mix the remaining sugar and cinnamon in a separate bowl and set aside.","When the dough has risen, turn out onto a floured work surface and gently roll out into a 36x24cm/14x9½in rectangle. Spread the cinnamon-sugar-butter evenly over the dough with a table or palette knife.","With the longest edge closest to you, roll the dough up into a cylinder. Cut into 12 even slices.","Place each slice onto a flattened out paper cupcake case on a baking tray, or into a greased muffin tin. (Baking in a muffin tin will make your cinnamon buns taller and domed.)","Cover with a clean tea towel and set aside to prove again for 30–45 minutes, or until risen.","Preheat the oven to 200C/180C Fan/Gas 6.","Brush the tops of the buns with beaten egg and dust liberally with the cinnamon sugar. Bake for 12 minutes until the buns are dark golden-brown. Enjoy warm with a cup of coffee."]'::jsonb, 'https://www.themealdb.com/images/media/meals/as88dq1762772486.jpg', 'themealdb'),
('Nordic smørrebrød with asparagus and horseradish cream', ARRAY['norway', 'vegetarian']::text[], ARRAY['vegetarian']::text[], 37, 45, 82, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 6, '[{"name":"Creme Fraiche","measure":"150ml"},{"name":"Horseradish","measure":"2 tblsp"},{"name":"Lemon Juice","measure":"1 teaspoon"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Vegetable Oil","measure":"Dash"},{"name":"Shallots","measure":"2"},{"name":"Salt","measure":"Pinch"},{"name":"White Asparagus","measure":"8"},{"name":"Asparagus","measure":"8"},{"name":"Rye Bread","measure":"4 slices"},{"name":"Butter","measure":"1 tblsp"},{"name":"västerbottensost cheese","measure":"100g"},{"name":"Dill","measure":"Sprinking"},{"name":"Salt","measure":"Pinch"},{"name":"Black Pepper","measure":"Pinch"}]'::jsonb, '["To make the horseradish cream, mix the crème fraîche, grated horseradish, lemon juice, salt and white pepper in a bowl. Refrigerate until serving.","To make the crispy shallots, heat some vegetable oil in a frying pan over a medium heat. Add the sliced shallots and fry until golden brown and crispy.","Remove with a slotted spoon and drain on a plate lined with kitchen paper. Season with a pinch of salt.","To make the open sandwich, bring a large saucepan of salted water to the boil, then blanch half of the asparagus (four white and four green) until tender-crisp, about 2–3 minutes.","Add ice to a bowl of cold water. Use a slotted spoon to remove the asparagus from the boiling water and immediately transfer to the iced water to stop cooking. Thinly slice the remaining asparagus lengthwise to serve raw.","Pre-heat the grill until hot. Spread the rye bread with butter and grill until golden and crisp.","To serve, place the grilled bread slices on serving plates. Arrange both the blanched and raw asparagus on the bread. Drizzle with horseradish cream, then sprinkle grated cheese over the top. Garnish with the crispy shallots and some fresh dill to finish."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8a8fu01762772651.jpg', 'themealdb'),
('Fiskesuppe (Creamy Norwegian Fish Soup)', ARRAY['norway', 'seafood']::text[], ARRAY['pescatarian']::text[], 29, 70, 99, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Fish fillet","measure":"1 lb"},{"name":"Garlic","measure":"1 clove"},{"name":"Potatoes","measure":"2 medium"},{"name":"Carrots","measure":"2"},{"name":"Leek","measure":"1"},{"name":"Butter","measure":"3  tablespoons"},{"name":"Flour","measure":"5 tablespoons"},{"name":"Fish Stock","measure":"4 cups"},{"name":"Milk","measure":"1 cup"},{"name":"Creme Fraiche","measure":"1 1/4 cup"},{"name":"Shrimp","measure":"1 cup"},{"name":"Chives","measure":"1 tablespoon"}]'::jsonb, '["▢","Cut the fish fillets in cubes or strips. Crush or chop the garlic. Rinse the vegetables and cut into thin strips.","▢","Heat the butter in a pot and add the garlic. Once the garlic starts to turn golden add the flour, whisking well.","▢","Add the fish stock and continue to whisk until there are no lumps.","▢","Add the vegetables and milk and bring to a boil. Cook for about 10 minutes.","▢","Add the crème fraîche (or sour cream). Bring the soup back to a simmer and once the soup begins to bubble again turn off the heat. Keep the soup on the burner and add the fish. Let the fish cook in the hot soup for 5 minutes. If using shrimp, add right before serving.","▢","Sprinkle with chives (or dill or parsley) before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/raqjbj1762773035.jpg', 'themealdb'),
('Karbonader (Lean Beef Patties) with Caramelized Onions', ARRAY['norway', 'beef']::text[], ARRAY['gluten_free']::text[], 23, 75, 98, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Onion","measure":"2"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Ground Beef","measure":"1 lb"},{"name":"Salt","measure":"1/2 teaspoon"},{"name":"Pepper","measure":"1/2 teaspoon"},{"name":"Nutmeg","measure":"1/2 teaspoon"},{"name":"Cornstarch","measure":"1/2 tbs"},{"name":"Water","measure":"50 ml"},{"name":"Butter","measure":"2 tblsp"}]'::jsonb, '["Grate half an onion and set aside. Slice the rest of the onions and fry in butter on low/medium heat until caramelized.","▢","In a bowl, mix together ground beef, grated onion, salt, pepper, nutmeg, potato/corn starch, and water.","▢","Form into a sausage and cut 6 patties. Using a knife make a light grid pattern in each patty.","▢","Brown both sides of the karbonader in butter on high heat, then turn down to low heat and fry for another 2 – 3 minutes.","▢","Serve the karbonader and onions with potatoes, stewed peas, and brown sauce for dinner, or on a slice of bread for lunch or a snack."]'::jsonb, 'https://www.themealdb.com/images/media/meals/0bpjb11763075817.jpg', 'themealdb'),
('Kvæfjord Cake “Verdens Beste” (World’s Best Cake)', ARRAY['norway', 'dessert']::text[], ARRAY['vegetarian']::text[], 37, 175, 212, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Egg Yolks","measure":"2 large"},{"name":"Cornstarch","measure":"2 tblsp"},{"name":"Granulated Sugar","measure":"1/4 cup"},{"name":"Heavy Cream","measure":"2/3 Cup"},{"name":"Milk","measure":"3/4 cup"},{"name":"vanilla pod","measure":"1"},{"name":"Butter","measure":"2/3 Cup"},{"name":"Granulated Sugar","measure":"3/4 cup"},{"name":"Egg Yolks","measure":"5 Large"},{"name":"Flour","measure":"1 1/4 cup"},{"name":"Baking Powder","measure":"1.5 tsp"},{"name":"Milk","measure":"1/2 cup"},{"name":"Egg White","measure":"7"},{"name":"Granulated Sugar","measure":"1 1/2 cups"},{"name":"Almonds","measure":"Sliced"},{"name":"Whipping Cream","measure":"1 1/4 cup"}]'::jsonb, '["Vanilla custard","▢","Separate the egg yolks and set aside the whites to use in the meringue.","▢","Whisk together the egg yolks, cornstarch and sugar in a bowl.","▢","Heat the cream and milk in a saucepan. Split open the vanilla pod and add the beans to the saucepan. Once the milk begins to bubble pour about half of it into the bowl with the egg mixture, whisking constantly. Then return the saucepan to the heat and pour the egg mixture back into the saucepan with remaining milk, whisking constantly. Once the mixture thickens lower the heat and continue whisking for about 30 seconds.","▢","Pour the custard into a clean bowl and cover with plastic wrap, placing the plastic directly on the top layer of the custard. Chill in the fridge.","Cake","▢","Mix together butter and sugar until light and fluffy. Add egg yolks one at a time, setting aside the egg whites for the meringue. Add the flour mixed with baking powder. Stir in the milk, beating until smooth (you can use an electric mixer if you prefer).","▢","Preheat oven to 320°F (160°C). Cover a baking sheet with baking paper and spread out the batter into a large, even rectangle.","Meringue topping","▢","Whisk together the egg whites and sugar until you get glossy, stiff peaks. The meringue should hold its form – if it still melts continue whisking.","▢","Spread out the meringue on top of the cake batter. Use a spatula to form light waves with the meringue. Sprinkle almonds on top of the meringue. Bake for about 30 minutes, until the meringue and almonds are golden.","Cream filling","▢","Whisk the cream into stiff peaks. Carefully fold in the vanilla custard.","Assembly","▢","Once the cake has cooled, cut it in half. You can use scissors for this, or a knife on a cutting board, slicing through the baking paper as well.","▢","Place half of the cake on a serving platter with the meringue side down and peel off the baking paper.","▢","Spread the cream filling across the cake. Then carefully remove the other half of the cake from the baking paper and place it over the cream filling, meringue side up.","▢","Serve with fresh berries."]'::jsonb, 'https://www.themealdb.com/images/media/meals/gdn1ot1763075684.jpg', 'themealdb'),
('Suksessterte (Norwegian almond “success cake”)', ARRAY['norway', 'dessert']::text[], ARRAY['vegetarian']::text[], 25, 105, 130, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Almonds","measure":"2 cups"},{"name":"Egg","measure":"3"},{"name":"Granulated Sugar","measure":"1 1/4 cup"},{"name":"Flour","measure":"2 tblsp"},{"name":"Baking Powder","measure":"1 teaspoon"},{"name":"Egg Yolks","measure":"5"},{"name":"Heavy Cream","measure":"1/2 cup"},{"name":"Granulated Sugar","measure":"1/3 cup"},{"name":"Vanilla Extract","measure":"1 teaspoon"},{"name":"Butter","measure":"100g"}]'::jsonb, '["Almond base","▢","Preheat oven to 345°F (175°C) and grease cake form (I use a 27 cm spring form) – you can line the bottom with baking paper if you like.","▢","Grind almonds in an almond grinder or food processor. I like to keep them a bit coarse.","▢","Gently whisk the eggs and sugar together until combined (no longer). Stir in the ground almonds, flour, and baking powder.","▢","Pour batter into cake form and bake for about 45 – 50 minutes, monitoring to make sure the top doesn''t burn.","Yellow egg cream","▢","Add egg yolks, heavy cream, sugar, and vanilla to a saucepan. Heat over low/medium heat while stirring constantly until the mixture thickens – about 15 minutes. Turn up the heat if the mixture doesn''t thicken, but be careful not to boil.","▢","Let the mixture cool to room temperature and then add the butter. You can use an electric mixer for a fluffy egg cream.","Assembly","▢","Wait for the cake to cool completely before removing from form and frosting."]'::jsonb, 'https://www.themealdb.com/images/media/meals/de83k51763075604.jpg', 'themealdb'),
('Mazariner – Scandinavian Almond Tartlets', ARRAY['norway', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 105, 138, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Flour","measure":"3 Cups"},{"name":"Powdered Sugar","measure":"1 1/4 cup"},{"name":"Butter","measure":"200g"},{"name":"Egg","measure":"1"},{"name":"Egg","measure":"3"},{"name":"Powdered Sugar","measure":"1 1/4 cup"},{"name":"Butter","measure":"100g"},{"name":"Vanilla Extract","measure":"2 teaspoons"},{"name":"Flour","measure":"2 tblsp"},{"name":"Almond Flour","measure":"2 cups"},{"name":"Almond Extract","measure":"1 teaspoon"},{"name":"Powdered Sugar","measure":"2 cups"},{"name":"Heavy Cream","measure":"3  tablespoons"},{"name":"Almond Extract","measure":"1/4 tsp"}]'::jsonb, '["Shells","▢","Combine the flour and powdered sugar in a food processor. Add the butter and pulse until it''s evenly distributed. Add the egg and pulse until the dough comes together.","▢","Roll out the dough on a floured surface. Cut the dough in circles with a large mug. Press the circles down into a greased muffin pan. Put the pan of shells in the fridge while you prepare the almond filling.","Almond filling","▢","Preheat oven to 355°F (180°C).","▢","Whisk the egg and powdered sugar together until thick and airy. Melt the butter and stir it into the egg mixture. Stir in the vanilla, flour, and almond extract. Stir in the almond flour.","▢","Pipe or spoon the almond filling onto the shells, filling the shells about 3/4 full.","▢","Bake the mazariner for 20 – 25 minutes, until light golden brown. Cool on a wire rack.","Glaze","▢","Mix together the powdered sugar and liquid until you get a spreadable glaze. Spread the glaze on top of the mazariner and if you wish, decorate with sprinkles, or anything you like."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uh1n5u1763075545.jpg', 'themealdb'),
('Asado', ARRAY['argentina', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 13, 80, 93, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 2, '[{"name":"Mixed Beef Cuts","measure":"2kg"},{"name":"Chorizo","measure":"4"},{"name":"Morcilla","measure":"2"},{"name":"Salt","measure":"To taste"}]'::jsonb, '["Prepare the Fire: Start a wood fire in your grill and let it burn down to coals.","Season the Meat: Generously salt the beef cuts.","Grill the Meat: Place the beef on the grill, starting with the thickest cuts farthest from the coals. Add chorizo and morcilla after the beef has been cooking for a while.","Cook to Perfection: Cook the meat, turning occasionally, until it reaches your desired doneness. Typically, ribs may take up to 2 hours; thinner cuts will cook faster.","Rest and Serve: Let the meat rest for about 10 minutes before slicing. Serve with chimichurri sauce and grilled vegetables.","Pro Tips:","Use a mix of wood and charcoal for a consistent heat source. Wood adds flavor, while charcoal maintains temperature.","Season the meat just before grilling to ensure it retains its moisture and flavor.","Serving Suggestions:","Serve with a side of chimichurri sauce, a fresh tomato salad, and crusty bread. Pair with a robust Malbec wine to complement the rich flavors of the meat."]'::jsonb, 'https://www.themealdb.com/images/media/meals/kgfh3q1763075438.jpg', 'themealdb'),
('Empanadas', ARRAY['argentina', 'beef']::text[], ARRAY[]::text[], 29, 65, 94, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"All purpose flour","measure":"500g"},{"name":"Butter","measure":"200g"},{"name":"Water","measure":"120ml"},{"name":"Salt","measure":"1 tsp"},{"name":"Ground Beef","measure":"500g"},{"name":"Onion","measure":"2 chopped"},{"name":"Egg","measure":"4 Chopped"},{"name":"Green Olives","measure":"100g"},{"name":"Cumin","measure":"1 teaspoon"},{"name":"Paprika","measure":"1 teaspoon"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}]'::jsonb, '["Make the Dough: Mix flour and salt in a large bowl. Add butter, using your fingers to blend into a crumbly texture. Gradually add water, mixing until a dough forms. Wrap and chill for 30 minutes.","Prepare the Filling: Cook onions in a pan until translucent. Add ground beef, cooking until browned. Stir in spices, then remove from heat. Once cooled, mix in eggs and olives.","Assemble: Roll out the dough and cut into circles. Place a spoonful of filling in each, fold over, and seal the edges.","Cook: Bake at 200°C (400°F) for 20-25 minutes, or until golden.","Pro Tips:","For a flakier crust, incorporate a tablespoon of vinegar into the dough mixture. This helps prevent gluten formation.","Seal the edges of the empanadas with a fork to ensure they do not open during baking or frying."]'::jsonb, 'https://www.themealdb.com/images/media/meals/q99te31763075494.jpg', 'themealdb'),
('Milanesa', ARRAY['argentina', 'beef']::text[], ARRAY['dairy_free']::text[], 19, 65, 84, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef Cutlet","measure":"4"},{"name":"Egg","measure":"2 Beaten"},{"name":"Breadcrumbs","measure":"200g"},{"name":"Parsley","measure":"2 tbs chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}]'::jsonb, '["Season the Cutlets: Salt and pepper the cutlets.","Bread the Cutlets: Dip each cutlet in egg, then coat with a mixture of breadcrumbs, parsley, and garlic.","Fry: Heat oil in a large pan over medium heat. Fry the cutlets until golden and cooked through, about 3-4 minutes per side.","Serve: Serve hot with lemon wedges or a side salad.","Pro Tips:","For an extra crispy crust, use panko breadcrumbs mixed with finely grated Parmesan cheese.","Gently pound the cutlets to an even thickness for uniform cooking."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wdfa171763065079.jpg', 'themealdb'),
('Choripán', ARRAY['argentina', 'pork']::text[], ARRAY['dairy_free']::text[], 11, 65, 76, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 2, '[{"name":"Chorizo","measure":"4"},{"name":"Crusty Bread","measure":"4"},{"name":"Chimichurri sauce","measure":"Drizzle"}]'::jsonb, '["Grill the Chorizos: Cook the chorizos on a grill or pan until fully cooked, about 10-15 minutes.","Prepare the Rolls: Slice the rolls and toast them lightly on the grill or in a pan.","Assemble: Slice each chorizo lengthwise and place in a roll. Top with a generous amount of chimichurri sauce.","Serve: Enjoy immediately while hot.","Pro Tips:","Grill the chorizo slowly on medium heat to prevent the skin from bursting and to ensure it cooks evenly throughout.","Toast the bread on the grill to absorb some of the chorizo''s flavors."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5i25sg1763075353.jpg', 'themealdb'),
('Matambre a la Pizza', ARRAY['argentina', 'beef']::text[], ARRAY['gluten_free']::text[], 19, 65, 84, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef Flank Steak","measure":"1 kg"},{"name":"Tomato Sauce","measure":"200g"},{"name":"Mozzarella","measure":"200g"},{"name":"Oregano","measure":"1 tbsp"},{"name":"Green Olives","measure":"100g"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}]'::jsonb, '["Prepare the Steak: Season the steak with salt and pepper. Grill one side until half-cooked.","Add Toppings: Spread tomato sauce over the cooked side, then add cheese, oregano, and olives.","Finish Grilling: Grill until the cheese is melted and bubbly.","Serve: Slice and serve hot.","Pro Tips:","Tenderize the matambre by scoring it lightly on both sides. This helps it cook more evenly and absorb the flavors.","Precook the matambre on the grill before adding the toppings to ensure it''s fully cooked without burning the cheese."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wf49qs1763075222.jpg', 'themealdb'),
('Easy Spanish chicken', ARRAY['spanish', 'chicken']::text[], ARRAY['gluten_free']::text[], 29, 30, 59, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Extra Virgin Olive Oil","measure":"2 tbsp"},{"name":"Onion","measure":"1"},{"name":"Chorizo","measure":"150g"},{"name":"Red Pepper","measure":"1"},{"name":"Yellow Pepper","measure":"1"},{"name":"sweet smoked paprika","measure":"1 teaspoon"},{"name":"Garlic","measure":"4 cloves"},{"name":"Tinned Tomatos","measure":"400g"},{"name":"Green Olives","measure":"150g"},{"name":"Butter Beans","measure":"400g"},{"name":"Chicken Thighs","measure":"8"},{"name":"Parsley","measure":"1 Handfull"}]'::jsonb, '["Heat the oven to 200C/180C fan/gas 6. Heat the olive oil in a large ovenproof frying pan over a medium heat and fry the onion, chorizo and peppers along with a pinch of salt and pepper for 15 mins until the veg has softened and the chorizo has released its oils. Add the paprika and garlic, and cook for another few minutes until fragrant.","Tip in the chopped tomatoes, olives and butter beans, stir to combine and season. Nestle in the chicken thighs and season well. Transfer to the oven and bake for 40 mins until the chicken skin is crisp and the meat cooked through and tender. Scatter with the parsley and serve.","Watch after ad (0.04):","Budget Egg Ideas"]'::jsonb, 'https://www.themealdb.com/images/media/meals/kzxflc1763194887.jpg', 'themealdb'),
('Arroz con gambas y calamar', ARRAY['spanish', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 25, 25, 50, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Raw King Prawns","measure":"24"},{"name":"Olive Oil","measure":"2 tbsp"},{"name":"Onion","measure":"1 small"},{"name":"Bay Leaf","measure":"1"},{"name":"Saffron","measure":"1 pinch"},{"name":"Paella Rice","measure":"450g"},{"name":"Tomato Puree","measure":"2 teaspoons"},{"name":"White Wine","measure":"200ml"},{"name":"Seafood stock","measure":"650ml"},{"name":"Squid","measure":"3 Medium"}]'::jsonb, '["Peel and devein most of the prawns (a fishmonger should be able to do this for you), keeping a few whole for decoration, if you like. Heat the olive oil in a large frying pan or shallow flameproof casserole over a medium-low heat and fry the onion for 5 mins until softened. Add the bay leaf, saffron, rice and tomato purée, and cook for 1-2 mins more, stirring.","Pour in the wine and bubble for 1-2 mins, then pour in the seafood stock and 150ml water. Cook for 5 mins, then add the squid, season well and stir to combine. Bring to the boil, then cover and reduce the heat to a gentle simmer. Cook for 12 mins more, adding a little more water if the mixture starts to look dry.","Uncover the pan and stir through the peeled prawns, then arrange any whole prawns on top of the rice mixture. Cover again and simmer for a further 5-6 mins until the prawns are pink and cooked through. Leave to stand for a couple of minutes before serving from the pan."]'::jsonb, 'https://www.themealdb.com/images/media/meals/jc6oub1763196663.jpg', 'themealdb'),
('Spanish chicken pie', ARRAY['spanish', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 23, 25, 48, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Potatoes","measure":"1 kg"},{"name":"Paprika","measure":"3 tsp"},{"name":"Olive Oil","measure":"2 teaspoons"},{"name":"Onion","measure":"2 sliced"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Tinned Tomatos","measure":"800g"},{"name":"Chicken","measure":"300g"},{"name":"Roasted pepper","measure":"140g"},{"name":"Green Olives","measure":"Handful"}]'::jsonb, '["Heat oven to 200C/fan 180C/gas 6. Boil the potatoes for 15-20 mins until tender. Drain, return to the pan, then mash with some seasoning and 2 tsp of the paprika.","Meanwhile, heat the oil in a large pan, then fry the onions and garlic for a few mins until softened. Stir in the remaining paprika for 1 min, add the tomatoes , then, bring to a simmer. Tip into a large ovenproof dish, then stir in the chicken, peppers, olives and some seasoning.","Spoon over the mash, then bake for 15 mins until the mash is golden on top and the sauce is bubbling."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8ovxf41763253962.jpg', 'themealdb'),
('Chorizo & soft-boiled egg salad', ARRAY['spanish', 'pork']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 19, 45, 64, 'easy', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Baby New Potatoes","measure":"500g"},{"name":"Egg","measure":"4"},{"name":"Green Beans","measure":"225g"},{"name":"Chorizo","measure":"225g"},{"name":"Garlic Clove","measure":"1 sliced"},{"name":"Sherry vinegar","measure":"2 tbsp"},{"name":"Parsley","measure":"2 tbsp chopped"}]'::jsonb, '["Cook the potatoes in a large pan of boiling salted water for 12 mins, adding the eggs after 6 mins, and the beans for the final 2 mins. Drain everything and cool the eggs under cold running water.","Meanwhile fry chorizo slices for 1-2 mins, until beginning to crisp. Remove from the pan with a slotted spoon and set aside, leaving the oil from the chorizo in the pan. Add the garlic to the pan and cook gently for 1 min.","Remove the pan from the heat, stir in the vinegar and parsley, then toss with the potatoes, beans, chorizo and seasoning. Shell the eggs, cut into quarters and add to the salad."]'::jsonb, 'https://www.themealdb.com/images/media/meals/v8eaed1763257313.jpg', 'themealdb'),
('Pollo en pepitoria', ARRAY['spanish', 'chicken']::text[], ARRAY['dairy_free']::text[], 39, 35, 74, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Saffron","measure":"Pinch"},{"name":"Extra Virgin Olive Oil","measure":"4 tbsp"},{"name":"Garlic Clove","measure":"6"},{"name":"Almonds","measure":"35g"},{"name":"Stale bread","measure":"30g"},{"name":"Parsley","measure":"2 tbs chopped"},{"name":"Chicken Thighs","measure":"8"},{"name":"Onion","measure":"1 chopped"},{"name":"Carrots","measure":"1 chopped"},{"name":"Celery","measure":"1 chopped"},{"name":"Dry sherry","measure":"250ml"},{"name":"Chicken Stock","measure":"350ml"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Cloves","measure":"Pinch"},{"name":"Bay Leaves","measure":"2"},{"name":"Egg","measure":"2"},{"name":"Almonds","measure":"2 tblsp"}]'::jsonb, '["Put the saffron in a small bowl with 75ml of just-boiled water. Stir and set aside. Heat 2 tbsp of the oil in a broad, shallow casserole dish. Cook the garlic until pale gold in colour, then add the blanched almonds and bread, and continue to fry until everything is golden. Tip into a food processor with some salt and pepper and the parsley, and whizz together.","Heat 2 more tbsp of the oil in the pan and brown the chicken all over, seasoning as you cook. Put in a bowl and set aside.","Remove all but about 2 tbsp of chicken fat from the pan and cook the onion, carrot and celery until golden. Add the sherry, stirring to dislodge any brown bits that have stuck to the pan. Pour in the stock and the saffron (with its water), and bring to the boil, then turn the heat down to a simmer. Add the spices and bay leaves, and put the chicken back in the pan with any juices. Season and gently cook the chicken for about 40 mins with the lid on.","Transfer the chicken to a bowl again, leaving the sauce in the pan, and cover with foil to keep warm. Remove the yolks from the eggs and roughly chop the whites. Mash the egg yolks in a small bowl and gradually mix in a couple of tbsp of the sauce. Bring the remaining sauce to the boil to reduce a bit (you want it to just coat the chicken), then turn the heat down. Remove the bay and cinnamon stick. Add the egg yolks and cook for a few mins until the mixture has thickened. Stir in the almond mixture that you made earlier (this will thicken the sauce, too). Put the chicken back in the pan and heat it for about 3 mins, spooning the sauce over it. Season to taste.","Scatter over the extra parsley, the almonds pieces and the chopped egg whites (if you’re going to use them). You can serve this straight from the dish with some rice, if you like."]'::jsonb, 'https://www.themealdb.com/images/media/meals/li30ck1763281992.jpg', 'themealdb'),
('Spanish fig & almond balls', ARRAY['spanish', 'dessert']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 21, 30, 51, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Almonds","measure":"100g"},{"name":"Figs","measure":"500g"},{"name":"Dried Apricots","measure":"85g"},{"name":"Dried cranberries","measure":"50g"},{"name":"Brandy","measure":"1 tablespoon"},{"name":"Clear Honey","measure":"1 tblsp"},{"name":"Cloves","measure":"1 teaspoon"},{"name":"Sesame Seed","measure":"100g"}]'::jsonb, '["Whizz the almonds in a food processor until most are finely chopped, then tip into a large bowl. Roughly chop the figs, then whizz to a smooth sticky paste. Scrape onto the almonds then, using your hands, mix together well with the dried fruit, brandy, honey and cloves.","Divide the mixture into 6 and roll into balls. Tip the sesame seeds onto a tray, then roll the balls in them until covered. Cover the tray loosely with a clean tea towel, then leave the fig balls to dry for a week before packaging. Will keep in a cool place for 2 months."]'::jsonb, 'https://www.themealdb.com/images/media/meals/si2rty1763282314.jpg', 'themealdb'),
('Spanish Chicken', ARRAY['spanish', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 19, 20, 39, 'easy', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Chicken Thighs","measure":"8"},{"name":"Onion","measure":"3 sliced thinly"},{"name":"Paprika","measure":"2 teaspoons"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Parsley","measure":"Handful"},{"name":"Chicken Stock","measure":"150ml"},{"name":"Olive Oil","measure":"1 tablespoon"}]'::jsonb, '["Heat oven to 190C/170C fan/gas 5. Put all the ingredients into a large, wide ovenproof dish. Mix everything together with your hands and season.","Bake for 45 mins, stirring the onions after 20 mins, until the chicken is golden and the onions tender. Serve with rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/pqulvm1763282839.jpg', 'themealdb'),
('Seafood rice', ARRAY['spanish', 'seafood']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 21, 20, 41, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Olive Oil","measure":"1 tbsp"},{"name":"Leek","measure":"1 sliced"},{"name":"Chorizo","measure":"110g"},{"name":"Turmeric","measure":"1 teaspoon"},{"name":"Rice","measure":"300g"},{"name":"Fish Stock","measure":"1 L"},{"name":"Peas","measure":"200g"},{"name":"Frozen Seafood mix","measure":"400g"}]'::jsonb, '["Heat the oil in a deep frying pan, then soften the leek for 5 mins without browning. Add the chorizo and fry until it releases its oils. Stir in the turmeric and rice until coated by the oils, then pour in the stock. Bring to the boil, then simmer for 15 mins, stirring occasionally.","Tip in the peas and cook for 5 mins, then stir in the seafood to heat through for a final 1-2 mins cooking or until rice is cooked. Check for seasoning and serve immediately with lemon wedges."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5r5rvx1763287943.jpg', 'themealdb'),
('Chorizo & chickpea soup', ARRAY['spanish', 'pork']::text[], ARRAY['dairy_free']::text[], 19, 40, 59, 'easy', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Tinned Tomatos","measure":"400g"},{"name":"Chorizo","measure":"110g"},{"name":"Savoy Cabbage","measure":"140g"},{"name":"Chilli Flakes","measure":"Sprinkling"},{"name":"Chickpeas","measure":"400g can"},{"name":"Chicken Stock","measure":"1"},{"name":"Crusty Bread","measure":"To serve"}]'::jsonb, '["Put a medium pan on the heat and tip in the tomatoes, followed by a can of water. While the tomatoes are heating, quickly chop the chorizo into chunky pieces (removing any skin) and shred the cabbage.","Pile the chorizo and cabbage into the pan with the chilli flakes and chickpeas, then crumble in the stock cube. Stir well, cover and leave to bubble over a high heat for 6 mins or until the cabbage is just tender. Ladle into bowls and eat with crusty or garlic bread."]'::jsonb, 'https://www.themealdb.com/images/media/meals/kggfo91763288633.jpg', 'themealdb'),
('Ajo blanco', ARRAY['spanish', 'starter']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 15, 25, 40, 'easy', '{"calories":300,"protein_g":14,"carbs_g":28,"fat_g":14}'::jsonb, 2, '[{"name":"White bread","measure":"150g"},{"name":"Almonds","measure":"200g"},{"name":"Extra Virgin Olive Oil","measure":"50 ml"},{"name":"Garlic Clove","measure":"1"},{"name":"Red Wine Vinegar","measure":"1 ½ tbsp"}]'::jsonb, '["Tip the bread into a bowl and pour over 350ml water. Leave to soak for 10 mins.","Blend the ingredients together with 350ml water and 1 tsp salt.","Let the soup cool in the fridge for 1 hr or so, then serve with a drizzle of oil and some black pepper."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5jdtie1763289302.jpg', 'themealdb'),
('Salt cod tortilla', ARRAY['spanish', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 19, 25, 44, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Olive Oil","measure":"4 tbsp"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Jersey Royal Potatoes","measure":"300g"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Egg","measure":"8"},{"name":"Parsley","measure":"2 1/2 Tbs"},{"name":"Salt Cod","measure":"300g"}]'::jsonb, '["Heat half the oil in a frying pan, and sauté the onion over a medium heat until soft and pale gold – this will take about 8 mins. Remove from the pan, set aside, and add the potatoes to the pan. Cook until they are tender but not falling apart, carefully turning every so often. Cover the pan some of the time to help the slices cook through. Add the onions back to the pan along with the garlic and cook for another 4 mins. Tip into a bowl with the eggs, parsley and some seasoning and mix together. Leave to sit for half an hour.","Meanwhile, put the cod in a saucepan and cover with water. Bring up to a simmer. Remove from the heat, cover and leave for 10 mins. Drain, leave to cool and remove the skin and any bones. Break into large flakes and add to the potato and egg mixture.","Heat the rest of the oil in a non-stick frying pan. Pour in the tortilla mix and cook over a medium-low heat until it is just set and coming away from the sides of the pan. You might need to cover it to help the centre set. Be careful not to overcook it. Put a spatula underneath the tortilla every so often to make sure it isn’t sticking. Slide the tortilla onto a plate, then put the pan on top and flip the tortilla into it, uncooked side-down. Cook over a low heat until golden, or grill until just set. Leave to cool a little before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/njj1681763297231.jpg', 'themealdb'),
('Patatas bravas', ARRAY['spanish', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 27, 20, 47, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Olive Oil","measure":"3  tablespoons"},{"name":"Onion","measure":"1 small finely diced"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Tinned Tomatos","measure":"225g"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Paprika","measure":"2 teaspoon"},{"name":"Chilli Powder","measure":"Pinch"},{"name":"Sugar","measure":"Pinch"},{"name":"Parsley","measure":"Chopped"},{"name":"Potatoes","measure":"900g"},{"name":"Olive Oil","measure":"2 tbsp"}]'::jsonb, '["Heat the oil in a pan and fry the onion for about 5 mins until softened. Add the garlic, chopped tomatoes, tomato purée, sweet paprika, chilli powder, sugar and a pinch of salt, then bring to the boil, stirring occasionally. Lower to a simmer and cook for 10 mins until pulpy. Can be kept chilled for up to 24 hrs.","Heat oven to 200C/180C fan/gas 6. Pat the potatoes dry with kitchen paper, then tip into a roasting tin and toss in the olive oil and some seasoning. Roast for 40-50 mins until crisp and golden. Tip the potatoes into serving dishes and spoon over the tomato sauce. Sprinkle with some fresh parsley to serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/bvg8sn1763298713.jpg', 'themealdb'),
('Quick gazpacho', ARRAY['spanish', 'starter']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 17, 20, 37, 'easy', '{"calories":300,"protein_g":14,"carbs_g":28,"fat_g":14}'::jsonb, 2, '[{"name":"Passata","measure":"250g"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Sherry vinegar","measure":"1 teaspoon"},{"name":"Lime","measure":"Juice of 1/2"}]'::jsonb, '["step 1\r\nIn a blender (or with a stick blender), whizz together the passata, red pepper, chilli, garlic, sherry vinegar and lime juice until smooth.","Season to taste, then serve with ice cubes"]'::jsonb, 'https://www.themealdb.com/images/media/meals/h5qmn31763304965.jpg', 'themealdb'),
('Prawns with Romesco sauce', ARRAY['spanish', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 27, 35, 62, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Red Pepper","measure":"1"},{"name":"Garlic Clove","measure":"3 Large"},{"name":"Red Chilli","measure":"1 large"},{"name":"Tomato","measure":"1 large"},{"name":"Shelled Hazelnuts","measure":"10"},{"name":"Almonds","measure":"10"},{"name":"Parsley","measure":"3 sprigs"},{"name":"Bread","measure":"1 sliced"},{"name":"Olive Oil","measure":"120ml"},{"name":"Red Wine Vinegar","measure":"2 tblsp"},{"name":"Tiger Prawns","measure":"400g"}]'::jsonb, '["Prepare ahead - halve the pepper lengthways and remove the seeds and stalk. Line a grill pan with foil and put the pepper halves, skin side up, on the grill pan with the whole garlic cloves, chilli and tomato. Grill for 2 minutes, turn the tomato, then grill for a further 2 minutes. Remove the tomato with a large spoon, then peel, quarter and remove the seeds. Then chop the tomato roughly.","Continue grilling the pepper, chilli and garlic for 4-5 minutes, until the pepper and chilli skins have blackened and the garlic is starting to soften (the garlic skin will start to split when it is ready). When cool enough to handle, peel and halve the chilli, and scrape out and discard the seeds. Peel the pepper and roughly chop both the pepper and chilli.","Spread nuts over the foil and grill until toasted. Finely chop the nuts and parsley in a food processor. Tip into a small bowl.","Heat 3 tablespoons of oil in a frying pan, add the pepper, garlic and chilli and fry for 3 minutes. Tear up the bread and add to the pan, turning it in the oil until lightly browned. Pulse in food processor with the tomatoes, salt, vinegar and oil until roughly chopped. Tip into a bowl. Leave to cool and store in fridge for up to 3 days.","On the day add the nuts and parsley to the sauce and mix. Serve in a small bowl on a plate with the peeled prawns. Supply cocktail sticks for spearing the prawns."]'::jsonb, 'https://www.themealdb.com/images/media/meals/u03xhi1763308917.jpg', 'themealdb'),
('Spanish beans with chicken & chorizo', ARRAY['spanish', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 25, 25, 50, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Pinto Beans","measure":"300g"},{"name":"Onion","measure":"1 chopped"},{"name":"Paprika","measure":"1 tablespoon"},{"name":"Thyme","measure":"Sprigs of fresh"},{"name":"Bay Leaves","measure":"Pinch"},{"name":"Parsley","measure":"Bunch"},{"name":"Chicken Thighs","measure":"4"},{"name":"Jersey Royal Potatoes","measure":"250g"},{"name":"Chorizo","measure":"250g"},{"name":"Spinach","measure":"100g"}]'::jsonb, '["Soak the beans for at least 4 hrs or overnight in a large bowl with plenty of water to cover. Next day, rinse and drain, then put in a large heavy based pan with the onion, paprika, herb bundle and chicken. Pour over enough water or stock to cover, bring to the boil, then reduce the heat, cover and simmer for 45 mins.","Remove the chicken to a plate, then add the potatoes and chorizo to the pan. Continue cooking for 30 mins until the beans and potatoes are tender.","Discard the skin and bones from the chicken and tear into large chunks. Return the chicken to the pan with the spinach and simmer for 5 mins."]'::jsonb, 'https://www.themealdb.com/images/media/meals/bpkxtw1763332446.jpg', 'themealdb'),
('Chorizo & tomato salad', ARRAY['spanish', 'pork']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 17, 40, 57, 'easy', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 2, '[{"name":"Beef tomatoes","measure":"3"},{"name":"Red Onions","measure":"1/2"},{"name":"Thyme","measure":"Sprigs of fresh"},{"name":"Sherry vinegar","measure":"1 tablespoon"},{"name":"Extra Virgin Olive Oil","measure":"2 tblsp"},{"name":"Chorizo","measure":"100g"}]'::jsonb, '["Put the tomatoes in a bowl with the onion and thyme. Season, then drizzle with the vinegar and oil. Let the flavours mingle while you cook the chorizo.","In a hot, dry pan, fry the chorizo slices until browned on both sides. Serve the tomatoes with the fried chorizo, drizzled with a little oil from the pan."]'::jsonb, 'https://www.themealdb.com/images/media/meals/6cskio1763338156.jpg', 'themealdb'),
('Tom yum soup with prawns', ARRAY['thai', 'seafood']::text[], ARRAY['gluten_free']::text[], 33, 25, 58, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Onion","measure":"200g"},{"name":"Tomato","measure":"150g"},{"name":"Red Chilli","measure":"20g"},{"name":"Galangal","measure":"15g"},{"name":"Lemongrass Stalks","measure":"2"},{"name":"Raw King Prawns","measure":"250g"},{"name":"Chicken Stock Cube","measure":"1"},{"name":"Oyster Mushrooms","measure":"120g"},{"name":"makrut lime leaves","measure":"8"},{"name":"Fish Sauce","measure":"25 ml"},{"name":"Lime juice","measure":"25 ml"},{"name":"Coconut Milk","measure":"70 ml"},{"name":"Thai Chilli Jam","measure":"1 tblsp"},{"name":"Coriander","measure":"Handful"}]'::jsonb, '["Pour 1.3 litres water into a large saucepan over a high heat. Add the onion, tomato, chilli, galangal, lemongrass, prawn heads and chicken stock cube. Stir and bring to a boil, then reduce the heat to medium and simmer for 20 mins until the liquid has reduced.","Carefully strain the hot broth into a large heatproof bowl or jug, then discard the prawn heads. Return the strained veg and herb mixture to the saucepan and pour over the broth. Stir through the mushrooms and lime leaves, then cook for 3 mins until the mushrooms are tender.","Add 1 tbsp sugar, the fish sauce, lime juice, coconut milk and prawns. Bring to the boil and cook until the prawns are cooked through, about 1-2 mins. Remove from the heat. Remove the lemongrass, then stir in the Thai chilli jam, if using. Scatter over the coriander to finish, if you like, and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/l50vz41763422681.jpg', 'themealdb'),
('Tom yum (hot & sour) soup with prawns', ARRAY['thai', 'seafood']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 23, 20, 43, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Chicken Stock","measure":"700ml"},{"name":"Lemongrass","measure":"1"},{"name":"Galangal","measure":"5 Slices"},{"name":"Coriander","measure":"6"},{"name":"makrut lime leaves","measure":"3"},{"name":"King Prawns","measure":"6"},{"name":"Fish Sauce","measure":"3  tablespoons"},{"name":"Green Chilli","measure":"6 small"},{"name":"Lime juice","measure":"4 tablespoons"}]'::jsonb, '["Bring the stock to a boil in a medium-sized saucepan. Add the lemongrass, galangal, coriander roots and lime leaves, then simmer for 2 mins.","Add the prawns, fish sauce, chillies and lime juice, then return to the boil. Taste and adjust the seasoning with either more lime juice or fish sauce, then garnish with coriander leaves and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/9c5nlx1763424766.jpg', 'themealdb'),
('Thai-style steamed fish', ARRAY['thai', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 19, 20, 39, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Trout","measure":"2"},{"name":"Ginger","measure":"Knob"},{"name":"Garlic Clove","measure":"1 small finely diced"},{"name":"Red Chilli","measure":"1 small finely diced"},{"name":"Lime","measure":"Juice/zest of one"},{"name":"Baby Pak Koi","measure":"3"},{"name":"Soy Sauce","measure":"2 tblsp"}]'::jsonb, '["Nestle the fish fillets side by side on a large square of foil and scatter the ginger, garlic, chilli and lime zest over them. Drizzle the lime juice on top and then scatter the pieces of pak choi around and on top of the fish. Pour the soy sauce over the pak choi and loosely seal the foil to make a package, making sure you leave space at the top for the steam to circulate as the fish cooks.","Steam for 15 minutes. (If you haven’t got a steamer, put the parcel on a heatproof plate over a pan of gently simmering water, cover with a lid and steam.)"]'::jsonb, 'https://www.themealdb.com/images/media/meals/yx8j1i1763484612.jpg', 'themealdb'),
('Thai chicken cakes with sweet chilli sauce', ARRAY['thai', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 27, 20, 47, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Chicken Breast","measure":"2 large"},{"name":"Garlic","measure":"1 clove"},{"name":"Ginger","measure":"1 small"},{"name":"Onion","measure":"1 chopped"},{"name":"Coriander","measure":"4 tbs"},{"name":"Green Chilli","measure":"1 chopped"},{"name":"Olive Oil","measure":"2 tblsp"},{"name":"sweet chilli sauce","measure":"To serve"},{"name":"Lime","measure":"To serve"},{"name":"Spring Onions","measure":"Chopped"},{"name":"Red Chilli","measure":"Chopped"}]'::jsonb, '["Toss the chicken, garlic, ginger, onion, coriander and chilli into a food processor and season well. Blitz until the chicken is finely ground and everything is well mixed. Use your hands to shape six small cakes.","Heat the oil in a frying pan, then fry the cakes over a medium heat for about 6-8 mins, turning once. Serve hot, with sweet chilli sauce, lime wedges, coriander, shredded spring onion and red chilli."]'::jsonb, 'https://www.themealdb.com/images/media/meals/6s3i3p1763488540.jpg', 'themealdb'),
('Thai green chicken soup', ARRAY['thai', 'chicken']::text[], ARRAY['gluten_free']::text[], 33, 25, 58, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Sunflower Oil","measure":"2 tblsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Chicken Thighs","measure":"500g"},{"name":"Garlic Clove","measure":"4 sliced"},{"name":"Thai Green Curry Paste","measure":"280g"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Chicken Stock","measure":"2 Litres"},{"name":"Lime Leaves","measure":"5"},{"name":"Fish Sauce","measure":"2 tblsp"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Green Beans","measure":"280g"},{"name":"Bamboo Shoot","measure":"150g"},{"name":"Lime","measure":"Juice of 2"},{"name":"Basil","measure":"Bunch"}]'::jsonb, '["Heat the oil in your largest pan, add the onion and fry for 3 mins to soften. Add the chicken and garlic, and cook until the chicken changes colour.","Add the curry paste, coconut milk, stock, lime leaves and fish sauce, then simmer for 12 mins. Add the chopped onion tops, green beans and bamboo shoots and cook for 4-6 mins, until the beans are just tender.","Meanwhile, put the lime juice and basil in a narrow jug and blitz with a hand blender to make a smooth green paste. Pour into the soup with the sliced spring onion and heat through. Serve with lime wedges for a light lunch or supper or as a make-ahead starter."]'::jsonb, 'https://www.themealdb.com/images/media/meals/7kb44y1763589084.jpg', 'themealdb'),
('Pistachio Kunafa Chocolate Cake and Cupcakes', ARRAY['saudi_arabian', 'dessert']::text[], ARRAY['vegetarian']::text[], 31, 80, 111, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"White Chocolate","measure":"6 tablespoons"},{"name":"Unsalted Pistachio","measure":"1 cup"},{"name":"Condensed Milk","measure":"3  tablespoons"},{"name":"Milk","measure":"5 tablespoons"},{"name":"Oreo Cream Biscuits","measure":"25"},{"name":"Milk","measure":"1/2 cup"},{"name":"Baking Powder","measure":"1/2 teaspoon"},{"name":"Vinegar","measure":"1/2 teaspoon"},{"name":"Salt","measure":"1 pinch"},{"name":"Sevaiiya","measure":"150g"},{"name":"Ghee","measure":"1 tablespoon"},{"name":"Dark Chocolate","measure":"120ml"},{"name":"Malai","measure":"4 tablespoons"}]'::jsonb, '["For Chocolate Cake:Ready all the ingredients. Powder the oreo biscuits, pinch salt and mix warm milk as needed and make a cake batter. Add in baking powder and vinegar and mix.","Grease a loose bottomed tin. Pour a 1cm thick layer of the batter.","Bake in a preheated oven @160°C for 7-8 minutes or until the knife comes out clean. Cool on wire rack.","For Homemade Pistachio Paste:Ready all the pistachio paste ingredients. Slightly melt white chocolate on a double boiler.(else the mixer blade may break) Coarsely powder the pistachio in mixer. Add in condensed milk.","Add in slightly warmed and slightly melted white chocolate and milk as required and crush to a smooth paste.(Green food colour can be add. I haven''t.)","For Kunafa: In a kadhaai take ghee and roast the sevaiiya on slow gas. Keep stirring until a pleasant roasted aroma releases. Cool it. Add in the Homemade pistachio paste.Mix well.","Lip smacking Kunafa is ready. Spread a 2 cm layer on the cooled chocolate cake.","Melt dark chocolate and strained malai and prepare the chocolate ganache. Cool and pour on the Kunafa layer.","Garnish Pistachio Kunafa Chocolate Cake with chopped pistachio and silver balls. Keep in fridge for 2-3 hours. Then unmould the Kunafa Cake.","I also prepared Kunafa cupcakes. Cut and enjoy. The cake looked so pretty that we could either save it or have it!! ☺","Cross sectional view of the Pistachio Kunafa Chocolate Cake.","Enjoy with a new sweet delicacy this festive season with family and friends."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yh3sg71763741307.jpg', 'themealdb'),
('Yemeni Lahsa (Elite Shakshuka)', ARRAY['saudi_arabian', 'breakfast']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 19, 25, 44, 'easy', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Egg","measure":"5"},{"name":"Onion","measure":"1 Diced"},{"name":"Tomato","measure":"1 Diced"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Allspice","measure":"1/4 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Liquid Cheese","measure":"3  tablespoons"}]'::jsonb, '["First, On medium heat, heat the olive oil and add the diced onion until it wethers. Next, add the tomatoes and cook for another 4-5 min. Lastly, add the all spice, salt, and cracked pepper.","Add the eggs and mix throughly for 2 minutes and cover to cook 5-6 minutes until top is solidified. Lastly, spread the liquid cheese and have it covered for a minute.","I served mine Mediterranean style with hash-browns, Egyptian fava beans, Turkish salami and olives, cheese wedges, and greek feta."]'::jsonb, 'https://www.themealdb.com/images/media/meals/30s7vf1763741844.jpg', 'themealdb'),
('Shawarma bread', ARRAY['saudi_arabian', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 17, 45, 62, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Flour","measure":"1 cup"},{"name":"Salt","measure":"1 tsp"},{"name":"Sugar","measure":"1/2 tsp"},{"name":"Baking Powder","measure":"1/2 tsp"},{"name":"Oil","measure":"1 tablespoon"},{"name":"Water","measure":"Splash"}]'::jsonb, '["Sieve flour and add baking powder,salt,sugar,oil nd mix together","Add water nd knead the dough for like 10mins","Cover the mixture and allow it to rise","After it rised transfer it to a work surface and form a round (you can use a plate or pot''s lid)","Heat ur pan and put it","It''ll start puffing then you turn it","And lastly put it in in a warm place, then you''ll see it has pocket"]'::jsonb, 'https://www.themealdb.com/images/media/meals/i8l2fu1763742525.jpg', 'themealdb'),
('Rice paper dumplings', ARRAY['vietnamese', 'pork']::text[], ARRAY['dairy_free']::text[], 35, 50, 85, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"White Cabbage","measure":"1/4"},{"name":"Carrots","measure":"1"},{"name":"Shiitake Mushrooms","measure":"100g"},{"name":"Ground Pork","measure":"400g"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Ginger","measure":"20g"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Rice Paper Sheets","measure":"20"},{"name":"Vegetable Oil","measure":"75 ml"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Rice Vinegar","measure":"2 tablespoons"},{"name":"Sesame Seed","measure":"1/2 tbs"},{"name":"Spring Onions","measure":"2 sliced"}]'::jsonb, '["Tip the cabbage into a food processor and blitz until finely chopped. Season with ½ tsp salt, toss well and set aside for 15 mins. Tip into a clean tea towel and squeeze out as much water as you can. Tip into a bowl with the carrot, mushrooms, pork mince, garlic, ginger, soy sauce, sesame oil and spring onions. Season with black pepper. Scrunch everything together using your hands, mixing well until everything is combined.","Soak the spring roll sheets for a couple of seconds in a shallow dish of warm water, then transfer to an oiled chopping board. Working with one sheet at a time, spoon 1 heaped tbsp of the filling into the middle, then fold the bottom up and over the filling. Fold down the top of the sheet, then the sides to fully encase and make a neat square. If the dumpling feels a little fragile, soak another sheet and wrap it again. Repeat with the remaining sheets and filling, transferring the dumplings to an oiled plate as you go.","Heat the oil in a large, non-stick frying pan (ensuring it is no more than a third full) over a medium-high heat and fry the dumplings for 3-5 mins until golden brown. Use a slotted spoon or spider to turn them, then cover with a lid and cook for another 3-4 mins until golden. Remove the lid and cook for 1-2 mins.","Meanwhile, combine all the dipping sauce ingredients in small bowl. Serve the dumplings with the dipping sauce on the side."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sfahy01763752319.jpg', 'themealdb'),
('Vietnamese caramel trout', ARRAY['vietnamese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 23, 20, 43, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Golden Caster Sugar","measure":"50g"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Ginger","measure":"large piece"},{"name":"Rainbow Trout","measure":"2"},{"name":"Bok Choi","measure":"2 heads"},{"name":"Lemon","measure":"Juice of 1/2"},{"name":"Coriander","measure":"Sprigs of fresh"},{"name":"Rice","measure":"Steamed"}]'::jsonb, '["Put the sugar in a large shallow pan, along with a small splash of water. Heat gently, swirling the pan, until the sugar has dissolved. Increase the heat and bubble the syrup until it turns a dark amber colour. Add the fish sauce, most of the chilli and ginger, then splash in 1 tbsp water to dilute. Boil again until syrupy, then add the fish fillets, skin-side down, and the bok choi, cut-side down.","Cover the pan with a lid and simmer for 4-5 mins until the fish is cooked and the bok choi has wilted. Turn off the heat, squeeze over the lemon and scatter with the remaining chilli, ginger and the coriander sprigs. Serve with rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/p02vq41763754350.jpg', 'themealdb'),
('Purple sprouting broccoli tempura with nuoc cham', ARRAY['vietnamese', 'miscellaneous']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 25, 25, 50, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 4, '[{"name":"Corn Flour","measure":"50g"},{"name":"Plain Flour","measure":"100g"},{"name":"Sesame Seed","measure":"1 tablespoon"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Soda Water","measure":"250ml"},{"name":"Purple Sprouting Broccoli","measure":"200g"},{"name":"Fish Sauce","measure":"2 tablespoons"},{"name":"Lime","measure":"Juice of 2"},{"name":"Birds-eye Chillies","measure":"1 chopped"},{"name":"Sugar","measure":"2 tablespoons"}]'::jsonb, '["For the nuoc cham, whisk together all of the ingredients with 5 tbsp hot water in a small bowl. Set aside while you make the tempura.","Whisk the cornflour, plain flour, sesame seeds (if using) and a large pinch of salt together. Fill a large, deep pan no more than a third full with the vegetable oil and heat until it reaches 180C or a cube of bread dropped in browns in 20 seconds.","Quickly whisk the soda water into the flour mixture, being careful not to overmix, then dunk in the broccoli using tongs. Carefully lower into the hot oil and cook for 2-3 mins until crisp. Drain on kitchen paper, then serve with the nuoc cham on the side for dipping."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xnv4wf1763756529.jpg', 'themealdb'),
('Salt & pepper squid', ARRAY['vietnamese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 33, 20, 53, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Corn Flour","measure":"85g"},{"name":"Plain Flour","measure":"85g"},{"name":"Black Pepper","measure":"2 tsp"},{"name":"Szechuan Peppercorns","measure":"2 tsp"},{"name":"Sunflower Oil","measure":"For frying"},{"name":"Squid","measure":"400g"},{"name":"Spring Onions","measure":"Sliced"},{"name":"Green Chilli","measure":"Sliced"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Cucumber","measure":"1/2"},{"name":"Red Onions","measure":"1 chopped"},{"name":"Rice Vinegar","measure":"100 ml"},{"name":"Caster Sugar","measure":"1 tablespoon"},{"name":"Fish Sauce","measure":"2 tsp"}]'::jsonb, '["To make the dipping sauce, mix all the ingredients in a small bowl until the sugar has dissolved, then set aside. Mix the cornflour and plain flour with both peppers and 2 tsp sea salt in a large bowl, then set aside. Line a tray with kitchen paper and make sure you have more salt to sprinkle with.","Heat about 7cm of oil to 180C in a deep fryer, wok or deep pan. If you don’t have a thermometer, you can test it with a cube of bread – it should brown in 20 secs. Coat the squid well with the flour mix and fry in batches for about 2 mins each or until crisp. Use a slotted spoon to lift out the squid, then drain on the kitchen paper and sprinkle with a little more salt. Serve the squid scattered with the spring onion and chilli, with the dipping sauce on the side."]'::jsonb, 'https://www.themealdb.com/images/media/meals/yxiilf1763759428.jpg', 'themealdb'),
('Salmon noodle soup', ARRAY['vietnamese', 'seafood']::text[], ARRAY['dairy_free']::text[], 25, 20, 45, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Chicken Stock","measure":"1 L"},{"name":"Thai Red Curry Paste","measure":"2 tsp"},{"name":"Rice Noodles","measure":"100g"},{"name":"Shiitake Mushrooms","measure":"150g"},{"name":"Sweetcorn","measure":"125g"},{"name":"Salmon","measure":"2"},{"name":"Lime","measure":"Juice of 2"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Brown Sugar","measure":"Pinch"},{"name":"Coriander","measure":"Bunch"}]'::jsonb, '["Pour the stock into a large pan, bring to the boil, then stir in the curry paste. Add the noodles and cook for 8 mins. Tip in the mushrooms and corn and cook for 2 mins more.","Add the salmon to the pan and cook for 3 mins or until cooked through. Remove from the heat and stir in the lime juice, soy sauce and a pinch of sugar. Ladle into 4 bowls and sprinkle over the coriander just before you serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ikizdm1763760862.jpg', 'themealdb'),
('Vietnamese-style caramel pork', ARRAY['vietnamese', 'pork']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 27, 40, 67, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Ground Nut Oil","measure":"1 ½ tbsp"},{"name":"Pork Shoulder Steaks","measure":"500g"},{"name":"Shallots","measure":"2 chopped"},{"name":"Ground Ginger","measure":"1 tablespoon"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Brown Sugar","measure":"75g"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Chilli Sauce","measure":"2 tsp"},{"name":"Spring Onions","measure":"4"},{"name":"Rice","measure":"Steamed"},{"name":"Pak Choi","measure":"To serve"}]'::jsonb, '["Heat 1 tbsp of the oil in a wok over a high heat and stir-fry the pork in batches until browned all over. Remove with a slotted spoon and set aside.","Turn the heat right down and add the remaining oil, then stir in the shallots, ginger and chilli. Cook over a low heat for a couple of mins until just starting to soften. Add the sugar, fish sauce and 200ml water to the pan and stir everything together. Bring to the boil, stirring, so that the sugar dissolves, then return the pork to the pan. Bubble vigorously for 8-10 mins until the sauce thickens to coat the meat and become glossy. Taste and stir in a little more fish sauce, if needed, along with the chilli sauce. Sprinkle with the spring onions and serve with steamed rice and pak choi."]'::jsonb, 'https://www.themealdb.com/images/media/meals/4mzt101763761546.jpg', 'themealdb'),
('Vietnamese-style veggie hotpot', ARRAY['vietnamese', 'vegetarian']::text[], ARRAY['vegetarian']::text[], 27, 40, 67, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Vegetable Oil","measure":"2 tsp"},{"name":"Ginger","measure":"4cm finely chopped"},{"name":"Garlic Clove","measure":"2 chopped"},{"name":"Butternut Squash","measure":"1/2"},{"name":"Soy Sauce","measure":"2 tsp"},{"name":"Brown Sugar","measure":"2 tsp"},{"name":"Vegetable Stock","measure":"200ml"},{"name":"Green Beans","measure":"100g shredded"},{"name":"Spring Onions","measure":"4 sliced"},{"name":"Coriander Leaves","measure":"To serve"},{"name":"Jasmine Rice","measure":"To serve"}]'::jsonb, '["step 1\r\nHeat the oil in a medium-size, lidded saucepan.","Add the ginger and garlic, then stir-fry for about 5 mins.","Add the squash, soy sauce, sugar and stock.","Cover, then simmer for 10 mins.","Remove the lid, add the green beans, then cook for 3 mins more until the squash and beans are tender.","Stir the spring onions through at the last minute, then sprinkle with coriander and serve with rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/4uje7l1763762276.jpg', 'themealdb'),
('Beef pho', ARRAY['vietnamese', 'beef']::text[], ARRAY['dairy_free']::text[], 39, 45, 84, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef Stock","measure":"1 L"},{"name":"Onion","measure":"1 large"},{"name":"Ginger","measure":"1 Large Chopped"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Star Anise","measure":"2"},{"name":"Coriander Seeds","measure":"1 tsp"},{"name":"Cloves","measure":"1/2 teaspoon"},{"name":"Sirloin steak","measure":"225g"},{"name":"Palm Sugar","measure":"1 tsp"},{"name":"Fish Sauce","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"1 ½ tbsp"},{"name":"Rice Noodles","measure":"200g"},{"name":"Spring Onions","measure":"2 sliced"},{"name":"Birds-eye Chillies","measure":"1 small"},{"name":"Basil","measure":"Handful"},{"name":"Coriander","measure":"Handful"},{"name":"Lime","measure":"1"}]'::jsonb, '["Tip the beef stock along with 500ml of water into a large saucepan. Sit the onion and ginger in a frying pan over a high heat and char on all sides, around 3-5 mins (you can also do this under your grill). Once charred, add to the beef stock. In the same pan, toast the spices for 2-3 mins and once they begin to smell fragrant, add them to the beef stock as well. Bring the stock to the boil, then turn to a simmer and cook for 30mins before straining.","Meanwhile, cut the fat from the steak and wrap in cling film, then put into the freezer for 15 mins – this will make your steak really easy to slice! Slice it thinly, then cover with cling film again and pop into the fridge.","Taste the beef stock and use the palm sugar, fish sauce and soy to season. Cook the noodles according to package instructions and split between two bowls, topping each with the sliced beef. Bring the stock to the boil and then pour into the bowls (the heat will cook the beef). Top each with the spring onions, chilli slices and herbs. Serve with the lime wedges to squeeze over."]'::jsonb, 'https://www.themealdb.com/images/media/meals/pbzcrx1763765096.jpg', 'themealdb'),
('Tofu, greens & cashew stir-fry', ARRAY['vietnamese', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 27, 35, 62, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Broccoli","measure":"1 head"},{"name":"Garlic Clove","measure":"4 sliced"},{"name":"Red Chilli","measure":"1 sliced"},{"name":"Spring Onions","measure":"1  bunch"},{"name":"Soya Bean","measure":"140g"},{"name":"Pak Choi","measure":"2 heads"},{"name":"Marinated Tofu","measure":"300g"},{"name":"Hoisin Sauce","measure":"1 ½ tbsp"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Cashew Nuts","measure":"25g"}]'::jsonb, '["step 1\r\nHeat the oil in a non-stick wok.","Add the broccoli, then fry on a high heat for 5 mins or until just tender, adding a little water if it begins to catch.","Add the garlic and chilli, fry for 1 min, then toss through the spring onions, soya beans, pak choi and tofu.","Stir-fry for 2-3 mins.","Add the hoisin, soy and nuts to warm through."]'::jsonb, 'https://www.themealdb.com/images/media/meals/minfsc1763766806.jpg', 'themealdb'),
('Vietnamese veg parcels', ARRAY['vietnamese', 'vegetarian']::text[], ARRAY['dairy_free']::text[], 31, 25, 56, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Rice Flour Pancakes","measure":"100g"},{"name":"Rice Noodles","measure":"50g"},{"name":"Chicken Breast","measure":"1"},{"name":"Carrots","measure":"1 sliced"},{"name":"Cucumber","measure":"1 sliced"},{"name":"Red Pepper","measure":"1 sliced"},{"name":"Lettuce","measure":"To serve"},{"name":"Coriander","measure":"To serve"},{"name":"Mint","measure":"To serve"},{"name":"Fish Sauce","measure":"4 tablespoons"},{"name":"Rice Vinegar","measure":"2 tablespoons"},{"name":"Lime","measure":"Juice of 1/2"},{"name":"Red Chilli","measure":"1 sliced"}]'::jsonb, '["Soak the rice fl our pancakes according to pack instructions or in boiling water for 30 secs. Remove and cool on kitchen paper. Soak the rice noodles according to pack instructions, then drain and cut them into 2cm strips.","Lay a rice pancake on a board and arrange some rice noodles, chicken, vegetables and herb leaves about a third of the way up, leaving a 1cm edge at the side. Fold the sides over the vegetables and then roll up lengthways to make a cigar. Store in the fridge, covered with moist kitchen paper for up to 1 day.","Mix together the ingredients for the dipping sauce and put into a bowl. To serve, arrange the rolls on a plate along with the leaves and herbs. To eat, wrap each roll in a piece of lettuce with a herb sprig and dunk into the sauce."]'::jsonb, 'https://www.themealdb.com/images/media/meals/f698g91763768731.jpg', 'themealdb'),
('Barbecue pork buns', ARRAY['vietnamese', 'pork']::text[], ARRAY['dairy_free']::text[], 25, 45, 70, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Sugar","measure":"85g"},{"name":"White Bread Mix","measure":"500g"},{"name":"Sunflower Oil","measure":"1 tablespoon"},{"name":"Bacon","measure":"12"},{"name":"Ginger","measure":"Knob"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Clear Honey","measure":"3  tablespoons"},{"name":"Tomato Puree","measure":"3  tablespoons"},{"name":"Egg","measure":"1 beaten"}]'::jsonb, '["Heat the oven to 200C/fan 180C/gas. Mix the sugar into the bread mix in a large bowl, then add water as instructed on the pack. Bring the dough together with a wooden spoon, then knead on a lightly floured surface for 5 mins until smooth. Put into a large bowl, cover with oiled cling film then leave in a warm place until doubled in size.","Meanwhile, heat the oil in a pan, then fry the bacon until crisp, about 5 mins. Add the ginger and garlic and fry for 1 min until soft, then tip in the soy, honey and tomato purée and stir well. Can be made up to 3 days ahead.","Turn out the dough and knead briefly, then pull into 12 even-sized balls. Flatten with your hands, then put a teaspoon-size blob of the filling in the middle. Draw the dough up and pinch it closed like a purse, then turn the bun over and sit it on a large baking sheet. Cover with oiled cling film and leave to rise for about 30 mins until the dough feels pillowy. Brush with egg and bake for 20 mins until golden. Serve warm with dipping sauce. Can be frozen after second rise for up to 1 month or baked up to a day ahead and re-warmed."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tzsy461763769901.jpg', 'themealdb'),
('Noodle bowl salad', ARRAY['vietnamese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 31, 20, 51, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Rice Noodles","measure":"125g"},{"name":"Sugar Snap Peas","measure":"200g"},{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Spring Onions","measure":"4 sliced"},{"name":"Coriander","measure":"Handful"},{"name":"Hot Smoked Flaked Salmon","measure":"150g"},{"name":"Pretzels","measure":"To serve"},{"name":"Soy Sauce","measure":"3  tablespoons"},{"name":"Clear Honey","measure":"1 tablespoon"},{"name":"Lemon Juice","measure":"1 tablespoon"},{"name":"Ground Nut Oil","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Ginger","measure":"Knob"}]'::jsonb, '["Drop the noodles into a large bowl, then pour over enough boiling water to cover. Tip in the sliced sugar snaps and leave for 4 minutes. Drain in a colander, put under cold running water to cool off, then drain again. Tip into a bowl and toss in the sesame oil.","Mix the dressing ingredients. Pile spring onions, coriander and salmon onto the noodles, pour over the dressing and toss everything together. Serve with a pretzel or bread roll."]'::jsonb, 'https://www.themealdb.com/images/media/meals/zry07j1763779321.jpg', 'themealdb'),
('Salmon noodle wraps', ARRAY['vietnamese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 19, 20, 39, 'easy', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Rice Noodles","measure":"100g"},{"name":"Spring Onions","measure":"3 sliced thinly"},{"name":"Petit Pois","measure":"50g"},{"name":"Chilli","measure":"85g"},{"name":"Coriander","measure":"85g"},{"name":"Lime","measure":"85g"},{"name":"Salmon","measure":"300g"}]'::jsonb, '["Heat oven to 200C/fan 180C/gas 6. Put the noodles in a bowl and pour over enough boiling water to just cover them. Leave for 2 mins, until they are bendable, but not too soft, then drain well. Return to the bowl with the spring onions, petit pois, salt and pepper and a third of the butter. Mix well until the butter has melted.","Pile the noodles and vegetables onto two large squares of baking parchment, then sit the salmon on top. Slice the remaining butter and arrange over the top of the salmon. Bring the ends of the paper over the fish, fold them together to seal, then tuck the ends of the paper underneath so there are no gaps. Put the parcels on a baking sheet and bake for 15-20 mins. Transfer to dinner plates and serve without delay."]'::jsonb, 'https://www.themealdb.com/images/media/meals/prrirc1763781360.jpg', 'themealdb'),
('Turkish lahmacun', ARRAY['vietnamese', 'beef']::text[], ARRAY['dairy_free']::text[], 33, 70, 103, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Strong white bread flour","measure":"500g"},{"name":"Fast action yeast","measure":"10g"},{"name":"Corn Flour","measure":"Sprinkling"},{"name":"Tomato","measure":"2"},{"name":"Green Chilli","measure":"2"},{"name":"Spring Onions","measure":"4 Chopped"},{"name":"Parsley","measure":"Bunch"},{"name":"Ground Beef","measure":"250g"},{"name":"Chilli Flakes","measure":"2 tsp"},{"name":"Ground Cumin","measure":"Pinch"},{"name":"Allspice","measure":"1 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Lemon","measure":"1/2"},{"name":"Red Onions","measure":"1"}]'::jsonb, '["Sift the flour into a large bowl, make a well in the middle and sprinkle in the yeast. Pour 125ml water over the yeast, then flick flour over the liquid to create a layer. Cover and leave to rise in a warm place for 15 mins until cracks appear on the surface of that layer.","Use your hands to mix in 250ml more water along with 1 tsp salt and knead the dough for about 10 mins until elastic and no longer sticky. Add a little more flour if you need to. Cover and leave to rise again in a warm place for 30 mins until doubled in size.","Heat the oven to as high as it will go (about 240C/220C fan/gas 9) and sprinkle one or two baking trays thinly with cornmeal.","Pour boiling water from the kettle over the tomatoes, leave to stand briefly, then drain and slip off the skins. Cut the tomatoes in half, cut out the stalks, scoop out the seeds and discard, then chop the flesh.","Halve the chillies lengthways, cut out the stalks, seeds and white inner membrane, then rinse. Cut lengthwise into fine strips, then crosswise into fine dice.","Put the tomatoes, chillies, spring onions, finely chopped parsley, beef mince, spices, 1 tsp salt and ½ tsp freshly ground black pepper into a bowl and mix well.","Take the dough and knead it briefly, then divide into four pieces and shape each into a ball. Roll each ball into a thin circle, place on the prepared baking trays. Spread with a thin layer of the meat mixture.","Bake each flatbread for 10-15 mins until the edges begin to darken. After removing from the oven, sprinkle the lahmacun with the roughly chopped parsley and sliced onion, then squeeze over a few drops of lemon juice. Serve straightaway."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tqd3ac1763786065.jpg', 'themealdb'),
('Turkish rice (vermicelli rice)', ARRAY['turkish', 'miscellaneous']::text[], ARRAY[]::text[], 15, 25, 40, 'easy', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Rice","measure":"300g"},{"name":"Vegetable Oil","measure":"3  tablespoons"},{"name":"Vermicelli Pasta","measure":"70g"},{"name":"Unsalted Butter","measure":"30g"},{"name":"Chicken Stock","measure":"600ml"}]'::jsonb, '["Pour the rice into a very large bowl under cold running water and carefully drain the water out of the bowl through a sieve. Repeat a few times until the water in the bowl is clear, then fill the bowl up with cold water and leave rice to soak for 10 mins while you cook the vermicelli.","Put the oil into a medium pan over medium heat. Add the vermicelli and stir continuously until the strands turn a rich golden brown, 2-3 mins. Remove from the heat, stir through the butter until it melts and allow the vermicelli to cool for 1-2 mins.","Drain the rice thoroughly through a sieve. Add the rice to the pan and stir well. Pour the hot stock into the pan, sprinkle in ½ tsp salt, stir well then return the pan to the hob over a high heat. Bring to the boil, then reduce the heat to the lowest it will go, put the lid on the pan and simmer for 7-9 mins. Remove the pan from the heat, cover with a couple of sheets of kitchen paper or a light tea towel and the pan lid, and let the rice sit in the pan for 10 mins. Fluff up with a fork before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xw1ruy1763786501.jpg', 'themealdb'),
('Hot cumin lamb wrap with crunchy slaw & spicy mayo', ARRAY['turkish', 'lamb']::text[], ARRAY['dairy_free']::text[], 27, 45, 72, 'medium', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 4, '[{"name":"Lamb Leg","measure":"4 small"},{"name":"Olive Oil","measure":"2 tsp"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"White Wine Vinegar","measure":"3  tablespoons"},{"name":"Carrots","measure":"2"},{"name":"Spring Onions","measure":"2 sliced"},{"name":"White Cabbage","measure":"400g"},{"name":"Sweet Peppadew Peppers","measure":"5"},{"name":"Mayonnaise","measure":"3  tablespoons"},{"name":"Pita Bread","measure":"4 large"}]'::jsonb, '["Heat a griddle pan. Rub the lamb steaks with the oil, cumin and some seasoning. Griddle for about 3-4 mins on each side or until cooked to your liking. Place to one side on a plate to rest.","In a large bowl, stir the sugar into the vinegar until dissolved. Add the carrots, spring onions, cabbage and some seasoning, and toss together.","Blitz the whole peppers and the mayo in a food processor. Add a heap of the salad to each flatbread. Slice the lamb, trimming off any excess fat and lay on top of the salad, drizzling with the resting juices. Spoon over the mayo and scatter with a few of the sliced peppers. Roll up and eat. If using pitta, split and stuff. Serve any extra salad on the side."]'::jsonb, 'https://www.themealdb.com/images/media/meals/jyylmo1763790808.jpg', 'themealdb'),
('Smoked aubergine purée', ARRAY['turkish', 'side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 15, 20, 35, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Aubergine","measure":"2 medium"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Yogurt","measure":"150ml"},{"name":"Dill","measure":"Bunch"}]'::jsonb, '["Heat grill to very hot. Slice the aubergines in half lengthways, then grill for 25 mins, turning occasionally, until soft – the skin will remain firm, but the flesh will soften. Lift the aubergines off the grill and leave until cool enough to handle.","Using a sharp knife, score the grilled flesh and scoop out the flesh with a spoon. Tip into a bowl and mash with a fork until you get a thick pulp. Beat in the lemon juice and garlic. Add the yogurt and dill, and season. Serve while still warm."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8c8m4q1763791156.jpg', 'themealdb'),
('Chicken wings with cumin, lemon & garlic', ARRAY['turkish', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 17, 20, 37, 'easy', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 2, '[{"name":"Chicken Wings","measure":"12"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Cumin Seeds","measure":"1 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Honey","measure":"1 tablespoon"}]'::jsonb, '["Using a pair of sharp kitchen scissors, cut each wing at the knuckle into two pieces. Mix the garlic, lemon zest and juice, cumin and oil with plenty of seasoning, then tip into a dish with the chicken wings and toss to coat. Cover and put in the fridge to marinate for at least 1 hr, or overnight if you have time.","Heat oven to 200C/180C fan/gas 6, or heat an outdoor barbecue. Bake the chicken wings on an oven tray for 45-50 mins until crisp, or barbecue for 20 mins, drizzling over the honey for the final 10 mins of each method. Serve on a platter with plenty of paper napkins. Fill small bowls with olives, pistachios or almonds, dates and pickled chillies and flatbreads to serve alongside, along with the dishes below."]'::jsonb, 'https://www.themealdb.com/images/media/meals/4hzyvq1763792564.jpg', 'themealdb'),
('Turkish lamb pilau', ARRAY['turkish', 'lamb']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 23, 40, 63, 'medium', '{"calories":540,"protein_g":36,"carbs_g":12,"fat_g":38}'::jsonb, 4, '[{"name":"Pine Nuts","measure":"Handful"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 Large Chopped"},{"name":"Cinnamon","measure":"2"},{"name":"Lamb","measure":"500g"},{"name":"Basmati Rice","measure":"250g"},{"name":"Lamb Stock","measure":"1"},{"name":"Dried Apricots","measure":"12"},{"name":"Mint","measure":"Handful"}]'::jsonb, '["Dry-fry the pine nuts or almonds in a large pan until lightly toasted, then tip onto a plate. Add the oil to the pan, then fry the onion and cinnamon together until starting to turn golden. Turn up the heat, stir in the lamb, fry until the meat changes colour, then tip in the rice and cook for 1 min, stirring all the time.","Pour in 500ml boiling water, crumble in the stock cube, add the apricots, then season to taste. Turn the heat down, cover and simmer for 12 mins until the rice is tender and the stock has been absorbed. Toss in the pine nuts and mint and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/cr2kyr1763793839.jpg', 'themealdb'),
('Hummus', ARRAY['turkish', 'side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 15, 25, 40, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Chickpeas","measure":"400g"},{"name":"Tahini Paste","measure":"1 tablespoon"},{"name":"Garlic Clove","measure":"1 large"},{"name":"Greek Yogurt","measure":"3  tablespoons"},{"name":"Lemon","measure":"Juice of half"}]'::jsonb, '["Drain the chickpeas into a sieve set over a bowl or jug to catch the liquid. Tip the chickpeas, tahini, garlic and yogurt into a food processor or blender and whizz to smooth.","Whizz in a tbsp of the chickpea liquid at a time until you have a nice consistency, then scrape into a bowl.","Stir in a squeeze of lemon juice and season to taste."]'::jsonb, 'https://www.themealdb.com/images/media/meals/gpon5u1763801180.jpg', 'themealdb'),
('Griddled flatbreads', ARRAY['turkish', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 15, 25, 40, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Strong Wholemeal Flour","measure":"250g"},{"name":"Strong white bread flour","measure":"250g"},{"name":"Yeast","measure":"15g"},{"name":"Sugar","measure":"1 tsp"},{"name":"Olive Oil","measure":"2 tablespoons"}]'::jsonb, '["Tip the flours into a food processor. Add the yeast, sugar and 1tsp salt, then mix well. Pour in 350ml warm water and the oil, then process to a soft dough. Mix for 1 min, then leave until doubled in size, about 1 hour.","Pulse the dough a couple of times just to knock out the air, then tip onto a floured surface. Cut the dough in half and roll out one half to a rectangle about 20 x 40cm. Trim the edges using a large sharp knife, then cut into eight 10cm squares. Line a large tray or two baking sheets with non-stick paper and arrange the bread rectangles over the tray in one layer. Repeat with the other half of the dough. Leave in a warm place for about 30 mins until the dough is just starting to rise.","Place bread directly onto the BBQ racks and cook for a couple of mins until they puff up, then flip over and cook on the other side. Tip into a basket and serve with the dips."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8825lo1763815264.jpg', 'themealdb'),
('Poulet Roti a l''Algerienne (Algerian Roast Chicken)', ARRAY['algerian', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 25, 25, 50, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Water","measure":"1 cup"},{"name":"Onion","measure":"1 chopped"},{"name":"Olive Oil","measure":"5 tablespoons"},{"name":"Balsamic Vinegar","measure":"2 tablespoons"},{"name":"Dijon Mustard","measure":"1 tablespoon"},{"name":"Garlic","measure":"3 Cloves Crushed"},{"name":"Black Pepper","measure":"1 tsp"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Chicken","measure":"1"}]'::jsonb, '["Preheat oven to 350 degrees F (175 degrees C).","Mix water, onion, olive oil, balsamic vinegar, Dijon mustard, garlic, black pepper, cayenne pepper, and salt together in a roasting dish. Add chicken; turn until well coated with mixture.","Bake in the preheated oven until an instant-read thermometer inserted into the thickest part of the thigh, near the bone, reads 165 degrees F (74 degrees C), about 1 hour 30 minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/nlxald1764112200.jpg', 'themealdb'),
('Algerian Kefta (Meatballs)', ARRAY['algerian', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 21, 50, 71, 'easy', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Ground Beef","measure":"1 lb"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Onion","measure":"1/2 cup"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Plum Tomatoes","measure":"3"},{"name":"Parsley","measure":"1 tsp"},{"name":"Water","measure":"1/2 cup"}]'::jsonb, '["Combine ground beef with 1/2 of the minced garlic and 1 tablespoon chopped onion in a large bowl. Mix with your hands until fully incorporated. Shape meat mixture into 1 1/2-inch oblong patties; you should have 12 to 14 meatballs.","Heat a large skillet over medium-high heat. Brown patties in batches in the hot skillet until crispy on both sides and no longer pink in the center, about 10 minutes. Set meatballs aside in a rimmed serving dish.","Reduce heat to medium and stir remaining chopped onion into drippings in the skillet. Season with salt and pepper. Cook, stirring constantly, until onion has softened and turned translucent, about 5 minutes. Stir in remaining garlic and cook for 30 seconds. Stir in Roma tomatoes, dried parsley, and ras el hanout. Pour in water. Cook until tomatoes are soft, about 5 minutes.","Pour tomato sauce over meatballs to serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8rfd4q1764112993.jpg', 'themealdb'),
('Chtitha Batata (Algerian Potato Stew)', ARRAY['algerian', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 29, 25, 54, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Garlic","measure":"4 cloves"},{"name":"Red Chilli","measure":"1 small"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Paprika","measure":"1 teaspoon"},{"name":"Black Pepper","measure":"1/2 teaspoon"},{"name":"Cayenne Pepper","measure":"1/2 teaspoon"},{"name":"Salt","measure":"1/2 teaspoon"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"New Potatoes","measure":"2 Lbs"},{"name":"Tomato Puree","measure":"1 tablespoon"},{"name":"Water","measure":"Boiled"},{"name":"Salt","measure":"To taste"}]'::jsonb, '["Combine garlic, chile pepper, cumin, paprika, black pepper, cayenne, and salt in a mortar; grind with a pestle until it forms a paste. Add olive oil and mix dersa well.","Heat a large saucepan over medium heat and stir-fry dersa until fragrant, 2 to 4 minutes. Add potato halves and stir to combine with the dersa. Stir in tomato paste. Pour in enough water to just cover the potatoes and bring to a boil. Reduce heat and simmer until potatoes are tender, about 40 minutes.","Ladle potatoes into a serving bowl. Spoon any remaining sauce over the potatoes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/q8pu1k1764114334.jpg', 'themealdb'),
('Algerian Bouzgene Berber Bread with Roasted Pepper Sauce', ARRAY['algerian', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 27, 35, 62, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Red Pepper","measure":"2"},{"name":"Tomato","measure":"4"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Jalapeno","measure":"1 chopped"},{"name":"Salt","measure":"To taste"},{"name":"Semolina","measure":"2 Lbs"},{"name":"Salt","measure":"1 1/2 tsp"},{"name":"Water","measure":"3 Cups"},{"name":"Olive Oil","measure":"4 tablespoons"},{"name":"Olive Oil","measure":"6 tablespoons"}]'::jsonb, '["Preheat your oven''s broiler. Place red bell peppers and tomatoes on a baking sheet, and roast under the broiler for about 8 minutes, turning occasionally. This should blacken the skin and help it peel off more easily. Cool, then scrape the skins off of the tomatoes and peppers, and place them in a large bowl. Remove cores and seeds from the bell peppers.","Heat 1 tablespoon of olive oil in a skillet over medium heat. Add the jalapenos and garlic, and cook until tender, stirring frequently. Remove from heat, and transfer the garlic and jalapeno to the bowl with the tomatoes and red peppers. Using two sharp steak knives (one in each hand), cut up the tomatoes and peppers to a coarse and soupy consistency. Stir, and set sauce aside.","Place the semolina in a large bowl, and stir in salt and 4 tablespoons of olive oil. Gradually add water while mixing and squeezing with your hand until the dough holds together without being sticky or dry, and molds easily with the hand. Divide into 6 pieces and form into balls.","For each round, heat 1 tablespoon of olive oil in a large heavy skillet over medium heat. Roll out dough one round at a time, to no thicker than 1/4 inch. Fry in the hot skillet until dark brown spots appear on the surface, and they are crispy. Remove from the skillet, and wrap in a clean towel while preparing the remaining flat breads.","To eat the bread and sauce, break off pieces of the bread, and scoop them into the sauce. It will slide off, but just keep reaching in!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/se5vhk1764114880.jpg', 'themealdb'),
('Khobz el Dar (Algerian Semolina Bread)', ARRAY['algerian', 'side']::text[], ARRAY['vegetarian']::text[], 31, 50, 81, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Semolina Flour","measure":"1/2 cup"},{"name":"Semolina Flour","measure":"2 tablespoons"},{"name":"Sesame Seed","measure":"3  tablespoons"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Yeast","measure":"1 tsp"},{"name":"Salt","measure":"3/4 teaspoon"},{"name":"Vegetable Oil","measure":"1/4 cup"},{"name":"Egg","measure":"1"},{"name":"Egg","measure":"1"},{"name":"Milk","measure":"1 cup"},{"name":"All purpose flour","measure":"3 Cups"},{"name":"All purpose flour","measure":"2 tablespoons"},{"name":"Water","measure":"1 tsp"}]'::jsonb, '["Mix 1/2 cup plus 2 tablespoons semolina, 2 tablespoons sesame seeds, sugar, yeast, and salt together in a large bowl. Whisk in oil, egg, and egg white. Stir in warm milk slowly until a liquid dough forms.","Cover the bowl with a plate or plastic wrap; let stand at room temperature until frothy, about 1 hour.","Stir in 2 3/4 cups flour with a wooden spoon until a sticky dough forms. Cover again and allow to rest for 30 minutes.","Line a baking sheet with parchment paper or a baking mat.","Sprinkle 1 tablespoon flour over the dough and your hands. Mix dough, adding flour as needed, 1 tablespoon at a time, until it pulls away from the sides of the bowl. Shape into a round loaf and place on the prepared baking sheet. Cover loosely with a towel and let rise for 1 hour in a warm place until loaf doubles in volume.","Preheat oven to 400 degrees F (200 degrees C).","Beat egg yolk and water in a bowl with a fork; brush over the entire surface of the loaf. Sprinkle 1 tablespoon sesame seeds on top.","Bake in the preheated oven until loaf is golden brown, about 20 to 25 minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5u37fy1764116774.jpg', 'themealdb'),
('Tajine de Poulet aux Carottes et Patates Douces (Chicken and Sweet Potato Tagine)', ARRAY['algerian', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 41, 35, 76, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Onion","measure":"2 sliced"},{"name":"Celery","measure":"2 sliced"},{"name":"Cilantro","measure":"1/2 bag"},{"name":"Parsley","measure":"1/2 bag"},{"name":"Turmeric","measure":"1/2 tsp"},{"name":"Ground Cumin","measure":"1/2 tsp"},{"name":"Paprika","measure":"1/2 teaspoon"},{"name":"Ground Ginger","measure":"1/4 tsp"},{"name":"Cayenne Pepper","measure":"1/4 tsp"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"},{"name":"Chicken Thighs","measure":"4"},{"name":"Olive Oil","measure":"Drizzle"},{"name":"Raisins","measure":"1/4 cup"},{"name":"Chicken Stock","measure":"1 cup"},{"name":"Sweet Potatoes","measure":"1 large"},{"name":"Carrots","measure":"3 sliced thinly"},{"name":"Prunes","measure":"1/4 cup"}]'::jsonb, '["Combine onions, celery, cilantro, and parsley in a large pot. Stir in turmeric, cumin, paprika, ginger, cayenne pepper, salt, and pepper. Place chicken thighs on top. Drizzle olive oil over chicken. Cover and simmer over low heat until chicken is tender, about 40 minutes.","Place raisins in a small bowl and cover with hot water; let soak for 10 minutes. Drain.","Preheat oven to 400 degrees F (200 degrees C).","Transfer chicken mixture into an oven-safe tagine or casserole dish. Add sweet potato and carrots. Cover with lid or aluminum foil.","Bake in the preheated oven until sweet potato is soft, about 40 minutes. Add drained raisins and prunes. Continue baking, covered, until raisins and prunes are heated through, about 10 minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/d8bfyg1764117503.jpg', 'themealdb'),
('Algerian Flafla (Bell Pepper Salad)', ARRAY['algerian', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 19, 25, 44, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Green Pepper","measure":"3"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Red Onions","measure":"1 tablespoon chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Plum Tomatoes","measure":"1 Diced"}]'::jsonb, '["Preheat an oven to 450 degrees F (230 degrees C). Place the whole peppers on aluminum foil. Bake until the skin is spotted black and the peppers are soft, 30 to 45 minutes, turning the peppers once if necessary.","Remove peppers from the oven and set aside to cool for 10 minutes. Peel off the skin and remove the stem and seeds. Chop the roasted peppers into half-inch pieces.","Heat the olive oil in a skillet over medium heat. Stir in the onion and cook, stirring frequently, until the onion has softened and turned translucent, about 5 minutes. Add the garlic, salt, and pepper; stir in the chopped peppers and tomato. Cook over medium heat, stirring occasionally, until the tomato is soft and the mixture is well incorporated, about 5 minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tbj1bs1764118062.jpg', 'themealdb'),
('Piernik (Polish gingerbread)', ARRAY['polish', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 35, 68, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Unsalted Butter","measure":"140g"},{"name":"Clear Honey","measure":"300g"},{"name":"Brown Sugar","measure":"100g"},{"name":"Self-raising Flour","measure":"375g"},{"name":"Ground Ginger","measure":"3 tsp"},{"name":"Ground Cinnamon","measure":"1 tsp"},{"name":"Ground Clove","measure":"1/2 teaspoon"},{"name":"Ground Nutmeg","measure":"1/4 tsp"},{"name":"Pepper","measure":"1/4 tsp"},{"name":"Egg","measure":"3 Large"},{"name":"Plum Jam","measure":"200g"},{"name":"Double Cream","measure":"225ml"},{"name":"Dark Chocolate","measure":"140g"},{"name":"Clear Honey","measure":"3  tablespoons"}]'::jsonb, '["Heat oven to 160C/140C fan/gas 3. Grease and line the base and sides of a deep 20cm cake tin with baking parchment. Put the honey, sugar and butter in a medium saucepan and cook over a medium heat until fully melted. Remove from the heat and allow to cool. Put the flour and spices in a large bowl and mix everything together.","Once the liquid ingredients have cooled, whisk in the eggs. Pour over the dry ingredients, whisking them together to form a smooth batter – be careful not to overmix as this can lead to a dry cake. Pour into the prepared tin and bake for 50-55 mins or until risen and a skewer inserted into the middle of the cake comes out clean. Allow the cake to cool in the pan for 20 mins before turning out onto a wire rack to cool completely.","Once cooled, use a large serrated knife to slice the cake into 3 layers. Spread the jam across the 2 bottom cake layers, then reassemble the cake and set aside while you make the glaze. Put the cream, chocolate and honey in a medium pan and cook over a low-medium heat until the chocolate is melted and you have a smooth, pourable mixture. Put the cake on a wire rack set over a parchment-lined baking tray and pour over the glaze, making sure to cover the entire cake. Use a fish slice to carefully transfer the cake to a serving plate and allow the glaze to set. To decorate, dust with a little edible gold powder, if you like. Uniced, this cake will keep for up to 5 days. Once iced, enjoy within 3 days – just keep in the fridge, but remove before serving and eat at room temperature."]'::jsonb, 'https://www.themealdb.com/images/media/meals/kwmdk41764120884.jpg', 'themealdb'),
('Pistachio cake', ARRAY['polish', 'dessert']::text[], ARRAY['vegetarian']::text[], 31, 35, 66, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Butter","measure":"250g"},{"name":"Pistachio","measure":"200g"},{"name":"Plain Flour","measure":"80g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Caster Sugar","measure":"225g"},{"name":"Egg","measure":"4"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Icing Sugar","measure":"100g"},{"name":"Mascarpone","measure":"250g"},{"name":"Double Cream","measure":"200ml"},{"name":"Pistachio Paste","measure":"100g"},{"name":"Raspberries","measure":"400g"},{"name":"Unwaxed Lime","measure":"1"}]'::jsonb, '["Heat the oven to 180C/160C fan/gas 4. Butter and line a 23cm springform cake tin. Tip 150g of the pistachios into a food processor and blitz until finely ground. Tip into a bowl and mix in the flour, baking powder and pinch of salt. Beat the butter and sugar in a separate bowl until fluffy and pale, around 5 mins. Crack in the eggs one at a time, beating well for 1 min after each addition, until they have all been added. Beat in the vanilla, then fold in the flour mixture gently. Carefully spoon into the prepared tin and bake for 35-40 mins until a skewer inserted into the middle comes out clean. Set aside to cool completely on a wire rack in the tin.","Meanwhile, sift the icing sugar into a bowl, then tip in the mascarpone, double cream and pistachio paste. Beat until well combined, then set aside in the fridge for 20-30 mins to thicken to a spooning consistency.","Cut the cooled cake in half horizontally using a serrated knife, so you have two layers. Put the bottom layer on a plate or cake stand and spread over a generous spoonful of the pistachio cream. Top with a generous handful of the raspberries so the cake is covered. Top with the other sponge half, then cover the top and sides of the cake with the remaining cream. Scatter over the last of the raspberries, the remaining pistachios and the lime zest to serve. Will keep chilled in an airtight container for two days."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xvgpng1764121726.jpg', 'themealdb'),
('Zapiekanki', ARRAY['polish', 'pork']::text[], ARRAY['gluten_free']::text[], 33, 50, 83, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"Baguette","measure":"2"},{"name":"Butter","measure":"1 tablespoon"},{"name":"Vegetable Oil","measure":"2 tsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Mushrooms","measure":"300g"},{"name":"Garlic","measure":"1 clove"},{"name":"Mayonnaise","measure":"1 tablespoon"},{"name":"Cheddar Cheese","measure":"50g"},{"name":"Ham","measure":"75g"},{"name":"Polish Kabanos","measure":"75g"},{"name":"Mozzarella","measure":"50g"},{"name":"Dill","measure":"2"},{"name":"Chives","measure":"1 tablespoon"},{"name":"Tomato Ketchup","measure":"Drizzle"}]'::jsonb, '["Heat the oven to 200C/180C fan/gas 6. Bake the baguettes on a baking tray for 8-10 mins, then leave to cool.","Heat 2 tsp of the butter and 1 tsp of the oil in a pan over a low heat and cook the chopped onion for 5 mins until soft. Stir in the mushrooms, turn the heat to medium and cook for 5-10 mins more until the veg is soft and the mushroom liquid has evaporated. Stir in the garlic and cook for 1-2 mins until soft. Season, then stir in the mayonnaise and remove from the heat.","Halve the baguettes lengthways, then return to the baking tray, cut-side up and spread over the mushroom mixture, then sprinkle over the cheddar, ham, kabanos and mozzarella. Bake for 8-10 mins, or until the cheese has melted and turned golden.","Meanwhile, heat the remaining butter and oil in a pan over a medium heat and fry the sliced onions for 5 mins until golden and soft. Remove from the heat and set aside. Once the pizzas are cooked, top with the caramelised onions, dill pickles (if using), the chives and a zig-zag drizzle of ketchup."]'::jsonb, 'https://www.themealdb.com/images/media/meals/72lmpt1764122511.jpg', 'themealdb'),
('Sauerkraut pierogi', ARRAY['polish', 'vegetarian']::text[], ARRAY['vegetarian']::text[], 29, 55, 84, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Sunflower Oil","measure":"1 tablespoon"},{"name":"Shallots","measure":"2"},{"name":"Sauerkraut","measure":"150g"},{"name":"Hispi (sweetheart) Cabbage","measure":"150g"},{"name":"Egg","measure":"1 large"},{"name":"Vegetable Oil","measure":"1/2 tbs"},{"name":"Plain Flour","measure":"350g"},{"name":"Vegetable Oil","measure":"For frying"},{"name":"Shallots","measure":"2"},{"name":"Plain Flour","measure":"Dusting"},{"name":"Butter","measure":"45g"},{"name":"Sour Cream","measure":"60 ml"}]'::jsonb, '["First, make the crispy shallots. Heat the oil in a saucepan to 180C (a cube of bread will turn golden in 15 secs). Toss the shallots in a little flour and deep-fry for 1 min or until light golden and crispy. Drain on kitchen paper. Can be made up to two days before and kept in an airtight container.","To make the filling, heat the oil in a medium non-stick frying pan and gently fry the shallots for 10 mins until starting to turn golden.","Add the sauerkraut and cabbage, and cook for 5-10 mins until the cabbage has softened. Taste and add a little salt if under-seasoned, or sugar if stringent. Scrape into a bowl and leave to cool completely.","To make the dough, mix the eggs and oil with 125ml water, then gradually add in the flour, mixing well with your hands. Knead it on a well-floured surface until the dough stops sticking to your hands. You should end up with firm, elastic dough. Wrap it in cling film and rest in the fridge for at least 30 mins, or overnight.","Flour your work surface generously. Roll out the dough to a 40cm circle or until the dough is as thick as £1 coin.","Using a 9cm cookie cutter, cut out discs in the dough – you should end up with about 25 discs. Do not throw away the off-cuts – we throw them in with the pierogi when boiling to minimise any waste.","Have a well-floured tray ready. Put 1 tsp of the filling into the centre of each disc. In your hand, fold in half around the filling and seal to create half-moon shapes. Put them on the floured tray, making sure they don’t touch each other.","Bring a large saucepan of salted water to the boil and carefully lower the pierogi in. Boil them for 2 mins or until they float to the top.","Drain and serve with a knob of butter and some soured cream. Finish by sprinkling the crispy shallots on top to serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ckbx1h1764123606.jpg', 'themealdb'),
('Pomegranate salad', ARRAY['polish', 'vegetarian']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 25, 20, 45, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Olive Oil","measure":"60 ml"},{"name":"Lemon Juice","measure":"2 tablespoons"},{"name":"Honey","measure":"1 tablespoon"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Baby Lettuce Leaves","measure":"100g"},{"name":"Cherry Tomatoes","measure":"250g"},{"name":"Spring Onions","measure":"3 chopped"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Pomegranate","measure":"1"},{"name":"Feta","measure":"50g"}]'::jsonb, '["Combine the olive oil, lemon juice, honey and thyme leaves in a large bowl. Season well, then tip in the lettuce, tomatoes, spring onions and chilli, and toss to combine.","Scoop out the pomegranate seeds over a bowl and remove any white membrane. Arrange the dressed salad on a platter, then scatter over the pomegranate seeds and feta."]'::jsonb, 'https://www.themealdb.com/images/media/meals/fqpqml1764359125.jpg', 'themealdb'),
('Polish patties (kotlety)', ARRAY['polish', 'side']::text[], ARRAY[]::text[], 23, 20, 43, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Bread Rolls","measure":"1"},{"name":"Milk","measure":"120ml"},{"name":"Onion","measure":"1 chopped"},{"name":"Vegetable Oil","measure":"100 ml"},{"name":"Ground Beef","measure":"500g"},{"name":"Egg","measure":"1"},{"name":"Garlic Clove","measure":"1"},{"name":"Marjoram","measure":"Pinch"},{"name":"Breadcrumbs","measure":"75g"}]'::jsonb, '["Soak the bread roll in the milk so it softens completely. Meanwhile, fry the onion in the oil for around 8 mins or until soft and golden. Add the fried onion to the beef mince along with the egg, garlic, marjoram and some seasoning. Squeeze the excess milk from the bread roll and add it to the mince mixture. Mix everything together and season well.","Divide the meat into 8 patties. Tip the dried breadcrumbs into a shallow bowl and coat the patties in it, all over. Heat some oil in a deep frying pan and fry the patties in batches on both sides until browned and cooked through, about 6-7 mins on each side."]'::jsonb, 'https://www.themealdb.com/images/media/meals/vvn5f71764360273.jpg', 'themealdb'),
('Bigos (Polish hunter''s stew)', ARRAY['polish', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 37, 45, 82, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"White Cabbage","measure":"1 sliced"},{"name":"Beef Stock","measure":"250ml"},{"name":"Mushrooms","measure":"100g"},{"name":"Lard","measure":"2 tablespoons"},{"name":"German Sausages","measure":"400g"},{"name":"Bacon","measure":"250g"},{"name":"Onion","measure":"2 chopped"},{"name":"Beef","measure":"750g"},{"name":"Prunes","measure":"200g"},{"name":"Bay Leaf","measure":"1"},{"name":"Cloves","measure":"2"},{"name":"Peppercorns","measure":"12"},{"name":"Juniper Berries","measure":"4"},{"name":"Allspice Berries","measure":"4"},{"name":"Red Wine","measure":"90 ml"},{"name":"Tomato Puree","measure":"2 tablespoons"}]'::jsonb, '["Put the cabbage in a heavy casserole dish, add the stock and cook over a low heat for about 50 mins, until tender.","Cut the soaked mushrooms into strips and save the soaking water. Heat the lard and fry the sausages and bacon, then scoop out, leaving the fat in the pan. Fry the onion in the same pan for 5-8 mins until lightly browned.","Add the mushrooms and their liquid along with all the cooked meat, onions and prunes, then cover and cook for 20 mins. Add the spices, red wine and tomato purée and bring to a simmer, then cover and cook for 1 hr. Season well and leave to cool. Will keep covered and chilled for up to two days. Bigos improves in flavour over a couple of days. Leave to cool first. Reheat until piping hot before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/fl4brj1764361323.jpg', 'themealdb'),
('Slow-roasted ham with lemon, garlic & sage', ARRAY['polish', 'pork']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 19, 50, 69, 'easy', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Garlic","measure":"5 chopped cloves"},{"name":"Lemon","measure":"Zest of 1"},{"name":"Salt","measure":"15g"},{"name":"Black Pepper","measure":"10g"},{"name":"Vegetable Oil","measure":"50 ml"},{"name":"Pork Shoulder","measure":"2kg"},{"name":"Dry White Wine","measure":"500ml"}]'::jsonb, '["Heat the oven to 200C/180C fan/gas 6. Bash the garlic, sage, lemon zest, salt and pepper together using a pestle and mortar until the mixture becomes a paste. Stir in the oil, then spread the mixture over the pork shoulder, avoiding the skin on top. Score the skin using a sharp knife, then rub a large pinch of salt into the skin. Tie the pork together using kitchen string.","Line a large baking tray with a double layer of foil and put the pork on top, skin-side up. Bring the sides of the foil up around the pork to create a parcel, then pour the wine into the tray around the sides. Transfer to the oven and reduce the temperature to 140C/120C fan/gas 1. Roast for 4-5 hrs, or until a meat thermometer inserted into the thickest part of the pork reads 70C.","Turn the oven up to 240C/220C fan/gas 9. Carefully spoon the pork roasting juices from the pan into a saucepan and cook over a medium heat for 10-15 mins, or until reduced by a third. Season to taste.","Meanwhile, arrange the foil around the meat so only the skin is exposed, then return to the oven for 10-15 mins until the skin is puffed up and browned all over. Leave to rest for 20 mins before slicing. Serve with the sauce drizzled over."]'::jsonb, 'https://www.themealdb.com/images/media/meals/w36ets1764362474.jpg', 'themealdb'),
('Raspberry mousse', ARRAY['polish', 'dessert']::text[], ARRAY['gluten_free']::text[], 15, 35, 50, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Gelatine Leafs","measure":"2"},{"name":"Raspberries","measure":"350g"},{"name":"Caster Sugar","measure":"60g"},{"name":"Lemon","measure":"Juice of 1"},{"name":"Whipping Cream","measure":"500ml"}]'::jsonb, '["Put the gelatine leaves in a bowl, cover with warm water and leave to soak for 5 mins. Drain and squeeze out any excess water.","Tip the raspberries into a pan over a medium-low heat along with the sugar and lemon juice. Cook for 5-6 mins until the berries have completely broken down. Push the mixture through a sieve set over a bowl, discarding the seeds. Stir in the gelatine leaves until dissolved (if they don’t dissolve, pour the mixture into a clean saucepan and heat gently until dissolved). Set aside to cool for 15 mins.","Whip the cream to soft peaks using an electric whisk, then gently fold this into the raspberry mixture. Spoon into the ramekins or moulds and chill overnight, or for at least 6 hrs. Serve with raspberries scattered over the top."]'::jsonb, 'https://www.themealdb.com/images/media/meals/v5jrnn1764362830.jpg', 'themealdb'),
('Mini bundt cakes', ARRAY['polish', 'dessert']::text[], ARRAY['vegetarian']::text[], 21, 40, 61, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Butter","measure":"150g"},{"name":"Plain Flour","measure":"175g"},{"name":"Caster Sugar","measure":"125g"},{"name":"Egg","measure":"3"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Cocoa Powder","measure":"2 tsp"},{"name":"Milk","measure":"3  tablespoons"},{"name":"Icing Sugar","measure":"1 tablespoon"}]'::jsonb, '["Heat the oven to 180C/160C fan/gas 4. Melt 25g butter and generously brush into the holes of a mini bundt tins. Tip a little flour into each hole and shake to coat, then tip out the excess. Beat the butter, caster sugar and a pinch of salt together using an electric whisk. Add the eggs, one at a time, beating well after each addition. Combine the flour and baking powder in a separate bowl, then sift this into the wet ingredients and stir until smooth. Combine the cocoa powder and milk in a small bowl until smooth.","Spoon 1 tbsp of the plain batter into each hole of the bundt tin. Mix the remaining plain batter with the cocoa powder mixture, then divide this between the holes. Bake for 15-18 mins, or until a skewer inserted into the cakes comes out clean. Leave to cool in the tin for 5 mins, then turn out onto a wire rack and leave to cool completely. Dust with icing sugar to serve.","Pour 1 tablespoon of light batter into each mold. Mix the remaining batter with the stirred cocoa mixture and then fill the molds with a tablespoon.","Bake the mini Bundt cakes in the preheated oven for 15-18 minutes , depending on the size of the molds. After 15 minutes of baking time, use a toothpick to test with a skewer and, if necessary, bake for another 3 minutes. Let the mini Bundt cakes cool down completely in the tin. Then carefully remove from the mold. Dust with some icing sugar and serve. Enjoy your meal!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/tzt3it1764363293.jpg', 'themealdb'),
('Braised stuffed cabbage', ARRAY['polish', 'vegetarian']::text[], ARRAY['vegetarian', 'dairy_free', 'gluten_free']::text[], 27, 25, 52, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Cabbage Leaves","measure":"6 large"},{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"1 chopped"},{"name":"Rosemary","measure":"2 tsp"},{"name":"Celery","measure":"1 chopped"},{"name":"Basmati Rice","measure":"140g"},{"name":"Cooked Chestnut","measure":"140g"},{"name":"Cranberry","measure":"50g"},{"name":"Vegetable Stock","measure":"300ml"},{"name":"Balsamic Vinegar","measure":"1 tablespoon"},{"name":"Clear Honey","measure":"1 tsp"}]'::jsonb, '["Heat oven to 180C/fan 160C/gas 4. Remove the tough central stalk from the cabbage leaves. Bring a large pan of salted water to the boil, add the cabbage, then cook for just 1-2 mins until the leaves are starting to wilt. Drain and refresh under cold running water. Drain well, then pat dry with a tea towel.","Heat the oil in a pan, add the onion, then fry for 5 mins until slightly browned. Add the rosemary and celery, then cook for 8 mins more. Stir in the rice, then cook for a min or so until the grains are glistening. Remove from the heat, stir in the chestnuts and cranberries, then season.","Spoon a little stuffing onto a cabbage leaf, roll up and fold in the sides to enclose the filling. Put in a single layer in a large, oiled, shallow ovenproof dish with the join underneath. Fill the remaining leaves in the same way. Mix the stock, vinegar and honey, then pour over the cabbage. Cover the dish tightly with foil, bake for 1 hr, uncover, then cook for a further 15 mins."]'::jsonb, 'https://www.themealdb.com/images/media/meals/z267f71764364072.jpg', 'themealdb'),
('Pork rib bortsch', ARRAY['polish', 'pork']::text[], ARRAY['gluten_free']::text[], 35, 45, 80, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"Pork Back Ribs","measure":"1kg"},{"name":"Bay Leaves","measure":"2"},{"name":"Dried white beans","measure":"1 tablespoon"},{"name":"Carrots","measure":"1 large"},{"name":"Onion","measure":"1 sliced"},{"name":"Garlic Clove","measure":"3 sliced thinly"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Red Chilli","measure":"2 chopped"},{"name":"Beetroot","measure":"2"},{"name":"Potatoes","measure":"3 chopped"},{"name":"Tomato Puree","measure":"3  tablespoons"},{"name":"White Cabbage","measure":"1/2"},{"name":"Parsley","measure":"Handful"},{"name":"Dill","measure":"Handful"},{"name":"Sour Cream","measure":"300g"}]'::jsonb, '["Cut the meat into large pieces, put in your largest saucepan and cover with 5 litres water. Bring to the boil over a high heat, skimming away any foam that rises to the surface. Add the bay leaves. Season. Turn the heat down to a simmer and cook for 1 hr, or until the meat is soft and falls off the bone. Add the beans if using dried.","Turn the heat up. Bring back to the boil, then reduce the heat and simmer for another 20 mins – the beans should still be slightly raw. Add the carrots, onions, garlic and pepper. Stir well, then add the chillies, if using. Cook for 15 mins more.","Stir in the beetroot and cook for 10 mins before adding the potatoes. After 15 mins, add the tomato purée to taste and beans, if using canned, and bring to the boil. Cook for 5 mins, add the cabbage and cook for 5 mins more. Season, then garnish with the parsley and dill. Turn off the heat and leave to stand for 5 mins. Serve with soured cream on the side."]'::jsonb, 'https://www.themealdb.com/images/media/meals/om5hsl1764364721.jpg', 'themealdb'),
('Beetroot & red cabbage sauerkraut', ARRAY['polish', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 15, 30, 45, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 2, '[{"name":"Beetroot","measure":"320g"},{"name":"Red Cabbage","measure":"450g"},{"name":"Onion","measure":"1 small"},{"name":"Caraway Seed","measure":"2 tsp"},{"name":"Sea Salt","measure":"1 tsp"}]'::jsonb, '["Tip all the ingredients into a large bowl, add 1-1½ tsp freshly ground black pepper, then scrunch it all together with your hands for 5 mins. You might want to wear gloves to avoid staining your skin with the beetroot juices.","Press the veg down in the bowl with your hands, then cover the surface and up the side of the bowl with a large sheet of compostable cling film or something reusable like a beeswax wrap. Now place another similar-sized bowl on top. Press down hard and add anything heavy (packs of rice or cans work well) to weigh it down so the juices rise to cover the surface. Cover again.","Leave to ferment at room temperature for at least five days, but for maximum flavour, leave for one-five weeks (until the bubbling subsides).","Check the sauerkraut. After a few days, you will see bubbles that have built up as it ferments. Give it a stir, then cover and weigh it down again as before. The cabbage will become increasingly sour the longer it’s fermented, so taste it now and again. When you like the flavour, transfer it to sterilised jars and keep chilled. Will keep chilled for up to six months."]'::jsonb, 'https://www.themealdb.com/images/media/meals/ra2k8a1764365055.jpg', 'themealdb'),
('Tangy cabbage slaw', ARRAY['ukrainian', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 25, 20, 45, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Mayonnaise","measure":"250ml"},{"name":"Lemon","measure":"Zest and juice of 1"},{"name":"Cider Vinegar","measure":"2 tablespoons"},{"name":"Wholegrain Mustard","measure":"2 tablespoons"},{"name":"Celery Salt","measure":"1 tsp"},{"name":"White Cabbage","measure":"1/4"},{"name":"Red Cabbage","measure":"1/4"},{"name":"Carrots","measure":"2"},{"name":"Onion","measure":"1 Diced"},{"name":"Celery","measure":"2 sliced"}]'::jsonb, '["Whisk together mayonnaise, lemon zest and juice, vinegar, mustard and celery salt in a small bowl, then season generously.","Add cabbage, carrots, onion and celery. Mix well and refrigerate. Can be made up to 1 day ahead."]'::jsonb, 'https://www.themealdb.com/images/media/meals/e2g2r21764367568.jpg', 'themealdb'),
('Beetroot latkes', ARRAY['ukrainian', 'vegetarian']::text[], ARRAY['vegetarian']::text[], 29, 25, 54, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Rapeseed Oil","measure":"1 tablespoon"},{"name":"Greek Yogurt","measure":"4 tablespoons"},{"name":"Mint","measure":"1/2 bag"},{"name":"Rocket","measure":"150g"},{"name":"Cherry Tomatoes","measure":"130g"},{"name":"Beetroot","measure":"400g"},{"name":"Egg","measure":"1 beaten"},{"name":"Plain Flour","measure":"1 tablespoon"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Caraway Seed","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1/2 teaspoon"},{"name":"Lemon","measure":"Zest of 1"}]'::jsonb, '["Heat the oven to 180C/160C fan/gas 4. Make the latkes by combining all of the ingredients.","Heat the oil in a large non-stick pan. Spoon in the mixture to make six round latkes. Fry for 4-5 mins on each side, then transfer to a baking sheet and bake for 10 mins.","Combine the yogurt and mint in a small bowl. Toss the salad leaves and tomatoes together, then serve the latkes with the mint yogurt and salad."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qwicc91764368097.jpg', 'themealdb'),
('Rosemary braised red cabbage with kabanos', ARRAY['ukrainian', 'pork']::text[], ARRAY['gluten_free']::text[], 25, 45, 70, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Red Cabbage","measure":"1/2"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Butter","measure":"Knob"},{"name":"Red Onions","measure":"1 sliced"},{"name":"Red Wine Vinegar","measure":"125ml"},{"name":"Brown Sugar","measure":"140g"},{"name":"Red Chilli","measure":"1 chopped"},{"name":"Rosemary","measure":"2 sprigs"},{"name":"Bramley Apples","measure":"1 chopped"},{"name":"Kabanos Sausages","measure":"8"}]'::jsonb, '["Halve the cabbage, remove the tough stem and thinly slice. Place in a large pan with all the other ingredients apart from the sausages, then mix in 300ml water and some salt and pepper.","Bring to a simmer, then reduce the heat, cover with a well-fitting lid and gently cook for 1½ hrs, stirring frequently. If too dry, you can add a little more water.","Add the kabanos to the cabbage mixture, place a lid on the pan and gently simmer for 20 mins. Remove the lid and cook for a further 10 mins. Serve alongside some simple mash or boiled potatoes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/s1jxzl1764369317.jpg', 'themealdb'),
('Beetroot pancakes', ARRAY['ukrainian', 'dessert']::text[], ARRAY['vegetarian']::text[], 27, 35, 62, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Beetroot","measure":"3"},{"name":"Milk","measure":"50 ml"},{"name":"Self-raising Flour","measure":"200g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Maple Syrup","measure":"2 tablespoons"},{"name":"Vanilla Extract","measure":"1/2 teaspoon"},{"name":"Egg","measure":"3"},{"name":"Butter","measure":"25g"},{"name":"Frozen Mixed Berries","measure":"200g"},{"name":"Blackcurrant Jam","measure":"2 tablespoons"},{"name":"Greek Yogurt","measure":"100g"}]'::jsonb, '["Put the beetroot in a jug with the milk and blend with a stick blender until smooth. Pour into a bowl with the rest of the pancake ingredients and whisk until smooth and vibrant purple.","Put a small knob of butter in a large non-stick frying pan and heat over a medium-low heat until melted and foamy. Now create 3 or 4 pancakes each made from 2 tbsp of the batter. Cook for 2-3 mins then flip over and cook for a further minute until cooked through. Repeat with any remaining batter. Heat oven to lowest setting and keep the pancakes warm in there until needed.","Serve with your favourite pancake toppings or make a simple compote by simmering frozen berries in with 1 tbsp blackcurrant jam until bubbling and syrupy (about 5-10 mins). In a small bowl stir together the remaining jam and the yogurt. Stack the cooked pancakes with the yogurt and pour the warm berry compote over the top."]'::jsonb, 'https://www.themealdb.com/images/media/meals/xlqqhw1764369924.jpg', 'themealdb'),
('Torta de fiambre', ARRAY['uruguayan', 'pork']::text[], ARRAY[]::text[], 23, 55, 78, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Cheddar Cheese","measure":"150g"},{"name":"Ham","measure":"200g"},{"name":"Egg","measure":"3"},{"name":"Vegetable Oil","measure":"100g"},{"name":"Milk","measure":"240g"},{"name":"All purpose flour","measure":"120g"},{"name":"Baking Powder","measure":"2 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Dried Oregano","measure":"To taste"}]'::jsonb, '["Line the bottom of a springform of 20-2cm (8-9inches) with parchment paper, I usually leave some overhang as the batter is very liquid and may spill a bit. Preheat oven to 220 degrees Celsius.","Grate the cheese and take out the ham.","Mix all remaining ingredients in a large bowl for about one to two minutes.","Pour half the batter into the prepared pan, it is going to be very liquid. Then place ham and cheese on top and pour the remaining batter on top.","Bake for about 20-25 minutes or until top is golden. Wait for a few minutes before releasing from the pan and enjoy either hot or cold with some fresh herbs."]'::jsonb, 'https://www.themealdb.com/images/media/meals/okl9cm1764371087.jpg', 'themealdb'),
('Chocolate alfajores', ARRAY['uruguayan', 'dessert']::text[], ARRAY['vegetarian']::text[], 31, 45, 76, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Butter","measure":"150g"},{"name":"Sugar","measure":"70g"},{"name":"Egg","measure":"1"},{"name":"Honey","measure":"25g"},{"name":"All purpose flour","measure":"175g"},{"name":"Cornstarch","measure":"80g"},{"name":"Unsweetened Cocoa","measure":"30g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Dulce de leche","measure":"400g"},{"name":"Milk Chocolate","measure":"500g"},{"name":"Butter","measure":"100g"},{"name":"Orange","measure":"Zest of 1"}]'::jsonb, '["For the cookies cream the butter with the sugar for a few minutes. Then add the egg and honey and mix well. Add flour, cornstarch, cocoa, baking soda and baking powder and mix until you get a dough. Wrap in plastic wrap and chill for at least half an hour or overnight.","Line two baking sheets with parchment paper, preheat oven to 200 degrees Celsius.","Divide dough into two parts, put one part back in the fridge before using. Roll out second part to about 2 millimeters and cut out round cookies with 5-6 centimeters in diameter. This can be done with a cookie cutter or glass. You should get 30 cookies in total or even more, I get about 40. Bake one baking sheet at the time for about 8-10min. Let cookies cool.","For the filling look for two cookies of the same size and place about one teaspoon of dulce de leche onto the bottom one before sandwiching together.","Chop semi-sweet chocolate and melt with butter and orange zest on low heat. Dunk each sandwich cookie into the chocolate and let cool off on parchment paper before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/k9o0xr1764373018.jpg', 'themealdb'),
('Vanilla alfajores', ARRAY['uruguayan', 'dessert']::text[], ARRAY['vegetarian']::text[], 29, 40, 69, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Dulce de leche","measure":"150g"},{"name":"Coconut Flakes","measure":"50g"},{"name":"Butter","measure":"100g"},{"name":"Sugar","measure":"100g"},{"name":"Egg","measure":"1"},{"name":"Egg Yolks","measure":"1"},{"name":"Cornstarch","measure":"200g"},{"name":"All purpose flour","measure":"100g"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Dulce de leche","measure":"150g"},{"name":"Coconut Flakes","measure":"50g"}]'::jsonb, '["For the sandwich cookie cream the soft butter for about a minute, then add the sugar and cream for another two minutes. Incorporate the egg fully before mixing in the egg yolk. Once everything is nicely combined, add all remaining ingredients and mix one more time. Form dough into a ball and wrap in plastic wrap. Chill for at least half an hour or overnight.","Preheat oven to 180 degrees Celsius and line two baking sheets with parchment paper.","Divide dough in half, put one back in the fridge and roll out the other thickly on a lightly floured surface. Cut out cookies with either the bottom of a glass or a cookie cutter around 6cm in diameter. Repeat with all the dough.","Bake for about 8-10min, the cookies will look very pale. Let cool off before filling half with each a teaspoon of dulce de leche. Place other half of cookies on top and roll the sides of each cookie in the coconut flakes (it helps if the dulce de leche was pressed down to the sides of the cookie). Enjoy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/3wnyvh1764373818.jpg', 'themealdb'),
('Venezuelan Arepas', ARRAY['venezuela', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 13, 90, 103, 'hard', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Cornmeal","measure":"2 cups"},{"name":"Water","measure":"2 1/2 cups"},{"name":"Salt","measure":"1 tsp"},{"name":"Vegetable Oil","measure":"1 tablespoon"}]'::jsonb, '["Preheat oven to 410° F.","Pour the water into a large bowl. Make sure it is room temperature.","Add the salt. Blend well with a mixer, fork or spatula to make sure it dissolves well.","While you continue to beat the mixture, slowly add the corn meal—a little bit at a time.","Once all the flour is added, keep mixing until the corn meal, water and salt are thoroughly blended and dissolved.","Set aside the masa in its bowl. Let it rest for 5 minutes so that the flour is thoroughly hydrated. This type of corn flour does not have any gluten, so it doesn’t need to be kneaded. The masa should be smooth, firm yet malleable.","While waiting for the 5 minutes’ rest, heat your budare (or comal, griddle, cast-iron pan or non-stick pan) over medium heat. Coat with a little bit of the oil.","Fill a small bowl with water to wet your hands to make the arepas.","Take about 2 Tbsp of the masa in your damp hands. The masa should fit easily in your palm so that it is easy to shape into a small ball.","Cross your hands, so that one is on top of the other, with the masa ball between them. Rotate your right hand in a circle, so that you are at the same time both pressing the masa into a flat disc and keeping its round shape.","arepa making","The last step in shaping your arepa is to quickly pass and lightly press the masa disc from one hand to the other until it is about ¾ of an inch thick and 4 inches wide. Smooth the edges with your fingertips (quickly dip them into the water bowl first) so that they stay as round as possible and without cracks.","arepa making","Place your arepas in batches on the preheated surface of your budare griddle or nonstick pan. Let each side turn golden, about 4 to 5 minutes per side. Check them often so that they don’t burn.","Once they are nicely browned on both sides, place the arepas on a baking sheet in your preheated oven for 10 minutes. They should be somewhat puffy, so that if you tap an arepa lightly on top, it will sound like you are tapping an empty box.","Serve arepas hot, whether you stuff with them with your choice of fillings or serve solo to accompany your favorite Venezuelan guiso or stew."]'::jsonb, 'https://www.themealdb.com/images/media/meals/3hcy191764376285.jpg', 'themealdb'),
('Venezuelan Sancocho', ARRAY['venezuela', 'beef']::text[], ARRAY['gluten_free']::text[], 39, 60, 99, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Hind Shank","measure":"2 Lbs"},{"name":"Onion","measure":"2 small"},{"name":"Pepper","measure":"1/2"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Garlic","measure":"4 Cloves Crushed"},{"name":"Leek","measure":"1"},{"name":"Beef Stock","measure":"8 cups"},{"name":"Sweet Red Peppers","measure":"1/2 cup"},{"name":"Scallions","measure":"1/2 cup"},{"name":"Sweetcorn","measure":"2"},{"name":"Cassaba","measure":"1/2 lb"},{"name":"Yautia","measure":"1/2 lb"},{"name":"White Yam","measure":"1/2 lb"},{"name":"Butternut Squash","measure":"1/2 lb"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Cilantro","measure":"Chopped"}]'::jsonb, '["Add hind shank, 1 halved small onion, halved bell pepper, 4 whole garlic cloves, the dark green leaves of the leek, and stock to a large stockpot. Cook for 45-60 minutes until the meat is fork-tender. NOTE: the meat can take a bit longer to be fork-tender; that is okay, just add more cooking time if necessary.","When the meat is tender, remove the big pieces of vegetables and bones. Discard.","Add diced onion, 2 minced garlic, mini sweet peppers, sliced leeks (light green part), scallions, yucca, and corn; Mix and simmer covered over medium heat for 5- 8 minutes, until the yucca is starting to soften. NOTE: the yuca can take a bit longer to start softening; that is okay, just add more cooking time if necessary.","Add yautia, white yam, and butternut squash. Mix to combine. Simmer covered over medium heat for 5 – 6 minutes, until all the root vegetables are tender. NOTE: Do not cook too much, or they will fall apart.","Taste and add salt to your taste, if necessary. Add cilantro and the remaining 2 minced garlic cloves. Mix and let simmer for 2 more minutes.","Serve hot in large soup bowls, dividing the meat and vegetables evenly. Add a squish of lime juice and/or hot sauce, if desired. Serve along with arepas and or casabe (cassava bread)."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8859m71764377470.jpg', 'themealdb'),
('Venezuelan Coconut Chicken', ARRAY['venezuela', 'chicken']::text[], ARRAY['gluten_free']::text[], 33, 50, 83, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Chicken Breasts","measure":"2"},{"name":"Onion","measure":"2 chopped"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Bay Leaves","measure":"4"},{"name":"Black Pepper","measure":"Pinch"},{"name":"Turmeric","measure":"Pinch"},{"name":"Cumin","measure":"Pinch"},{"name":"Salt","measure":"Pinch"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Tomato","measure":"3"},{"name":"Ginger Paste","measure":"1 tablespoon"},{"name":"Olive Oil","measure":"1/3 cup"},{"name":"Coconut Milk","measure":"1 Can"},{"name":"Water","measure":"1/2 cup"}]'::jsonb, '["Cut the chicken up into bite size pieces. Peel and cut the onions, mince the garlic.","Assemble the rest of the ingredients and you are ready to start cooking.","Make the Dish","Heat up a fry pan over medium heat. Add the oil and when hot, sauté the onion until translucent. Remove from pan and transfer to a blender or food processor.","Add tomatoes, garlic, turmeric, cumin, sugar, ginger paste, coconut milk, water and blend smooth.","In the same pan you cooked the onion, add the chicken and brown all sides. This should take about 3 minutes.","Add the blender ingredients and bay leaves to the pan, bring to a simmer and cook until the chicken is white inside and the liquid is creamy. (15 to 20 minutes)","Remove the bay leaves and serve with white rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/z2sw3o1764378271.jpg', 'themealdb'),
('Cassava pizza', ARRAY['venezuela', 'pork']::text[], ARRAY['gluten_free']::text[], 21, 60, 81, 'medium', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Casabe","measure":"6 cut thick slices"},{"name":"Tomato Sauce","measure":"450g"},{"name":"Chorizo","measure":"225g"},{"name":"Turkey Ham","measure":"225g"},{"name":"Sweetcorn","measure":"75g"},{"name":"Green Olives","measure":"40g"},{"name":"Paprika","measure":"55g"},{"name":"Mozzarella","measure":"50g"}]'::jsonb, '["Preheat the oven to 200ºC.","Cut the bacon or chorizo into medium pieces and the paprika into strips.","Spread a little tomato sauce and mozzarella cheese on each portion of cassava.","Add the bacon or chorizo, corn, turkey ham, some olives and paprika.","Bake for 7 to 10 minutes.","Remove from the oven and enjoy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/lrfdwz1764438393.jpg', 'themealdb'),
('Oatmeal pancakes', ARRAY['venezuela', 'breakfast']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 25, 35, 60, 'medium', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Egg","measure":"1 medium"},{"name":"Milk","measure":"80 ml"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Salt","measure":"Pinch"},{"name":"Vanilla Extract","measure":"1 dash"},{"name":"Ground Oats","measure":"150g"},{"name":"Butter","measure":"150g"},{"name":"Sugar Syrup","measure":"1 tablespoon"},{"name":"Strawberries","measure":"3"}]'::jsonb, '["Place all the ingredients in the glass and beat.","Let the mixture stand for 10 minutes.","Grease a hot frying pan with a little butter and pour a little of the mixture.","When it starts to bubble on the surface, turn over with a spatula. Cook over medium-low heat so that they do not burn.","Finally, add the caramel and strawberries."]'::jsonb, 'https://www.themealdb.com/images/media/meals/c400ok1764439058.jpg', 'themealdb'),
('Venezuelan turnovers', ARRAY['venezuela', 'side']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 31, 25, 56, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Ground Beef","measure":"450g"},{"name":"Pepper","measure":"Pinch"},{"name":"Ground Cumin","measure":"Pinch"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 cup"},{"name":"Green Pepper","measure":"1/2 cup"},{"name":"Red Pepper","measure":"1/2 cup"},{"name":"Garlic Powder","measure":"1 tsp"},{"name":"Capers","measure":"1/4 cup"},{"name":"Tomato Sauce","measure":"1 Can"},{"name":"Sazon","measure":"1 Can"},{"name":"Yellow Masarepa","measure":"2"},{"name":"Vegetable Oil","measure":"For frying"}]'::jsonb, '["Season meat with Adobo. In skillet, heat oil on medium high. Cook meat until pink is gone. Stir in onion, pepper, garlic, alcaparras, tomato sauce and Sazón. Cook, stirring often until most of the liquid has evaporated (about 20 minutes). Cool.","Prepared dough should be moist and should hold together, but it should not stick to your fingers. Start with about ½ cup of dough and roll into a ball between palms of your hands. Working on a sheet of non-stick parchment paper, form the ball into a 5-inch circle about ⅛ inch thick. Place a generous tbsp. of filling on one half of circle and using parchment paper close dough over to form a semi-circle. To seal and trim edges of the empanada, press lip of inverted bowl over semi-circle shaped patty. Repeat for all the Empanadas.","In large skillet on medium high, heat ½ inch of oil until hot but not smoking. Cook empanadas in batches, turning once or twice until lightly browned. Drain on paper towel. Do not over crowd skillet or let oil get too hot."]'::jsonb, 'https://www.themealdb.com/images/media/meals/zjtfp31764440795.jpg', 'themealdb'),
('Jiggs Dinner', ARRAY['canadian', 'beef']::text[], ARRAY['gluten_free']::text[], 21, 65, 86, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Beef","measure":"2 Lbs"},{"name":"Yellow Split Peas","measure":"1 cup"},{"name":"Cabbage","measure":"1 head"},{"name":"Carrots","measure":"6"},{"name":"Turnips","measure":"1 large"},{"name":"Potatoes","measure":"8"},{"name":"Butter","measure":"3  tablespoons"},{"name":"Black Pepper","measure":"To taste"}]'::jsonb, '["The night before, break salt beef into big chunks and soak in water overnight, at least 8-10 hours. Put split peas into a bowl and cover with water to soak overnight.","Drain the salt beef and place it into a large stockpot. Cover with fresh water, at least 6-7 litres. Place the split peas into a pease pudding canvas bag or triple layer of cheesecloth and tie, making sure to leave room for peas to expand inside the bag.","Put the bag inside the pot, tying the strings to the outside handle so it doesn''t stick to the bottom of the pot with the salt beef. Bring to a boil, then lower the heat and simmer for 2 hours.","Remove the peas pudding bag and empty contents into a bowl, mixing with butter and pepper for taste. Set aside.","Add your cabbage to the pot and boil for 20 more minutes. Then add turnip, carrots and potatoes then boil for 20 more, or until vegetables are tender.","Remove salt beef and vegetables from the pot and put them on a platter.","Use the cooking liquid in two ways; as a pot liquor which some people like to drink or reduce it to make a jus or gravy to pour over the meal."]'::jsonb, 'https://www.themealdb.com/images/media/meals/z1tfnw1764443171.jpg', 'themealdb'),
('Saskatoon Pie', ARRAY['canadian', 'dessert']::text[], ARRAY['vegetarian']::text[], 33, 55, 88, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"All purpose flour","measure":"6 cups"},{"name":"Salt","measure":"2 tsp"},{"name":"Unsalted Butter","measure":"1 cup"},{"name":"Vegetable Shortening","measure":"1 cup"},{"name":"Egg","measure":"1 large"},{"name":"Vinegar","measure":"1 tablespoon"},{"name":"Water","measure":"Splash"},{"name":"Saskatoon Berries","measure":"5 Cups"},{"name":"Sugar","measure":"1/2 cup"},{"name":"Sugar","measure":"1 tablespoon"},{"name":"Cornstarch","measure":"3  tablespoons"},{"name":"Unsalted Butter","measure":"2 tablespoons"},{"name":"Egg","measure":"1 beaten"},{"name":"Water","measure":"1 tablespoon"}]'::jsonb, '["To make the pastry, place the flour and salt in a large bowl. Mix well. Add the cubes of butter and shortening and mix them in (I like to use my hands to mix the fat into the flour, but you can use a pastry blender) just until it looks like coarse oatmeal with some pea-sized bits remaining. Place the egg in a 2-cup measure and beat it with a fork. Beat in the vinegar and just enough ice-cold water to bring it to the 1-cup mark. Stir this into the flour mixture, just until the dough clings together. I like to use my hands for this part as well, but a wooden spoon would also work. Try not to overmix it.","On a lightly floured surface, gather the dough into a ball and divide it into 5 evenly sized portions. Shape each portion into a disc and wrap tightly in plastic. Chill 2 of these discs for 1 hour. Freeze the other 3 in a resealable freezer bag for future use. The pastry keeps well in the freezer for up to 2 months.","Preheat the oven to 350°F. Place the rack in the lower third of the oven. Line a baking sheet with aluminum foil to catch drippings.","On a lightly floured surface, roll out 1 disc of pastry into a 12-inch circle, or thereabouts. Place it in the bottom of a 9-inch pie plate, with the pastry overhanging the edges of the pie plate.","To make the filling, place the saskatoon berries in a large bowl and stir in the 1/2 cup sugar and the cornstarch until well combined. Pour the berry mixture into the bottom of the pie. Dot with the butter. On a lightly floured surface, roll out the pastry in another 12-inch circle for the top crust. Use a ruler to guide you when cutting the pastry into 6 wide, long strips to keep the edges straight. Save the 2 end pieces in case you need to do any patching. I like wide strips, but if you like a thinner look, feel free to cut thin strips of pastry. Weave the pastry strips, going over and under, making sure they connect with the edges of the pie crust. Fold over the edges of the bottom crust, tucking in the lattice ends. This will help to trap the juices and give a rustic look.","If you prefer a cleaner, tidier look, you can trim the overhanging pieces and crimp the edges with a fork. Brush the top of the pie with the egg wash. Sprinkle with the remaining Tbsp sugar. Place the pie on the prepared baking sheet and bake it for about 90 – 100 minutes, until it’s golden brown and bubbling. Remove the pie from the oven and place it on a wire rack to cool.","Serve the pie warm or at room temperature with whipped cream or ice cream. Makes 6 servings. This keeps well if covered with plastic and refrigerated for up to 4 days."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5xdrkw1764444472.jpg', 'themealdb'),
('Grape Nut Ice Cream', ARRAY['jamaican', 'dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 13, 40, 53, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Heavy Cream","measure":"2 cups"},{"name":"Condensed Milk","measure":"1 1/4 oz"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Grape Nut Cereal","measure":"1 cup"}]'::jsonb, '["In a large bowl, use an electric mixer to whip the cold heavy cream until stiff peaks form. Gently fold in the sweetened condensed milk and vanilla extract until well combined.","Fold in the cereal and stir until evenly distributed throughout the mixture.","Pour the mixture into a freezer-safe container (such as a loaf pan). Lay plastic wrap on top of the ice cream to avoid freezer burn. Cover the container and freeze for at least 6 hours or until solid.","Once frozen, let the ice cream sit at room temperature for a few minutes to soften slightly before scooping and serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1xscby1764790242.jpg', 'themealdb'),
('Jamaican Spice Bun Recipe', ARRAY['jamaican', 'dessert']::text[], ARRAY['vegetarian']::text[], 37, 60, 97, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"All purpose flour","measure":"380g"},{"name":"Baking Powder","measure":"2 tsp"},{"name":"Ground Cinnamon","measure":"2 tsp"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Egg","measure":"1 large"},{"name":"Brown Sugar","measure":"150g"},{"name":"Beer","measure":"250g"},{"name":"Milk","measure":"1/3 cup"},{"name":"Honey","measure":"1/4 cup"},{"name":"Unsalted Butter","measure":"4 tablespoons"},{"name":"Molasses","measure":"1 tablespoon"},{"name":"Caramelized Sugar Sauce","measure":"1 tsp"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Dried cranberries","measure":"1/2 cup"},{"name":"Raisins","measure":"1/2 cup"},{"name":"Dried Cherries","measure":"1/2 cup"}]'::jsonb, '["Soak the craisins, raisins, and cherries in the 1 cup of beer. Set aside and allow to soak for 30 minutes.","Preheat the oven to 325 degrees Fahrenheit. Grease an 8x4 loaf pan. Set aside.","Combine all-purpose flour, baking powder, ground cinnamon, salt, in a large bowl and set aside.","In another bowl, combine brown sugar, egg, milk, honey, melted butter, molasses, browning, vanilla extract, and the beer that’s soaking the fruit. Do not pour the fruit in at this time, just the beer. Mix to combine.","Remove 2 tablespoon of flour from the flour mixture and toss the fruit in it. Set aside.","Make a well in the middle of the bowl of dry ingredients and pour in wet mixture, stirring until fully combined. And the fruits to the mixture and stir until incpororated.","Pour mixture into prepared loaf pan and bake in the preheated oven for 50-60 minutes or until a toothpick comes out clean.","Cool for 5 minutes in the pan and then move to a cooling rack to finish cooling. Serve with slices of cheddar cheese."]'::jsonb, 'https://www.themealdb.com/images/media/meals/08c5f41764791918.jpg', 'themealdb'),
('Corned Beef and Cabbage – Jamaican Style', ARRAY['jamaican', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 27, 55, 82, 'medium', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Cabbage","measure":"1/2"},{"name":"Green Pepper","measure":"1 chopped"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Corned Beef","measure":"12 ounces"},{"name":"Plum Tomatoes","measure":"2 chopped"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Tomato Ketchup","measure":"1 tablespoon"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}]'::jsonb, '["Heat olive oil in a skillet or Dutch pot over medium-high heat. Add onion and green pepper and sauté for about 3-5 minutes.","Add garlic and stir for about 1 minute.","Add shredded cabbage and stir. Cook for about about 3-5 minutes, stirring often until softened.","Add corned beef, Roma tomatoes, and thyme and stir. Add ketchup and scotch bonnet pepper sauce and stir. Reduce heat and cook on medium for about 3-5 minutes, until the corned beef is heated through. Remove from heat.","Serve with white rice, bread, or on its own."]'::jsonb, 'https://www.themealdb.com/images/media/meals/kdz63q1764793442.jpg', 'themealdb'),
('Jamaican Instant Pot Rice and Beans', ARRAY['jamaican', 'vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 29, 70, 99, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Spring Onions","measure":"2 chopped"},{"name":"Rice","measure":"2 cups"},{"name":"Coconut Milk","measure":"3/4 cup"},{"name":"Water","measure":"3/4 cup"},{"name":"Salt","measure":"1 1/2 tsp"},{"name":"Allspice","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Kidney Beans","measure":"450g"},{"name":"Thyme","measure":"2 sprigs"}]'::jsonb, '["Instructions","Set Instant Pot to \"Sauté.\" Once Hot, add olive oil. Then add yellow onion and stir until softened, about 3 minutes. Add garlic and green onions and stir for about 30 more seconds.","Press “Cancel” on the Instant Pot. Add rice, coconut milk, water, salt, allspice, and black pepper and stir.","Pour undrained kidney beans on top of the rice mixture. Do not stir. Lay sprigs of thyme on top. Cover the Instant Pot, ensuring the valve is set to “Sealing.”","Press “Manual” or “Pressure Cook” on the Instant Pot and set for High pressure for 6 minutes.","Once the pressure cooking time is done, allow it to natural release for 10 minutes, then quick release any remaining pressure by moving valve to \"Venting\"","Open lid and remove thyme sprigs. Fluff rice with fork and Enjoy!","Stove Top Instructions","Heat olive oil in a large pot over medium heat. Add yellow onion and stir until softened, about 3 minutes. Add garlic and green onions and stir for about 30 more seconds.","Add rice, undrained kidney beans, coconut milk, water, salt, allspice, and black pepper and stir until combined. Lay thyme on top. Bring mixture to a simmer.","Cover with a lid and reduce heat to low. Allow to cook for 18 minutes over low heat, then remove from heat. Leave the lid on for an additional 5 minutes.","Open the lid and remove the thyme. Fluff rice with fork. Enjoy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/11bvtm1764795135.jpg', 'themealdb'),
('Jamaican Boiled Dumplings', ARRAY['jamaican', 'side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 15, 50, 65, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Water","measure":"8 cups"},{"name":"Salt","measure":"1/2 tbs"},{"name":"All purpose flour","measure":"2 cups"},{"name":"Salt","measure":"1 tsp"},{"name":"Water","measure":"1/2 cup"}]'::jsonb, '["Instructions","In a large pot, bring water and salt to a boil to boil the dumplings.","In a large mixing bowl, combine the all-purpose flour and salt, stirring to distribute the salt evenly throughout the flour. Gradually add water to the flour mixture, mixing with your hands until a dough forms.","Divide the dough into equal-sized pieces, rolling each into a smooth ball. Flatten each ball slightly with the palm of your hand to form a round, circular dumpling. It should look like a thick disk.","Carefully drop the dumplings into the boiling water, one at a time, ensuring that they don''t stick together. You can use a wooden spoon to stir the dumplings in the water.","Boil the dumplings for 15-20 minutes, or until they are cooked through and have risen to the surface of the water. Stir occasionally to prevent sticking.","Use a slotted spoon to remove the cooked dumplings from the pot, allowing any excess water to drain.","Serve with your favorite recipes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/tsdbcq1764795636.jpg', 'themealdb'),
('Jamaican Curry Goat', ARRAY['jamaican', 'goat']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 33, 75, 108, 'hard', '{"calories":480,"protein_g":36,"carbs_g":12,"fat_g":30}'::jsonb, 6, '[{"name":"Goat Meat","measure":"3 Lbs"},{"name":"Jamaican Curry Powder","measure":"2.5 tbsp"},{"name":"Ground Ginger","measure":"1/2 tsp"},{"name":"All-purpose Seasoning","measure":"1/2 tsp"},{"name":"Allspice","measure":"1/4 tsp"},{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"6 cloves sliced"},{"name":"Thyme","measure":"3 sprigs"},{"name":"Oil","measure":"2 tablespoons"},{"name":"Water","measure":"1 1/4 cup"},{"name":"Scotch Bonnet","measure":"1"},{"name":"Russet Potato","measure":"1 large"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"}]'::jsonb, '["Equipment","QT Pressure cooker","Instructions","Rinse goat meat with vinegar and water.","Season goat meat with 1 ½ tablespoon curry powder, all-purpose seasoning, ground ginger, allspice, onion, garlic cloves, and thyme. Marinate for at least 4 hours or up to overnight.","Remove onion and garlic from goat and set aside.","Set an electric pressure cooker, like an Instant Pot, on high sauté and add oil. Add goat meat and brown, about 2-3 minutes per side. Remove goat from insert and add 1 tablespoon oil and remaining curry powder and sauté for about 10 seconds. Then add onions and garlic and sauté until softened. About 4 minutes. If the onions look dry, add a little water and continue to sauté.","Add goat and water to the pressure cooker and cover the pressure cooker. Cook for 40 minutes on high pressure. Allow to naturally release for 10 minutes, then release the remaining pressure.","Once all the pressure has been released, open the pressure cooker. Place on sauté for 10-15 minutes, add potatoes and a whole scotch bonnet pepper. Cook until potatoes have softened. Remove scotch bonnet pepper."]'::jsonb, 'https://www.themealdb.com/images/media/meals/uc9qp11764796575.jpg', 'themealdb'),
('Jamaican Fried Dumplings', ARRAY['jamaican', 'side']::text[], ARRAY['vegetarian']::text[], 15, 40, 55, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"All purpose flour","measure":"2 cups"},{"name":"Baking Powder","measure":"2 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Milk","measure":"3/4 cup"},{"name":"Oil","measure":"1 1/2 cup"}]'::jsonb, '["Add flour, baking powder, and salt in a large bowl and stir to combine. Pour in the milk and stir until combined. Then roll the mixture into a ball and lightly knead until it comes together.","Break off about 10 pieces of dough and form them into balls. Set them aside.","In a 10-inch skillet, heat enough oil over medium heat to fry the dumplings, until the oil is about 350 degrees.","Once the dumplings are browned on one side, flip them and cook until both sides are browned, about 2-3 minutes each.","Once done, remove the dumplings from the oil and place them on paper towels or a cooling rack to drain off any excess oil.","Serve and enjoy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/dd7t4d1764877271.jpg', 'themealdb'),
('Jamaican Rice and Peas', ARRAY['jamaican', 'vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 25, 35, 60, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Rice","measure":"2 cups"},{"name":"Coconut Milk","measure":"380g"},{"name":"Kidney Beans","measure":"450g"},{"name":"Water","measure":"1 cup"},{"name":"Kosher Salt","measure":"2 tsp"},{"name":"Ground Allspice","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Spring Onions","measure":"3"},{"name":"Thyme","measure":"2 sprigs"},{"name":"Scotch Bonnet","measure":"1"}]'::jsonb, '["Equipment","Dutch oven","Add rice, coconut milk, kidney beans, water, kosher salt, allspice, and black pepper to a large pot and stir until combined. Lay green onions, thyme and Scotch bonnet pepper on top. Bring mixture to a boil.","Once boiling, reduce heat to low and cover with a lid. Allow to cook covered for 18 minutes over low heat, then remove from heat. Leave the lid on for an additional 5 minutes.","Open the lid and remove the green onion, Scotch bonnet pepper, and thyme. Fluff the rice and peas with a fork. Serve and enjoy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/pkyvrn1764878267.jpg', 'themealdb'),
('Beef Mandi', ARRAY['india', 'beef']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 29, 90, 119, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Basmati Rice","measure":"1 kg"},{"name":"Beef Stock","measure":"5 Cups"},{"name":"Onion","measure":"2 medium"},{"name":"Garlic","measure":"5 chopped cloves"},{"name":"Green Chilli","measure":"2"},{"name":"Tomato","measure":"1 small"},{"name":"Salt","measure":"2 1/2 Tsp"},{"name":"Oil","measure":"3  tablespoons"},{"name":"Turmeric Powder","measure":"1 ½ tsp"},{"name":"Cardamom","measure":"1/2 tsp"},{"name":"Cloves","measure":"1/2 tsp"},{"name":"Bay Leaf","measure":"1/2 tsp"}]'::jsonb, '["Wash the beef and cut into large pieces. Season lightly with salt and turmeric.","Heat ghee/oil in a large pot. Add sliced onions and sauté until light golden.","Add garlic, green chilies, and tomato; cook until softened.","Add the mandi spice mix: coriander, cumin, black pepper, cinnamon, cardamom, cloves, and bay leaves.","Add beef pieces and stir on medium heat until the meat is well coated with spices.","Pour in water or beef stock. Cover and simmer until beef is tender (about 1.5–2 hours depending on cut).","Remove beef carefully and set aside. Strain and measure the broth.","Add washed, soaked basmati rice to the broth (usually 1 cup rice = 1.5–2 cups liquid). Adjust seasoning and bring to a boil.","Lower heat, cover, and cook the rice until fluffy.","Place the beef pieces over the rice and steam on low heat for 10 minutes so flavors combine.","Optional: For smoky flavor, place a small hot charcoal on foil in the pot, add 1 tsp butter/oil, immediately cover for 5 minutes. Remove coal before serving.","Fluff rice and serve beef mandi with salad or chutney."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1nalo51765188375.jpg', 'themealdb'),
('Jamaican Cornmeal Porridge', ARRAY['jamaican', 'breakfast']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 21, 35, 56, 'easy', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Water","measure":"4 cups"},{"name":"Coconut Milk","measure":"380g"},{"name":"Fine Yellow Cornmeal","measure":"1 cup"},{"name":"Vanilla Extract","measure":"1 1/2 tsp"},{"name":"Ground Cinnamon","measure":"1/2 tsp"},{"name":"Ground Nutmeg","measure":"1/2 tsp"},{"name":"Ground Allspice","measure":"1/4 tsp"},{"name":"Sweetened Condensed Milk","measure":"1/2 cup"}]'::jsonb, '["Add 2 ½ cups water, 1 can coconut milk to a 4 QT heavy bottomed pot. Bring to a boil over medium-high heat.","Meanwhile, add 1 cup cornmeal and 1 ½ cup water to a large mixing cup and whisk until smooth.","Once the pot begins to boil, whisk in cornmeal mixture and continue to whisk for about 1 minute, ensuring there are no lumps. Reduce heat to low and cover with a tight fitting lid.","Cook over low heat for 15-20 minutes, stirring occasionally. When there is about 5 minutes left, stir in vanilla extract, cinnamon, nutmeg, and all-spice. Remove from heat and sweeten with condensed milk.","Serve and enjoy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sng9bm1765320170.jpg', 'themealdb'),
('Chinese Orange Chicken', ARRAY['chinese', 'chicken']::text[], ARRAY['dairy_free']::text[], 45, 80, 125, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 6, '[{"name":"Orange","measure":"Zest of 1"},{"name":"Orange Juice","measure":"1/4 cup"},{"name":"Soy Sauce","measure":"1/4 cup"},{"name":"Water","measure":"1/4 cup"},{"name":"Rice Vinegar","measure":"1/3 cup"},{"name":"Cornstarch","measure":"1 tablespoon"},{"name":"Sesame Seed Oil","measure":"1 tablespoon"},{"name":"Sugar","measure":"1/2 cup"},{"name":"Chicken Thighs","measure":"650g"},{"name":"Egg","measure":"2 large"},{"name":"Salt","measure":"1 tsp"},{"name":"Black Pepper","measure":"1/4 tsp"},{"name":"Cornstarch","measure":"1/2 cup"},{"name":"All purpose flour","measure":"1/2 cup"},{"name":"Vegetable Oil","measure":"2 cups"},{"name":"Garlic","measure":"2 cloves chopped"},{"name":"Shallots","measure":"1 chopped"},{"name":"Scallions","measure":"Sliced"},{"name":"Sesame Seed","measure":"Garnish"},{"name":"Rice","measure":"To serve"}]'::jsonb, '["Make the orange sauce:","Whisk together sauce ingredients in a medium bowl. Set aside.","Prep the chicken:","Cut chicken into about 1-inch cubes. Whisk eggs with salt and black pepper in a bowl and add chicken. Stir together.","In a separate bowl, whisk together flour and cornstarch. Remove chicken from eggs with a slotted spoon or tongs, letting excess egg drain off, then transfer to cornstarch mixture and coat well.","Fry the chicken:","Add oil to a large 10- to 12-inch skillet. Heat over medium-high heat until it reaches 350°F. If you don’t have a thermometer, you can also test the temperature by sprinkling in some flour. If the oil is hot enough, it should fizzle immediately.","Once oil is hot, fry the chicken in two batches. The oil might not completely cover the chicken—that’s okay. Cook for 3 to 4 minutes. Flip the chicken pieces and cook until the chicken is cooked through, about 3 to 4 more minutes. Total cook time is about 6 to 8 minutes.","Remove fried chicken cubes and transfer to a plate lined with paper towels, so the chicken can drain. Repeat until all the chicken is cooked.","Simmer the chicken in the sauce:","Once chicken is done, pour out hot oil and wipe pan clean. Add a fresh tablespoon of oil along with chopped garlic and shallot. Cook for a minute and then add the sauce. Simmer the sauce until it starts to thicken.","Once the sauce is lightly bubbling, add fried chicken and toss together to coat. The sauce should continue to thicken and stick to the chicken. Let simmer for a minute or two more. Serve orange chicken over cooked white rice, garnished with sesame seeds and fresh scallions.","Did you love this recipe? Let us know with a rating and review!","LEFTOVERS! The orange chicken keeps well in the fridge for 5 days. Reheat in a skillet with a splash of water over low heat. Freeze the orange chicken for up to 3 months, but be sure to thaw it before reheating so the chicken doesn’t clump together."]'::jsonb, 'https://www.themealdb.com/images/media/meals/s73ytv1765567838.jpg', 'themealdb'),
('Beef and Broccoli Stir-Fry', ARRAY['chinese', 'beef']::text[], ARRAY['dairy_free']::text[], 33, 100, 133, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Soy Sauce","measure":"1 tsp"},{"name":"Dry sherry","measure":"1 tsp"},{"name":"Cornstarch","measure":"1/2 tsp"},{"name":"Black Pepper","measure":"1/8 teaspoon"},{"name":"Sirloin steak","measure":"1 lb"},{"name":"Oyster Sauce","measure":"2 tablespoons"},{"name":"Dry sherry","measure":"1 tsp"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Chicken Stock","measure":"1/4 cup"},{"name":"Broccoli","measure":"1 lb"},{"name":"High Heat Cooking Oil","measure":"2 tablespoons"},{"name":"Garlic","measure":"2 cloves minced"},{"name":"Cornstarch","measure":"1 tsp"},{"name":"Water","measure":"1 tablespoon"}]'::jsonb, '["Marinate the beef:","Stir together the beef marinade ingredients (1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper) in a medium bowl.","Add the beef slices and stir until coated. Let stand for 10 minutes.","Prepare the sauce:","Stir together the sauce ingredients (2 tablespoons oyster sauce, 1 teaspoon Chinese rice wine, 1 teaspoon soy sauce, 1/4 cup chicken broth) in a small bowl. Set aside.","Blanch or steam the broccoli:","Bring a pot of water to a boil. Add the broccoli and cook until crisp-tender, about 2 minutes. Drain thoroughly.","Stir-fry the beef:","Heat a large frying pan or wok over high heat until a bead of water sizzles and instantly evaporates upon contact. Add the cooking oil and swirl to coat.","Add the beef and immediately spread it out all over the surface of the wok or pan in a single layer (preferably not touching).","Let the beef fry undisturbed for 1 minute. Flip the beef slices over, add the garlic to the pan, and fry for an additional 30 seconds to 1 minute until no longer pink.","Add the sauce, cornstarch, and broccoli:","Pour in the sauce and the cornstarch slurry (1 teaspoon cornstarch dissolved in 1 tablespoon of water). Stir until the sauce boils and thickens, about 30 seconds. Stir in the broccoli.","Serve immediately, with steamed rice or on its own."]'::jsonb, 'https://www.themealdb.com/images/media/meals/m0p0j81765568742.jpg', 'themealdb'),
('Singapore Noodles with Shrimp', ARRAY['chinese', 'seafood']::text[], ARRAY['dairy_free']::text[], 41, 100, 141, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Sesame Seed Oil","measure":"2 tsp"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Seasoned Rice Vinegar","measure":"2 tablespoons"},{"name":"Vermicelli Rice Noodles","measure":"6 oz"},{"name":"Egg","measure":"2 large"},{"name":"Ground Ginger","measure":"2 tblsp"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Carrots","measure":"2"},{"name":"Jalapeno","measure":"1 sliced"},{"name":"Onion","measure":"1/2"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Ham","measure":"4 oz"},{"name":"Napa Cabbage","measure":"1/2"},{"name":"Scallions","measure":"4"},{"name":"Red Pepper","measure":"1/2"},{"name":"Curry Powder","measure":"2 tsp"},{"name":"Shrimp","measure":"1/2 lb"},{"name":"Cilantro Leaves","measure":"2 tablespoons"}]'::jsonb, '["For the sweet onion, look for Vidalia, OSO Sweet, or Walla Walla. The super-sweet varieties are more suited to this stir-fry because at the end of cooking, the onion still has a slight crunch.","Make the sauce:","In a bowl, combine the sesame oil, soy sauce, and rice vinegar.","Cook the rice noodles:","Bring a large saucepan of water to a boil, add the noodles, and use tongs to turn them so they are submerged. Cook for 2 minutes, or until they are tender but still have some bite (they will cook a little more once you add them to the skillet).","Drain, rinse with cold water, and use scissors to snip the noodles several times to break them up into shorter lengths.","Scramble the eggs:","In a small bowl whisk together the eggs. Heat the skillet or Dutch oven over medium heat. Add 1 tablespoon of the peanut or canola oil. Add the eggs and scramble them for 2 minutes, or until they form large, soft curds. Transfer them from the pan to a plate or bowl.","Cook the vegetables:","Add 1 tablespoon of the remaining oil to the pan. When it is hot, add the ginger, garlic, carrots, jalapeño, onion, and salt. Cook, stirring constantly, for 2 minutes or until the vegetables start to soften.","Add the remaining ingredients:","Sprinkle the vegetable mixture with the remaining 1 tablespoon peanut or canola oil. When the oil is hot, add the ham, cabbage, scallions, red pepper, and curry powder to the pan. Cook, stirring constantly, for 1 minute.","Add the shrimp and cook, stirring, for 3 more minutes or until the shrimp are bright pink and cooked through.","Add the noodles in batches:","Add the eggs, the sauce mixture, and half the noodles to the pan. Toss for 1 minute.","Add the remaining noodles and continue tossing for 1 minute more until they are thoroughly combined and the mixture is heated through.","Serve:","Taste for seasoning and add more salt or soy sauce, if you like. Sprinkle with cilantro leaves and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/f3cxnc1765656994.jpg', 'themealdb'),
('Silken Tofu with Sesame Soy Sauce', ARRAY['chinese', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 15, 35, 50, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 2, '[{"name":"Silken Tofu","measure":"16 ounces"},{"name":"Soy Sauce","measure":"3  tablespoons"},{"name":"Chinese Sesame Sauce","measure":"2 tablespoons"},{"name":"Scallions","measure":"1 sliced"},{"name":"Sesame Seed","measure":"2 tsp"}]'::jsonb, '["Prepare the tofu:","Drain the tofu and gently remove it from its packaging onto a large plate. Carefully slice the tofu into 1/2-inch slabs widthwise. With the palm of your hands, gently push the sliced tofu sidewise so that they fan out over the plate.","Garnish with toppings and serve:","Drizzle the soy sauce and sesame sauce on top. Then garnish it with scallions and sesame seeds, and serve.","Tightly cover leftovers and refrigerate for up to 2 days. You can enjoy it cold straight out of the fridge or you can reheat it by microwaving in 30-second increments until warmed through"]'::jsonb, 'https://www.themealdb.com/images/media/meals/j9nray1765657692.jpg', 'themealdb'),
('Egg Foo Young', ARRAY['chinese', 'seafood']::text[], ARRAY['dairy_free']::text[], 39, 80, 119, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 6, '[{"name":"Unsalted Beef Stock","measure":"1 cup"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Shaoxing Wine","measure":"1 tablespoon"},{"name":"Oyster Sauce","measure":"1 tablespoon"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Cornstarch","measure":"1 tablespoon"},{"name":"Water","measure":"1 tablespoon"},{"name":"Cornstarch","measure":"1 tablespoon"},{"name":"Water","measure":"1 tablespoon"},{"name":"Egg","measure":"8 large"},{"name":"Kosher Salt","measure":"1/2 tsp"},{"name":"Sugar","measure":"1/4 tsp"},{"name":"Spring Onions","measure":"1"},{"name":"Mung Bean Sprouts","measure":"1 cup"},{"name":"Shrimp","measure":"20"},{"name":"Vegetable Oil","measure":"3 Cups"},{"name":"Jasmine Rice","measure":"2 cups"}]'::jsonb, '["Make the gravy:","In a small saucepan, add the beef stock, soy sauce, Shaoxing wine, oyster sauce, and white pepper powder over medium heat. Whisk together and bring to a simmer.","Combine the cornstarch and water in a small bowl and whisk to dissolve. Add to the saucepan and whisk until the gravy thickens and coats the back of the spoon, 2 to 3 minutes. Cover the saucepan with a lid and keep it warm on the lowest possible heat.","Make the egg foo young batter:","In a medium bowl, whisk together the cornstarch and water until dissolved. Add the eggs, salt, and sugar. Whisk until well combined and there are no more egg white clumps.","Add the green onion, bean sprouts, and shrimp. Stir until everything is evenly coated.","Fry the egg foo young:","Add the vegetable oil to a large wok; it should reach about 2 inches up the sides. Heat the oil over medium-high heat to 350°F, or until vigorous bubbles form around an inserted wooden chopstick.","With a ladle, gently and slowly add 1/4 of the omelet batter. Egg foo young should immediately bubble and puff up like magic. Fry until golden brown and crispy on each side, about 2 minutes per side. If there are any light spots, use a ladle to gently baste it with hot oil.","Tip","Egg foo young can be a bit tricky to flip. The easiest method is to put a tool in each hand (a spider, slotted spoon, tongs, and large chopsticks are all good candidates) and gently coax the omelet over, pulling up on one side and pushing down and around on the other.","Remove the omelet and place it on a paper towel-lined baking sheet. Let it cool for 5 minutes. Meanwhile, repeat with the remaining batter to make 4 omelets. If needed, add more oil to the pan between batches.","Serve and enjoy:","Plate each egg foo young over a bed of rice. Spoon the warm gravy over the top and serve immediately."]'::jsonb, 'https://www.themealdb.com/images/media/meals/47y6ii1765658818.jpg', 'themealdb'),
('Sichuan Style Stir-Fried Chinese Long Beans', ARRAY['chinese', 'vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 21, 20, 41, 'easy', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Chinese Long Beans","measure":"1/2 lb"},{"name":"Peanut Oil","measure":"1 tablespoon"},{"name":"Dried Chillies","measure":"6"},{"name":"Sichuan Pepper","measure":"1 tsp"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Sugar","measure":"1/2 tsp"},{"name":"Sesame Seed Oil","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"Splash"}]'::jsonb, '["Chinese long beans can be found in both green and purple varieties. Both have similar flavors and textures, and either kind can be used for this recipe.","If you don''t have a wok, use a sturdy, large sauté pan that has at least a two-inch lip."]'::jsonb, 'https://www.themealdb.com/images/media/meals/i0610h1765659464.jpg', 'themealdb'),
('Chinese Tomato Egg Stir Fry', ARRAY['chinese', 'vegetarian']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 25, 55, 80, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Plum Tomatoes","measure":"1 lb"},{"name":"Vegetable Oil","measure":"1 tablespoon"},{"name":"Eggs","measure":"5 Large"},{"name":"Sesame Seed Oil","measure":"1 tsp"},{"name":"Chicken Bouillon Powder","measure":"2 tsp"},{"name":"Sugar","measure":"2 tsp"},{"name":"Pepper","measure":"1/2 tsp"},{"name":"Salt","measure":"1/4 tsp"},{"name":"Spring Onions","measure":"1"},{"name":"Jasmine Rice","measure":"2 cups"}]'::jsonb, '["You can use chicken broth in place of the chicken bouillon powder. Add 1/4 cup of broth followed by 2 teaspoons of cornstarch dissolved in 1 tablespoPrepare the tomatoes:","Slice the tomatoes in half. Remove the tough stem from each half that connects to the vine. Cut each half into equal thirds (you’ll get 6 slices from each tomato).","Make the soft scrambled eggs:","In a cold, 8 to 10-inch nonstick skillet, add the vegetable oil and beaten eggs. Turn the heat to medium. Once a thin layer of eggs is just beginning to cook on the bottom, push the eggs in one direction to create layers of scrambled eggs.","Cook, gently stirring the whole time, until the scramble eggs are mostly set but still slightly wet and shiny, 2 to 5 minutes. Remove the eggs to a plate and, if needed, wipe out the pan.","Stir-fry the tomatoes and seasonings:","Add the sesame oil to the pan followed by the tomatoes and stir-fry over medium heat until the tomatoes are softened but not mushy, about 3 minutes. Add the chicken bouillon powder, sugar, and white pepper. Toss until combined and the sugar and bouillon have dissolved, about 1 minute.","Add eggs, stir-fry, and garnish:","Add the eggs back to the pan with the tomatoes. Stir-fry for about 2 minutes to heat through and combine. Taste, adding salt only if needed. Sprinkle with the green onions and serve with steamed rice.on of water, plus salt to taste."]'::jsonb, 'https://www.themealdb.com/images/media/meals/rwvw8q1765660071.jpg', 'themealdb'),
('Sichuan Eggplant', ARRAY['chinese', 'vegetarian']::text[], ARRAY['dairy_free']::text[], 31, 110, 141, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Egg Plants","measure":"1.5 pounds sliced"},{"name":"Peanut Oil","measure":"2 tablespoons"},{"name":"Chicken Stock","measure":"1/4 cup"},{"name":"Sugar","measure":"2 tsp"},{"name":"Soy Sauce","measure":"1/2 tsp"},{"name":"Chilli Bean Paste","measure":"1 ½ tbsp"},{"name":"Sichuan Pepper","measure":"2 tsp"},{"name":"Ginger","measure":"2 tsp"},{"name":"Garlic","measure":"5 cloves"},{"name":"Cornstarch","measure":"1 tsp"},{"name":"Apple Cider Vinegar","measure":"2 tsp"},{"name":"Scallions","measure":"4 Chopped"},{"name":"Cilantro","measure":"Garnish"}]'::jsonb, '["This recipe calls for asian eggplants, or Japanese eggplants. They are long and thin compared to a European or globe eggplant, and much more tender and delicate. If you can''t find them you can substitute globe eggplant, but the dish is really best with the asian eggplant.","*A lot of grocery stores have Asian ingredient aisles now. You should be able to find chili-bean paste, a mixture of preserved chilies mixed with mashed soybeans, there or at any Asian market. (Do not confuse with black bean paste or chili-garlic paste.)","**Sichuan peppercorns are available at some stores and online for quite cheap. They aren''t spicy like other peppers but rather have a citrusy flavor and induce a tingly, numbing sensation like a carbonated drink.","Prep eggplant, chili sauce, cornstarch slurry, vinegar and scallions:","Begin your mise en place. Quarter the eggplant lengthwise and chop into large batons and set aside.","In a small bowl, mix together the chicken stock, sugar, and soy sauce and set it aside.","In a second bowl, mix together the chili bean paste, garlic, ginger, and sichuan peppercorns and set it aside.","In a third bowl, mix together the cornstarch with a tablespoon of water and set it aside.","Lastly, in a fourth bowl, mix together the scallions and vinegar and set it aside.","Sauté eggplant:","Place the oil in a wok or large sauté pan over medium-high heat until the oil is almost smoking. Add the eggplant and sauté, allowing it to sit for a few seconds each time you move it to allow it to brown and blister. If the eggplant absorbs all the oil and some pieces don''t get any then add a little more oil.","Add the chili bean paste, garlic, ginger, and sichuan peppercorns and sauté:","until fragrant, about 30 seconds.","Add the chicken stock mixture:","turn the heat to medium-low and simmer for 90 seconds.","Add the cornstarch mixture:","and stir together until the sauce thickens a bit.","Add the scallions and vinegar:","and cook for 15 seconds to diffuse their harsh flavors a bit.","Garnish with cilantro and serve."]'::jsonb, 'https://www.themealdb.com/images/media/meals/1oz4nb1765687990.jpg', 'themealdb'),
('Sweet and Sour Chicken', ARRAY['chinese', 'chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 31, 90, 121, 'hard', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Chicken Thighs","measure":"1 lb"},{"name":"Egg White","measure":"1 large"},{"name":"Kosher Salt","measure":"1 tsp"},{"name":"Cornstarch","measure":"2 tsp"},{"name":"Pineapple Chunks","measure":"10 oz"},{"name":"Pineapple Juice","measure":"1/4 cup"},{"name":"White Vinegar","measure":"1/4 cup"},{"name":"Tomato Ketchup","measure":"1/4 cup"},{"name":"Brown Sugar","measure":"3  tablespoons"},{"name":"Oil","measure":"4 tsp"},{"name":"Red Pepper","measure":"1 chopped"},{"name":"Yellow Pepper","measure":"1 chopped"},{"name":"Ginger","measure":"1 tsp"}]'::jsonb, '["Coat the chicken with egg white:","In a bowl, combine the chicken with the egg white, 1/2 teaspoon kosher salt, and cornstarch. Stir to coat the chicken evenly. Let sit for 15 minutes at room temperature or up to overnight in the refrigerator.","Make the sweet and sour sauce:","Whisk together the pineapple juice, vinegar, ketchup, 1/2 teaspoon kosher salt, and brown sugar.","Stir-fry the chicken over high heat:","Heat a large frying pan or wok over high heat until a bead of water instantly sizzles and evaporates. Pour in 1 tablespoon of cooking oil and swirl to coat. It''s important that the pan is very hot.","Add the chicken and spread the pieces out in one layer. Let the chicken fry untouched for 1 minute, until the bottoms are browned.","Flip and fry the other side for 1 minute. The chicken should still be pinkish in the middle. Dish out the chicken onto a clean plate, leaving as much oil in the pan as possible.","Stir-fry the bell pepper and ginger:","Reduce the heat to medium and add the remaining 1 teaspoon of cooking oil. Let the oil heat up before adding the bell pepper chunks and ginger. Fry for 1 minute.","Add the pineapple, sauce, and then, the chicken:","Add the pineapple chunks and the sweet and sour sauce. Turn up the heat to high. When the sauce is simmering, add the chicken pieces back in.","Let simmer for 1 to 2 minutes, until the chicken is cooked through. Timing depends on how thick you''ve cut your chicken. The best way to tell if the chicken is done is to take a piece out and cut into it. If it''s pink, add another minute to the cooking.","Adjust the seasoning and serve:","Taste the sauce and add more brown sugar or vinegar to suit your tastes, if you’d like.","Serve hot with steamed white or brown rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/arzs741766434335.jpg', 'themealdb'),
('Napa Cabbage with Dried Shrimp', ARRAY['chinese', 'seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 27, 95, 122, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Dried Shrimp","measure":"2 tablespoons"},{"name":"Boiling Water","measure":"3/4 cup"},{"name":"Napa Cabbage","measure":"1 head"},{"name":"Peanut Oil","measure":"2 tablespoons"},{"name":"Scallions","measure":"4 Chopped"},{"name":"Ginger","measure":"1 tablespoon"},{"name":"Soy Sauce","measure":"1 tablespoon"},{"name":"Water","measure":"1 tablespoon"},{"name":"Cornstarch","measure":"2 tsp"},{"name":"Kosher Salt","measure":"1 tsp"},{"name":"Pepper","measure":"1/2 tsp"}]'::jsonb, '["Dried shrimp gives this Chinese dish a punch of salty umami flavor. You can find it at an Asian grocery store in the frozen or refrigerated section. Look for small-sized dried shrimp, about a 1/4-inch in size. If you use medium or large dried shrimp, hydrate the shrimp with more water (1 cup for medium-sized shrimp, 1 1/4 cup for large) and for longer time (45 to 60 minutes), then chop it up into smaller 1/4-inch chunks. To make this recipe vegetarian, omit the dried shrimp and use four or five dried shiitake mushrooms, rehydrated, and sliced thin.","Rehydrate the dried shrimp:","Place the dried shrimp in a small bowl and pour the boiling water over it. Cover with a small plate and let sit for 30 minutes so the shrimp can rehydrate. The shrimp will be lighter in color and plump up slightly.","Prep the cabbage:","Meanwhile, split the napa cabbage in half lengthwise. Rinse the cabbage and shake it dry. Cut out the core of the cabbage and discard.","Set out two large bowls. Cut the remaining cabbage into 1-inch pieces, putting the thicker white pieces at the bottom of the cabbage into one bowl and the top thinner leafy green pieces into the other bowl.","Drain the shrimp:","Once the shrimp has rehydrated, drain it and discard the liquid.","Cook the shrimp and cabbage:","In a large wok or skillet over high heat add the peanut oil, swirling it around to coat the pan.","Heat until the oil looks shimmering hot, then carefully add the scallions, ginger, and rehydrated shrimp, paying specially attention as the wet ingredients may cause the hot oil to splatter. Toss with a spatula until the scallions are bright green and the entire mixture is fragrant, about 1 minute.","Add the thicker white part of the napa cabbage to the pan and lower the heat to medium high. Continue to cook and stir for 3 to 4 minutes, or until the edges of the cabbage pieces start to look slightly translucent but the center of the cabbage pieces are still opaque white.","Reduce the heat to medium low and add the leafy green pieces of cabbage into the pan. Cook until the leaves are wilted, about 2 minutes.","Make a cornstarch slurry:","In a small bowl, combine the soy sauce, cold water, and cornstarch, stirring to make a slurry. Then pour over the cabbage and continue to cook and stir until a sauce has thickened slightly to the consistency of whole milk.","Season the stir fry:","Season the stir fry with salt and pepper, then taste and add more salt and pepper if you wish. The cabbage will be translucent and silky looking, with specks of dried shrimp all over."]'::jsonb, 'https://www.themealdb.com/images/media/meals/9nh4dl1766435484.jpg', 'themealdb'),
('Dutch poffertjes (mini pancakes)', ARRAY['netherlands', 'breakfast']::text[], ARRAY['vegetarian']::text[], 23, 35, 58, 'medium', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Flour","measure":"125g"},{"name":"Buckwheat Flour","measure":"125g"},{"name":"Eggs","measure":"2"},{"name":"Butter","measure":"1 knob"},{"name":"Milk","measure":"300ml"},{"name":"Yeast","measure":"10g"},{"name":"vanilla sugar","measure":"1tsp"},{"name":"Butter","measure":"To serve"},{"name":"Icing Sugar","measure":"To serve"}]'::jsonb, '["Mix the dry yeast with some of the luke warm milk en stir until dissolved.","Place buckwheat and the flour together in a bowl and make a small circle in the middle. Add the yeast mixture into it. Add the milk and stir until you have a smooth batter.","Add the eggs, salt and vanille sugar and stir through. Leave to stand and rise for about 45 minutes.","Heat the poffertjespan and add a bit of butter into each hole. Fill halfway with batter and first bake one side until you can see the top dry out a little. Turn the poffertjes around with a small fork and bake the other side until cooked and golden brown.","Serve the poffertjes with butter and icing sugar"]'::jsonb, 'https://www.themealdb.com/images/media/meals/oaqz9f1766593912.jpg', 'themealdb'),
('Apple cake', ARRAY['netherlands', 'dessert']::text[], ARRAY['vegetarian']::text[], 23, 70, 93, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Eggs","measure":"4"},{"name":"Sugar","measure":"200g"},{"name":"Self-raising Flour","measure":"200g"},{"name":"Melted Butter","measure":"200g"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Ground Cinnamon","measure":"1 tsp"},{"name":"Apples","measure":"3"},{"name":"Salt","measure":"Pinch"},{"name":"Ground Sugar","measure":"Sprinkling"}]'::jsonb, '["Preheat the oven to 180°C. (350˚F) Grease a cake pan and line it with baking paper.","In a large bowl, break the four eggs with the sugar and beat until they have tripled in volume and become fluffy.","Sift the self-rising baking flour and add it to your egg mixture. Fold this over, preserving as much air as possible. Add the melted (and slightly cooled) butter and mix until combined.","Add cinnamon, pinch of salt and vanilla extract.","Add the diced apple to the batter and gently fold them into the batter so that the apple pieces are evenly distributed. You can roll the apple pieces through some more cinnamon.","Pour the batter into the prepared cake pan and smooth the top with a spatula.","Place the apple slices on top of the batter and press lightly. Sprinkle optionally with some almond shavings.","Bake the apple cake in the preheated oven for about 45-50 minutes, or until a wooden skewer comes out clean when inserted into the center of the cake.","Remove the cake from the oven and let it cool in the mold for a few minutes. Then carefully remove the cake from the mold and let cool completely on a wire rack.","Sprinkle the cooled apple cake with powdered sugar"]'::jsonb, 'https://www.themealdb.com/images/media/meals/c0gmo31766594751.jpg', 'themealdb'),
('Gevulde speculaas', ARRAY['netherlands', 'dessert']::text[], ARRAY['vegetarian']::text[], 25, 50, 75, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Self-raising Flour","measure":"300g"},{"name":"Brown Sugar","measure":"150g"},{"name":"Speculaas Spice Mix","measure":"10g"},{"name":"Salt","measure":"Pinch"},{"name":"Butter","measure":"125g"},{"name":"Milk","measure":"10 tblsp"},{"name":"Almond Paste","measure":"300g"},{"name":"Egg","measure":"1"},{"name":"Milk","measure":"For brushing"},{"name":"Almonds","measure":"Garnish"}]'::jsonb, '["Mix the self-rising flour, sugar, speculaas spice mix and salt. Add the butter and milk and knead into a firm ball of dough. Start with 6 tablespoons of milk, if the dough is too stiff you can add more milk.","Wrap the dough in plastic wrap and refrigerate overnight. You can process and bake it immediately, but the flavor will be much better if you let it rest.","Mix the almond paste with half of the beaten egg and knead well. This makes it easier to work with and gives it a better and tastier texture.","Take half of the dough and roll it out to 20 x 20 cm. Place in a baking pan lined with parchment paper. Spread the almond paste mixture evenly. Roll out the remaining dough and place on top of the almond paste.","Brush the top with the remaining beaten egg. Garnish with almonds and top with another layer of egg wash.","Bake the filled speculaas for 40 minutes at 180°C/350℉ (conventional oven) or until done."]'::jsonb, 'https://www.themealdb.com/images/media/meals/rw64di1766595573.jpg', 'themealdb'),
('Ramen Noodles with Boiled Egg', ARRAY['chinese', 'miscellaneous']::text[], ARRAY['vegetarian', 'dairy_free']::text[], 21, 30, 51, 'easy', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 4, '[{"name":"Noodles","measure":"1 Packet"},{"name":"Water","measure":"2 cups"},{"name":"Egg","measure":"1 large"},{"name":"Soy Sauce","measure":"1 tbsp"},{"name":"Chilli Sauce","measure":"1/2 tsp"},{"name":"Spring Onions","measure":"1 tbls"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Pepper","measure":"1/2 tbs"}]'::jsonb, '["Boil: Bring water to a boil, gently add eggs, and cook for exactly 6½ to 7 minutes.","Ice Bath: Immediately transfer the eggs to a bowl of ice water for 3–5 minutes to stop cooking.","Marinate (Optional but recommended): Peel the eggs and marinate in a mix of 2 tbsp soy sauce, 2 tbsp mirin, 1 tsp sugar, and 4 tbsp water for at least 4 hours (or overnight).","Serve: Slice in half, letting the yolk flow into the broth"]'::jsonb, 'https://www.themealdb.com/images/media/meals/ip5xtp1769779958.jpg', 'themealdb'),
('Dutch Apple Pie', ARRAY['netherlands', 'dessert']::text[], ARRAY['vegetarian']::text[], 23, 70, 93, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Butter","measure":"175g"},{"name":"Egg Yolks","measure":"2"},{"name":"Flour","measure":"300g"},{"name":"Sugar","measure":"200g"},{"name":"Salt","measure":"Pinch"},{"name":"Cinnamon","measure":"1"},{"name":"Raisins","measure":"100g"},{"name":"Apples","measure":"6"},{"name":"Cold Water","measure":"1 tablespoon"}]'::jsonb, '["Add the flour, 150 gr of the sugar, pinch of salt and 1 egg yolk in the bowl of a food processor. Cut the butter into small cubes and add to the bowl. Turn this into a firm dough. Don''t over process, you do not want the dough to turn warm. Check if it sticks by pinching it between your fingers.","Turn out onto a piece of plastic wrap. Make a round ball of it by using your hands and roll it into the plastic. Place into the fridge for half an hour to cool.","Take a round baking tin of 22 cm diameter and cover this with baking paper. Brush the sides with butter.","Preheat the oven to 170˚C (340˚F)","Cut the apple into cubes and mix this with the raisins, the left over sugar and the cinnamon.","Place the cooled dough on a flat surface sprinkled with flour and roll out into a thin sheet. Place this into the baking tin and cover the bottom and the sides well. I usually just press it into the tin without rolling it out. I find that the easiest way but it is less smooth. Just do whatever works for you.","Make sure you keep 1/4 of the dough separate to form the strips on the top.","Once the bottom and sides are covered with the dough, take the rusks and crumble them over the bottom. You can use breadcrumbs for this as well. Shake it a bit so it is divided equally across the bottom.","Add the apple mixture and divide well over the tin. Rol out the rest of the dough and cut into strips. Place that over the top of the pie in a diamond shaped pattern. Brush the strokes and sides with the other egg yolk and place in the preaheated oven.","Bake the apple pie for about 1 hour or until golden and cooked through. Leave to cool in the tin and make sure the sides are loose before opening the tin."]'::jsonb, 'https://www.themealdb.com/images/media/meals/zy4fs51777540384.jpg', 'themealdb'),
('Apple Potato Mash (Hete bliksem)', ARRAY['netherlands', 'side']::text[], ARRAY['gluten_free']::text[], 25, 45, 70, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Apples","measure":"250g"},{"name":"Potatoes","measure":"250g"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Maple Syrup","measure":"1 tsp"},{"name":"Ground Cinnamon","measure":"Sprinkling"},{"name":"Bacon","measure":"4"},{"name":"Cheese","measure":"200g"},{"name":"Salt","measure":"Pinch"},{"name":"Egg","measure":"1"},{"name":"Sesame Seed","measure":"50g"}]'::jsonb, '["Clean and peel the potatoes and cut them into even size chunks. Boil them in salted water for about 10 min and then add the cleaned and chopped apples into the boiling water. Add the cinnamon stick as well. Leave to boil for another 10 minutes or until both apples and potatoes are to your liking. I like mine to be fairly chunky but that is a personal preference","In the mean time bake the streaky bacon in a dry frying pan until crispy and set aside to drain on paper towels.","Slice a few apple pieces and melt a little butter in a fryin pan. Add the apple slices to it and add a bit of maple syrup into the pan as well as some cinnamon. Let it simmer until the apple is soft.","Prepare a plate with one whisked egg and one plate with sesame seeds. Cut your cheese into the required size. The smaller it is, the easier it is too handle.","Dip the cheese into the egg and make sure it coats all sides. Then dip the cheese into the sesame seeds and make sure it is covered everywhere.","Heat a non stick frying pan on high until nice and hot. Put the cheese slice in and bake until the sesame seeds are brown. You have to do this rather quickly or the cheese will melt completely. Turn and bake the other side.","Drain the apples and potatoes and mash them together. Taste and add cinnamon and salt where needed. Remove the cinnamon stick before mashing"]'::jsonb, 'https://www.themealdb.com/images/media/meals/pa03n41777540582.jpg', 'themealdb'),
('Traditional Dutch rice tart (rijstevlaai)', ARRAY['dessert']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 33, 35, 68, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Flour","measure":"200g"},{"name":"Coconut Oil","measure":"75g"},{"name":"Vegetable Millk","measure":"100g"},{"name":"Yeast","measure":"10g"},{"name":"Sugar","measure":"50g"},{"name":"Dessert Rice","measure":"150g"},{"name":"Sugar","measure":"100g"},{"name":"Vegetable Millk","measure":"700g"},{"name":"Vanilla Extract","measure":"1 tsp"},{"name":"Cardamom","measure":"2"},{"name":"Star Anise","measure":"2"},{"name":"Cinnamon Stick","measure":"1"},{"name":"Baking Powder","measure":"1/2 tsp"},{"name":"Lemon Juice","measure":"1/2 tsp"}]'::jsonb, '["Heat the oven to 180°C. For the dough, mix flour and sugar in a bowl. Heat the 100 grams of milk to lukewarm and dissolve the yeast in it. Let stand for a while until it starts to bubble. Then add to the flour along with the coconut oil and mix into a smooth dough. Let rise for 30 minutes, covered, in a warm place.","Meanwhile, make the rice pudding by putting the rice with sugar, milk and vanilla extract in a saucepan. Add the cardamom, star anise and cinnamon. Bring to a boil and cook, stirring constantly. Take out the spices. In a small bowl, mix baking soda with lemon juice/apple vinegar. Stir well until baking soda is dissolved, then mix into the rice pudding.","Roll out the dough on a floured work surface (it is very sticky, but don’t stress it will be fine) and line the bottom and edges of a greased mold with it. Spread the rice pudding over the bottom and bake for about 25 to 30 minutes."]'::jsonb, 'https://www.themealdb.com/images/media/meals/x8opo81777582259.jpg', 'themealdb'),
('Arnhemse meisjes', ARRAY['dessert']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 15, 75, 90, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Puff Pastry","measure":"5 Slices"},{"name":"vanilla sugar","measure":"100g"},{"name":"Cinnamon","measure":"1/2 tsp"},{"name":"Cardamom","measure":"1/2"},{"name":"Lime","measure":"Zest of 1"}]'::jsonb, '["Take your puff pastry from the freezer and defrost.","Sprinkle some flour on the kitchen counter. Stack the sheets of puff pastry on top of each other and roll them out with a rolling pin. You want those five sheets to end up being as thin as one sheet.","Using a round or oval form press into the puff pastry and try to be as economical doing that as possible. You want to have as many cookies as you can.","Mix the vanilla sugar with the cinnamon, cardemom and limezest in a little bowl","Remove the flour from the counter and sprinkle with a bit of the sugar mix.","Brush your puff pastry with a little bit of eggwash and than dip into the sugar mix and roll them softly to press the sugar in.","Put your sugary puff pastry on a baking sheet (greased or with baking paper) and leave the dough to rest for about 20 to 25 minutes. this will make the cookies even crisper.","Preheat the oven in the meantime to 180 C and put the baking tray in the oven.","bake the cookies golden brown in about 25 minutes and make sure the sugar is caramelised nicely","And voila, Girls from Arnhem with an Almeerse twist","Voila, Arnhemse Meisjes met een Almeerse twist."]'::jsonb, 'https://www.themealdb.com/images/media/meals/y4t9zg1777628842.jpg', 'themealdb'),
('Slagroomtaart', ARRAY['dessert']::text[], ARRAY['vegetarian']::text[], 25, 45, 70, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Eggs","measure":"175g"},{"name":"Sugar","measure":"100g"},{"name":"vanilla sugar","measure":"10g"},{"name":"Flour","measure":"75g"},{"name":"Cornstarch","measure":"25g"},{"name":"Jam","measure":"6 tablespoons"},{"name":"Nougatine","measure":"100g"},{"name":"Whipping Cream","measure":"750 ml"},{"name":"Sugar","measure":"6 tablespoons"},{"name":"Fruit Mix","measure":"5"}]'::jsonb, '["Beat the eggs, sugar and vanilla sugar until light and fluffy. I beat this in a stand mixer on medium-high speed for about 10 minutes.","Sift the flour and cornstarch and add to the mixture. Fold this gently into the mixture; you don’t want all the air you whipped in to disappear.","Pour the batter into a greased baking pan. Bake the cake base at 180°C/350°F (conventional oven) for 30 minutes. The cake is done when you press lightly on the top and it springs back. Allow the cake to cool in the pan for a few minutes before removing it to a cake rack.","Meanwhile, prepare the nougatine and jam according to the recipe if you haven’t already.","Let the cake cool completely before you cut it. If, like me, you used a 20 cm/8 inch spring form pan, cut the cake into three layers."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wxfmk41777628643.jpg', 'themealdb'),
('Baghlaw-e-Khanagi', ARRAY['dessert']::text[], ARRAY['vegetarian']::text[], 23, 60, 83, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Flour","measure":"600g"},{"name":"Eggs","measure":"3"},{"name":"Milk","measure":"450ml"},{"name":"Vegetable Oil","measure":"75 ml"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Ground Walnuts","measure":"50g"},{"name":"Cardamom","measure":"10g"},{"name":"Sugar","measure":"300g"},{"name":"Water","measure":"1 L"}]'::jsonb, '["Place flour in a bowl, and create a hole in the middle of the flour. Whisk eggs, and then pour whisked eggs into the well.","Add milk, and combine. Then, stir in the ground walnuts, baking powder and cardamom, and add to the mixture. Fold ingredients into the mixture until it forms an elastic dough consistency.","Take dough and with a rolling pin, roll out into a thin rectangle on a clean surface. Then, from the longest side of the rectangle, fold the dough into 3cm-wide lines, until the dough is fully rolled in a long line. Cut folded dough horizontally into 3cm pieces","Heat a deep pan of the vegetable oil, and wait till it reaches frying temperature. Whilst you are waiting. Fill a deep pan with 1 litre of water, and bring to the boil.  Then, pour in the sugar, and stir gently until it becomes thick and syrup-like. Turn down the heat and leave to simmer.","Carefully lower each piece of dough into the frying oil. Fry until golden brown.","When golden brown, take the Baghlaw pieces out of the oil, and place them into the sugar syrup to coat.","Remove from the syrup and whilst still warm, sprinkle with ground walnuts, so they stick to the Baghlaw.","Leave to cool. Then, enjoy with your friends and family!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/bjtjyl1779552068.jpg', 'themealdb'),
('Haft Mewa Recipe', ARRAY['side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 21, 30, 51, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Dried Apricots","measure":"110g"},{"name":"Light Raisins","measure":"50g"},{"name":"Raisins","measure":"110g"},{"name":"Walnuts","measure":"50g"},{"name":"Almonds","measure":"50g"},{"name":"Pistachio","measure":"50g"},{"name":"Cherry","measure":"50g"},{"name":"Rose water","measure":"Splash"}]'::jsonb, '["Wash the apricots and both raisins and place in a bowl - cover with cold water to 5cm above the fruit.","Put the walnuts, pistachos and almonds in another bowl or pan and add boiling water. Leave to soak, and then peel off all the skins as they soften. This is a fiddly job and make take some time - but it''s definitely worth the effort! Throw away the water.","Combine the fruits with the nuts and cherries, including the juice they have been soaking in. Add the rose water, cover the mixture and leave in the fridge to rest for two days. When you leave the mix, the juice will become sweeter and syrupy, giving the dish a really unique consistency.","To serve, spoon the fruit, nuts and juice into individual bowls or cups, and enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/io2u3z1779551885.jpg', 'themealdb'),
('Kadu Borani', ARRAY['vegetarian']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 25, 35, 60, 'medium', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Squash","measure":"1 medium"},{"name":"Onion","measure":"5 chopped"},{"name":"Green Chilli","measure":"To taste"},{"name":"Oil","measure":"Splash"},{"name":"Turmeric","measure":"1 tsp"},{"name":"Garlic","measure":"1 Bulb"},{"name":"Sugar","measure":"7 tablespoons"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Water","measure":"2 cups"},{"name":"Yogurt","measure":"4 tablespoons"}]'::jsonb, '["Peel the squash and cut it into pieces 1cm wide. Deep fry it in oil until golden and set aside.","Using the same pan and oil, deep fry the onions until golden. Remove the onions and grind with the garlic (if using garlic paste, mix it into the onions once ground).","Add a small amount of oil to a pan on medium heat. Once hot, add the turmeric. Mix the salt into one cup of water and add it to the turmeric. Add a layer of squash, then a layer of onion and garlic. Repeat this step until the squash, onion and garlic have been used up.","Add the sugar and one cup of water. Turn the heat down and cook until the water has reduced.","Add 1-2 tablespoons of melted curd to a plate, add the squash on top with another layer of melted curd. At last, add some green chilli and serve!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/walmi81779552709.jpg', 'themealdb'),
('Muraba-E-Kadu (Pumpkin Jam)', ARRAY['miscellaneous']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 13, 45, 58, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Pumpkin","measure":"1 kg"},{"name":"Orange","measure":"1 kg"},{"name":"Sugar","measure":"750g"},{"name":"Cardamom","measure":"60g"}]'::jsonb, '["Remove the skin of the pumpkin. Also remove the inner seeds.","Cut the flesh into 2cm cubes.","Take the zest off the oranges, with as little pith as possible, and cut into matchstick-sized strips.","Extract the juice from the oranges. Remove the seeds from the cardamom pods and reserve.","Place the pumpkin, orange juice, orange strips, sugar and whole cardamom pod seeds in a large pan, mix well and leave to marinate for about 10 hours or overnight. Stir occasionally.","Bring the mixture to the boil, then reduce the heat and simmer until the liquid has thickened and become syrupy. This can take about an hour or a little bit longer.","Leave to cool then place in clean, dry jars. Enjoy!"]'::jsonb, 'https://www.themealdb.com/images/media/meals/ug6bwk1779556566.jpg', 'themealdb'),
('Tavë me Presh ska Mish Meatless Leek Bake', ARRAY['vegetarian']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 29, 60, 89, 'hard', '{"calories":400,"protein_g":16,"carbs_g":50,"fat_g":16}'::jsonb, 4, '[{"name":"Leek","measure":"500g"},{"name":"Red Pepper","measure":"3 diced"},{"name":"Rice","measure":"200g"},{"name":"Garlic","measure":"1 clove finely chopped"},{"name":"Vegetable Stock","measure":"1 L"},{"name":"Paprika","measure":"1 tsp"},{"name":"Oregano","measure":"1 tsp"},{"name":"Parsley","measure":"1 tsp"},{"name":"Basil","measure":"1 tsp"},{"name":"Salt","measure":"Pinch"},{"name":"Pepper","measure":"Pinch"},{"name":"Olive Oil","measure":"Splash"}]'::jsonb, '["Prepare the dish","Fry the leeks in a small dash of olive oil for a few minutes until they start to brown.","Prepare the Dish","Add the roasted red peppers, garlic, stock, herbs, salt, pepper and paprika. Give it a good stir, add the rice and stir again.","Leave it to come to the boil. Leave to simmer for 2 minutes.","Pour the mixture into a baking tray with a depth of 2 inches or more. Mix thoroughly and ensure equally levelled out.","Cooking","Place on the bottom self of a preheated oven at 180 degrees. Leave to bake for 1 hour.","Serving","Once cooked turn off the oven and keeping the door open leave the leek bake to cool for 10 minutes before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/p5m3w21779644533.jpg', 'themealdb'),
('Kulaç Soda Bread', ARRAY['side']::text[], ARRAY['vegetarian']::text[], 15, 75, 90, 'hard', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Flour","measure":"450g"},{"name":"Greek Yogurt","measure":"500g"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Olive Oil","measure":"Splash"}]'::jsonb, '["Prepare","On a large baking tray or a clean work surface, mix together the dry ingredients - flour, baking soda and salt.","Make a well in the middle and add the yogurt. Using your hands slowly combined the ingredients together to start to form a dough.","Kneed the dough on a floured surface, adding extra flour if you find the texture too sticky. The dough is ready when it is of a pizza dough texture and still very slightly sticky, this should only take a few minutes.","On a baking tray add a little oil and put the dough on top. Shape and flatten the dough into a circle shape ensuring the height of the dough is about 5cm.","Cover the dough with a little bit of olive oil, ensure it is fully covered.","You can bake the Kulaç as it is or you can create patterns which also helps with even cooking. The most common patterns are using the back of a fork to slightly press down to create line dents all over or spiking the dough with the fork.","Baking","Place on the bottom shelf of a pre heated oven. Bake for 40 minutes or until the dough is golden and firm to touch.","Cooling","Once removed from the oven, stand upright or place on a cooling rack to allow the Kulaç to cool.","Serving","Cut the Kulaç the way you would a cake into 8 slices. If you are serving warm you may want to snap and pull apart the bread with your hands instead."]'::jsonb, 'https://www.themealdb.com/images/media/meals/9aia021779646058.jpg', 'themealdb'),
('Shendetlie Honey and Nut Cake', ARRAY['dessert']::text[], ARRAY['vegetarian']::text[], 23, 75, 98, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Sugar","measure":"300g"},{"name":"Eggs","measure":"3"},{"name":"Melted Butter","measure":"180g"},{"name":"Flour","measure":"700g"},{"name":"Walnuts","measure":"100g"},{"name":"Honey","measure":"4 tablespoons"},{"name":"Baking Powder","measure":"1 tsp"},{"name":"Sugar","measure":"220g"},{"name":"Water","measure":"450ml"}]'::jsonb, '["Prepare","In a mixing bowl cream together the eggs, sugar and cooled melted butter then add the honey and soda.","Add half the flour and the walnuts (you can add the walnuts whole or ground them) and mix well.","Add the rest of the flour and using your hands kneed the mixture together until a firm dough is formed.","Coat a large baking tray (traditionally a circle tray is used about 30cm is best with a 2 - 3 inch height) with olive oil. Add the dough and press it down so that it fits the whole tray. Try and get the dough flat and equal in height all over.","Baking","Place on the bottom shelf of a cold oven and turn the temperture up to 180 degrees. Bake for 35 minutes and the dough has turned dark brown and is firm to touch.","Remove from the oven and leave to cool while making the syrup.","Adding the Syrup","Add the sugar and water to a saucepan and bring to the boil. Leave boiling for 10 minutes, mixing occasionally. Remove from the heat.","Cut the Shendetlie into squares of diamond shapes and pour over the hot syrup. Use enough of the syrup to cover the cake plus 1 cm overflowing, sitting on top. This will soak into the cake while you leave it to cool for at least 1 hour before serving."]'::jsonb, 'https://www.themealdb.com/images/media/meals/fx0exq1779646651.jpg', 'themealdb'),
('Flija Layered Pancake / Crepe', ARRAY['breakfast']::text[], ARRAY['vegetarian']::text[], 29, 60, 89, 'hard', '{"calories":420,"protein_g":18,"carbs_g":42,"fat_g":20}'::jsonb, 4, '[{"name":"Flour","measure":"1 kg"},{"name":"Water","measure":"1 L"},{"name":"Salt","measure":"1 tsp"},{"name":"Melted Butter","measure":"220g"},{"name":"Vegetable Oil","measure":"200ml"},{"name":"Greek Yogurt","measure":"5 tablespoons"},{"name":"Melted Butter","measure":"220g"},{"name":"Vegetable Oil","measure":"200ml"},{"name":"Clotted Cream","measure":"3  tablespoons"},{"name":"Melted Butter","measure":"220g"},{"name":"Sour Cream","measure":"500ml"},{"name":"Olive Oil","measure":"3  tablespoons"}]'::jsonb, '["Prepare the Flour Batter","Mix together the flour, water and salt ensuring all the lumps are dissolved. The mixture should be thick but still of a pouring consistency, add a little extra water if required. Put to one side.","Prepare the Batter Filling","Mix together the butter, oil and chosen yogurt / cream ensuring all the lumps are dissolved. The mixture should be runny, leave to rest for 10 minutes before given it another good mix. The consistency should be similar to custard. Put to one side.","Baking","Preheat the gill to a medium setting (I use mark 4 of 6). Take a large deep baking tray or pie pan and rub some olive oil over the base. Make the first layer of flour batter using a squirty bottle or laydel, don''t try to pour the batter as it will be too thick in the pan. You need to make a star effect by leaving triangles between each line of batter layers. Place under the grill until golden brown. This will take between 3 - 5 minutes.","Remove from under the grill and using a brush or the back of spoon rub over the whole pan (both battered and un-battered areas) a layer of the batter filling. Then, add a layer of the flour filling, use the same star effect this time placing the lines of batter through the gaps left from the previous layering. Also, leaving the same triangle shapes between each line. Place under the grill until golden brown. This will take between 3 - 5 minutes.","Repeat step 4 until all the mixture has been used and ensuring each triangle gap is filled with flour batter on each layer - this will take around 2 hours. After every couple of layers, use one layer just to fill up any spaces (large gaps between the batter stars) that may have started to show.","Serving","Once the Flija is ready serve straight away with honey or yogurt."]'::jsonb, 'https://www.themealdb.com/images/media/meals/eqnf3p1779649407.jpg', 'themealdb'),
('Cambodian Stir-fried Morning Glory with Pork, Fermented Soybeans, and Garlic', ARRAY['pork']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 21, 55, 76, 'easy', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 4, '[{"name":"Morning Glory","measure":"1  bunch"},{"name":"Minced Pork","measure":"150g"},{"name":"Soya Bean","measure":"2 tablespoons"},{"name":"Garlic","measure":"4 Cloves Chopped"},{"name":"Oil","measure":"For frying"},{"name":"Fish Sauce","measure":"Dash"},{"name":"Sugar","measure":"Dash"},{"name":"Chilli","measure":"Sprinkling"}]'::jsonb, '["In a wok or large pan, heat 1 tablespoon of vegetable oil over medium heat. Once the oil is hot, add the garlic and stir-fry for about 30 seconds, until fragrant but not burnt.","Add the minced pork to the pan and break it up with a spatula. Stir-fry until the pork is fully cooked and browned, about 2-3 minutes.","Stir in the fermented soy beans and cook for another minute, mixing it thoroughly with the pork.","Toss in the cut morning glory and stir-fry for 2-3 minutes to retain its bright green colour and crisp texture.","Check the seasoning and adjust with fish sauce or sugar if needed. Transfer to a serving dish and serve immediately with steamed rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/wympxc1779734808.jpg', 'themealdb'),
('Crispy fried fish with ginger and fermented soybeans (trey chien chuon)', ARRAY['seafood']::text[], ARRAY['pescatarian', 'dairy_free']::text[], 23, 55, 78, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Ginger","measure":"2 cups"},{"name":"Fish fillet","measure":"1 lb"},{"name":"Tempura Flour","measure":"2 tablespoons"},{"name":"Oil","measure":"2 cups"},{"name":"Garlic","measure":"4 cloves"},{"name":"Soya Bean","measure":"800g"},{"name":"Sugar","measure":"1/2 tbs"},{"name":"Water","measure":"1/2 cup"},{"name":"Spring Onions","measure":"3"}]'::jsonb, '["Fry the ginger in plenty of oil until golden and slightly crispy. Set aside for later.","Cut the fish into strips. Dredge the fish in a very thin layer of tempura flour.","Fry the fish in plenty of oil until golden brown and crispy. You can use the same oil as you were using to fry the ginger.","Crush the garlic and chop it into small pieces. Chop the spring onion.","Drain the fermented soybeans using a colander. If you are using salted beans (soybeans in a very salty brine), you need to wash the beans in water before you add them to the dish.","Add a tablespoon of oil to a deep pan or a large pot, and sauté the garlic until slightly golden.","Add the soybeans and stir fry for a few minutes. If the soybeans are very salty, add ¼- ½ tablespoon sugar to balance the flavor.","Add water and fry for a minute.","Just before serving, stir in the fried ginger, the spring onion, and the crispy fish. Serve with steamed rice."]'::jsonb, 'https://www.themealdb.com/images/media/meals/9q1ci41779735714.jpg', 'themealdb'),
('Cambodian Waffles (Num Poum)', ARRAY['dessert']::text[], ARRAY['vegetarian']::text[], 17, 30, 47, 'easy', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 2, '[{"name":"Rice Flour","measure":"1/2 cup"},{"name":"Wheat Flour","measure":"1/2 cup"},{"name":"Coconut Milk","measure":"1/2 cup"},{"name":"Palm Sugar","measure":"3/4 cup"},{"name":"Eggs","measure":"2"},{"name":"Salt","measure":"1/2 tsp"}]'::jsonb, '["In a bowl, mix the flour, coconut milk, palm sugar and eggs and salt.","Brush a waffle iron with oil pour in the batter and cook over an open fire until light brown and crispy."]'::jsonb, 'https://www.themealdb.com/images/media/meals/h7zrys1779736460.jpg', 'themealdb'),
('BEEF LOK LAK (Lok Lak Sach Ko)', ARRAY['beef']::text[], ARRAY['dairy_free']::text[], 37, 60, 97, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 6, '[{"name":"Beef Tenderloin","measure":"1 kg"},{"name":"Garlic","measure":"5 cloves"},{"name":"Oil","measure":"2 tablespoons"},{"name":"Palm Sugar","measure":"1.5 tablespoon"},{"name":"Sea Salt","measure":"1 tsp"},{"name":"White Wine","measure":"2 tablespoons"},{"name":"Oyster Sauce","measure":"2 tablespoons"},{"name":"Soy Sauce","measure":"2 tablespoons"},{"name":"Sesame Seed Oil","measure":"1.5 tablespoon"},{"name":"Lettuce","measure":"500g"},{"name":"Tomato","measure":"400g"},{"name":"Onion","measure":"200g"},{"name":"Eggs","measure":"4"},{"name":"Sea Salt","measure":"1.5 tablespoon"},{"name":"Kampot Pepper","measure":"1 tablespoon"},{"name":"Lime juice","measure":"1 tablespoon"}]'::jsonb, '["Fry the eggs sunny-side up and set aside. Finely chop the garlic. Wash the lettuce leaves and drain well. Thinly slice the onion and tomatoes.","Cut the beef tenderloin into 2–3 cm cubes. Marinate with sea salt, palm sugar, Chinese cooking wine, oyster sauce, soy sauce, and sesame oil. Mix well.","Heat a frying pan on high heat with cooking oil. Add chopped garlic and stir until the garlic browns lightly. Add the marinated beef (with all the marinade) and cook for 5–7 minutes, depending on how rare you want the beef.","Dry roast the black Kampot peppercorns in a frying pan over medium-low heat for 2–3 minutes until fragrant. Grind the roasted pepper, place it in a bowl, then add sea salt and lime juice. Mix well.","On a serving plate, arrange a bed of lettuce, then layer tomatoes, then onions. Spoon the cooked beef over the vegetables and place fried eggs on top. Serve with the Kampot pepper sauce and fragrant steamed rice.","Sear hot and fast, Lok Lak is at its best when the beef stays tender and juicy, with a bold, bright dipping sauce to cut through the richness."]'::jsonb, 'https://www.themealdb.com/images/media/meals/t2b8bn1779737789.jpg', 'themealdb'),
('Authentic Laos Tapioca Pudding with Bananas', ARRAY['dessert']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 21, 55, 76, 'medium', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 4, '[{"name":"Warm Water","measure":"1 cup"},{"name":"Water","measure":"4 cups"},{"name":"Tapioca","measure":"3  tablespoons"},{"name":"Coconut Milk","measure":"14 oz jar"},{"name":"Sugar","measure":"2 tablespoons"},{"name":"Banana","measure":"3 Cups"},{"name":"Water","measure":"4 cups"},{"name":"Salt","measure":"To taste"}]'::jsonb, '["In a bowl of warm water, add tapioca pearls and allow them to soak for 20 minutes.","Prepare bananas by peeling them and cutting them into ½ inch slices. Set the slices aside","On a stove, pour in 4 cups of water and bring it to a boil. Add in the banana slices.","After 20 minutes, drain the tapioca pearls in cold water to allow the pearls to separate from each other.","Add the tapioca pearls into the the pot. Allow to simmer for 3 minutes or until the tapioca pearls turn clear.","Next, add in sugar and pour in the coconut cream. Stir the ingredients gently for 3 minutes to incorporate the flavors.","Add salt to taste."]'::jsonb, 'https://www.themealdb.com/images/media/meals/5pmn0g1779813285.jpg', 'themealdb'),
('Corn on the cob with lime, green chilli and coconut butter', ARRAY['side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 29, 30, 59, 'medium', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 4, '[{"name":"Vegetable Stock","measure":"1 L"},{"name":"Corn On The Cob","measure":"6"},{"name":"Coconut Milk","measure":"400ml"},{"name":"Lime","measure":"Zest and juice of 2"},{"name":"Green Chilli","measure":"1"},{"name":"Salt","measure":"Pinch"},{"name":"Black Pepper","measure":"Pinch"},{"name":"Butter","measure":"25g"},{"name":"Desiccated Coconut","measure":"100g"},{"name":"Shallots","measure":"100g"},{"name":"Coriander","measure":"10g"},{"name":"Parsley","measure":"10g"}]'::jsonb, '["Bring the stock to a rolling boil in a big, deep pan. Slip in the cobs, leave to cook for about five minutes, then turn off the heat and leave the corn to sit in the stock as it cools.","Put a heavy-based dry frying pan on a high heat and, once hot, lay the drained corn in the pan and char for a couple of minutes on each side – you’ll probably need to cook them two or three at a time, so you don’t overcrowd the pan. Put the coconut milk, lime juice and chillies in a small saucepan, season lightly, then bring up to a gentle simmer. Stir in the butter, turn off the heat and set aside.","For the topping, toast the coconut flakes in a hot dry frying pan – coconut burns very easily, so keep them moving and keep your eye on them. As soon as the coconut has a golden, burnished, toasted colour, tip it into a bowl, leave to cool, then mix with the crispy shallots and herbs, and season to taste.","To serve, spoon some of the coconut milk mixture over each cob, sprinkle with the toasted coconut mix and lime zest, and tuck in."]'::jsonb, 'https://www.themealdb.com/images/media/meals/brhaoj1780086661.jpg', 'themealdb'),
('Slow-cooked, Wadadli-spiced Cubano pork belly', ARRAY['pork']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free', 'gluten_free']::text[], 35, 55, 90, 'hard', '{"calories":500,"protein_g":34,"carbs_g":14,"fat_g":34}'::jsonb, 6, '[{"name":"Olive Oil","measure":"175ml"},{"name":"Coriander","measure":"4 tablespoons"},{"name":"Parsley","measure":"4 tablespoons"},{"name":"Oregano","measure":"6 tablespoons"},{"name":"Mint","measure":"6 tablespoons"},{"name":"Red Chilli","measure":"2"},{"name":"Green Chilli","measure":"1"},{"name":"Orange","measure":"Zest and juice of 2"},{"name":"Lime","measure":"Zest and juice of 2"},{"name":"Grapefruit","measure":"Juice of 1"},{"name":"Garlic","measure":"40g"},{"name":"Ground Cumin","measure":"3 tsp"},{"name":"Ground Allspice","measure":"2 tablespoons"},{"name":"Salt","measure":"To taste"},{"name":"Black Pepper","measure":"To taste"}]'::jsonb, '["Blitz all the marinade ingredients in a food processor or with a hand blender. Lay the pork in a large dish, pour over the marinade, then turn the meat in the mixture, rubbing in the marinade all over and making sure every bit of the belly is coated. Cover the dish and leave overnight in the fridge.","The next day, heat the oven to 140C (120C fan)/275F/gas 1. Lift the meat out of its marinade (don’t wipe off any that sticks to the joint, though; just leave most of the marinade behind in the dish) and transfer to a large roasting dish. Cover with foil, slip into the oven and roast for four and a half hours – every now and then (say, three or four times over the whole cooking period), take the dish out of the oven, lift off the foil lid and spoon the juices from the bottom of the dish over the meat. Return the foil lid, then put back in the oven.","After the time is up, remove the foil, turn up the heat to 180C (160C fan)/350F/gas 4 and give the pork a final blast – after 15-20 minutes, the top will take on a lovely colour and the meat should be yielding and soft enough to cut with a spoon.","To make crackling shards to serve with the meat, heat the oven to 200C (180C fan)/390F/gas 6 and line a roasting tray with baking paper. Lightly score the skin from the pork belly with a sharp knife, then rub it with a three or four fat pinches of salt – I also like to add a few caraway, cumin or fennel seeds at this point (use anything that takes your fancy). Cut the skin into long strips and lay these fat side down on the lined tray (you can, of course, leave it whole, but I think its pleasing to dress the plate with long, golden shards of crackling). Lay a second sheet of baking paper on top of the skin, then put a second baking tray of the same size on top, and roast for 45 minutes to an hour (if by this point the crackling has not gone crisp, just put it back in the oven and carry on roasting it until it has).","Cut or pull the pork apart, top with finely chopped coriander and flat-leaf parsley and shards of crackling, if you have made them, and serve at once"]'::jsonb, 'https://www.themealdb.com/images/media/meals/t1hg8s1780087329.jpg', 'themealdb'),
('Jajek', ARRAY['side']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 17, 20, 37, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Yogurt","measure":"2 cups"},{"name":"Cold Water","measure":"1 cup"},{"name":"Garlic","measure":"1 clove peeled crushed"},{"name":"Salt","measure":"1/2 tsp"},{"name":"Dried Mint","measure":"1 tsp"},{"name":"Cucumber","measure":"1"}]'::jsonb, '["Place yogurt, water, garlic and salt in food processor and process for a few seconds. Transfer to a bowl and mix with mint and cucumber.  Best served chilled for a few hours.","When serving, add a few ice cubes to add additional refreshment!  Makes about four servings."]'::jsonb, 'https://www.themealdb.com/images/media/meals/8x0vgs1780090328.jpg', 'themealdb'),
('Bolita di Keshi', ARRAY['miscellaneous']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 13, 45, 58, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 2, '[{"name":"Cheddar Cheese","measure":"1 lb"},{"name":"Feta","measure":"1 lb"},{"name":"Eggs","measure":"1 beaten"},{"name":"Cornstarch","measure":"5 tablespoons"}]'::jsonb, '["Grate finely and toss together.","lb. sharp yellow cheese (cheddar or oude boerenkaas)","lb. keshi di buriko (or any white cheese such as fromage blanc, queso blanco, ricotto, feta etc.)","Stir in:","eggs, beaten","Tbs. Cornstarch","Shape the mixture into small balls. These may be kept indefinitely in the freezer. Drop the balls into deep, hot fat and fry until golden. Serve piping hot on toothpicks."]'::jsonb, 'https://www.themealdb.com/images/media/meals/skzd0x1780091674.jpg', 'themealdb'),
('Balchi di Pisca', ARRAY['seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 27, 75, 102, 'hard', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"Salt Cod","measure":"1"},{"name":"Potatoes","measure":"3 Medium"},{"name":"Tomato","measure":"1"},{"name":"Green Pepper","measure":"1/2"},{"name":"Onion","measure":"1 medium"},{"name":"Garlic","measure":"1 clove peeled sliced"},{"name":"Tobasco Sauce","measure":"1/2 tsp"},{"name":"Nutmeg","measure":"Dash"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Egg","measure":"1"}]'::jsonb, '["These delectable fish balls can also be made with salmon or fish fillets. Substitute one large can of salmon or one pound of any white fish for the cod.","Soak for twenty-four hours:","salted cod, or bakijow Discard the water.","Place cod in saucepan with fresh water to cover. Simmer gently until the fish flakes easily when tested with the tines of a fork. Strain, reserving a bit of the broth. De bone the cod and set it aside for later use. In a saucepan, bring to boil in water to cover: 3 medium potatoes, peeled and diced When the potatoes are tender, drain them well. Add the cod and mash the two ingredients thoroughly together.","Place in the container of an electric blender:","tomato, peeled and chopped","/2 green pepper, chopped","medium onion, peeled and chopped","clove garlic, slivered","/2 tsp. Tabasco sauce, or minced hot pepper","Dash of nutmeg","Salt and pepper to taste","Blend for a few seconds and pour the sauce over the mashed fish mixture. Combine these ingredients well and add 1 egg, beaten Mixture should be stiff enough to mold into balls about one and a half inches in diameter, If it''s too dry, add the fish stock a tablespoon at a time. Fry the balls in hot, deep fat until golden brown."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qqwhw51780093126.jpg', 'themealdb'),
('Satee', ARRAY['beef']::text[], ARRAY['dairy_free']::text[], 27, 110, 137, 'hard', '{"calories":520,"protein_g":38,"carbs_g":18,"fat_g":32}'::jsonb, 4, '[{"name":"Onion","measure":"1 chopped"},{"name":"Garlic","measure":"2 cloves"},{"name":"Lemons","measure":"Juice of 2"},{"name":"Sugar","measure":"2 tablespoons"},{"name":"Soy Sauce","measure":"1 cup"},{"name":"Salt","measure":"1 tsp"},{"name":"Ground Coriander","measure":"1 tsp"},{"name":"Oil","measure":"1 cup"},{"name":"Beef","measure":"4-5 pound"},{"name":"Oil","measure":"1 cup"},{"name":"Soy Sauce","measure":"2 tablespoons"}]'::jsonb, '["To make the marinade for the satee put in the container of an electric blender:","large onion, coarsely chopped 2 cloves of garlic","Juice of 2 lemons","Tbs. of sugar 1 cup of soy sauce","tsp. salt 1 tsp. ground coriander for beef (or chicken) or 1 tsp. ground ginger for pork","cup of oil","Blend thoroughly and pour over:","lbs. of beef or pork tenderloin, cubed","DO NOT marinate overnight, but only for a few hours.","Place the meat on: 36 skewers","Blend well:","cup of oil","Tbs. Soy sauce","Pour into a large shallow dish.","To keep meat from becoming dry, roll each skewer in seasoned oil before frying.","Satee is also excellent when barbecued."]'::jsonb, 'https://www.themealdb.com/images/media/meals/dqxtlh1780153831.jpg', 'themealdb'),
('Clear Soup with Semolina Dumplings', ARRAY['miscellaneous']::text[], ARRAY[]::text[], 21, 40, 61, 'medium', '{"calories":420,"protein_g":18,"carbs_g":44,"fat_g":18}'::jsonb, 4, '[{"name":"Semolina","measure":"120g"},{"name":"Butter","measure":"60g"},{"name":"Egg","measure":"1"},{"name":"Salt","measure":"Pinch"},{"name":"Nutmeg","measure":"Pinch"},{"name":"Oil","measure":"Splash"},{"name":"Beef Stock","measure":"1 L"},{"name":"Parsley","measure":"Chopped"}]'::jsonb, '["Allow butter to come to room temperature before beating in a bowl until creamed. Season with salt and a small, delicate pinch of nutmeg.","Add in the egg, stirring vigorously. Sprinkle the semolina over this, and mix it in well until the surface is smooth. Cover with saran wrap and leave to rest for 15 – 20 minutes.","Use two spoons, dipped regularly into hot water throughout, to press or shape dumplings from the paste. You can also place these on a lightly oiled board or plate and again leave them to stand for a short while (this allows the dumplings to rise even more).","Heat a generous quantity of salted water in a large pan. Place the dumplings into the water and bring them back to a boil before turning down the heat and leaving to simmer gently for 10 – 15 minutes (do not boil). Carefully turn the dumplings occasionally.","Remove the semolina dumplings carefully and put them in the heated soup. Serve promptly, with a garnish of sprinkled parsley or chives.","The semolina dumplings can also be cooked in the beef broth, but this causes the soup to take on a slightly dull appearance. The cooked dumplings should never be left standing in the soup for too long, as they will “soak up” the soup and become softened."]'::jsonb, 'https://www.themealdb.com/images/media/meals/qserum1780156275.jpg', 'themealdb'),
('Tendir Choreyi (Tandoori Bread)', ARRAY['side']::text[], ARRAY['vegetarian', 'dairy_free']::text[], 17, 75, 92, 'hard', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Yeast","measure":"2 1/2 Tsp"},{"name":"Warm Water","measure":"1 1/2 cups"},{"name":"Salt","measure":"1 tsp"},{"name":"Flour","measure":"3 Cups"},{"name":"Egg Yolks","measure":"For brushing"},{"name":"Poppy Seeds","measure":"1 tsp"}]'::jsonb, '["First a quick note about tandoori bread (or tandoori anything, really). The name comes from the clay oven, or \"tandoor\" that it is traditionally cooked in, and you will never be able to duplicate the flavor of any tandoori recipe without one of those ovens, no matter how hard you try. Now, a tandoor oven is actually a part of my dream kitchen (I love naan bread and tandoori chicken) but I don''t have one in my current kitchen, so this bread just goes in a plain oven, which makes it not very authentic. However, this is how an Azerbaijani stranded in the US would make a tandoori bread, so I guess I don''t feel too bad about including it in my meal.","The ingredients for this bread are roughly similar to the ingredients for a basic french bread, but the shape is different and it is topped with poppy seeds which actually makes it quite beautiful in appearance. In fact this bread is quite possibly the most beautiful thing I''ve ever baked (my cakes certainly don''t fall into that category).","So as always I used my bread machine, but this time I didn''t proof the yeast first. I just put it in the little yeast dispenser at the top of my machine, then added the water, flour and salt to the bucket. I put it on the dough cycle and then went and picked my kids up from school.","This bread uses very basic ingredients, including bread flour and salt.","If you want to do it the old-fashioned way:","Mix the yeast with the water and let stand for a few minutes. Then sift the flour with the salt into a large bowl. Gradually add the water and yeast and mix with your hand until the dough forms a ball.","Turn out onto a lightly floured surface. Knead the dough for 8 to 10 minutes, or until it is smooth. Put it in a large bowl and cover, then let it rise in a warm spot until doubled (this typically takes 1 to 1 1/2 hours).","The dough after it has risen.","Punch down and turn out onto a lightly floured surface. Stretch the dough until it is an oblong shape, then with a rolling pin roll it until it is about 1/2 inch thick. Transfer to a greased or non-stick baking sheet and let stand for another 15 minutes.","After stretching and rolling, your dough should be roughly this shape.","Cut crosshatches in the top of the dough, about four in either direction. Brush with the beaten egg yolk (I mixed mine with a little bit of water to make it easier to work with) and sprinkle with poppy seeds.","Crosshatches, egg wash and poppy seeds give this bread its distinctive look.","Bake in a preheated oven at about 400 degrees for 20 to 25 minutes, until golden on top"]'::jsonb, 'https://www.themealdb.com/images/media/meals/5mfmh01780158856.jpg', 'themealdb'),
('Bangladeshi fish curry with daikon', ARRAY['seafood']::text[], ARRAY['pescatarian', 'dairy_free', 'gluten_free']::text[], 29, 55, 84, 'medium', '{"calories":380,"protein_g":34,"carbs_g":18,"fat_g":18}'::jsonb, 4, '[{"name":"White Fish","measure":"450g"},{"name":"Daikon Radish","measure":"450g"},{"name":"Vegetable Oil","measure":"4 tablespoons"},{"name":"Garlic","measure":"4 cloves"},{"name":"Onion","measure":"1 medium"},{"name":"Salt","measure":"2 tsp"},{"name":"Ground Turmeric","measure":"1 tsp"},{"name":"Ground Coriander","measure":"2 tsp"},{"name":"Chilli Powder","measure":"2 tsp"},{"name":"Green Chilli","measure":"2"},{"name":"Coriander Leaves","measure":"Handful"},{"name":"Lime","measure":"1"}]'::jsonb, '["If you are using rohu fish it will usually be frozen. Soak it in cold water for 30-45 minutes to defrost and while still a little firm, descale and cut each steak into quarters and wash in cold saltwater a few times. Drain and set aside. If using an alternative such as cod, cut into 2 ½ inch chunks then rinse, drain and set aside","Top and tail the daikon and peel using a potato peeler. Cut in half widthways then cut each half down the middle, lengthways. Now slice into 2cm-thick half-moon pieces. Rinse and set aside","Place a large, shallow saucepan over a medium heat and add the oil. When the oil is hot add the crushed garlic and stir for a minute until pale golden","Add the onion paste and salt and cook for 3-5 minutes, until the onion softens and becomes translucent, stirring occasionally","Pour in 200ml of water then cover and cook for 10 minutes, stirring once or twice","After 10 minutes add the ground spices and stir for a couple of minutes so that the spices cook through. Cover and cook for 5 minutes over a low heat then stir in the daikon. After a minute or so add 200ml of water. Cover and cook for 10 minutes on a medium heat","Add the fish pieces to the pan and mix thoroughly so that the fish is coated in the spices. Gently shake the pan and cover and cook for 5 minutes on medium heat. It is very important not to stir the pot after this stage","Meanwhile, boil some water. After the 5 minutes are over carefully pour 500ml hot water into the pan. When doing this pour into the sides of the pan so that you don’t pour boiling water directly onto the fish","Give the pan a gentle shake then cover and simmer over high heat for 15 minutes. Add the chopped coriander and chillies and continue cooking for another 5 minutes then turn off the heat. Serve immediately with rice and the lime wedges"]'::jsonb, 'https://www.themealdb.com/images/media/meals/r7mcjm1780261264.jpg', 'themealdb'),
('Bengali Chicken Curry with Potatoes', ARRAY['chicken']::text[], ARRAY['dairy_free', 'gluten_free']::text[], 29, 20, 49, 'medium', '{"calories":430,"protein_g":40,"carbs_g":15,"fat_g":22}'::jsonb, 4, '[{"name":"Olive Oil","measure":"2 tablespoons"},{"name":"Onion","measure":"2 diced"},{"name":"Ginger Garlic Paste","measure":"1 tablespoon"},{"name":"Tomato","measure":"2 diced"},{"name":"Cayenne Pepper","measure":"1 tsp"},{"name":"Curry Powder","measure":"1 tsp"},{"name":"Garam Masala","measure":"1 tsp"},{"name":"Ground Turmeric","measure":"1 tsp"},{"name":"Ground Cumin","measure":"1 tsp"},{"name":"Chicken Breast","measure":"4"},{"name":"Red Potatoes","measure":"2 large"},{"name":"Cilantro","measure":"1/2 cup"}]'::jsonb, '["Heat the olive oil in a large skillet over medium-high heat. Cook and stir the onions in the hot oil until translucent, about 5 minutes. Add the ginger-garlic paste and continue cooking another 5 minutes. Reduce heat to medium; stir the tomatoes into the mixture and cook until the tomatoes are pulpy, 5 to 10 minutes. Season with the cayenne pepper, curry powder, garam masala, turmeric, and cumin; cook and stir another 5 minutes.","Add the chicken and potatoes to the mixture in the skillet; simmer, stirring occasionally, until the potatoes are tender and the chicken is no longer pink in the center, about 20 minutes. Sprinkle the cilantro over the mixture and continue simmering another 10 minutes. Serve hot."]'::jsonb, 'https://www.themealdb.com/images/media/meals/9ya6o71780262651.jpg', 'themealdb'),
('Breadfruit in Butter Sauce Recipe', ARRAY['dessert']::text[], ARRAY['vegetarian']::text[], 33, 140, 173, 'hard', '{"calories":450,"protein_g":6,"carbs_g":62,"fat_g":20}'::jsonb, 6, '[{"name":"Breadfruit","measure":"1/2"},{"name":"Onion","measure":"1/2"},{"name":"Olive Oil","measure":"1 tablespoon"},{"name":"Butter","measure":"125g"},{"name":"Onion","measure":"3"},{"name":"Garlic","measure":"1 tablespoon"},{"name":"Tinned Tomatos","measure":"500ml"},{"name":"Parsley","measure":"3  tablespoons"},{"name":"Lime juice","measure":"1 tablespoon"},{"name":"Salt","measure":"To taste"},{"name":"Pepper","measure":"To taste"},{"name":"Water","measure":"250ml"},{"name":"Red Pepper Paste","measure":"To taste"},{"name":"Parsley","measure":"Garnish"}]'::jsonb, '["Captain William Bligh was chosen to lead an expedition to the South Seas to bring the breadfruit to the Caribbean.","His devotion to the breadfruit saplings and neglect of his crew’s water needs lead to the famous “Mutiny on the Bounty” on his first attempt. Cast overboard; Captain Bligh made his way hundreds of miles to safety in an open boat.","On his second attempt in 1793, he sailed into Jamaica’s Port Royal Harbour with a ship so crowded with beautiful leafy breadfruit saplings that the Jamaicans rowed out toward “the ship that has bush.”","Today large, lush breadfruit trees grow throughout the Caribbean, bearing the football-like starchy staple that has kept hunger away from many a door. Breadfruit may be difficult to find outside the Caribbean.","You will need the following ingredients:","/2 medium breadfruit","/2 small onion","tablespoon olive oil","oz/125g butter","medium onions, cut into rings","tablespoon garlic finely chopped","medium 16floz/500ml tin whole tomatoes, drained and sliced","/4 cup or 3 tablespoons parsley, diced","tablespoon lime juice","Salt and pepper to taste","cup 8oz or 250ml water","Red pepper sauce to taste.","Garnish: fresh parsley, chopped.","Instructions:","Cut the breadfruit, remove the seeds in the core, and peel. Boil in salted water with a little onion and oil, over high heat until tender and drain.","Meanwhile, melt the butter in a frying pan and lightly brown the onion rings. Add the garlic, tomatoes, parsley, lime juice, salt, and pepper. Continue to sauté for a couple of minutes. Add the water, bring to the boil and simmer for 5-10 minutes.","Slice the cooled breadfruit and place it in a serving dish. Pour the butter sauce over the breadfruit.","Garnish with chopped fresh parsley.","Serves 4"]'::jsonb, 'https://www.themealdb.com/images/media/meals/z672jx1780263633.jpg', 'themealdb'),
('Bajan Salt Bread Recipe', ARRAY['side']::text[], ARRAY['vegetarian', 'vegan', 'dairy_free']::text[], 17, 35, 52, 'easy', '{"calories":250,"protein_g":6,"carbs_g":36,"fat_g":9}'::jsonb, 2, '[{"name":"Yeast","measure":"2 tubs"},{"name":"Sugar","measure":"2 tsp"},{"name":"Salt","measure":"1 tsp"},{"name":"Vegetable Oil","measure":"2 tablespoons"},{"name":"Flour","measure":"6 cups"},{"name":"Warm Water","measure":"2 1/2 cups"}]'::jsonb, '["Sift half the flour, mix with salt and yeast in a large mixing bowl, and slowly add warm water until the mixture forms a stiff dough. Add more sifted flour until you have a stiff enough dough to knead.","Lightly flour the work surface, knead the dough for 10 minutes until it is smooth and elastic, and then place it in a greased bowl. Now place the bowl warmly for 40-50 minutes until it has doubled. You know the dough is ready when you poke a finger, and the indentation remains.","Preheat oven to 425 degrees F or 220 degrees C.","Now divide the dough into 12 equal portions, roll each into a fist size ball, and place on a greased baking sheet. Now place in a warm place again for a further 40 minutes or again until the dough has doubled in size.","Now place in the oven’s center and bake for 25-30 minutes until golden brown rolls sound hollow when tapped."]'::jsonb, 'https://www.themealdb.com/images/media/meals/sr7chd1780264758.jpg', 'themealdb');
